  // pra URL canônica (/recurring/demands ou /recurring/lists) via setRecurringTab.
  if (p === '/recurring') {
    let tab = 'demandas';
    try { tab = localStorage.getItem('kastor-rec-tab') || 'demandas'; } catch {}
    return { page: 'recurring', tab };
  }
  // Análises (Capacidade + Relatórios em abas). Bare usa a aba persistida; sub-rotas
  // explícitas fixam a aba. /capacity e /reports antigos redirecionam pra cá (compat).
  if (p === '/analytics') {
    let tab = 'capacity';
    try { tab = localStorage.getItem('kastor-an-tab') || 'capacity'; } catch {}
    return { page: 'analytics', tab };
  }
  if (p === '/analytics/capacity' || p === '/capacity') return { page: 'analytics', tab: 'capacity' };
  if (p === '/analytics/reports'  || p === '/reports')  return { page: 'analytics', tab: 'reports' };
  // Base de conhecimento: /knowledge-base = grid; /knowledge-base/:slug-id = post
  // /knowledge-base/new = editor (novo); /knowledge-base/:slug-id/edit = editor (editar)
  if (p === '/knowledge-base')                    return { page: 'kb' };
  if (p === '/knowledge-base/new')                return { page: 'post-editor', op: 'new' };
  {
    let mm;
    if ((mm = p.match(/^\/knowledge-base\/([a-z0-9-]+)\/edit$/))) return { page: 'post-editor', op: 'edit', postId: extractRouteId(mm[1]) };
    if ((mm = p.match(/^\/knowledge-base\/([a-z0-9-]+)$/))) return { page: 'kb', postId: extractRouteId(mm[1]) };
  }
  // Docs (nativos): /docs = manual home; /docs/manual/:sec e /docs/erros/:sec
  if (p === '/docs')                              return { page: 'docs', doc: 'manual' };
  if (p === '/docs/manual')                       return { page: 'docs', doc: 'manual' };
  if (p === '/docs/erros')                        return { page: 'docs', doc: 'erros' };
  {
    let mm;
    if ((mm = p.match(/^\/docs\/manual\/([a-z0-9-]+)$/))) return { page: 'docs', doc: 'manual', section: mm[1] };
    if ((mm = p.match(/^\/docs\/erros\/([a-z0-9-]+)$/)))  return { page: 'docs', doc: 'erros',  section: mm[1] };
  }
  if (PATH_TO_PAGE[p]) return { page: PATH_TO_PAGE[p] };
  let m;
  if ((m = p.match(/^\/demands\/new$/)))                    return { page: 'list',         modal: 'demand',  op: 'new' };
  if ((m = p.match(/^\/demands\/([^/]+)\/edit$/)))          return { page: 'list',         modal: 'demand',  op: 'edit', id: extractRouteId(m[1]) };
  // Detalhe da demanda é uma página dedicada agora (deixou de ser modal).
  if ((m = p.match(/^\/demands\/([^/]+)$/)))                return { page: 'demand-detail', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/new$/)))                    return { page: 'clients',      modal: 'client',  op: 'new' };
  if ((m = p.match(/^\/clients\/([^/]+)\/edit$/)))          return { page: 'clients',      modal: 'client',  op: 'edit', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/([^/]+)\/report$/)))        return { page: 'clients',      view: 'report', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/([^/]+)\/projects\/([^/]+)\/edit$/))) return { page: 'clients', modal: 'project', op: 'edit', id: extractRouteId(m[2]), clientId: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/([^/]+)\/projects\/([^/]+)\/report$/))) return { page: 'clients', view: 'project-report', id: extractRouteId(m[2]), clientId: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/([^/]+)\/projects\/([^/]+)$/))) return { page: 'clients', view: 'project-detail', id: extractRouteId(m[2]), clientId: extractRouteId(m[1]) };
  if ((m = p.match(/^\/clients\/([^/]+)$/)))                return { page: 'clients',      view: 'detail', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/projects\/new$/)))                   return { page: 'projects',     modal: 'project', op: 'new' };
  if ((m = p.match(/^\/projects\/([^/]+)\/edit$/)))         return { page: 'clients',      modal: 'project', op: 'edit', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/projects\/([^/]+)\/report$/)))       return { page: 'clients',      view: 'project-report', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/projects\/([^/]+)$/)))               return { page: 'clients',      view: 'project-detail', id: extractRouteId(m[1]) };
  if ((m = p.match(/^\/flows\/new$/)))                      return { page: 'flows',        modal: 'flow',    op: 'new' };
  if ((m = p.match(/^\/flows\/([^/]+)$/)))                  return { page: 'flows',        modal: 'flow',    op: 'edit', id: m[1] };
  if ((m = p.match(/^\/users\/new$/)))                      return { page: 'users',        modal: 'user',    op: 'new' };
  if ((m = p.match(/^\/users\/([^/]+)$/)))                  return { page: 'users',        modal: 'user',    op: 'edit', id: m[1] };
  if ((m = p.match(/^\/integrations\/webhooks\/new$/)))     return { page: 'integrations', modal: 'webhook', op: 'new' };
  if ((m = p.match(/^\/integrations\/webhooks\/([^/]+)$/))) return { page: 'integrations', modal: 'webhook', op: 'edit', id: m[1] };
