function renderDevTools() {
  const wrap = $('devtools-groups');
  if (!wrap) return;
  // Gate final no cliente — a nav-item já é admin-only, mas se cair aqui via URL
  // direto o non-admin vê uma mensagem em vez do hub.
  if (!me?.isAdmin) {
    wrap.innerHTML = `<div class="empty-state">Sem permissão. Só administradores acessam esta tela.</div>`;
    return;
  }
  wrap.innerHTML = DEVTOOLS_GROUPS.map(g => `
    <div class="dt-group">
      <div class="dt-group-head">
        <div class="dt-group-title">${esc(g.title)}</div>
        ${g.hint ? `<div class="dt-group-hint">${esc(g.hint)}</div>` : ''}
      </div>
      <div class="dt-grid">
        ${g.links.map(l => `
          <a class="dt-card" href="${esc(l.path)}" onclick="devToolsOpen(event, '${esc(l.path)}')">
            <div class="dt-card-icon"><i data-lucide="${esc(l.icon || 'link')}" class="ic-sm"></i></div>
            <div class="dt-card-body">
              <div class="dt-card-label">${esc(l.label)}</div>
              <div class="dt-card-path">${esc(l.path)}</div>
              ${l.desc ? `<div class="dt-card-desc">${esc(l.desc)}</div>` : ''}
            </div>
            <div class="dt-card-arrow"><i data-lucide="arrow-up-right" class="ic-xs"></i></div>
          </a>`).join('')}
      </div>
    </div>
  `).join('');
  paintIcons();
}
/* Cli-side navigation dos cards. Usa history.pushState + applyRoute pra
   respeitar o SPA (sem full reload). Ctrl/⌘/middle-click deixam o browser
   abrir em nova aba naturalmente. */
function devToolsOpen(evt, path) {
  if (!evt) return;
  if (evt.metaKey || evt.ctrlKey || evt.shiftKey || evt.button === 1) return; // deixa o browser
  evt.preventDefault();
  history.pushState(null, '', path);
  applyRoute();
}
/* ─── DOCS NATIVAS ───
   Substitui o iframe antigo — o HTML do doc é fetchado, o `<style>` extraído
   e o body injetado em Shadow DOM (isolamento perfeito de estilos). A
   navegação interna (cards, prev/next, "Todos os tópicos", cross-doc)
   passa a usar rotas SPA `/docs/manual/:sec` e `/docs/erros/:sec` — a URL
   é a fonte da verdade, deep-links funcionam nativamente. */
const DOCS_MAP = {
  manual: { url: '/docs/Manual-do-Usuario.html', title: 'Manual do Usuário' },
  erros:  { url: '/docs/Codigos-de-Erro.html',   title: 'Códigos de Erro' }
};
const _docsCache = {}; // { key: { style, body, initialBodyClass } }
async function _fetchDocContent(key) {
  if (_docsCache[key]) return _docsCache[key];
  const spec = DOCS_MAP[key]; if (!spec) throw new Error('doc desconhecido: ' + key);
  const html = await (await fetch(spec.url + '?ts=' + Date.now())).text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  let style = '';
  doc.querySelectorAll('style').forEach(s => style += s.textContent + '\n');
  const bodyEl = doc.querySelector('body');
  const initialBodyClass = bodyEl?.className || '';
  const body = bodyEl?.innerHTML || '';
  // Rescope pra Shadow DOM: `:root` e `body` não existem dentro do shadow.
  // Ambos precisam virar `:host` pra as custom properties + estilos de body
  // (font-family, background, cor, etc.) serem aplicados no elemento host.
  // Sintaxe do :host: filtros vão DENTRO dos parens (`:host(.foo)`, não `:host.foo`).
  // Ordem importa: primeiro os padrões compostos, depois os standalone.
  style = style
    .replace(/:root\[([^\]]+)\]/g, ':host([$1])')
    .replace(/:root:not\(\s*([^)]+)\s*\)/g, ':host(:not($1))')
    .replace(/:root\b/g, ':host')  // `\b` só funciona depois do `t` (não antes de `:`)
    .replace(/\bbody\s*\.([a-zA-Z_-][\w-]*)/g, ':host(.$1)')
    .replace(/\bbody\s*:not\(\s*([^)]+)\s*\)/g, ':host(:not($1))')
    .replace(/\bbody\b/g, ':host');
  _docsCache[key] = { style, body, initialBodyClass };
  return _docsCache[key];
}
async function renderDocsFromRoute() {
  const container = document.getElementById('docs-container');
  if (!container) return;
  const path = location.pathname;
  let key = 'manual', section = null;
  let m;
  if ((m = path.match(/^\/docs\/manual\/([a-z0-9-]+)$/))) { key = 'manual'; section = m[1]; }
  else if (path === '/docs/manual') { key = 'manual'; }
  else if ((m = path.match(/^\/docs\/erros\/([a-z0-9-]+)$/))) { key = 'erros'; section = m[1]; }
  else if (path === '/docs/erros') { key = 'erros'; }
  else if (path === '/docs' || path === '/docs/') { key = 'manual'; }
  await _mountDoc(container, key, section);
}
async function _mountDoc(container, key, section) {
  const currentDoc = container.dataset.doc;
  // Se doc mudou, refaz o mount inteiro; senão só troca a seção.
  if (currentDoc !== key) {
    let content;
    try { content = await _fetchDocContent(key); }
    catch (e) { container.textContent = 'Falha ao carregar documentação.'; return; }
    // Shadow root pra isolamento total de estilos
    const shadow = container.shadowRoot || container.attachShadow({ mode: 'open' });
    // CSS extra AO FINAL — sobrescreve baseado no `data-theme` espelhado do app,
    // independente do `prefers-color-scheme` do browser. Sem isso, o doc segue
    // a preferência do sistema em vez do toggle do app.
    // Palette alinhada com o app (cinzas neutros, não azulados/roxeados).
    // Os valores originais do doc tinham tint azul (#0B0B10 → RGB 11,11,16); aqui
    // usamos as mesmas cores do app (#161616, #262626, #ECECEC) pra o doc não
    // "destoar" do resto quando embed. Mantém dark/light aos pares.
    const themeOverride = `
      :host([data-theme="dark"]) {
        --bg: #161616; --surface: #262626; --surface-2: #363636; --surface-3: #474747;
        --hairline: rgba(255,255,255,0.06); --border: rgba(255,255,255,0.08);
        --text: #ECECEC; --text-dim: #B8B8B8; --text-muted: #A3A3A3;
        --accent-soft: rgba(122,0,255,0.15);
        --shadow: 0 12px 32px rgba(0,0,0,0.32);
      }
      :host([data-theme="light"]) {
        --bg: #F5F5F5; --surface: #FFFFFF; --surface-2: #F0F0F0; --surface-3: #E5E5E5;
        --hairline: rgba(0,0,0,0.07); --border: rgba(0,0,0,0.10);
        --text: #1A1A1A; --text-dim: #4A4A4A; --text-muted: #6B6B6B;
        --accent-soft: rgba(122,0,255,0.10);
        --shadow: 0 4px 20px rgba(0,0,0,0.06);
      }
    `;
    shadow.innerHTML = `<style>:host { display: block; }\n${content.style}\n${themeOverride}</style>${content.body}`;
    // Aplica a classe inicial do body no host (ex.: on-home)
    container.className = 'docs-container' + (content.initialBodyClass ? ' ' + content.initialBodyClass : '');
    container.dataset.doc = key;
    _wireDocShadowNav(shadow, container, key);
    _mirrorAppThemeToDocs(container);
  }
  _showDocSection(container, key, section);
}
/* Espelha o `data-theme` do app pro container do doc, e observa mudanças
   (toggle de tema) pra sincronizar em tempo real. */
function _mirrorAppThemeToDocs(container) {
  const sync = () => {
    const t = document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
    container.setAttribute('data-theme', t);
  };
  sync();
  // MutationObserver único (idempotente por container)
  if (container._themeMo) return;
  container._themeMo = new MutationObserver(muts => {
    if (muts.some(m => m.attributeName === 'data-theme')) sync();
  });
  container._themeMo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
}
function _wireDocShadowNav(shadow, container, docKey) {
  // Cards (só o manual tem) — click abre section via SPA nav
  shadow.querySelectorAll('.doc-card[data-section]').forEach(c => {
    c.addEventListener('click', (e) => {
      e.preventDefault();
      _navDoc(`/docs/${docKey}/${c.dataset.section}`);
    });
  });
  // Botão "← Todos os tópicos"
  shadow.querySelectorAll('.home-crumb').forEach(b => {
    b.addEventListener('click', (e) => {
      e.preventDefault();
      _navDoc(`/docs/${docKey}`);
    });
  });
  // Prev/Next
  shadow.querySelectorAll('.nav-btn').forEach(b => {
    b.addEventListener('click', (e) => {
      const target = b.dataset.target;
      if (!target) return;
      e.preventDefault();
      _navDoc(`/docs/${docKey}/${target}`);
    });
  });
  // Search (só manual) — só filtra local, sem router
  const searchInput = shadow.getElementById && shadow.getElementById('doc-search');
  if (searchInput) {
    const cards = [...shadow.querySelectorAll('.doc-card')];
    const emptyMsg = shadow.getElementById('home-empty');
    const doSearch = () => {
      const q = String(searchInput.value || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      let visible = 0;
      cards.forEach(c => {
        if (!q) { c.classList.remove('hidden'); visible++; return; }
        const hay = (
          (c.querySelector('.doc-card-name')?.textContent || '') + ' ' +
          (c.dataset.group || '') + ' ' +
          (c.dataset.kw || '') + ' ' +
          (c.querySelector('.doc-card-desc')?.textContent || '')
        ).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
        const hit = q.split(/\s+/).every(part => hay.includes(part));
        c.classList.toggle('hidden', !hit);
        if (hit) visible++;
      });
      if (emptyMsg) emptyMsg.style.display = visible ? 'none' : '';
    };
    searchInput.addEventListener('input', doSearch);
    searchInput.addEventListener('keydown', e => {
      if (e.key === 'Escape') { searchInput.value = ''; doSearch(); }
    });
  }
  // Links internos <a href="#xxx"> → SPA nav (na mesma doc)
  shadow.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      const s = a.getAttribute('href').slice(1);
      if (s) _navDoc(`/docs/${docKey}/${s}`);
    });
  });
  // Cross-doc links: "Codigos-de-Erro.html", "Manual-do-Usuario.html", com ou sem #hash
  shadow.querySelectorAll('a[href^="Codigos-de-Erro.html"], a[href^="Manual-do-Usuario.html"]').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      const href = a.getAttribute('href');
      const [file, sec] = href.split('#');
      const otherKey = file.startsWith('Codigos') ? 'erros' : 'manual';
      _navDoc(sec ? `/docs/${otherKey}/${sec}` : `/docs/${otherKey}`);
    });
  });
}
/* Nav interna dos docs: push na URL + re-render. navPush não dispara popstate
   nem chama applyRoute, então precisamos reaplicar manualmente. */
function _navDoc(path) {
  navPush(path);
  renderDocsFromRoute();
}
function _showDocSection(container, docKey, section) {
  const shadow = container.shadowRoot;
  if (!shadow) return;
  if (docKey === 'manual') {
    // Manual tem card grid + section view. `.on-home` no host controla qual aparece.
    if (!section) {
      container.classList.add('on-home');
    } else {
      container.classList.remove('on-home');
      shadow.querySelectorAll('main section').forEach(s => s.classList.toggle('is-active', s.id === section));
      _updateManualPrevNext(shadow, section);
    }
    // Rola pro topo
    const main = shadow.querySelector('main.section-view');
    if (main) main.scrollTop = 0;
    window.scrollTo({ top: 0, behavior: 'instant' });
  } else if (docKey === 'erros') {
    // Erros é uma doc scroll-single-page. Section = id do card de erro (com ou sem prefixo `detalhe-`)
    if (section) {
      const target = shadow.getElementById(section)
                  || shadow.getElementById('detalhe-' + section);
      if (target) target.scrollIntoView({ behavior: 'instant', block: 'start' });
    } else {
      window.scrollTo({ top: 0, behavior: 'instant' });
    }
  }
}
// Atualiza os botões prev/next baseado na ordem dos cards.
function _updateManualPrevNext(shadow, section) {
  const cards = [...shadow.querySelectorAll('.doc-card[data-section]')];
  const order = cards.map(c => c.dataset.section);
  const idx = order.indexOf(section);
  const prev = idx > 0 ? order[idx - 1] : null;
  const next = idx >= 0 && idx < order.length - 1 ? order[idx + 1] : null;
  const prevBtn = shadow.querySelector('.nav-btn.prev');
  const nextBtn = shadow.querySelector('.nav-btn.next');
  if (prevBtn) {
    prevBtn.disabled = !prev;
    prevBtn.dataset.target = prev || '';
    const t = shadow.getElementById('nav-prev-title');
    const name = prev ? cards.find(c => c.dataset.section === prev)?.querySelector('.doc-card-name')?.textContent : '—';
    if (t) t.textContent = name || '—';
  }
  if (nextBtn) {
    nextBtn.disabled = !next;
    nextBtn.dataset.target = next || '';
    const t = shadow.getElementById('nav-next-title');
    const name = next ? cards.find(c => c.dataset.section === next)?.querySelector('.doc-card-name')?.textContent : '—';
    if (t) t.textContent = name || '—';
  }
}

function renderCurrent() {
  switch (currentPage) {
    case 'dashboard':  renderDashboard(); break;
    case 'list':       renderList(); renderCalendar('all'); break;
    case 'mine':       renderMine(); renderCalendar('mine'); break;
    case 'analytics':  renderAnalytics(); break;
    case 'agenda':     renderAgenda(); break;
    case 'templates':  renderTemplates(); break;
    case 'recurring':  renderRecurring(); break;
    case 'integrations': renderIntegrations(); break;
    case 'devtools':   renderDevTools(); break;
    case 'passwords':  renderPasswords(); break;
    case 'kb':         renderKbFromRoute(); break;
    case 'post-editor': renderPostEditorFromRoute(); break;
    case 'demand-detail': if (detailId) renderDetail(); break;
    case 'docs':       renderDocsFromRoute(); break;
    case 'clients': {
      // Decide entre grid, detalhe de cliente ou detalhe de projeto sem perder estado
      // quando refreshData() roda com um modal aberto (URL temporariamente em /projects/<id>/edit).
      const path = location.pathname;
      const isOnGridUrl = path === '/clients' || path === '/clients/';
      const clientDetailMatch = path.match(/^\/clients\/([^/]+)$/);
      const projectDetailMatch = path.match(/^\/projects\/([^/]+)$/);
      const reportMatch = path.match(/^\/clients\/([^/]+)\/report$/);
      const projectReportMatch = path.match(/^\/projects\/([^/]+)\/report$/);
      const clientDetailId = clientDetailMatch ? clientDetailMatch[1] : null;
      const projectDetailId = projectDetailMatch ? projectDetailMatch[1] : null;
      const reportId = reportMatch ? reportMatch[1] : null;
      const projectReportId = projectReportMatch ? projectReportMatch[1] : null;
      if (isOnGridUrl) {
        currentClientId = null;
        currentProjectId = null;
        renderClients();
      } else if (projectReportId && projectById(projectReportId)) {
        currentProjectId = projectReportId;
        const p = projectById(projectReportId);
        currentClientId = p?.clientId || null;
        showProjectReportView();
        renderProjectReport(projectReportId);
      } else if (reportId && clientById(reportId)) {
        currentClientId = reportId;
        showClientReportView();
        renderClientReport(reportId);
      } else if (projectDetailId && projectById(projectDetailId)) {
        currentProjectId = projectDetailId;
        showProjectDetailView();
        renderProjectDetail(projectDetailId);
      } else if (clientDetailId && clientById(clientDetailId)) {
        currentClientId = clientDetailId;
        currentProjectId = null;
        showClientDetailView();
        renderClientDetail(clientDetailId);
      } else if (currentProjectId && projectById(currentProjectId)) {
        // URL em outra rota (modal), preserva o detalhe de projeto que estava aberto
        showProjectDetailView();
        renderProjectDetail(currentProjectId);
      } else if (currentClientId && clientById(currentClientId)) {
        showClientDetailView();
        renderClientDetail(currentClientId);
      } else {
        renderClients();
      }
      break;
    }
    case 'clientsModels': {
      // Subtela dentro da página Clientes — mesmo container, view diferente.
      // O nav ativa 'clients'; forçamos aqui pra o item da sidebar refletir.
      document.querySelectorAll('.nav-item').forEach(n => n.classList.toggle('active', n.dataset.page === 'clients'));
      document.querySelectorAll('.page').forEach(p => p.classList.toggle('active', p.id === 'page-clients'));
      $('topbar-title').textContent = 'Modelos de Cliente';
      showClientsModelsView();
      renderClientsModels();
      break;
    }
    case 'projects':   renderProjects(); break;
    case 'flows': {
      // Mantém a subview de um cliente aberta quando refreshData()/SSE roda (ou
      // ao fechar/salvar um fluxo). Sem isso, qualquer re-render voltava pro grid.
      if (currentClientView && (currentClientView === '__general__' || clientById(currentClientView))) {
        $('flows-view-clients').style.display = 'none';
        $('flows-view-detail').style.display = '';
        renderClientFlows(currentClientView);
      } else {
        currentClientView = null;
        renderFlows();
      }
      break;
    }
    case 'workspaces': renderWorkspaces(); break;
    case 'users':      renderUsers(); break;
    case 'trash':      renderTrash(); break;
    case 'recurringDemands': renderRecurringDemands(); break;
    case 'profile':    renderProfile(); break;
  }
  // Escopa a pintura de ícones na página ativa em vez do documento inteiro.
  paintIcons(document.querySelector('.page.active') || undefined);
}

/* ─── FILTROS COMUNS ─── */
function fillSelect(sel, options, currentValue, firstLabel) {
  const prev = currentValue !== undefined ? currentValue : sel.value;
  const sorted = options.slice().sort((a, b) => norm(a.label).localeCompare(norm(b.label)));
  sel.innerHTML = `<option value="">${firstLabel}</option>` +
    sorted.map(o => `<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('');
  if ([...sel.options].some(op => op.value === prev)) sel.value = prev;
}
function fillRoleSelect(selId, currentValue) {
  const sel = $(selId);
  const sorted = roles.slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  sel.innerHTML = '<option value="">— Sem área —</option>' +
    sorted.map(r => `<option value="${esc(r.name)}" ${r.name === currentValue ? 'selected' : ''}>${esc(r.name)}</option>`).join('');
}
function fillPositionSelect(selId, currentValue) {
  const sel = $(selId);
  if (!sel) return;
  const sorted = (positions || []).slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  sel.innerHTML = '<option value="">— Sem cargo —</option>' +
    sorted.map(p => `<option value="${esc(p.name)}" ${p.name === currentValue ? 'selected' : ''}>${esc(p.name)}</option>`).join('');
}
function matchPeriod(dateStr, period, range) {
  if (!period) return true;
  // 'custom' usa range { start, end } explícito — start/end podem ser vazios
  // (só limita a extremidade preenchida). Sem nenhum dos dois → não filtra.
  if (period === 'custom') {
    const start = range?.start || '';
    const end = range?.end || '';
    if (!start && !end) return true;
    if (!dateStr) return false;
    const d = String(dateStr).slice(0, 10);
    if (start && d < start) return false;
    if (end && d > end) return false;
    return true;
  }
  if (!dateStr) return false;
  const d = String(dateStr).slice(0,10);
  const now = new Date();
  const today = todayStr();
  if (period === 'today') return d === today;
  if (period === '7') {
    const lim = new Date(); lim.setDate(lim.getDate() + 7);
    return d >= today && d <= lim.toISOString().slice(0,10);
  }
  if (period === 'month') {
    const pref = today.slice(0,7);
    return d.startsWith(pref);
  }
  if (period === 'lastmonth') {
    const lm = new Date(now.getFullYear(), now.getMonth() - 1, 15);
    const pref = `${lm.getFullYear()}-${String(lm.getMonth()+1).padStart(2,'0')}`;
    return d.startsWith(pref);
  }
  if (period === '90') {
    const lim = new Date(); lim.setDate(lim.getDate() - 90);
    return d >= lim.toISOString().slice(0,10) && d <= today;
  }
  return true;
}

/* ─── DASHBOARD ─── */
// Escopo por squad: '' = todos os squads acessíveis; caso contrário, apenas um.
// Guardado no próprio DOM (dash-f-squad) — sem estado global paralelo.
function dashScopeWsIds() {
  const wsId = $('dash-f-squad')?.value || '';
  if (wsId) return [wsId];
  return (workspaces || [])
    .filter(w => me?.isAdmin || (me?.workspaces || []).includes(w.id))
    .map(w => w.id);
}
function dashScopedDemands() { const ids = new Set(dashScopeWsIds()); return demands.filter(d => ids.has(d.workspaceId)); }
function dashScopedProjects() { const ids = new Set(dashScopeWsIds()); return projects.filter(p => ids.has(p.workspaceId)); }
function dashScopedFlows() { const ids = new Set(dashScopeWsIds()); return flows.filter(f => ids.has(f.workspaceId)); }
function dashScopedUsers() {
  const ids = dashScopeWsIds();
  return users.filter(u => u.active !== false && (u.isAdmin || (u.workspaces || []).some(w => ids.includes(w))));
}
function dashDemandTypes() {
  return [...new Set(dashScopedFlows().map(f => f.demandType).filter(Boolean))].sort();
}
function dashFilteredDemands() {
  const fu = $('dash-f-user').value;
  const fp = $('dash-f-period').value;
  const ft = $('dash-f-type').value;
  const fc = $('dash-f-client').value;
  return dashScopedDemands().filter(d => {
    if (fu && d.ownerId !== fu) return false;
    if (!matchPeriod(effDue(d), fp)) return false;
    if (ft && demandType(d) !== ft) return false;
    if (fc) {
      const p = projectById(d.projectId);
      if (!p || p.client !== fc) return false;
    }
    return true;
  });
}
function clearDashFilters() {
  ['dash-f-user','dash-f-period','dash-f-type','dash-f-client','dash-f-squad'].forEach(id => { if ($(id)) $(id).value = ''; });
  renderDashboard();
}
// Traduz o valor do filtro dash-f-period em janela YYYY-MM-DD [from, to].
// Retorna { from, to, label } onde label é uma legenda humana pro card.
function _dashPeriodRange(period) {
  const today = new Date(); today.setHours(0,0,0,0);
  const ymd = (d) => d.toISOString().slice(0, 10);
  if (period === 'today') return { from: ymd(today), to: ymd(today), label: 'hoje' };
  if (period === '7') {
    const end = new Date(today); end.setDate(today.getDate() + 6);
    return { from: ymd(today), to: ymd(end), label: 'próximos 7 dias' };
  }
  if (period === 'month') {
    const start = new Date(today.getFullYear(), today.getMonth(), 1);
    const end   = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    return { from: ymd(start), to: ymd(end), label: MONTHS[today.getMonth()].toLowerCase() };
  }
  if (period === 'lastmonth') {
    const start = new Date(today.getFullYear(), today.getMonth() - 1, 1);
    const end   = new Date(today.getFullYear(), today.getMonth(), 0);
    return { from: ymd(start), to: ymd(end), label: MONTHS[start.getMonth()].toLowerCase() };
  }
  if (period === '90') {
    const start = new Date(today); start.setDate(today.getDate() - 90);
    return { from: ymd(start), to: ymd(today), label: 'últimos 90 dias' };
  }
  // 'Todo o período' — sem from/to; usa mês corrente por default pro card não
  // ficar carregando anos de eventos sem sentido.
  const start = new Date(today.getFullYear(), today.getMonth(), 1);
  const end   = new Date(today.getFullYear(), today.getMonth() + 1, 0);
  return { from: ymd(start), to: ymd(end), label: MONTHS[today.getMonth()].toLowerCase() };
}
// Popula o card "Horas em reunião" — chama /api/google/meeting-hours com o
// escopo atual do dashboard (squad + usuário + período).
async function refreshDashMeetingHours() {
  const val = $('dash-kpi-meetings-value');
  const sub = $('dash-kpi-meetings-sub');
  if (!val) return;
  const period = $('dash-f-period')?.value || '';
  const range = _dashPeriodRange(period);
  const params = new URLSearchParams();
  if (range.from) params.set('from', range.from);
  if (range.to)   params.set('to',   range.to);
  const uid = $('dash-f-user')?.value || '';
  if (uid) params.set('userId', uid);
  const wsId = $('dash-f-squad')?.value || '';
  if (wsId) params.set('workspaceId', wsId);
  try {
    const r = await api('/google/meeting-hours?' + params.toString());
    val.textContent = fmtHours(r.hours || 0);
    const who = uid ? (userById(uid)?.name?.split(' ')[0] || '') : '';
    const label = who ? `${who} · ${range.label}` : range.label;
    if (sub) sub.textContent = `${r.count || 0} evento${(r.count || 0) === 1 ? '' : 's'} · ${label}`;
  } catch (e) {
    val.textContent = '—';
    if (sub) sub.textContent = 'Sem dados';
  }
}

/* ─── Widget "Meu dia" ───
   Foco pessoal no topo do dashboard: prazo hoje, atrasadas suas, menções não
   lidas. Sempre relativo ao usuário logado. Não respeita os filtros da tela. */
function renderMyDay() {
  const wrap = $('my-day-grid');
  if (!wrap || !me) return;
  const today = todayStr();
  // Escopo: demandas visíveis pro usuário (workspaces acessíveis), não deletadas,
  // não concluídas. "Suas" = ownerId === me.id OU watcher.
  const mine = (demands || []).filter(d => {
    if (d.deletedAt) return false;
    if (isDone(d)) return false;
    if (!(me.isAdmin || (me.workspaces || []).includes(d.workspaceId))) return false;
    if (d.ownerId === me.id) return true;
    if (Array.isArray(d.watchers) && d.watchers.includes(me.id)) return true;
    return false;
  });
  const dueToday = mine.filter(d => effDue(d) === today).slice(0, 20);
  const overdue  = mine.filter(d => isLate(d)).slice(0, 20);
  const mentionsUnread = (notifications || [])
    .filter(n => !n.read && n.type === 'mention')
    .slice(0, 20);

  const anyContent = dueToday.length + overdue.length + mentionsUnread.length > 0;
  // Se não há nada relevante, esconde totalmente — dashboard vira o de sempre.
  if (!anyContent) { wrap.style.display = 'none'; return; }
  wrap.style.display = '';
  wrap.innerHTML = [
    _myDayCard('Prazo hoje', 'calendar-check', dueToday, _myDayDemandRow, 'Você não tem entregas pra hoje.'),
    _myDayCard('Atrasadas', 'alert-triangle', overdue, _myDayOverdueRow, 'Nada atrasado. ', 'danger'),
    _myDayCard('Menções não lidas', 'at-sign', mentionsUnread, _myDayMentionRow, 'Nenhuma menção nova.')
  ].join('');
  paintIcons();
}
function _myDayCard(title, icon, items, rowFn, empty, tone) {
  const rows = items.slice(0, 3).map(rowFn).join('');
  const more = items.length > 3
    ? `<div class="my-day-more">+ ${items.length - 3} mais</div>`
    : '';
  const body = items.length
    ? `<div class="my-day-items">${rows}${more}</div>`
    : `<div class="my-day-empty">${esc(empty)}</div>`;
  return `<div class="my-day-card ${tone ? 'is-' + tone : ''}">
    <div class="my-day-head">
      <span class="my-day-title"><i data-lucide="${icon}" class="ic-sm"></i> ${esc(title)}</span>
      <span class="my-day-count">${items.length}</span>
    </div>
    ${body}
  </div>`;
}
function _myDayDemandRow(d) {
  const p = projectById(d.projectId);
  const proj = p ? esc(p.name) : '—';
  return `<button type="button" class="my-day-row" onclick="showDetail('${esc(d.id)}')">
    <span class="my-day-row-name">${esc(d.name)}</span>
    <span class="my-day-row-sub">${proj}</span>
  </button>`;
}
function _myDayOverdueRow(d) {
  const due = effDue(d);
  const days = due ? Math.max(1, Math.floor((Date.now() - new Date(due + 'T00:00:00').getTime()) / 86400000)) : 0;
  return `<button type="button" class="my-day-row" onclick="showDetail('${esc(d.id)}')">
    <span class="my-day-row-name">${esc(d.name)}</span>
    <span class="my-day-row-sub">${days} dia${days === 1 ? '' : 's'} de atraso</span>
  </button>`;
}
function _myDayMentionRow(n) {
  const dName = n.demandName || 'demanda';
  return `<button type="button" class="my-day-row" onclick="openNotif('${esc(n.id)}', '${esc(n.demandId || '')}')">
    <span class="my-day-row-name">${esc(dName)}</span>
    <span class="my-day-row-sub">${esc(fmtDateTime(n.createdAt))}</span>
  </button>`;
}

function renderDashboard() {
  // Widget pessoal no topo — recalculado a cada re-render.
  renderMyDay();
  // Filtro por squad — "Todos" agrega todos os squads acessíveis. Popula antes
  // dos outros filtros porque eles dependem do escopo dele.
  const accessibleWs = (workspaces || []).filter(w => me?.isAdmin || (me?.workspaces || []).includes(w.id));
  const squadSel = $('dash-f-squad');
  if (squadSel) {
    // Só faz sentido mostrar o filtro quando há mais de um squad acessível.
    const parent = squadSel.closest('.filter-group');
    if (accessibleWs.length <= 1) {
      if (parent) parent.style.display = 'none';
      squadSel.value = '';
    } else {
      if (parent) parent.style.display = '';
      fillSelect(squadSel, accessibleWs.map(w => ({ value: w.id, label: w.name })), undefined, 'Todos os squads');
    }
  }
  // selects de filtro (preservando seleção) — agora escopados ao squad
  fillSelect($('dash-f-user'), dashScopedUsers().map(u => ({ value: u.id, label: u.name })), undefined, 'Todos os usuários');
  fillSelect($('dash-f-type'), dashDemandTypes().map(t => ({ value: t, label: t })), undefined, 'Todos os tipos');
  fillSelect($('dash-f-client'),
    [...new Set(dashScopedProjects().map(p => p.client).filter(Boolean))].sort().map(c => ({ value: c, label: c })),
    undefined, 'Todos os clientes');

  // por padrão o dashboard abre filtrado para o usuário ativo
  if (!dashUserInit) {
    dashUserInit = true;
    if ([...$('dash-f-user').options].some(o => o.value === me.id)) $('dash-f-user').value = me.id;
  }

  // Filtros salvos da sessão anterior vencem o default acima (mas só na primeira
  // pintura do dashboard — depois disso o user já interagiu).
  restoreFilters('dashboard');

  ['dash-f-user','dash-f-period','dash-f-type','dash-f-client','dash-f-squad'].forEach(id => {
    if ($(id)) $(id).classList.toggle('filtering', !!$(id).value);
  });

  // Estilizar os filtros como dropdowns customizados
  applyFilterDropdown('dash-f-squad');
  applyFilterDropdown('dash-f-user', { userIcon: true });
  applyFilterDropdown('dash-f-client');
  applyFilterDropdown('dash-f-period');
  applyFilterDropdown('dash-f-type');
  applyFilterDropdown('hours-f-period');

  const list = dashFilteredDemands();

  // Escopo COMPLETO do escopo de squad (ignora filtros de período/tipo/cliente)
  // — usado por Próximos 7 dias, Em atraso, Radar de projetos. Esses widgets
  // sempre olham "a partir de hoje" independente do filtro de período.
  const wsAll = dashScopedDemands();

  // ── KPIs (respeitam filtros) ──
  const open = list.filter(d => !isDone(d));
  const late = list.filter(isLate);
  const ymNow = new Date().toISOString().slice(0,7);
  const doneMonth = list.filter(d => d.completedAt && d.completedAt.slice(0,7) === ymNow);
  let hoursMonth = 0;
  list.forEach(d => (d.timeEntries || []).forEach(e => {
    const when = ((e.start || e.createdAt || '') + '').slice(0,7);
    if (when === ymNow) hoursMonth += Number(e.hours) || 0;
  }));

  $('dash-kpis').innerHTML = `
    <div class="dash-kpi">
      <div class="dash-kpi-label">Em andamento</div>
      <div class="dash-kpi-value">${open.length}</div>
      <div class="dash-kpi-sub">demandas abertas no filtro</div>
    </div>
    <div class="dash-kpi ${late.length ? 'is-danger' : ''}">
      <div class="dash-kpi-label">Em atraso</div>
      <div class="dash-kpi-value">${late.length}</div>
      <div class="dash-kpi-sub">deadline vencido</div>
    </div>
    <div class="dash-kpi">
      <div class="dash-kpi-label">Entregues no mês</div>
      <div class="dash-kpi-value">${doneMonth.length}</div>
      <div class="dash-kpi-sub">${MONTHS[new Date().getMonth()]}</div>
    </div>
    <div class="dash-kpi">
      <div class="dash-kpi-label">Horas apontadas</div>
      <div class="dash-kpi-value">${fmtHours(hoursMonth)}</div>
      <div class="dash-kpi-sub">mês corrente</div>
    </div>
    <div class="dash-kpi" id="dash-kpi-meetings">
      <div class="dash-kpi-label">Horas em reunião</div>
      <div class="dash-kpi-value" id="dash-kpi-meetings-value">—</div>
      <div class="dash-kpi-sub" id="dash-kpi-meetings-sub">Google Calendar</div>
    </div>
  `;
  animateCounters($('dash-kpis'));
  // Busca assíncrona: não bloqueia render, mostra "—" até chegar.
  refreshDashMeetingHours();

  // ── Demandas previstas / Em atraso / Radar / Top responsáveis / Throughput ──
  renderDashForecast();
  renderDashOverdue(wsAll);
  renderDashRadar();
  renderDashTopOwners(list);
  renderDashPriorityDonut(list);
  renderDashChart(list);
  renderHoursBoard(list);
  saveFilters('dashboard');
}

// ── Demandas previstas ── quadro heatmap 2×7 (14 dias úteis). Puxa o SLA das
// etapas pra prever QUANDO cada demanda vai chegar na etapa do usuário-alvo.
// Escopo: usuário selecionado no filtro do dashboard (default = usuário logado).
let _forecastByDay = null; // Map<ymd, [{ d, stageLabel, remaining }]> — pro modal do dia

// Réplica do addDays do backend: soma dias corridos e empurra o resultado pra
// fora do fim de semana (sáb→seg, dom→seg). Mesmo "cálculo padrão dos prazos".
function forecastAddDays(ymdStr, days) {
  const base = ymdStr ? new Date(ymdStr + 'T12:00:00') : new Date();
  base.setDate(base.getDate() + (Number(days) || 0));
  const dow = base.getDay();
  if (dow === 6) base.setDate(base.getDate() + 2);
  if (dow === 0) base.setDate(base.getDate() + 1);
  return base.toISOString().slice(0, 10);
}
// Os próximos 14 dias ÚTEIS (pula fim de semana), a partir de hoje.
function dashForecastDays() {
  const days = [];
  const d = new Date(); d.setHours(0,0,0,0);
  while (days.length < 14) {
    const dow = d.getDay();
    if (dow !== 0 && dow !== 6) days.push(new Date(d));
    d.setDate(d.getDate() + 1);
  }
  return days;
}
function forecastLevel(n) {
  if (n <= 0) return 0;
  if (n <= 3) return 1;   // verde
  if (n <= 6) return 2;   // amarelo
  if (n <= 9) return 3;   // laranja
  return 4;               // vermelho (≥10)
}
function forecastDeliverables(d) {
  const parts = [];
  const p = Number(d.qtyPieces) || 0, a = Number(d.qtyArts) || 0, v = Number(d.qtyVariations) || 0;
  if (p) parts.push(`${p} peça${p > 1 ? 's' : ''}`);
  if (a) parts.push(`${a} arte${a > 1 ? 's' : ''}`);
  if (v) parts.push(`${v} var.`);
  return parts.length ? parts.join(' · ') : '—';
}
/* Data (YYYY-MM-DD) em que a demanda deve CHEGAR na primeira etapa futura de
   responsabilidade de `userId`. Null se o user não está numa etapa futura.
   - Etapa atual termina no stageDueDate; se atrasada/sem due, conta de hoje
     (o atraso empurra a previsão pra frente).
   - Soma o SLA (deadlineDays) só das etapas ENTRE a atual e a do user — entrega
     antecipada não adianta a previsão (SLAs independentes). */
// Chegada por usuário numa passada só: userId -> { ymd, stageLabel, remaining }
// pra a PRIMEIRA etapa futura que cada pessoa é dona. Base do quadro do dashboard
// (1 user) E do mapa de prazos em modo "previstas" (todos os users de uma vez).
function forecastArrivalsByUser(d) {
  const out = new Map();
  if (!d || d.deletedAt || isDone(d)) return out;
  const stages = activeStagesOf(d);
  if (stages.length < 2) return out;
  const curIdx = stages.findIndex(s => s.id === d.status);
  if (curIdx < 0) return out;
  const today = todayStr();
  const curLabel = stages[curIdx].label || '—';
  let cursor;
  if (d.stageDueDate) cursor = (d.stageDueDate < today) ? forecastAddDays(today, 0) : d.stageDueDate;
  else cursor = forecastAddDays(today, stages[curIdx].deadlineDays || 0);
  // Ao ENTRAR na etapa i, a demanda chega em `cursor` (fim da etapa i-1). Só a
  // primeira etapa futura de cada dono conta (a demanda "chega" a ele ali).
  for (let i = curIdx + 1; i < stages.length; i++) {
    const owner = resolveStageOwnerId(d, stages[i]);
    if (owner && !out.has(owner)) {
      out.set(owner, { ymd: cursor, stageLabel: curLabel, remaining: i - curIdx });
    }
    cursor = forecastAddDays(cursor, stages[i].deadlineDays || 0);
  }
  return out;
}
function forecastArrivalFor(d, userId) {
  if (!userId) return null;
  return forecastArrivalsByUser(d).get(userId) || null;
}
function renderDashForecast() {
  const el = $('dash-forecast');
  const sub = $('dash-forecast-sub');
  if (!el) return;
  const targetUserId = ($('dash-f-user') && $('dash-f-user').value) || me?.id || null;
  const days = dashForecastDays();
  const ymd = (d) => d.toISOString().slice(0, 10);
  const byDay = new Map(days.map(d => [ymd(d), []]));
  _forecastByDay = byDay;
  if (targetUserId) {
    dashScopedDemands().forEach(d => {
      if (d.deletedAt) return;
      const fc = forecastArrivalFor(d, targetUserId);
      if (!fc) return;
      const bucket = byDay.get(fc.ymd);
      if (!bucket) return; // fora da janela de 14 dias úteis → não mostra
      bucket.push({ d, stageLabel: fc.stageLabel, remaining: fc.remaining });
    });
  }
  const total = [...byDay.values()].reduce((s, a) => s + a.length, 0);
  const tName = targetUserId ? (userById(targetUserId)?.name || '').split(' ')[0] : '';
  if (sub) sub.textContent = total
    ? `${total} demanda${total === 1 ? '' : 's'} prevista${total === 1 ? '' : 's'}${tName ? ' pra ' + esc(tName) : ''} nos próximos 14 dias úteis`
    : 'Nenhuma demanda prevista pra chegar nos próximos 14 dias úteis';

  const todayK = todayStr();
  el.innerHTML = days.map((dt) => {
    const k = ymd(dt);
    const n = byDay.get(k).length;
    const lvl = forecastLevel(n);
    const isToday = k === todayK;
    const wd = dt.toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', '').toUpperCase();
    return `<div class="dash-forecast-cell fc-${lvl} ${isToday ? 'is-today' : ''} ${n ? '' : 'is-empty'}"
                 ${n ? `onclick="openForecastDay('${k}')"` : ''}>
      <div class="dash-forecast-day">${isToday ? 'HOJE' : esc(wd)}</div>
      <div class="dash-forecast-date">${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}</div>
      <div class="dash-forecast-count">${n || ''}</div>
    </div>`;
  }).join('');
}
// Modal com a lista de demandas previstas pra um dia do quadro.
function openForecastDay(ymdStr) {
  const items = (_forecastByDay && _forecastByDay.get(ymdStr)) || [];
  if (!items.length) return;
  const dt = new Date(ymdStr + 'T12:00:00');
  const label = dt.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit' }).replace('-feira', '');
  const titleEl = $('forecast-modal-title');
  if (titleEl) titleEl.textContent = 'Demandas previstas — ' + label;
  const rows = items.slice()
    .sort((a, b) => (a.remaining - b.remaining) || norm(a.d.name).localeCompare(norm(b.d.name)))
    .map(it => {
      const d = it.d;
      const p = projectById(d.projectId);
      return `<tr onclick="closeModal('forecast-modal'); showDetail('${esc(d.id)}')">
        <td class="fc-td-name">${esc(d.name)}${p ? `<div class="fc-td-sub" style="font-size:11px;font-weight:400">${esc(p.name)}</div>` : ''}</td>
        <td>${esc(it.stageLabel)}</td>
        <td style="text-align:center">${it.remaining}</td>
        <td>${esc(forecastDeliverables(d))}</td>
      </tr>`;
    }).join('');
  const body = $('forecast-modal-body');
  if (body) body.innerHTML = `
    <table class="forecast-table">
      <thead><tr>
        <th>Demanda</th><th>Etapa atual</th>
        <th style="text-align:center">Etapas restantes</th><th>Entregáveis</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>`;
  openModal('forecast-modal');
}

// Filtro na tela de demandas por dia específico via deep-link ?due=YYYY-MM-DD.
// A URL fica compartilhável e sobrevive a refresh. Chip visível na barra de
// filtros permite remover o filtro sem editar a URL manualmente.
function goToDayInList(ymdStr) {
  // Preserva query params existentes; troca só o due.
  const url = '/demands?due=' + encodeURIComponent(ymdStr);
  history.pushState(null, '', url);
  goPage('list');
}
// Lê ?due da URL corrente. Retorna 'YYYY-MM-DD' ou null.
function currentDueFilter() {
  try {
    const u = new URL(location.href);
    const raw = u.searchParams.get('due');
    if (!raw) return null;
    // Valida formato pra não confiar cegamente na URL.
    if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) return null;
    return raw;
  } catch { return null; }
}
function clearDueFilter() {
  const u = new URL(location.href);
  u.searchParams.delete('due');
  history.replaceState(null, '', u.pathname + (u.search || '') + u.hash);
  renderList();
}
// Chip visível na barra de filtros da tela de demandas quando ?due tá ativo.
// Botão X remove o filtro e reseta a URL.
function renderDueFilterChip() {
  const wrap = $('due-filter-chip-wrap');
  if (!wrap) return;
  const due = currentDueFilter();
  if (!due) { wrap.style.display = 'none'; wrap.innerHTML = ''; return; }
  const label = new Date(due + 'T12:00:00').toLocaleDateString('pt-BR', {
    weekday: 'long', day: '2-digit', month: 'long', year: 'numeric'
  });
  wrap.style.display = '';
  wrap.innerHTML = `<div class="due-filter-chip">
    <i data-lucide="calendar" class="ic-sm"></i>
    <span>Prazo em <strong>${esc(label)}</strong></span>
    <button type="button" class="due-filter-chip-close" onclick="clearDueFilter()" title="Remover filtro">
      <i data-lucide="x" class="ic-xs"></i>
    </button>
  </div>`;
  paintIcons();
}

// ── Em atraso — top 5 mais atrasadas (sempre a partir de hoje, ignora filtros) ──
function renderDashOverdue(wsAll) {
  const el = $('dash-overdue');
  const sub = $('dash-overdue-sub');
  if (!el) return;
  const overdue = wsAll.filter(isLate);
  const today0 = new Date(); today0.setHours(0,0,0,0);
  const withDelay = overdue.map(d => {
    const due = effDue(d);
    const dueD = due ? new Date(due) : null;
    const daysLate = dueD ? Math.floor((today0 - dueD) / 86400000) : 0;
    return { d, daysLate };
  }).sort((a, b) => b.daysLate - a.daysLate);

  if (sub) sub.textContent = `${overdue.length} demanda${overdue.length === 1 ? '' : 's'} com prazo vencido`;

  if (!overdue.length) {
    el.innerHTML = `<div class="dash-empty-inline">
      <i data-lucide="check-circle-2" class="ic-sm"></i>
      Nada atrasado.
    </div>`;
    paintIcons();
    return;
  }

  el.innerHTML = withDelay.slice(0, 5).map(({ d, daysLate }) => {
    const proj = projectById(d.projectId);
    const client = proj?.client || (proj?.clientId ? clientById(proj.clientId)?.name : '') || '';
    const owner = effectiveOwnerOf(d);
    const ownerHtml = owner
      ? `<div class="dash-overdue-owner">${avatarHTML(owner, 'avatar avatar-xs')} <span class="dash-overdue-owner-name">${esc(owner.name)}</span></div>`
      : `<div class="dash-overdue-owner dash-overdue-owner--empty"><i data-lucide="user-x" class="ic-xs"></i> <span>Sem responsável</span></div>`;
    // Meta: "Cliente · Projeto". Se um lado faltar, mostra só o outro.
    const metaParts = [];
    if (client) metaParts.push(esc(client));
    if (proj?.name) metaParts.push(esc(proj.name));
    const metaText = metaParts.join(' · ');
    return `<div class="dash-overdue-row" onclick="showDetail('${esc(d.id)}')">
      <div class="dash-overdue-days">
        <strong>${daysLate}</strong>
        <span>dia${daysLate === 1 ? '' : 's'}</span>
      </div>
      <div class="dash-overdue-body">
        <div class="dash-overdue-name">${esc(d.name)}</div>
        ${metaText ? `<div class="dash-overdue-meta">${metaText}</div>` : ''}
      </div>
      ${ownerHtml}
    </div>`;
  }).join('');
  paintIcons();
}

// ── Radar de projetos ── grid de cards com semáforo.
// Sem filtro de cliente: todos os projetos ativos do workspace, mostra qual cliente.
// Com filtro de cliente: só os projetos daquele cliente, sem repetir a identificação.
function renderDashRadar() {
  const el = $('dash-radar');
  const sub = $('dash-radar-sub');
  if (!el) return;
  const clientFilter = $('dash-f-client')?.value || '';
  const wsProjs = dashScopedProjects().filter(p => p.active !== false);
  const shown = clientFilter
    ? wsProjs.filter(p => p.client === clientFilter)
    : wsProjs;
  const scopedDemands = dashScopedDemands();

  // Só interessa quem tem demanda atrasada — projetos "verdes" saem do radar.
  const withOverdue = shown.map(p => {
    const projDemands = scopedDemands.filter(d => d.projectId === p.id && !isDone(d));
    const overdue = projDemands.filter(isLate).length;
    return { p, projDemands, overdue };
  }).filter(x => x.overdue > 0);

  if (sub) {
    sub.textContent = clientFilter
      ? `${withOverdue.length} projeto${withOverdue.length === 1 ? '' : 's'} com atraso · ${clientFilter}`
      : `${withOverdue.length} projeto${withOverdue.length === 1 ? '' : 's'} com atraso`;
  }

  if (!withOverdue.length) {
    el.innerHTML = `<div class="dash-empty-inline">Nenhum projeto com atraso${clientFilter ? ` em ${esc(clientFilter)}` : ''}. 🎉</div>`;
    return;
  }

  // Semáforo: amarelo = até 20%, vermelho = >20% (verde não aparece — já filtrado acima).
  const cards = withOverdue.map(({ p, projDemands, overdue }) => {
    const total = projDemands.length;
    const ratio = total > 0 ? overdue / total : 0;
    const status = ratio > 0.2 ? 'critical' : 'warn';
    const label = `${overdue} atrasada${overdue === 1 ? '' : 's'}`;
    const clientLabel = clientFilter ? '' : `<div class="dash-radar-client">${esc(p.client || '—')}</div>`;
    return `<div class="dash-radar-card dash-radar-${status}"
                 onclick="openProjectDetail('${esc(p.id)}')"
                 title="${esc(p.name)} · ${label} · ${total} demanda${total === 1 ? '' : 's'} abertas">
      <div class="dash-radar-body">
        <div class="dash-radar-name">${esc(p.name)}</div>
        ${clientLabel}
        <div class="dash-radar-meta">${total} aberta${total === 1 ? '' : 's'} · ${label}</div>
      </div>
    </div>`;
  });

  el.innerHTML = cards.join('');
}

// ── Top responsáveis ── entregas do mês por conclusão de etapa.
//
// Regra: um usuário ganha 1 entrega quando conclui SUA etapa em uma demanda.
// "Concluir" = existe stage_changed no histórico com details.fromId = stage.id
// no mês corrente. Contabiliza APENAS a PRIMEIRA etapa (em ordem do fluxo) em
// que o usuário é responsável naquela demanda — se ele estiver em várias
// etapas da mesma demanda, só a primeira conta.
function renderDashTopOwners(list) {
  const el = $('dash-top-owners');
  if (!el) return;
  const ymNow = new Date().toISOString().slice(0,7);
  const byUser = new Map();

  list.forEach(d => {
    const flow = flowById(d.flowId);
    if (!flow) return;
    const stages = activeStagesOf(d, flow); // ordem customizada da instância
    const stageChangeEvents = (d.history || []).filter(h => h.action === 'stage_changed' && h.details && h.details.fromId);
    const seenUsers = new Set();

    for (const stage of stages) {
      const uid = resolveStageOwnerId(d, stage);
      if (!uid) continue;
      if (seenUsers.has(uid)) continue; // usuário já contabilizado nesta demanda
      seenUsers.add(uid); // marca como "primeira etapa" mesmo se ainda não concluiu

      // Etapa concluída? Procura o PRIMEIRO stage_changed cuja fromId é ela.
      const evt = stageChangeEvents.find(h => h.details.fromId === stage.id);
      if (!evt) continue; // não concluída ainda → sem crédito
      if ((evt.at || '').slice(0,7) !== ymNow) continue; // outro mês

      byUser.set(uid, (byUser.get(uid) || 0) + 1);
    }
  });

  const rows = [...byUser.entries()]
    .map(([uid, n]) => ({ u: userById(uid), n }))
    .filter(x => x.u)
    .sort((a, b) => b.n - a.n)
    .slice(0, 6);

  if (!rows.length) {
    el.innerHTML = emptyMini('Nenhuma entrega no mês.');
    return;
  }
  const max = Math.max(...rows.map(r => r.n));
  el.innerHTML = rows.map(r => {
    const pct = Math.round((r.n / max) * 100);
    return `<div class="dash-top-row">
      <div class="dash-top-user">${avatarHTML(r.u, 'avatar avatar-xs')} <span>${esc(r.u.name)}</span></div>
      <div class="dash-top-track"><div class="dash-top-fill" style="width:${pct}%"></div></div>
      <div class="dash-top-value">${r.n}</div>
    </div>`;
  }).join('');
}

/* Donut de distribuição das demandas EM ABERTO por prioridade (respeita filtros). */
function renderDashPriorityDonut(list) {
  const el = $('dash-prio-donut'); if (!el) return;
  const sub = $('dash-prio-sub');
  const open = list.filter(d => !isDone(d));
  const total = open.length;
  const segments = PRIORITIES.map(p => ({
    value: open.filter(d => (d.priority || 3) === p.value).length,
    color: p.color, label: p.label
  }));
  if (sub) sub.textContent = `${total} demanda${total === 1 ? '' : 's'} em aberto no filtro`;
  if (!total) { el.innerHTML = emptyMini('Nenhuma demanda em aberto.'); return; }
  const legend = segments.filter(s => s.value > 0).map(s => `
    <div class="donut-legend-row">
      <span class="donut-legend-dot" style="background:${s.color}"></span>
      <span class="donut-legend-label">${esc(s.label)}</span>
      <span class="donut-legend-value">${s.value}</span>
      <span class="donut-legend-pct">${Math.round(s.value / total * 100)}%</span>
    </div>`).join('');
  el.innerHTML = `<div class="donut-widget">
    <div class="donut-chart">${donutSVG(segments, { centerValue: total, centerSub: 'abertas' })}</div>
    <div class="donut-legend">${legend}</div>
  </div>`;
}

/* Anima cada .metric-value de 0 até o número final usando easing.
   Guarda o último valor renderizado em data-last-value para só animar
   quando muda (assim filtros que mantêm o número não re-disparam). */
function animateCounters(scope) {
  if (!scope) return;
  const reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const els = scope.querySelectorAll('.metric-value');
  els.forEach(el => {
    const raw = (el.textContent || '').trim();
    const target = parseInt(raw.replace(/[^\d-]/g, ''), 10);
    if (!Number.isFinite(target)) return;
    if (el.dataset.lastValue === String(target)) return;
    el.dataset.lastValue = String(target);
    if (target === 0 || reduced) { el.textContent = String(target); return; }
    const duration = 650;
    const start = performance.now();
    const ease = t => 1 - Math.pow(1 - t, 3);
    function tick(now) {
      const t = Math.min(1, (now - start) / duration);
      const v = Math.round(ease(t) * target);
      el.textContent = String(v);
      if (t < 1) requestAnimationFrame(tick);
      else el.textContent = String(target);
    }
    requestAnimationFrame(tick);
  });
}
/* Throughput chart — 12 semanas de entregas, dividido em no prazo × atrasadas.
   Reaproveita attachChartHover (o tooltip a ser preservado).
   Independente dos filtros de período (sempre 12 semanas), mas respeita
   filtros de cliente/usuário/tipo pela `list` recebida. */
function renderDashChart(list) {
  const chartEl = $('dash-chart');
  if (!chartEl) return;

  // Buckets semanais começando na segunda-feira. 12 semanas retroativas.
  const t = new Date(); t.setHours(0,0,0,0);
  const dayOfWeek = t.getDay(); // 0 = domingo
  const daysToMonday = (dayOfWeek + 6) % 7;
  const currentMonday = new Date(t); currentMonday.setDate(t.getDate() - daysToMonday);
  const weeks = 12;
  const buckets = [];
  for (let i = weeks - 1; i >= 0; i--) {
    const start = new Date(currentMonday); start.setDate(start.getDate() - i * 7);
    const end = new Date(start); end.setDate(end.getDate() + 6);
    buckets.push({
      date: start, // usado pra label X no SVG abaixo
      ymdStart: start.toISOString().slice(0,10),
      ymdEnd: end.toISOString().slice(0,10),
      onTime: 0, late: 0
    });
  }
  list.forEach(d => {
    if (!d.completedAt) return;
    const compYmd = d.completedAt.slice(0,10);
    const b = buckets.find(bk => compYmd >= bk.ymdStart && compYmd <= bk.ymdEnd);
    if (!b) return;
    if (wasLate(d)) b.late++;
    else b.onTime++;
  });

  const lines = [
    { key: 'onTime', label: 'No prazo',  color: '#10b981' },
    { key: 'late',   label: 'Atrasadas', color: '#ef4444' },
  ];
  const visible = lines;
  const days = weeks; // reuso do nome de variável pelo bloco SVG abaixo

  // SVG dimensions (proporção wide para preencher melhor cards largos)
  const w = 1600, h = 360, pad = { t: 20, r: 30, b: 42, l: 50 };
  const innerW = w - pad.l - pad.r, innerH = h - pad.t - pad.b;
  // Y max
  let yMax = 0;
  visible.forEach(l => { buckets.forEach(b => { if (b[l.key] > yMax) yMax = b[l.key]; }); });
  yMax = Math.max(4, Math.ceil(yMax * 1.15));
  // Gridlines em 5 níveis
  const gridSteps = 5;
  const gridLevels = [];
  for (let i = 0; i <= gridSteps; i++) gridLevels.push(Math.round(yMax * i / gridSteps));

  // X positions
  const xAt = i => pad.l + (days <= 1 ? 0 : i * innerW / (days - 1));
  const yAt = v => pad.t + innerH - (v / yMax) * innerH;

  // Linhas retas com quebras secas (sem suavização) — fidelidade exata aos dados
  const smoothPath = (pts) => {
    if (pts.length < 2) return '';
    return 'M ' + pts.map(p => `${p[0]} ${p[1]}`).join(' L ');
  };

  // Linhas + área (só se for uma linha visível, mostra área; com múltiplas fica poluído)
  const showArea = visible.length === 1;
  const pathParts = visible.map(l => {
    const pts = buckets.map((b, i) => [xAt(i), yAt(b[l.key])]);
    const path = smoothPath(pts);
    let area = '';
    if (showArea) {
      const areaPts = pts.slice();
      const last = areaPts[areaPts.length - 1], first = areaPts[0];
      const baseY = pad.t + innerH;
      area = `<path d="${smoothPath(areaPts)} L ${last[0]} ${baseY} L ${first[0]} ${baseY} Z" fill="${l.color}" fill-opacity="0.1"/>`;
    }
    const dots = pts.map(p => `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${l.color}" opacity="0.85"/>`).join('');
    return `${area}<path d="${path}" fill="none" stroke="${l.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${dots}`;
  }).join('');

  // X labels (mostra 6-8 marcadores)
  const maxLabels = 8;
  const labelStep = Math.max(1, Math.ceil(days / maxLabels));
  const xLabels = buckets.map((b, i) => {
    if (i % labelStep !== 0 && i !== days - 1) return '';
    const dd = String(b.date.getDate()).padStart(2, '0');
    const mm = String(b.date.getMonth() + 1).padStart(2, '0');
    return `<text x="${xAt(i)}" y="${h - 12}" fill="var(--text-muted)" font-size="11" text-anchor="middle">${dd}/${mm}</text>`;
  }).join('');

  // Y labels + gridlines
  const yEls = gridLevels.map(v => `
    <line x1="${pad.l}" x2="${w - pad.r}" y1="${yAt(v)}" y2="${yAt(v)}" stroke="var(--border)" stroke-width="1" stroke-dasharray="3 4" opacity="0.5"/>
    <text x="${pad.l - 10}" y="${yAt(v) + 4}" fill="var(--text-muted)" font-size="11" text-anchor="end">${v}</text>
  `).join('');

  // Marcadores e guide pra tooltip — invisíveis até o hover
  const markerEls = visible.map((l, i) =>
    `<circle id="dash-mk-${i}" r="5" fill="${l.color}" stroke="#fff" stroke-width="2" vector-effect="non-scaling-stroke" style="opacity:0;pointer-events:none"/>`
  ).join('');
  const guideEl = `<line id="dash-guide" class="chart-guide" x1="0" y1="${pad.t}" x2="0" y2="${pad.t + innerH}" stroke="rgba(255,255,255,0.35)" stroke-width="1" vector-effect="non-scaling-stroke" style="opacity:0;pointer-events:none"/>`;

  $('dash-chart').innerHTML = `
    <div class="chart-hover-host" id="dash-chart-host" style="position:relative">
      <svg viewBox="0 0 ${w} ${h}" class="dash-chart-svg" preserveAspectRatio="none">
        ${yEls}
        ${pathParts}
        ${xLabels}
        ${guideEl}
        ${markerEls}
      </svg>
      <div class="chart-tooltip" id="dash-chart-tooltip"></div>
    </div>`;

  // Wire hover — pra cada bucket, monta uma "série" com (y, value, color) por linha visível
  const tipPoints = buckets.map((b, i) => ({
    x: xAt(i),
    label: b.date.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' }),
    series: visible.map(l => ({ name: l.label, value: b[l.key], y: yAt(b[l.key]), color: l.color }))
  }));
  const host = $('dash-chart-host');
  if (host) {
    attachChartHover(host, {
      viewBox: { w, h, padL: pad.l, padR: pad.r, padT: pad.t, innerH },
      points: tipPoints,
      lineEls: $('dash-guide'),
      markerEls: visible.map((_, i) => $('dash-mk-' + i)),
      tooltipEl: $('dash-chart-tooltip'),
      format: (v) => String(v)
    });
  }
}

/* Quadro de apontamento de horas */
function renderHoursBoard(list) {
  const fu = $('dash-f-user').value;
  const hp = $('hours-f-period').value;
  // entradas de tempo das demandas filtradas; se houver filtro de usuário,
  // considera apenas as horas apontadas por ele
  const rows = [];
  list.forEach(d => (d.timeEntries || []).forEach(e => {
    if (fu && e.userId !== fu) return;
    if (hp && !matchPeriod(e.createdAt, hp)) return;
    rows.push({ demand: d, entry: e });
  }));
  const total = rows.reduce((acc, r) => acc + (Number(r.entry.hours) || 0), 0);

  // por etapa (label + cor resolvidos pelo fluxo da demanda)
  const byStage = new Map();
  rows.forEach(r => {
    const f = flowById(r.demand.flowId);
    const s = f ? f.stages.find(x => x.id === r.entry.stageId) : null;
    const key = s ? s.label : 'Outras';
    const cur = byStage.get(key) || { label: key, color: s ? s.color : '#64748B', hours: 0 };
    cur.hours += Number(r.entry.hours) || 0;
    byStage.set(key, cur);
  });
  const stages = [...byStage.values()].sort((a,b) => b.hours - a.hours);
  const maxStage = Math.max(1, ...stages.map(s => s.hours));

  // por demanda — quando há filtro de usuário, agrupa por demanda+usuário
  // para mostrar quem apontou. Caso contrário, agrupa só por demanda.
  const groupByUser = !!fu;
  const byDemand = new Map();
  rows.forEach(r => {
    const key = groupByUser ? `${r.demand.id}::${r.entry.userId || ''}` : r.demand.id;
    const cur = byDemand.get(key) || { d: r.demand, userId: r.entry.userId, hours: 0 };
    cur.hours += Number(r.entry.hours) || 0;
    byDemand.set(key, cur);
  });
  const dList = [...byDemand.values()].sort((a,b) => b.hours - a.hours);

  $('hours-board').innerHTML = `
    <div class="hours-card">
      <div class="hours-total"><span class="hours-total-value">${fmtHours(total)}</span><span class="hours-total-label">total apontado${fu ? ' por ' + esc(userById(fu)?.name || '') : ''} no filtro</span></div>
      ${stages.length ? stages.map(s => `
        <div class="hours-stage-row">
          <span class="hours-stage-name"><span class="pill-dot" style="background:${s.color}"></span>${esc(s.label)}</span>
          <span class="hours-stage-bar"><span class="hours-stage-fill" style="display:block;width:${s.hours/maxStage*100}%;background:${s.color}"></span></span>
          <span class="hours-stage-val">${fmtHours(s.hours)}</span>
        </div>`).join('') : '<div class="hours-empty">Nenhuma hora apontada nas demandas do filtro.</div>'}
    </div>
    <div class="hours-card">
      <div class="panel-title" style="margin-bottom:10px">Horas por demanda</div>
      ${dList.length ? dList.map(x => {
        const u = groupByUser ? userById(x.userId) : null;
        return `<div class="hours-demand-row">
          <span class="hours-demand-name" onclick="showDetail('${x.d.id}')">${esc(x.d.name)}</span>
          <span class="pill pill-muted" style="font-size:10px">${esc(projectById(x.d.projectId)?.name || '—')}</span>
          ${groupByUser ? `<span class="hours-demand-user">${u ? avatarHTML(u) + '<span>' + esc(u.name.split(' ')[0]) + '</span>' : '<span style="color:var(--text-muted)">—</span>'}</span>` : ''}
          <span class="hours-demand-val">${fmtHours(x.hours)}</span>
        </div>`;
      }).join('') : '<div class="hours-empty">Aponte horas dentro de uma demanda para vê-las aqui.</div>'}
    </div>`;
}

/* ─── DEMANDAS (LISTA GERAL) ─── */
function setListView(v) {
  listView = v;
  $('list-view-table').classList.toggle('active', v === 'table');
  $('list-view-kanban').classList.toggle('active', v === 'kanban');
  $('list-view-cal').classList.toggle('active', v === 'cal');
  $('list-table-view').style.display = v === 'table' ? '' : 'none';
  $('list-kanban-view').style.display = v === 'kanban' ? '' : 'none';
  $('list-cal-view').style.display = v === 'cal' ? '' : 'none';
  // Também marca o item do kebab menu como ativo (visual reflete escolha).
  ['table','kanban','cal'].forEach(k => {
    document.getElementById('list-view-item-' + k)?.classList.toggle('is-active', v === k);
  });
  if (v === 'cal') renderCalendar('all');
  if (v === 'kanban') renderKanban();
}
/* Kebab menu da barra de filtros — agrupa Lista/Kanban/Calendário + Export CSV. */
function toggleListViewMenu(ev) {
  ev?.stopPropagation();
  const menu = document.getElementById('list-view-menu');
  if (!menu) return;
  const willOpen = !menu.classList.contains('open');
  document.querySelectorAll('.list-view-menu.open').forEach(m => m.classList.remove('open'));
  if (willOpen) menu.classList.add('open');
}
function closeListViewMenu() {
  document.getElementById('list-view-menu')?.classList.remove('open');
}
document.addEventListener('click', ev => {
  const menu = document.getElementById('list-view-menu');
  if (!menu || !menu.classList.contains('open')) return;
  if (ev.target.closest('.list-view-menu-wrap')) return;
  menu.classList.remove('open');
}, true);

/* ─── EXPORT CSV ─── */
/* Escape RFC 4180: qualquer célula com `,`, `"` ou quebra de linha vira "…"
   com aspas internas duplicadas. Números/null viram string vazia se nulos. */
function csvCell(v) {
  if (v === null || v === undefined) return '';
  const s = String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function downloadCsv(headers, rows, filename) {
  // BOM UTF-8 pra Excel abrir com acentos certos. \r\n é padrão CSV.
  const bom = '﻿';
  const lines = [headers.map(csvCell).join(',')];
  for (const r of rows) lines.push(r.map(csvCell).join(','));
  const csv = bom + lines.join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 500);
}

/* Exporta as demandas atualmente filtradas na página /demands. Respeita
   busca, filtros e workspace ativo — o mesmo conjunto que aparece na tela. */
function exportDemandsCsv() {
  const list = listFilteredDemands();
  if (!list.length) { toast('Não há demandas pra exportar com os filtros atuais.', 'warn'); return; }
  const headers = [
    'ID', 'Nome', 'Squad', 'Cliente', 'Projeto', 'Fluxo', 'Etapa atual',
    'Responsável', 'Prioridade', 'Prazo etapa', 'Prazo final',
    'Horas estimadas', 'Horas apontadas', 'Peças', 'Artes', 'Variações',
    'Criada em', 'Concluída em', 'Status'
  ];
  const rows = list.map(d => {
    const p = projectById(d.projectId);
    const cl = p ? (clients.find(c => c.id === p.clientId)?.name || p.client || '') : '';
    const ws = wsById(d.workspaceId);
    const f = flowById(d.flowId);
    const st = stageOf(d);
    const owner = userById(d.ownerId);
    const totalHours = (d.timeEntries || []).reduce((s, e) => s + (Number(e.hours) || 0), 0);
    return [
      d.id, d.name, ws?.name || '', cl, p?.name || '', f?.name || '', st?.label || '',
      owner?.name || '', priorityLabel(d.priority) || '',
      d.stageDueDate || '', d.deadline || '',
      d.estimatedHours ?? '', totalHours.toFixed(2),
      d.qtyPieces ?? 0, d.qtyArts ?? 0, d.qtyVariations ?? 0,
      (d.createdAt || '').slice(0, 10),
      (d.completedAt || '').slice(0, 10),
      d.completedAt ? 'Concluída' : (st?.done ? 'Concluída' : 'Em andamento')
    ];
  });
  const ymd = new Date().toISOString().slice(0, 10);
  downloadCsv(headers, rows, `rework-demandas-${ymd}.csv`);
  toast(`${list.length} demanda${list.length === 1 ? '' : 's'} exportada${list.length === 1 ? '' : 's'}.`);
}

/* Exporta a visão atual de Capacidade (Equipe / Projeto / Cliente).
   Extrai as métricas direto do DOM renderizado (classes .capacity-row,
   .capacity-user-name, .capacity-stat) — garante que o CSV bate 1-pra-1
   com o que o usuário vê. Cada .capacity-stat gera 2 colunas (valor + label). */
function exportCapacityCsv() {
  const rowEls = document.querySelectorAll('#capacity-list .capacity-row');
  if (!rowEls.length) { toast('Não há dados de capacidade pra exportar.', 'warn'); return; }
  // Descobre quais métricas existem no primeiro row pra montar o header
  const firstStats = rowEls[0].querySelectorAll('.capacity-stat');
  const statLabels = [...firstStats].map(s => s.querySelector('.capacity-stat-label')?.textContent.trim() || 'métrica');
  const isTeam = capacityView === 'team';
  const nameCol = isTeam ? 'Usuário' : (capacityView === 'project' ? 'Projeto' : 'Cliente');
  const subCol = isTeam ? 'Área' : 'Detalhe';
  const headers = [nameCol, subCol, ...statLabels];
  if (isTeam) headers.push('Utilização');
  const rows = [];
  rowEls.forEach(row => {
    const name = row.querySelector('.capacity-user-name')?.textContent.trim() || '';
    const sub = row.querySelector('.capacity-user-role')?.textContent.trim() || '';
    const stats = [...row.querySelectorAll('.capacity-stat')].map(s => s.querySelector('.capacity-stat-value')?.textContent.trim() || '');
    const util = row.querySelector('.capacity-bar-label')?.childNodes[0]?.textContent.trim() || '';
    rows.push(isTeam ? [name, sub, ...stats, util] : [name, sub, ...stats]);
  });
  const ymd = new Date().toISOString().slice(0, 10);
  const label = { team: 'equipe', project: 'projetos', client: 'clientes' }[capacityView] || 'capacidade';
  downloadCsv(headers, rows, `rework-capacidade-${label}-${ymd}.csv`);
  toast(`${rows.length} linha${rows.length === 1 ? '' : 's'} exportada${rows.length === 1 ? '' : 's'}.`);
}

/* ─── Popover do filtro Período (pfp) ───
   Substitui o select + inputs de data. Presets no topo + calendário com range
   selecionável embaixo + rodapé (Limpar/Hoje). Estado persistido nos 3 hidden
   inputs (#filter-period, #filter-period-start, #filter-period-end) — bate com
   FILTER_KEYS['list'] e é consumido inalterado por listFilteredDemands. */
const PFP_PRESETS = [
  { val: '',          label: 'Todo o período' },
  { val: 'today',     label: 'Hoje' },
  { val: '7',         label: 'Próximos 7 dias' },
  { val: 'month',     label: 'Este mês' },
  { val: 'lastmonth', label: 'Mês passado' },
  { val: '90',        label: 'Últimos 90 dias' }
];
const PFP_MONTHS = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
let _pfpOpen = false;
let _pfpView = null; // { year, month } — mês visível no calendário

function togglePfp(evt) {
  if (evt) evt.stopPropagation();
  if (_pfpOpen) closePfp(); else openPfp();
}
function openPfp() {
  const pop = $('pfp-popover'); if (!pop) return;
  // Ponto de partida do mês visível: o start (se custom) ou hoje.
  const start = $('filter-period-start')?.value || '';
  const base = start ? new Date(start + 'T00:00:00') : new Date();
  _pfpView = { year: base.getFullYear(), month: base.getMonth() };
  pop.classList.add('open');
  _pfpOpen = true;
  pfpRenderPresets();
  pfpRenderCal();
  paintIcons();
}
function closePfp() {
  const pop = $('pfp-popover'); if (!pop) return;
  pop.classList.remove('open');
  _pfpOpen = false;
}
// Escuta cliques/Esc pra fechar. Cliques dentro do popover não fecham.
document.addEventListener('click', (e) => {
  if (!_pfpOpen) return;
  const pop = $('pfp-popover');
  const trg = $('pfp-trigger');
  if (pop && pop.contains(e.target)) return;
  if (trg && trg.contains(e.target)) return;
  closePfp();
});
document.addEventListener('keydown', (e) => {
  if (_pfpOpen && e.key === 'Escape') { e.preventDefault(); closePfp(); }
});

function pfpRenderPresets() {
  const wrap = $('pfp-presets'); if (!wrap) return;
  const cur = $('filter-period').value;
  wrap.innerHTML = PFP_PRESETS.map(p => `
    <button type="button" class="pfp-preset-btn ${p.val === cur && !pfpHasRange() ? 'active' : ''}" onclick="pfpPickPreset('${p.val}')">${esc(p.label)}</button>
  `).join('');
}
function pfpHasRange() {
  return !!($('filter-period-start')?.value || $('filter-period-end')?.value);
}
function pfpRenderCal() {
  const grid = $('pfp-cal-grid');
  const title = $('pfp-cal-title');
  if (!grid || !title || !_pfpView) return;
  const { year, month } = _pfpView;
  title.textContent = `${PFP_MONTHS[month]} · ${year}`;

  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrev  = new Date(year, month, 0).getDate();

  const startISO = $('filter-period-start').value || '';
  const endISO   = $('filter-period-end').value || '';
  const todayISO = todayStr();

  // Monta 42 células (6 semanas) — leadings do mês anterior + mês atual + trailings.
  const cells = [];
  for (let i = firstDow - 1; i >= 0; i--) {
    cells.push({ day: daysInPrev - i, month: month - 1, year: month === 0 ? year - 1 : year, other: true });
  }
  for (let d = 1; d <= daysInMonth; d++) cells.push({ day: d, month, year, other: false });
  while (cells.length < 42) {
    const last = cells[cells.length - 1];
    const nxt = new Date(last.year, last.month, last.day + 1);
    cells.push({ day: nxt.getDate(), month: nxt.getMonth(), year: nxt.getFullYear(), other: true });
  }

  grid.innerHTML = cells.map(c => {
    const iso = `${c.year}-${String(c.month + 1).padStart(2, '0')}-${String(c.day).padStart(2, '0')}`;
    const cls = ['pfp-day'];
    if (c.other) cls.push('other');
    if (iso === todayISO) cls.push('today');
    if (startISO && endISO) {
      if (iso === startISO && iso === endISO) cls.push('range-single');
      else if (iso === startISO) cls.push('range-start');
      else if (iso === endISO)   cls.push('range-end');
      else if (iso > startISO && iso < endISO) cls.push('range-mid');
    } else if (startISO && iso === startISO) {
      cls.push('range-single');
    }
    return `<button type="button" class="${cls.join(' ')}" data-iso="${iso}" onclick="pfpPickDay('${iso}')">${c.day}</button>`;
  }).join('');
}
function pfpNav(delta) {
  if (!_pfpView) return;
  _pfpView.month += delta;
  if (_pfpView.month < 0)  { _pfpView.month = 11; _pfpView.year--; }
  if (_pfpView.month > 11) { _pfpView.month = 0;  _pfpView.year++; }
  pfpRenderCal();
  paintIcons();
}
function pfpPickPreset(val) {
  // Preset limpa o range custom (mutuamente exclusivos).
  $('filter-period').value = val || '';
  $('filter-period-start').value = '';
  $('filter-period-end').value = '';
  closePfp();
  pfpUpdateTriggerLabel();
  renderList();
}
function pfpPickDay(iso) {
  const startEl = $('filter-period-start');
  const endEl = $('filter-period-end');
  const start = startEl.value, end = endEl.value;
  // Ciclo: (1) nada selecionado → define start; (2) só start → define end (ou reinicia
  // se o clique for antes do start); (3) range completo → reinicia com o novo start.
  let newStart, newEnd, done = false;
  if (!start || (start && end)) {
    newStart = iso; newEnd = '';
  } else if (iso < start) {
    newStart = iso; newEnd = '';
  } else {
    newStart = start; newEnd = iso; done = true;
  }
  startEl.value = newStart;
  endEl.value = newEnd;
  $('filter-period').value = 'custom';
  pfpRenderPresets();
  pfpRenderCal();
  pfpUpdateTriggerLabel();
  if (done) closePfp();
  renderList();
}
function pfpClear() {
  $('filter-period').value = '';
  $('filter-period-start').value = '';
  $('filter-period-end').value = '';
  pfpRenderPresets();
  pfpRenderCal();
  pfpUpdateTriggerLabel();
  renderList();
}
function pfpToday() {
  // Só volta o mês visível pra o atual — não altera filtro nem seleção.
  const t = new Date();
  _pfpView = { year: t.getFullYear(), month: t.getMonth() };
  pfpRenderCal();
  paintIcons();
}
function pfpUpdateTriggerLabel() {
  const trg = $('pfp-trigger'); if (!trg) return;
  const lbl = $('pfp-label');
  const p = $('filter-period').value;
  const s = $('filter-period-start').value;
  const e = $('filter-period-end').value;
  let text = 'Todo o período';
  const isFiltering = !!p;
  if (p === 'custom') {
    if (s && e) text = `${fmtPfpShort(s)} → ${fmtPfpShort(e)}`;
    else if (s)  text = `${fmtPfpShort(s)} → …`;
    else         text = 'Personalizado';
  } else if (p) {
    text = PFP_PRESETS.find(x => x.val === p)?.label || 'Período';
  }
  if (lbl) lbl.textContent = text;
  trg.classList.toggle('filtering', isFiltering);
}
function fmtPfpShort(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso || '');
  if (!m) return iso;
  const mo = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'][parseInt(m[2],10)-1];
  return `${parseInt(m[3], 10)} ${mo}`;
}
function pfpSyncFromInputs() {
  pfpUpdateTriggerLabel();
  if (_pfpOpen) { pfpRenderPresets(); pfpRenderCal(); }
}

/* ─── Picker de período da CAPACIDADE (Análise) ───
   Mesmo visual do filtro de Demandas (reaproveita o CSS .pfp-*), mas é uma
   instância ISOLADA (ids cap-pfp-*, inputs capacity-period*) pra não arriscar o
   filtro da Demandas. Presets voltados pra frente (capacidade é upcoming) +
   range custom no calendário. Estado nos 3 hidden inputs; consumido por
   renderCapacity() e persistido em FILTER_KEYS['capacity']. */
const CAP_PFP_PRESETS = [
  { val: '7',     label: 'Próximos 7 dias' },
  { val: '14',    label: 'Próximos 14 dias' },
  { val: '30',    label: 'Próximos 30 dias' },
  { val: 'month', label: 'Este mês' }
];
// Largura máxima de um range custom (dias corridos). O mapa de prazos tem uma
// coluna por dia — um range muito largo estoura o heatmap. Trava aqui.
const CAP_MAX_RANGE_DAYS = 45;
function capPfpAddDays(iso, n) {
  const d = new Date(iso + 'T00:00:00');
  d.setDate(d.getDate() + n);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
let _capPfpOpen = false;
let _capPfpView = null;
function capPfpToggle(evt) { if (evt) evt.stopPropagation(); if (_capPfpOpen) capPfpClose(); else capPfpOpen(); }
function capPfpOpen() {
  const pop = $('cap-pfp-popover'); if (!pop) return;
  const start = $('capacity-period-start')?.value || '';
  const base = start ? new Date(start + 'T00:00:00') : new Date();
  _capPfpView = { year: base.getFullYear(), month: base.getMonth() };
  pop.classList.add('open'); _capPfpOpen = true;
  capPfpRenderPresets(); capPfpRenderCal(); paintIcons();
}
function capPfpClose() { const pop = $('cap-pfp-popover'); if (pop) pop.classList.remove('open'); _capPfpOpen = false; }
document.addEventListener('click', (e) => {
  if (!_capPfpOpen) return;
  const pop = $('cap-pfp-popover'), trg = $('cap-pfp-trigger');
  if (pop && pop.contains(e.target)) return;
  if (trg && trg.contains(e.target)) return;
  capPfpClose();
});
document.addEventListener('keydown', (e) => { if (_capPfpOpen && e.key === 'Escape') { e.preventDefault(); capPfpClose(); } });
function capPfpHasRange() { return !!($('capacity-period-start')?.value || $('capacity-period-end')?.value); }
function capPfpRenderPresets() {
  const wrap = $('cap-pfp-presets'); if (!wrap) return;
  const cur = $('capacity-period').value;
  wrap.innerHTML = CAP_PFP_PRESETS.map(p =>
    `<button type="button" class="pfp-preset-btn ${p.val === cur && !capPfpHasRange() ? 'active' : ''}" onclick="capPfpPickPreset('${p.val}')">${esc(p.label)}</button>`
  ).join('');
}
function capPfpRenderCal() {
  const grid = $('cap-pfp-cal-grid'), title = $('cap-pfp-cal-title');
  if (!grid || !title || !_capPfpView) return;
  const { year, month } = _capPfpView;
  title.textContent = `${PFP_MONTHS[month]} · ${year}`;
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrev = new Date(year, month, 0).getDate();
  const startISO = $('capacity-period-start').value || '';
  const endISO = $('capacity-period-end').value || '';
  const todayISO = todayStr();
  // Escolhendo o FIM do range: desabilita dias além do limite de largura.
  const maxEndISO = (startISO && !endISO) ? capPfpAddDays(startISO, CAP_MAX_RANGE_DAYS - 1) : '';
  const cells = [];
  for (let i = firstDow - 1; i >= 0; i--) cells.push({ day: daysInPrev - i, month: month - 1, year: month === 0 ? year - 1 : year, other: true });
  for (let d = 1; d <= daysInMonth; d++) cells.push({ day: d, month, year, other: false });
  while (cells.length < 42) {
    const last = cells[cells.length - 1];
    const nxt = new Date(last.year, last.month, last.day + 1);
    cells.push({ day: nxt.getDate(), month: nxt.getMonth(), year: nxt.getFullYear(), other: true });
  }
  grid.innerHTML = cells.map(c => {
    const iso = `${c.year}-${String(c.month + 1).padStart(2, '0')}-${String(c.day).padStart(2, '0')}`;
    const cls = ['pfp-day'];
    if (c.other) cls.push('other');
    if (iso === todayISO) cls.push('today');
    if (startISO && endISO) {
      if (iso === startISO && iso === endISO) cls.push('range-single');
      else if (iso === startISO) cls.push('range-start');
      else if (iso === endISO) cls.push('range-end');
      else if (iso > startISO && iso < endISO) cls.push('range-mid');
    } else if (startISO && iso === startISO) cls.push('range-single');
    const disabled = maxEndISO && iso > maxEndISO;
    return `<button type="button" class="${cls.join(' ')}" data-iso="${iso}" ${disabled ? 'disabled' : ''} onclick="capPfpPickDay('${iso}')">${c.day}</button>`;
  }).join('');
}
function capPfpNav(delta) {
  if (!_capPfpView) return;
  _capPfpView.month += delta;
  if (_capPfpView.month < 0) { _capPfpView.month = 11; _capPfpView.year--; }
  if (_capPfpView.month > 11) { _capPfpView.month = 0; _capPfpView.year++; }
  capPfpRenderCal(); paintIcons();
}
function capPfpPickPreset(val) {
  $('capacity-period').value = val || '7';
  $('capacity-period-start').value = '';
  $('capacity-period-end').value = '';
  capPfpClose(); capPfpUpdateLabel(); renderCapacity();
}
function capPfpPickDay(iso) {
  const startEl = $('capacity-period-start'), endEl = $('capacity-period-end');
  const start = startEl.value, end = endEl.value;
  let newStart, newEnd, done = false;
  if (!start || (start && end)) { newStart = iso; newEnd = ''; }
  else if (iso < start) { newStart = iso; newEnd = ''; }
  else { newStart = start; newEnd = iso; done = true; }
  if (done) {
    const maxEnd = capPfpAddDays(newStart, CAP_MAX_RANGE_DAYS - 1);
    if (newEnd > maxEnd) newEnd = maxEnd; // trava a largura do range
  }
  startEl.value = newStart; endEl.value = newEnd;
  $('capacity-period').value = 'custom';
  capPfpRenderPresets(); capPfpRenderCal(); capPfpUpdateLabel();
  // Só re-renderiza quando o range fica completo (evita render com meia seleção).
  if (done) { capPfpClose(); renderCapacity(); }
}
function capPfpResetDefault() {
  $('capacity-period').value = '7';
  $('capacity-period-start').value = '';
  $('capacity-period-end').value = '';
  capPfpRenderPresets(); capPfpRenderCal(); capPfpUpdateLabel(); renderCapacity();
}
function capPfpToday() {
  const t = new Date();
  _capPfpView = { year: t.getFullYear(), month: t.getMonth() };
  capPfpRenderCal(); paintIcons();
}
function capPfpUpdateLabel() {
  const trg = $('cap-pfp-trigger'); if (!trg) return;
  const lbl = $('cap-pfp-label');
  const p = $('capacity-period').value, s = $('capacity-period-start').value, e = $('capacity-period-end').value;
  let text = 'Próximos 7 dias';
  if (p === 'custom') text = (s && e) ? `${fmtPfpShort(s)} → ${fmtPfpShort(e)}` : (s ? `${fmtPfpShort(s)} → …` : 'Personalizado');
  else if (p) text = CAP_PFP_PRESETS.find(x => x.val === p)?.label || 'Período';
  if (lbl) lbl.textContent = text;
  // "Filtrando" = qualquer coisa fora do padrão (Próximos 7 dias).
  trg.classList.toggle('filtering', p !== '7');
}
function capPfpSync() {
  capPfpUpdateLabel();
  if (_capPfpOpen) { capPfpRenderPresets(); capPfpRenderCal(); }
}

/* ─── Picker de data da AGENDA ───
   Popover clicando no label "10/08 → 21/08" (modo individual/semana) ou "seg 11/08"
   (modo time/dia) ou no label da agenda embed em Minhas Demandas. Reaproveita o
   visual dos pickers .pfp-* — sem presets, só o mini-calendário + botão "Hoje".
   Modo 'week' e 'mine-week' pulam pra semana que contém o dia clicado; modo 'day'
   define o agendaTeamDate. O popover é criado sob demanda e posicionado (fixed)
   embaixo do trigger clicado. */
let _agdpOpen = false;
let _agdpAnchor = null;    // 'week' | 'day' | 'mine-week'
let _agdpView = null;      // { year, month }

function agdpToggle(anchor, evt) {
  if (evt) evt.stopPropagation();
  if (_agdpOpen && _agdpAnchor === anchor) { agdpClose(); return; }
  agdpOpen(anchor);
}
function agdpOpen(anchor) {
  agdpClose();
  _agdpAnchor = anchor;
  let base;
  if (anchor === 'day')         base = new Date(agendaTeamDate || new Date());
  else if (anchor === 'mine-week') base = new Date();
  else                          base = new Date(agendaWeekStart || new Date());
  _agdpView = { year: base.getFullYear(), month: base.getMonth() };
  const pop = _agdpEnsurePopover();
  _agdpPosition(pop, anchor);
  pop.classList.add('open');
  _agdpOpen = true;
  const btn = document.getElementById(_agdpAnchorId(anchor));
  if (btn) btn.classList.add('is-open');
  agdpRender();
  paintIcons();
}
function agdpClose() {
  const pop = document.getElementById('agdp-popover');
  if (pop) pop.classList.remove('open');
  document.querySelectorAll('.agdp-trigger.is-open').forEach(b => b.classList.remove('is-open'));
  _agdpOpen = false;
  _agdpAnchor = null;
}
function _agdpAnchorId(anchor) {
  if (anchor === 'day') return 'agenda-day-label';
  if (anchor === 'mine-week') return 'mine-agenda-week-label';
  return 'agenda-week-label';
}
function _agdpEnsurePopover() {
  let pop = document.getElementById('agdp-popover');
  if (pop) return pop;
  pop = document.createElement('div');
  pop.id = 'agdp-popover';
  pop.className = 'agdp-popover pfp-popover';
  pop.addEventListener('click', (e) => e.stopPropagation());
  pop.innerHTML = `
    <div class="pfp-cal" style="border-top:0">
      <div class="pfp-cal-head">
        <button type="button" class="pfp-cal-nav" onclick="agdpNav(-1)" title="Mês anterior"><i data-lucide="chevron-left" class="ic-sm"></i></button>
        <span class="pfp-cal-title" id="agdp-cal-title"></span>
        <button type="button" class="pfp-cal-nav" onclick="agdpNav(1)" title="Próximo mês"><i data-lucide="chevron-right" class="ic-sm"></i></button>
      </div>
      <div class="pfp-cal-dow"><span>D</span><span>S</span><span>T</span><span>Q</span><span>Q</span><span>S</span><span>S</span></div>
      <div class="pfp-cal-grid" id="agdp-cal-grid"></div>
    </div>
    <div class="pfp-footer">
      <button type="button" class="pfp-footer-btn" onclick="agdpClose()">Fechar</button>
      <button type="button" class="pfp-footer-btn" onclick="agdpToday()">Hoje</button>
    </div>
  `;
  document.body.appendChild(pop);
  return pop;
}
function _agdpPosition(pop, anchor) {
  const btn = document.getElementById(_agdpAnchorId(anchor));
  if (!btn) return;
  const r = btn.getBoundingClientRect();
  const popW = pop.offsetWidth || 280;
  // Centraliza embaixo do trigger, mas trava dentro da viewport.
  let left = r.left + (r.width / 2) - (popW / 2);
  left = Math.max(8, Math.min(left, window.innerWidth - popW - 8));
  pop.style.top = (r.bottom + 6) + 'px';
  pop.style.left = left + 'px';
}
function agdpRender() {
  const title = document.getElementById('agdp-cal-title');
  const grid = document.getElementById('agdp-cal-grid');
  if (!title || !grid || !_agdpView) return;
  const { year, month } = _agdpView;
  title.textContent = `${PFP_MONTHS[month]} · ${year}`;

  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrev  = new Date(year, month, 0).getDate();

  // Destaque: dia selecionado (modo day) ou faixa da semana visualizada (modo week).
  let weekStartIso = '', weekEndIso = '', selectedIso = '';
  if (_agdpAnchor === 'day') {
    const d = agendaTeamDate || new Date();
    selectedIso = agendaYmd(d);
  } else {
    const ws = _agdpAnchor === 'mine-week' ? agendaWeekStartFor(new Date()) : (agendaWeekStart || agendaWeekStartFor(new Date()));
    const totalDays = 7 * (agendaWeeks || 2);
    const wsCopy = new Date(ws);
    const end = new Date(wsCopy);
    end.setDate(end.getDate() + totalDays - 1);
    weekStartIso = agendaYmd(wsCopy);
    weekEndIso = agendaYmd(end);
  }
  const todayISO = todayStr();
  const cells = [];
  for (let i = firstDow - 1; i >= 0; i--) {
    cells.push({ day: daysInPrev - i, month: month - 1, year: month === 0 ? year - 1 : year, other: true });
  }
  for (let d = 1; d <= daysInMonth; d++) cells.push({ day: d, month, year, other: false });
  while (cells.length < 42) {
    const last = cells[cells.length - 1];
    const nxt = new Date(last.year, last.month, last.day + 1);
    cells.push({ day: nxt.getDate(), month: nxt.getMonth(), year: nxt.getFullYear(), other: true });
  }
  grid.innerHTML = cells.map(c => {
    const iso = `${c.year}-${String(c.month + 1).padStart(2, '0')}-${String(c.day).padStart(2, '0')}`;
    const cls = ['pfp-day'];
    if (c.other) cls.push('other');
    if (iso === todayISO) cls.push('today');
    if (_agdpAnchor === 'day') {
      if (iso === selectedIso) cls.push('range-single');
    } else if (weekStartIso && weekEndIso && iso >= weekStartIso && iso <= weekEndIso) {
      if (iso === weekStartIso && iso === weekEndIso) cls.push('range-single');
      else if (iso === weekStartIso) cls.push('range-start');
      else if (iso === weekEndIso) cls.push('range-end');
      else cls.push('range-mid');
    }
    return `<button type="button" class="${cls.join(' ')}" data-iso="${iso}" onclick="agdpPickDay('${iso}')">${c.day}</button>`;
  }).join('');
}
function agdpNav(delta) {
  if (!_agdpView) return;
  _agdpView.month += delta;
  if (_agdpView.month < 0)  { _agdpView.month = 11; _agdpView.year--; }
  if (_agdpView.month > 11) { _agdpView.month = 0;  _agdpView.year++; }
  agdpRender();
  paintIcons();
}
function agdpToday() {
  const t = new Date();
  _agdpView = { year: t.getFullYear(), month: t.getMonth() };
  agdpRender();
  paintIcons();
}
function agdpPickDay(iso) {
  const d = new Date(iso + 'T00:00:00');
  if (_agdpAnchor === 'day') {
    agendaTeamDate = d;
  } else {
    // Individual / embed: pula pra semana que contém o dia clicado (âncora = segunda).
    agendaWeekStart = agendaWeekStartFor(d);
  }
  agdpClose();
  renderAgenda();
}
document.addEventListener('click', (e) => {
  if (!_agdpOpen) return;
  const pop = document.getElementById('agdp-popover');
  if (pop && pop.contains(e.target)) return;
  const anchors = ['agenda-week-label', 'agenda-day-label', 'mine-agenda-week-label']
    .map(id => document.getElementById(id));
  if (anchors.some(a => a && a.contains(e.target))) return;
  agdpClose();
});
document.addEventListener('keydown', (e) => {
  if (_agdpOpen && e.key === 'Escape') { e.preventDefault(); agdpClose(); }
});
window.addEventListener('resize', () => {
  if (!_agdpOpen) return;
  const pop = document.getElementById('agdp-popover');
  if (pop) _agdpPosition(pop, _agdpAnchor);
});
window.addEventListener('scroll', () => {
  if (!_agdpOpen) return;
  const pop = document.getElementById('agdp-popover');
  if (pop) _agdpPosition(pop, _agdpAnchor);
}, true);

/* Chip toggle "Status" (Abertas / Concluídas / Todas) da página Demandas.
   O <input type="hidden" id="filter-quick"> é a fonte de verdade — mantém
   compat com listFilteredDemands() e a persistência FILTER_KEYS['list']. */
function setDemandStatusFilter(v) {
  const inp = document.getElementById('filter-quick');
  if (!inp) return;
  inp.value = v || '';
  syncDemandStatusChip();
  renderList();
}
// Config de label + ícone + classe do ícone por status. Fonte de verdade única
// pra o trigger dropdown E pro item ativo no menu.
const DEMAND_STATUS_META = {
  '':     { label: 'Todas',      icon: 'layers',         cls: '' },
  'open': { label: 'Abertas',    icon: 'circle-dashed',  cls: 'status-ico-open' },
  'late': { label: 'Atrasadas',  icon: 'alert-triangle', cls: 'status-ico-late' },
  'done': { label: 'Concluídas', icon: 'check-circle-2', cls: 'status-ico-done' }
};
function syncDemandStatusChip() {
  const inp = document.getElementById('filter-quick');
  if (!inp) return;
  const v = inp.value || '';
  const meta = DEMAND_STATUS_META[v] || DEMAND_STATUS_META[''];
  // Atualiza trigger do dropdown (label + ícone + cor de fundo).
  const btn = document.getElementById('demand-status-drop-btn');
  const lbl = document.getElementById('demand-status-drop-lbl');
  const ico = document.getElementById('demand-status-drop-ico');
  if (lbl) lbl.textContent = meta.label;
  if (btn) {
    // Remove todas as variantes e aplica a atual — o CSS pinta o botão inteiro.
    btn.classList.remove('is-status-all', 'is-status-open', 'is-status-late', 'is-status-done');
    const cls = v === 'open' ? 'is-status-open' :
                v === 'late' ? 'is-status-late' :
                v === 'done' ? 'is-status-done' : 'is-status-all';
    btn.classList.add(cls);
  }
  if (ico) {
    // Força re-render do ícone (lucide observer pode não pegar mudança de data-lucide).
    const fresh = document.createElement('i');
    fresh.setAttribute('data-lucide', meta.icon);
    fresh.className = 'ic-md demand-status-drop-ico';
    fresh.id = 'demand-status-drop-ico';
    ico.replaceWith(fresh);
    if (typeof paintIcons === 'function') paintIcons();
  }
  // Marca o item ativo no menu.
  document.querySelectorAll('.demand-status-drop-item').forEach(b => {
    b.classList.toggle('is-active', (b.dataset.status || '') === v);
  });
}
function toggleDemandStatusDrop(ev) {
  ev?.stopPropagation();
  const menu = document.getElementById('demand-status-drop-menu');
  if (!menu) return;
  const willOpen = !menu.classList.contains('open');
  document.querySelectorAll('.demand-status-drop-menu.open').forEach(m => m.classList.remove('open'));
  if (willOpen) menu.classList.add('open');
}
function closeDemandStatusDrop() {
  document.getElementById('demand-status-drop-menu')?.classList.remove('open');
}
document.addEventListener('click', ev => {
  const menu = document.getElementById('demand-status-drop-menu');
  if (!menu || !menu.classList.contains('open')) return;
  if (ev.target.closest('.demand-status-drop-wrap')) return;
  menu.classList.remove('open');
}, true);

function listFilteredDemands() {
  const q  = norm($('search-input').value.trim());
  // Squad: CSV com IDs (multi-select). Vazio = todos os acessíveis. Compat: se
  // vier valor único legado (sem vírgula), trata como set de 1.
  const wsCsv = $('filter-workspace')?.value || '';
  const wsSet = new Set(wsCsv.split(',').filter(Boolean));
  const fu = $('filter-user').value;
  // Participante agora é multi (CSV). Match: qualquer user selecionado precisa
  // aparecer no set de participantes da demanda (OR entre eles).
  const partCsv = $('filter-participant')?.value || '';
  const partSet = new Set(partCsv.split(',').filter(Boolean));
  const fp = $('filter-project').value;
  const fc = $('filter-client')?.value || '';
  const fd = $('filter-period').value;
  const fdRange = fd === 'custom'
    ? { start: $('filter-period-start')?.value || '', end: $('filter-period-end')?.value || '' }
    : null;
  const fq = $('filter-quick').value;
  // Prioridade multi (CSV: "1,2,4"). Vazio = qualquer.
  const priCsv = $('filter-priority')?.value || '';
  const priSet = new Set(priCsv.split(',').filter(Boolean).map(x => Number(x)));
  const stuckDays = Number($('filter-stuck-days')?.value || 0);
  const noOwner = !!document.getElementById('filter-noowner')?.checked;
  const watched = !!document.getElementById('filter-watched')?.checked;
  const fCreator = $('filter-created-by')?.value || '';
  const fStageLabel = ($('filter-stage-label')?.value || '').trim();
  const fRec = $('filter-recurrence')?.value || '';
  const fAtt = $('filter-attachments')?.value || '';
  const fTime = $('filter-time-entries')?.value || '';
  const fDel = $('filter-pieces')?.value || '';
  const fCFrom = $('filter-created-from')?.value || '';
  const fCTo = $('filter-created-to')?.value || '';
  const fDFrom = $('filter-completed-from')?.value || '';
  const fDTo = $('filter-completed-to')?.value || '';
  const due = currentDueFilter(); // ?due=YYYY-MM-DD via URL (deep-link do dashboard)
  // Cross-workspace: todas as demandas acessíveis pro usuário logado, não deletadas.
  // filter-workspace agora é MULTI (CSV) — recorta pra 1+ workspaces específicos.
  return (demands || []).filter(d => {
    if (d.deletedAt) return false;
    if (!(me.isAdmin || (me.workspaces || []).includes(d.workspaceId))) return false;
    if (wsSet.size && !wsSet.has(d.workspaceId)) return false;
    if (q && !norm(d.name).includes(q)) return false;
    if (fu && d.ownerId !== fu) return false;
    if (partSet.size) {
      const ids = _demandParticipantIds(d);
      // AND: TODOS os users selecionados precisam participar da demanda pra passar.
      // (ex.: filtrar demandas em que Ana E João aparecem juntos)
      let all = true;
      for (const uid of partSet) if (!ids.has(uid)) { all = false; break; }
      if (!all) return false;
    }
    if (fp && d.projectId !== fp) return false;
    if (fc) {
      const proj = projectById(d.projectId);
      if (!proj || proj.clientId !== fc) return false;
    }
    if (!matchPeriod(effDue(d), fd, fdRange)) return false;
    if (due && effDue(d) !== due) return false;
    if (fq === 'late' && !isLate(d)) return false;
    if (fq === 'open' && isDone(d)) return false;
    if (fq === 'done' && !isDone(d)) return false;
    if (priSet.size && !priSet.has(Number(d.priority))) return false;
    if (noOwner && d.ownerId) return false;
    if (stuckDays > 0) {
      // Etapa parada = tempo desde stageEnteredAt (fallback pra createdAt se ausente).
      // Ignora demandas concluídas — não faz sentido "parada" pra fechadas.
      if (isDone(d)) return false;
      const anchor = d.stageEnteredAt || d.createdAt;
      if (!anchor) return false;
      const daysStuck = Math.floor((Date.now() - Date.parse(anchor)) / 86400000);
      if (daysStuck < stuckDays) return false;
    }
    if (fCreator) { if (_demandCreatorId(d) !== fCreator) return false; }
    if (fStageLabel) {
      const st = stageOf(d);
      const label = (d.stageLabels && d.stageLabels[d.status]) || st?.label || '';
      if (label !== fStageLabel) return false;
    }
    if (fRec === 'yes' && !(d.recurrence && d.recurrence.enabled)) return false;
    if (fRec === 'no' && (d.recurrence && d.recurrence.enabled)) return false;
    if (watched && !(Array.isArray(d.watchers) && d.watchers.includes(me?.id))) return false;
    if (fAtt === 'yes' && !(Array.isArray(d.attachments) && d.attachments.length)) return false;
    if (fAtt === 'no' && (Array.isArray(d.attachments) && d.attachments.length)) return false;
    if (fTime === 'yes' && !(Array.isArray(d.timeEntries) && d.timeEntries.length)) return false;
    if (fTime === 'no' && (Array.isArray(d.timeEntries) && d.timeEntries.length)) return false;
    if (fDel === 'yes' && !((d.qtyPieces || 0) + (d.qtyArts || 0) + (d.qtyVariations || 0) > 0)) return false;
    if (fDel === 'no' && ((d.qtyPieces || 0) + (d.qtyArts || 0) + (d.qtyVariations || 0) > 0)) return false;
    if (fCFrom || fCTo) {
      const ymd = (d.createdAt || '').slice(0, 10);
      if (fCFrom && ymd < fCFrom) return false;
      if (fCTo && ymd > fCTo) return false;
    }
    if (fDFrom || fDTo) {
      const ymd = (d.completedAt || '').slice(0, 10);
      if (!ymd) return false; // sem completedAt = não passa no filtro de conclusão
      if (fDFrom && ymd < fDFrom) return false;
      if (fDTo && ymd > fDTo) return false;
    }
    return true;
  });
}
/* Retorna o userId de quem CRIOU a demanda (via primeira entrada de history do tipo 'created').
   Retorna null se não encontrar. */
function _demandCreatorId(d) {
  const arr = Array.isArray(d.history) ? d.history : [];
  for (const h of arr) if (h && h.type === 'created') return h.userId || null;
  return null;
}
/* Popover de "Filtros avançados" — abre/fecha, limpa e mantém a badge com o
   número de filtros ativos. Reusa os selects existentes (mesmo IDs). */
function toggleAdvancedFilters(ev) {
  ev?.stopPropagation();
  const pop = document.getElementById('advanced-filters-pop');
  const btn = document.getElementById('advanced-filters-btn');
  if (!pop) return;
  const willOpen = !pop.classList.contains('open');
  pop.classList.toggle('open', willOpen);
  btn?.classList.toggle('is-open', willOpen);
}
function closeAdvancedFilters() {
  document.getElementById('advanced-filters-pop')?.classList.remove('open');
  document.getElementById('advanced-filters-btn')?.classList.remove('is-open');
}
// Filtros DENTRO do popover — mantém contador (badge) e reset centralizados.
const _AF_VALUE_IDS = [
  'filter-participant','filter-priority','filter-stuck-days',
  'filter-created-by','filter-stage-label','filter-recurrence',
  'filter-attachments','filter-time-entries','filter-pieces',
  'filter-created-from','filter-created-to','filter-completed-from','filter-completed-to'
];
const _AF_CHECKBOX_IDS = ['filter-noowner','filter-watched'];
function clearAdvancedFilters() {
  _AF_VALUE_IDS.forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  _AF_CHECKBOX_IDS.forEach(id => { const el = document.getElementById(id); if (el) el.checked = false; });
  _renderPriorityChips();
  renderList();
  _updateAdvancedFiltersBadge();
}
function _updateAdvancedFiltersBadge() {
  const badge = document.getElementById('advanced-filters-badge');
  if (!badge) return;
  let count = 0;
  _AF_VALUE_IDS.forEach(id => { if ((document.getElementById(id)?.value || '').trim()) count++; });
  _AF_CHECKBOX_IDS.forEach(id => { if (document.getElementById(id)?.checked) count++; });
  badge.textContent = String(count);
  badge.style.display = count > 0 ? '' : 'none';
}
/* Populador dos selects Criado por (userOpts) + Etapa atual (labels únicos entre fluxos). */
function _populateAdvancedSelectors(userOpts) {
  const creator = document.getElementById('filter-created-by');
  if (creator) {
    const prev = creator.value;
    const still = !prev || userOpts.some(u => u.id === prev);
    creator.innerHTML = '<option value="">Qualquer criador</option>' +
      userOpts.map(u => `<option value="${esc(u.id)}" ${still && u.id === prev ? 'selected' : ''}>${esc(u.name)}</option>`).join('');
    if (!still) creator.value = '';
  }
  const stageSel = document.getElementById('filter-stage-label');
  if (stageSel) {
    const prev = stageSel.value;
    // Union: label de todas as etapas de todos os fluxos acessíveis + additions das demandas visíveis.
    const set = new Set();
    (flows || []).forEach(f => {
      if (!(me.isAdmin || (me.workspaces || []).includes(f.workspaceId))) return;
      (f.stages || []).forEach(s => { if (s.label) set.add(s.label); });
    });
    (demands || []).forEach(d => {
      if (!(me.isAdmin || (me.workspaces || []).includes(d.workspaceId))) return;
      (d.stageAdditions || []).forEach(s => { if (s.label) set.add(s.label); });
    });
    const labels = [...set].sort((a, b) => norm(a).localeCompare(norm(b)));
    const still = !prev || labels.includes(prev);
    stageSel.innerHTML = '<option value="">Qualquer etapa</option>' +
      labels.map(l => `<option value="${esc(l)}" ${still && l === prev ? 'selected' : ''}>${esc(l)}</option>`).join('');
    if (!still) stageSel.value = '';
  }
}
/* Multi-select de Participantes — CSV no #filter-participant. Reusa o pattern
   do multi de Squads: popover com checkboxes + avatar do user. */
function _renderParticipantMultiMenu(userOpts) {
  const menu = document.getElementById('filter-participant-menu');
  const label = document.getElementById('filter-participant-label');
  const input = document.getElementById('filter-participant');
  if (!menu || !label || !input) return;
  const set = new Set((input.value || '').split(',').filter(Boolean));
  // Purga IDs órfãos (user removido do workspace, etc).
  const validIds = new Set(userOpts.map(u => u.id));
  [...set].forEach(id => { if (!validIds.has(id)) set.delete(id); });
  if ([...set].join(',') !== input.value) input.value = [...set].join(',');
  menu.innerHTML = userOpts.map(u => {
    const on = set.has(u.id);
    return `<label class="filter-multi-item">
      <input type="checkbox" ${on ? 'checked' : ''} onchange="toggleParticipantMultiItem('${esc(u.id)}', this.checked)">
      ${avatarHTML(u, 'avatar avatar-xs')}
      <span class="filter-multi-item-lbl">${esc(u.name)}</span>
    </label>`;
  }).join('') + (set.size ? `<button type="button" class="filter-multi-clear" onclick="clearParticipantMulti()">Limpar seleção</button>` : '');
  if (!set.size) label.textContent = 'Qualquer participante';
  else if (set.size === 1) {
    const u = userOpts.find(x => set.has(x.id));
    label.textContent = u ? u.name : '1 participante';
  } else label.textContent = set.size + ' participantes';
}
function toggleParticipantMulti(ev) {
  ev?.stopPropagation();
  const menu = document.getElementById('filter-participant-menu');
  if (!menu) return;
  const willOpen = !menu.classList.contains('open');
  document.querySelectorAll('.filter-multi-menu.open').forEach(m => m.classList.remove('open'));
  if (willOpen) menu.classList.add('open');
}
function toggleParticipantMultiItem(userId, on) {
  const input = document.getElementById('filter-participant');
  if (!input) return;
  const set = new Set((input.value || '').split(',').filter(Boolean));
  if (on) set.add(userId); else set.delete(userId);
  input.value = [...set].join(',');
  renderList();
  _updateAdvancedFiltersBadge();
}
function clearParticipantMulti() {
  const input = document.getElementById('filter-participant');
  if (input) input.value = '';
  renderList();
  _updateAdvancedFiltersBadge();
}
document.addEventListener('click', ev => {
  const menu = document.getElementById('filter-participant-menu');
  if (!menu || !menu.classList.contains('open')) return;
  if (ev.target.closest('#filter-participant-wrap')) return;
  menu.classList.remove('open');
}, true);
/* Chips multi-select de Prioridade. Estado no CSV do hidden #filter-priority. */
function _renderPriorityChips() {
  const host = document.getElementById('af-priority-chips'); if (!host) return;
  const input = document.getElementById('filter-priority'); if (!input) return;
  const active = new Set((input.value || '').split(',').filter(Boolean).map(x => Number(x)));
  host.innerHTML = (typeof PRIORITIES !== 'undefined' ? PRIORITIES : []).map(p => {
    const on = active.has(p.value);
    return `<button type="button" class="af-priority-chip${on ? ' is-active' : ''}" style="--pc:${p.color}"
              onclick="_togglePriorityChip(${p.value})">
      <span class="af-priority-dot" style="background:${p.color}"></span>${esc(p.label)}
    </button>`;
  }).join('');
}
function _togglePriorityChip(v) {
  const input = document.getElementById('filter-priority'); if (!input) return;
  const set = new Set((input.value || '').split(',').filter(Boolean).map(x => Number(x)));
  if (set.has(v)) set.delete(v); else set.add(v);
  input.value = [...set].join(',');
  _renderPriorityChips();
  renderList();
  _updateAdvancedFiltersBadge();
}
/* Multi-select de Squads — popover com checkboxes; estado no CSV do hidden #filter-workspace.
   Label do trigger reflete quantidade selecionada. */
function _renderWorkspaceMultiMenu(accessibleWs) {
  const menu = document.getElementById('filter-workspace-menu');
  const label = document.getElementById('filter-workspace-label');
  const input = document.getElementById('filter-workspace');
  if (!menu || !label || !input) return;
  const wsSet = new Set((input.value || '').split(',').filter(Boolean));
  // Só mantém IDs válidos (evita órfãos após um squad ser removido).
  const validIds = new Set(accessibleWs.map(w => w.id));
  [...wsSet].forEach(id => { if (!validIds.has(id)) wsSet.delete(id); });
  if ([...wsSet].join(',') !== input.value) input.value = [...wsSet].join(',');
  menu.innerHTML = accessibleWs.map(w => {
    const on = wsSet.has(w.id);
    return `<label class="filter-multi-item">
      <input type="checkbox" ${on ? 'checked' : ''} onchange="toggleWsMultiItem('${esc(w.id)}', this.checked)">
      <span class="filter-multi-item-dot" style="background:${esc(w.color || 'var(--accent)')}"></span>
      <span class="filter-multi-item-lbl">${esc(w.name)}</span>
    </label>`;
  }).join('') + (wsSet.size ? `<button type="button" class="filter-multi-clear" onclick="clearWsMulti()">Limpar seleção</button>` : '');
  // Label do trigger
  if (!wsSet.size) label.textContent = 'Squads';
  else if (wsSet.size === 1) {
    const w = accessibleWs.find(x => wsSet.has(x.id));
    label.textContent = w ? w.name : '1 squad';
  } else label.textContent = wsSet.size + ' squads';
}
function toggleWsMulti(ev) {
  ev?.stopPropagation();
  const menu = document.getElementById('filter-workspace-menu');
  if (!menu) return;
  const willOpen = !menu.classList.contains('open');
  document.querySelectorAll('.filter-multi-menu.open').forEach(m => m.classList.remove('open'));
  if (willOpen) menu.classList.add('open');
}
function toggleWsMultiItem(wsId, on) {
  const input = document.getElementById('filter-workspace');
  if (!input) return;
  const set = new Set((input.value || '').split(',').filter(Boolean));
  if (on) set.add(wsId); else set.delete(wsId);
  input.value = [...set].join(',');
  renderList();
}
function clearWsMulti() {
  const input = document.getElementById('filter-workspace');
  if (!input) return;
  input.value = '';
  renderList();
}
document.addEventListener('click', ev => {
  const menu = document.getElementById('filter-workspace-menu');
  if (!menu || !menu.classList.contains('open')) return;
  if (ev.target.closest('#filter-workspace-wrap')) return;
  menu.classList.remove('open');
}, true);
// Fecha o popover ao clicar fora.
document.addEventListener('click', ev => {
  const pop = document.getElementById('advanced-filters-pop');
  if (!pop || !pop.classList.contains('open')) return;
  if (ev.target.closest('.advanced-filters-wrap')) return;
  closeAdvancedFilters();
}, true);
/* Retorna o Set de userIds que "participam" da demanda: dono atual + responsável
   resolvido de CADA etapa do fluxo (incluindo additions, override por instância e
   roleAssignments do projeto/cliente). Usado no filtro "Participante" — mostra a
   demanda mesmo que ela ainda não tenha chegado na etapa daquele usuário. */
function _demandParticipantIds(d) {
  const set = new Set();
  if (d.ownerId) set.add(d.ownerId);
  const flow = flowById(d.flowId);
  if (flow && Array.isArray(flow.stages)) {
    flow.stages.forEach(s => {
      const uid = resolveStageOwnerId(d, s);
      if (uid) set.add(uid);
    });
  }
  (Array.isArray(d.stageAdditions) ? d.stageAdditions : []).forEach(s => {
    const uid = resolveStageOwnerId(d, s);
    if (uid) set.add(uid);
  });
  // Overrides por instância (stageResponsibles): já são cobertos por resolveStageOwnerId,
  // mas se algum id do map não bate com nenhuma stage (dead entry), inclui igual pra ser tolerante.
  Object.values(d.stageResponsibles || {}).forEach(uid => { if (uid) set.add(uid); });
  return set;
}

function renderList() {
  // Aplica filtros salvos da sessão anterior ANTES de capturar o valor atual
  // (o rebuild dos options abaixo respeita o value setado aqui via prevUser).
  const firstEnter = !_filtersRestored['list'];
  restoreFilters('list');
  // Ao ENTRAR na aba Demandas, o filtro de Squad vem travado no workspace
  // atual (activeWs) — apenas 1 squad selecionado por padrão.
  const wsInput = $('filter-workspace');
  if (firstEnter && activeWs && wsInput && !wsInput.value) wsInput.value = activeWs;
  // Populações cross-workspace — todas as opções acessíveis pro usuário.
  const accessibleWs = (workspaces || [])
    .filter(w => me.isAdmin || (me.workspaces || []).includes(w.id))
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  // Menu multi-select de squads (checkboxes) — estado no CSV do hidden #filter-workspace.
  _renderWorkspaceMultiMenu(accessibleWs);

  // CROSS-FILTER: se algum squad foi escolhido, os filtros de Usuário/Cliente/Projeto
  // só listam itens daqueles squads. Sem seleção, mostra tudo acessível.
  const wsCsv = wsInput?.value || '';
  const wsPickSet = new Set(wsCsv.split(',').filter(Boolean));
  const wsInScope = (wsId) => !wsPickSet.size || wsPickSet.has(wsId);

  // Usuários acessíveis. Cross-filter: user tem que estar no workspace escolhido
  // (ou ser admin — admin transita todos os workspaces).
  const prevUser = $('filter-user').value;
  const userOpts = (users || []).filter(u => u.active !== false &&
    (me.isAdmin || (u.workspaces || []).some(wid => (me.workspaces || []).includes(wid))) &&
    (!wsPickSet.size || u.isAdmin || (u.workspaces || []).some(w => wsPickSet.has(w))))
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  // Se o user escolhido não existe mais na lista filtrada, limpa o value.
  const userStillValid = !prevUser || userOpts.some(u => u.id === prevUser);
  const effectiveUser = userStillValid ? prevUser : '';
  $('filter-user').innerHTML = '<option value="">Usuário</option>' +
    userOpts.map(u => `<option value="${esc(u.id)}" ${u.id === effectiveUser ? 'selected' : ''}>${esc(u.name)}</option>`).join('');
  if (!userStillValid) $('filter-user').value = '';
  // Participante agora é multi via popover (renderizado abaixo por _renderParticipantMultiMenu).

  // Clientes acessíveis (ativos, com recorte de workspace). Populado ANTES dos
  // projetos porque o cliente escolhido recorta a lista de projetos (cross-filter).
  const accClients = (clients || [])
    .filter(c => c.active !== false && (me.isAdmin || (me.workspaces || []).includes(c.workspaceId)) && wsInScope(c.workspaceId))
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const prevClient = $('filter-client').value;
  const clientStillValid = !prevClient || accClients.some(c => c.id === prevClient);
  const effectiveClient = clientStillValid ? prevClient : '';
  fillSelect($('filter-client'), accClients.map(c => ({ value: c.id, label: c.name })), effectiveClient, 'Cliente');
  if (!clientStillValid) $('filter-client').value = '';

  // Projetos acessíveis (recorte de workspace + CROSS-FILTER pelo cliente escolhido:
  // com um cliente selecionado, só aparecem os projetos DELE).
  const accProjects = (projects || [])
    .filter(p => (me.isAdmin || (me.workspaces || []).includes(p.workspaceId)) && wsInScope(p.workspaceId)
      && (!effectiveClient || p.clientId === effectiveClient))
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const prevProj = $('filter-project').value;
  const projStillValid = !prevProj || accProjects.some(p => p.id === prevProj);
  fillSelect($('filter-project'), accProjects.map(p => ({ value: p.id, label: p.name })), projStillValid ? prevProj : '', 'Projeto');
  if (!projStillValid) $('filter-project').value = '';

  // Squad agora é multi-select custom (não é <select>) — a label do trigger é
  // atualizada por _renderWorkspaceMultiMenu. Não passa por applyFilterDropdown.
  applyFilterDropdown('filter-user', { userIcon: true });
  applyFilterDropdown('filter-client', { clientIcon: true });
  applyFilterDropdown('filter-project', { projectIcon: true });
  _renderParticipantMultiMenu(userOpts);
  _populateAdvancedSelectors(userOpts);
  _renderPriorityChips();
  _updateAdvancedFiltersBadge();
  // filter-period agora é hidden input controlado pelo popover pfp — sincroniza
  // label do trigger + estado visual do popover (caso esteja aberto).
  pfpSyncFromInputs();
  // filter-quick agora é um input hidden alimentado pelo chip toggle "Status".
  // Sincroniza o .active dos botões a partir do value (importante após restore).
  syncDemandStatusChip();
  renderDueFilterChip();

  const list = listFilteredDemands().slice().sort((a,b) => {
    let va, vb;
    if (sortKey === 'name')           { va = norm(a.name); vb = norm(b.name); }
    else if (sortKey === 'workspace') { va = norm(wsById(a.workspaceId)?.name || ''); vb = norm(wsById(b.workspaceId)?.name || ''); }
    else if (sortKey === 'project')   { va = norm(projectById(a.projectId)?.name || ''); vb = norm(projectById(b.projectId)?.name || ''); }
    else if (sortKey === 'client')    { va = norm(projectById(a.projectId)?.client || ''); vb = norm(projectById(b.projectId)?.client || ''); }
    else if (sortKey === 'type')      { va = norm(demandType(a) || ''); vb = norm(demandType(b) || ''); }
    else if (sortKey === 'status')    { const fa = flowById(a.flowId), fb = flowById(b.flowId); const ea = fa ? activeStagesOf(a, fa) : []; const eb = fb ? activeStagesOf(b, fb) : []; va = ea.findIndex(s => s.id === a.status); vb = eb.findIndex(s => s.id === b.status); if (va === -1) va = 999; if (vb === -1) vb = 999; }
    else if (sortKey === 'state')     {
      // Ordem: Ativa < Em atraso < Concluída (0/1/2)
      const stateVal = d => d.completedAt ? 2 : ((effDue(d) && effDue(d) < todayStr()) ? 1 : 0);
      va = stateVal(a); vb = stateVal(b);
    }
    else if (sortKey === 'owner')     { va = norm(userById(a.ownerId)?.name || ''); vb = norm(userById(b.ownerId)?.name || ''); }
    else if (sortKey === 'completed') { va = a.completedAt || '9999'; vb = b.completedAt || '9999'; }
    else if (sortKey === 'priority')  { va = a.priority || 3; vb = b.priority || 3; }
    else if (sortKey === 'qty')       { va = (a.qtyArts || 0); vb = (b.qtyArts || 0); }
    else                              { va = effDue(a) || '9999'; vb = effDue(b) || '9999'; }
    return (va < vb ? -1 : va > vb ? 1 : 0) * (sortAsc ? 1 : -1);
  });

  // Limpa seleções "fantasma" (IDs que não estão mais visíveis no filtro atual).
  // Sem isso o contador mostra "5 selecionadas" e as bulk actions agem em demandas
  // que o usuário não vê — confuso. Se alguém quiser reincluir, basta marcar de novo.
  if (selectedDemandIds && selectedDemandIds.size) {
    const visibleIds = new Set(list.map(d => d.id));
    for (const id of [...selectedDemandIds]) {
      if (!visibleIds.has(id)) selectedDemandIds.delete(id);
    }
  }

  if (!list.length) {
    $('list-table-body').innerHTML = `<tr><td colspan="9">${emptyState('Nenhuma demanda encontrada', 'Ajuste a busca ou os filtros para encontrar o que procura.', 'search')}</td></tr>`;
    if (listView === 'kanban') renderKanban();
    if (listView === 'cal') renderCalendar('all');
    refreshBulkBar();
    saveFilters('list');
    return;
  }
  $('list-table-body').innerHTML = list.map(d => {
    const p = projectById(d.projectId);
    const ws = wsById(d.workspaceId);
    const wsCell = ws
      ? `<span class="pill" style="color:${ws.color || '#7A00FF'};background:${hexDim(ws.color)}"><span class="pill-dot" style="background:${ws.color || '#7A00FF'}"></span>${esc(ws.name)}</span>`
      : '<span class="pill pill-muted">—</span>';
    const sel = selectedDemandIds.has(d.id);
    // Ordem: Demanda · Projeto · Cliente · Prioridade · Etapa · Responsável · Prazo · Conclusão
    return `<tr class="demand-row ${sel ? 'selected' : ''}" data-demand-id="${d.id}" onclick="onDemandRowClick(event, '${d.id}')">
      <td class="col-bulk-check"><input type="checkbox" class="bulk-check-row" ${sel ? 'checked' : ''} onclick="event.stopPropagation();toggleDemandSelection('${d.id}', this.checked)"></td>
      <td class="col-demand-name"><span class="demand-name">${esc(d.name)}</span></td>
      <td>${p ? esc(p.name) : '—'}</td>
      <td>${esc(p?.client || '—')}</td>
      <td>${priorityPill(d.priority)}</td>
      <td>${stagePillTruncated(d)}</td>
      <td>${cellUser(userById(d.ownerId))}</td>
      <td>${deadlineCell(d)}</td>
      <td>${d.completedAt ? fmtDate(d.completedAt) : '—'}</td>
    </tr>`;
  }).join('');
  paintIcons(); // ícones de urgência de prazo (alert-triangle / clock) nas linhas
  if (listView === 'kanban') renderKanban();
  if (listView === 'cal') renderCalendar('all');
  refreshBulkBar();
  saveFilters('list');
}
function sortList(key) {
  if (sortKey === key) sortAsc = !sortAsc; else { sortKey = key; sortAsc = true; }
  renderList();
}
// Versão debounced só pro campo de busca — evita rebuild da tabela em cada
// tecla. Cliques em selects e botões continuam usando renderList() direto.
// Exposta em window porque é chamada via oninput="…" inline no HTML, e const
// no top-level NÃO vira propriedade de window (diferente de function/var).
window.renderListDebounced = debounce(renderList, 120);

/* ─── KANBAN ─── */
/* Comparador estável para a ordem dentro de uma coluna. Demandas com
   kanbanOrder definido aparecem primeiro, ordenadas por esse valor crescente.
   As demais caem para o critério antigo (prioridade asc). */
function kanbanSort(a, b) {
  const ka = (a.kanbanOrder === null || a.kanbanOrder === undefined) ? null : Number(a.kanbanOrder);
  const kb = (b.kanbanOrder === null || b.kanbanOrder === undefined) ? null : Number(b.kanbanOrder);
  if (ka !== null && kb !== null) return ka - kb;
  if (ka !== null) return -1;
  if (kb !== null) return 1;
  return (a.priority || 3) - (b.priority || 3);
}
/* ── KANBAN: modo ──
   'attention' (padrão) = colunas por urgência de prazo, independentes de fluxo/etapa
   — resolve o problema de dezenas de colunas duplicadas quando há muitos fluxos.
   'stage' = board por etapa (mescla etapas homônimas entre fluxos). */
let kanbanMode = localStorage.getItem('kastor-kanban-mode') || 'attention';
const ATTENTION_BUCKETS = [
  { key: 'overdue', label: 'Atrasadas',       color: '#EF5050', hint: 'prazo vencido' },
  { key: 'today',   label: 'Vencem hoje',     color: '#FB7415', hint: 'prazo é hoje' },
  { key: 'week',    label: 'Próximos 7 dias', color: '#F5A718', hint: 'vencem na semana' },
  { key: 'later',   label: 'Mais pra frente', color: '#64748B', hint: 'prazo distante' },
  { key: 'nodue',   label: 'Sem prazo',       color: '#94A3B8', hint: 'sem deadline definido' },
];
function attentionBucketOf(d) {
  const due = effDue(d);
  if (!due) return 'nodue';
  const today = todayStr();
  if (due < today) return 'overdue';
  if (due === today) return 'today';
  const days = Math.round((Date.parse(due.slice(0, 10) + 'T00:00:00') - Date.parse(today + 'T00:00:00')) / 86400000);
  return days <= 7 ? 'week' : 'later';
}
function setKanbanMode(m) {
  kanbanMode = (m === 'stage') ? 'stage' : 'attention';
  localStorage.setItem('kastor-kanban-mode', kanbanMode);
  renderKanban();
}
function syncKanbanModeToggle() {
  document.querySelectorAll('.kanban-mode-toggle .client-status-btn[data-kmode]')
    .forEach(b => b.classList.toggle('active', b.dataset.kmode === kanbanMode));
  const hint = $('kanban-mode-hint');
  if (hint) hint.textContent = kanbanMode === 'attention'
    ? 'Cards organizados por urgência de prazo — não por etapa. Clique pra abrir e avançar.'
    : 'Colunas = etapas (mescladas entre fluxos). Melhor com um cliente/projeto no filtro.';
}
/* Board de atenção: colunas = buckets de urgência. Só demandas em aberto (o que
   precisa de ação). Ordena por prazo asc e prioridade. Sem drag — a posição vem
   do prazo; pra mudar, abre a demanda. */
function renderKanbanAttention(board) {
  const list = listFilteredDemands().filter(d => !isDone(d));
  const byBucket = new Map(ATTENTION_BUCKETS.map(b => [b.key, []]));
  for (const d of list) { const k = attentionBucketOf(d); if (byBucket.has(k)) byBucket.get(k).push(d); }
  const sortFn = (a, b) => {
    const da = effDue(a) || '9999-99-99', db = effDue(b) || '9999-99-99';
    if (da !== db) return da < db ? -1 : 1;
    return (a.priority || 3) - (b.priority || 3);
  };
  board.innerHTML = ATTENTION_BUCKETS.map(b => {
    const items = byBucket.get(b.key).sort(sortFn);
    return `<div class="kanban-column kanban-col--attention">
      <div class="kanban-column-head" style="border-top-color:${b.color}">
        <span class="pill-dot" style="background:${b.color}"></span>
        <span class="kanban-column-title">${esc(b.label)}</span>
        <span class="kanban-column-count">${items.length}</span>
      </div>
      <div class="kanban-column-body">
        ${items.length ? items.map(d => kanbanCard(d)).join('') : `<div class="kanban-column-empty">${b.key === 'overdue' ? 'Nada atrasado 🎉' : 'Vazio'}</div>`}
      </div>
    </div>`;
  }).join('');
  // Sem drag no modo atenção — a coluna é derivada do prazo.
  board.querySelectorAll('.kanban-card').forEach(c => c.setAttribute('draggable', 'false'));
  paintIcons();
}

/* ── Modo "Etapas" = bandas de progresso (name-independent) ──
   Mapeia CADA etapa por ESTRUTURA, não por nome: a flag `done` define "Concluído"
   e a POSIÇÃO relativa da etapa no fluxo define as 3 bandas ativas. Assim funciona
   pra qualquer nome de etapa, em qualquer fluxo, sem configuração nem adivinhação. */
const STAGE_BANDS = [
  { key: 'start', label: 'Início',       color: '#64748B' }, // slate
  { key: 'mid',   label: 'Em andamento', color: '#3B82F6' }, // azul
  { key: 'final', label: 'Reta final',   color: '#7A00FF' }, // roxo accent
  { key: 'done',  label: 'Concluído',    color: '#12B886' }, // verde
];
function stageBandOf(d) {
  const flow = flowById(d.flowId);
  if (!flow || !Array.isArray(flow.stages) || !flow.stages.length) return isDone(d) ? 'done' : 'mid';
  const cur = flow.stages.find(s => s.id === d.status);
  if (!cur) return isDone(d) ? 'done' : 'mid';
  if (cur.done) return 'done';
  // Entre as etapas ATIVAS (não-done), banda pela posição relativa: início / meio / fim.
  const active = flow.stages.filter(s => !s.done);
  const A = active.length;
  const j = active.findIndex(s => s.id === cur.id);
  if (A <= 1 || j < 0) return 'mid';
  const idx = Math.min(2, Math.floor((j / A) * 3)); // 0=start 1=mid 2=final
  return ['start', 'mid', 'final'][idx];
}
/* Board por bandas de progresso — sempre 4 colunas, independente do nº de fluxos.
   O card mostra a etapa real (subtítulo). Sem drag: a banda vem da posição da etapa;
   pra avançar de verdade, abre a demanda (mudança de etapa com toda a lógica). */
function renderKanbanBands(board) {
  const list = listFilteredDemands().slice().sort(kanbanSort);
  const byBand = new Map(STAGE_BANDS.map(b => [b.key, []]));
  for (const d of list) { const k = stageBandOf(d); if (byBand.has(k)) byBand.get(k).push(d); }
  board.innerHTML = STAGE_BANDS.map(b => {
    const items = byBand.get(b.key);
    return `<div class="kanban-column kanban-col--band">
      <div class="kanban-column-head" style="border-top-color:${b.color}">
        <span class="pill-dot" style="background:${b.color}"></span>
        <span class="kanban-column-title">${esc(b.label)}</span>
        <span class="kanban-column-count">${items.length}</span>
      </div>
      <div class="kanban-column-body">
        ${items.length ? items.map(d => kanbanCard(d)).join('') : '<div class="kanban-column-empty">Vazio</div>'}
      </div>
    </div>`;
  }).join('');
  board.querySelectorAll('.kanban-card').forEach(c => c.setAttribute('draggable', 'false'));
  paintIcons();
}

function renderKanban() {
  const board = $('kanban-board');
  if (!board) return;
  syncKanbanModeToggle();
  if (kanbanMode === 'attention') return renderKanbanAttention(board);
  return renderKanbanBands(board);
}

/* Conjunto ordenado de usuários envolvidos com uma demanda: owner primeiro,
   depois autores de comentário, autores no histórico e responsáveis por etapas
   definidos como override de instância. */
function demandCollaborators(d) {
  const seen = new Set();
  const out = [];
  const push = (uid) => {
    if (!uid || seen.has(uid)) return;
    const u = userById(uid);
    if (!u) return;
    seen.add(uid);
    out.push(u);
  };
  push(d.ownerId);
  (d.comments || []).forEach(c => push(c.userId));
  (d.history || []).forEach(h => push(h.userId));
  if (d.stageResponsibles && typeof d.stageResponsibles === 'object') {
    Object.values(d.stageResponsibles).forEach(push);
  }
  return out;
}

function kanbanCard(d) {
  const p = projectById(d.projectId);
  const owner = userById(d.ownerId);
  const due = effDue(d);
  const late = isLate(d);
  let ownerBlock;
  if (!owner) {
    ownerBlock = '<span class="kanban-card-owner-empty">Sem responsável</span>';
  } else {
    const collabs = demandCollaborators(d);
    const MAX = 3;
    const visible = collabs.slice(0, MAX);
    const more = collabs.length - visible.length;
    const tip = collabs.length > 1 ? collabs.map(u => u.name).join(', ') : owner.name;
    ownerBlock = `<div class="kanban-card-avatars" data-tooltip="${esc(tip)}">
      <span class="avatar-stack">
        ${visible.map((u, i) => `<span class="avatar-stack-item" style="z-index:${10 - i}">${avatarHTML(u, 'avatar avatar-stack-avatar')}</span>`).join('')}
        ${more > 0 ? `<span class="avatar-stack-more">+${more}</span>` : ''}
      </span>
      <span class="kanban-card-owner-name">${esc(owner.name.split(' ')[0])}</span>
    </div>`;
  }
  const dueBlock = due
    ? `<span class="kanban-card-due ${late ? 'late' : ''}"><i data-lucide="${late ? 'alert-triangle' : 'calendar'}" class="ic-xs"></i> ${esc(fmtDate(due))}</span>`
    : '';
  return `
    <div class="kanban-card" draggable="true" data-demand-id="${d.id}" onclick="showDetail('${d.id}')">
      <div class="kanban-card-top">${priorityPill(d.priority)}${statusPill(d)}${stageAgeChip(d)}</div>
      <div class="kanban-card-name">${esc(d.name)}</div>
      <div class="kanban-card-meta">${esc(p?.name || '—')}${p?.client ? ` · ${esc(p.client)}` : ''}</div>
      <div class="kanban-card-foot">
        ${ownerBlock}
        ${dueBlock}
      </div>
    </div>
  `;
}

/* ─── KANBAN: DRAG & DROP com reorder + placeholder ─── */
let _kanbanDndBound = false;
let _kbPlaceholder = null;
let _kbDraggingId = null;
function _kbEnsurePlaceholder() {
  if (_kbPlaceholder) return _kbPlaceholder;
  _kbPlaceholder = document.createElement('div');
  _kbPlaceholder.className = 'kanban-drop-placeholder';
  return _kbPlaceholder;
}
function _kbRemovePlaceholder() {
  if (_kbPlaceholder && _kbPlaceholder.parentElement) _kbPlaceholder.parentElement.removeChild(_kbPlaceholder);
}
/* Para um dado mouse Y dentro de uma coluna, retorna o card antes do qual
   o placeholder deve ser inserido (ou null se ele deve ir no final). */
function _kbCardAfter(body, y) {
  const cards = [...body.querySelectorAll('.kanban-card:not(.dragging)')];
  for (const c of cards) {
    const r = c.getBoundingClientRect();
    if (y < r.top + r.height / 2) return c;
  }
  return null;
}
function setupKanbanDragDrop() {
  if (_kanbanDndBound) return;
  const board = $('kanban-board');
  if (!board) return;
  _kanbanDndBound = true;

  // O click do showDetail é suprimido quando o mousedown vira drag (evita abrir o
  // modal logo após soltar o card).
  let suppressNextClick = false;

  board.addEventListener('dragstart', e => {
    const card = e.target.closest('.kanban-card');
    if (!card) return;
    e.dataTransfer.setData('text/plain', card.dataset.demandId);
    e.dataTransfer.effectAllowed = 'move';
    _kbDraggingId = card.dataset.demandId;
    // setTimeout pra Chrome aplicar a opacidade só depois do snapshot do drag image
    setTimeout(() => card.classList.add('dragging'), 0);
    suppressNextClick = true;
  });
  board.addEventListener('dragend', e => {
    const card = e.target.closest('.kanban-card');
    if (card) card.classList.remove('dragging');
    board.querySelectorAll('.kanban-column-body.drag-over').forEach(el => el.classList.remove('drag-over'));
    _kbRemovePlaceholder();
    _kbDraggingId = null;
    setTimeout(() => { suppressNextClick = false; }, 50);
  });
  board.addEventListener('dragover', e => {
    const body = e.target.closest('.kanban-column-body');
    if (!body) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    body.classList.add('drag-over');
    // Esconde o estado "vazio" enquanto arrasta sobre coluna sem cards
    const empty = body.querySelector('.kanban-column-empty');
    if (empty) empty.style.display = 'none';
    // Posiciona o placeholder antes do card mais próximo abaixo do cursor
    const placeholder = _kbEnsurePlaceholder();
    const ref = _kbCardAfter(body, e.clientY);
    if (ref) body.insertBefore(placeholder, ref);
    else body.appendChild(placeholder);
  });
  board.addEventListener('dragleave', e => {
    const body = e.target.closest('.kanban-column-body');
    if (!body) return;
    if (body.contains(e.relatedTarget)) return;
    body.classList.remove('drag-over');
    const empty = body.querySelector('.kanban-column-empty');
    if (empty) empty.style.display = '';
  });
  board.addEventListener('drop', e => {
    const body = e.target.closest('.kanban-column-body');
    if (!body) return;
    e.preventDefault();
    body.classList.remove('drag-over');
    const demandId = e.dataTransfer.getData('text/plain') || _kbDraggingId;
    const stageLabel = body.dataset.stageLabel;
    if (!demandId || !stageLabel) { _kbRemovePlaceholder(); return; }
    // Calcula índice alvo baseado na posição atual do placeholder.
    // Como o card sendo arrastado ainda está no DOM (com classe .dragging),
    // descontamos quantos cards dragging aparecem ANTES do placeholder
    // pra que o índice corresponda à lista SEM o source.
    let targetIndex = -1;
    const placeholder = _kbPlaceholder;
    if (placeholder && placeholder.parentElement === body) {
      const allChildren = [...body.children].filter(c => (c.classList && c.classList.contains('kanban-card')) || c === placeholder);
      const phIdx = allChildren.indexOf(placeholder);
      const draggingBefore = allChildren.slice(0, phIdx).filter(c => c.classList && c.classList.contains('dragging')).length;
      targetIndex = phIdx - draggingBefore;
    }
    _kbRemovePlaceholder();
    const card = document.querySelector(`.kanban-card[data-demand-id="${demandId}"]`);
    const sourceColBody = card ? card.closest('.kanban-column-body') : null;
    const sameColumn = sourceColBody === body;
    if (sameColumn) {
      handleKanbanReorder(demandId, body, targetIndex);
    } else {
      moveDemandToStage(demandId, stageLabel, targetIndex);
    }
  });
  // Suprime o click que viria após o drop
  board.addEventListener('click', e => {
    if (!suppressNextClick) return;
    const card = e.target.closest('.kanban-card');
    if (card) {
      e.stopPropagation();
      e.preventDefault();
    }
    suppressNextClick = false;
  }, true);
}

/* Helper: calcula um kanbanOrder novo entre dois vizinhos da coluna alvo.
   Usado tanto na reorder dentro da mesma coluna quanto no move cross-column
   com posição específica. Espaçamento padrão de 1000 reduz reescritas. */
function computeKanbanOrder(body, demandId, targetIndex) {
  const cards = [...body.querySelectorAll('.kanban-card')].filter(c => c.dataset.demandId !== demandId);
  if (targetIndex < 0) targetIndex = cards.length;
  if (targetIndex > cards.length) targetIndex = cards.length;
  const before = cards[targetIndex - 1];
  const after = cards[targetIndex];
  const beforeDemand = before ? demandById(before.dataset.demandId) : null;
  const afterDemand = after ? demandById(after.dataset.demandId) : null;
  const bo = beforeDemand && Number.isFinite(Number(beforeDemand.kanbanOrder)) ? Number(beforeDemand.kanbanOrder) : null;
  const ao = afterDemand && Number.isFinite(Number(afterDemand.kanbanOrder)) ? Number(afterDemand.kanbanOrder) : null;
  if (bo !== null && ao !== null) return (bo + ao) / 2;
  if (bo !== null) return bo + 1000;
  if (ao !== null) return ao - 1000;
  return Date.now(); // primeira reordenação na coluna
}

/* Reordena dentro da mesma coluna. OTIMISTA: aplica mudança local e
   re-renderiza ANTES da resposta da rede. Em erro, reverte. */
async function handleKanbanReorder(demandId, body, targetIndex) {
  const d = demandById(demandId);
  if (!d) return;
  const newOrder = computeKanbanOrder(body, demandId, targetIndex);
  const prevOrder = d.kanbanOrder ?? null;
  if (prevOrder === newOrder) return;
  d.kanbanOrder = newOrder;
  renderKanban();
  try {
    const upd = await api('/demands/' + demandId, 'PUT', { kanbanOrder: newOrder });
    patchDemand(upd); // server pode ter normalizado o valor
    // re-render apenas se algo realmente divergiu do otimismo
    if ((upd.kanbanOrder ?? null) !== newOrder) renderKanban();
  } catch (err) {
    // Rollback: restaura ordem antiga e re-renderiza
    d.kanbanOrder = prevOrder;
    renderKanban();
    toast(err.message || 'Erro ao reordenar', 'error');
  }
}

/* Move pra outra etapa. OTIMISTA: status + (opcional) kanbanOrder aplicados
   localmente antes do request; revertidos em caso de erro. */
async function moveDemandToStage(demandId, stageLabel, targetIndex) {
  const d = demandById(demandId);
  if (!d) return;
  const flow = flowById(d.flowId);
  if (!flow) { toast('Fluxo não encontrado para esta demanda', 'error'); return; }
  const target = flow.stages.find(s => s.label === stageLabel);
  if (!target) {
    toast(`A etapa "${stageLabel}" não existe no fluxo "${flow.name}". Mova a demanda dentro do mesmo fluxo.`, 'error');
    return;
  }
  if (target.id === d.status) return;

  // Calcula nova posição (kanbanOrder) se o usuário soltou em local específico.
  let newOrder = null;
  if (typeof targetIndex === 'number' && targetIndex >= 0) {
    const board = document.getElementById('kanban-board');
    const body = board && board.querySelector(`.kanban-column-body[data-stage-label="${CSS.escape(stageLabel)}"]`);
    if (body) newOrder = computeKanbanOrder(body, demandId, targetIndex);
  }

  // Snapshot pra rollback
  const prevStatus       = d.status;
  const prevKanbanOrder  = d.kanbanOrder ?? null;
  const prevStageEntered = d.stageEnteredAt;
  const prevCompletedAt  = d.completedAt;

  // Aplica otimisticamente
  d.status = target.id;
  if (newOrder !== null) d.kanbanOrder = newOrder;
  d.stageEnteredAt = nowIsoLocal();
  if (target.done && !d.completedAt) d.completedAt = d.stageEnteredAt;
  else if (!target.done) d.completedAt = null;

  renderKanban();
  // Animação imediata no card que acabou de cair
  requestAnimationFrame(() => {
    const card = document.querySelector(`.kanban-card[data-demand-id="${demandId}"]`);
    if (card) {
      card.classList.add('just-landed');
      setTimeout(() => card.classList.remove('just-landed'), 700);
      const col = card.closest('.kanban-column');
      if (col) {
        col.classList.add('flash-drop');
        setTimeout(() => col.classList.remove('flash-drop'), 700);
      }
    }
  });

  const payload = { status: target.id };
  if (newOrder !== null) payload.kanbanOrder = newOrder;
  try {
    const upd = await api('/demands/' + demandId, 'PUT', payload);
    patchDemand(upd);
    // Re-render só se server retornou estado diferente do otimismo (mudou owner por
    // auto-atribuição da etapa, completou em outra etapa, etc).
    const diverged = upd.status !== target.id
                  || (upd.kanbanOrder ?? null) !== (newOrder ?? prevKanbanOrder)
                  || upd.ownerId !== d.ownerId;
    if (diverged) renderKanban();
    toast(`Movido para "${target.label}"`, 'success');
  } catch (err) {
    // Rollback
    d.status         = prevStatus;
    d.kanbanOrder    = prevKanbanOrder;
    d.stageEnteredAt = prevStageEntered;
    d.completedAt    = prevCompletedAt;
    renderKanban();
    toast(err.message || 'Erro ao mover demanda', 'error');
  }
}

// Helper local — ISO da hora atual (mesma lógica do nowISO do server, lado cliente).
function nowIsoLocal() { return new Date().toISOString(); }

/* ─── MINHAS DEMANDAS ─── */
let mineSortKey = 'deadline', mineSortAsc = true;
let mineView = 'list'; // 'list' | 'cal' — persistido em localStorage
try { mineView = localStorage.getItem('kastor-mine-view') || 'list'; } catch {}

function setMineView(v) {
  if (v !== 'list' && v !== 'cal') v = 'list';
  mineView = v;
  try { localStorage.setItem('kastor-mine-view', v); } catch {}
  const listEl = $('mine-view-list');
  const calEl  = $('mine-view-cal');
  if (listEl) listEl.style.display = v === 'list' ? '' : 'none';
  if (calEl)  calEl.style.display  = v === 'cal'  ? '' : 'none';
  $('mine-view-list-btn')?.classList.toggle('active', v === 'list');
  $('mine-view-cal-btn')?.classList.toggle('active', v === 'cal');
  const title = $('mine-view-title');
  if (title) title.textContent = v === 'list' ? 'Minha Lista' : 'Meu Calendário';
  // Re-render pra garantir que a view alvo esteja fresca ao ser exibida.
  if (v === 'cal') renderCalendar('mine');
}
/* Escopo: TODAS as demandas atribuídas ao usuário logado, através de todos
   os workspaces a que ele tem acesso (não só o workspace ativo). Ignora
   soft-deleted. */
function myDemands() {
  return (demands || []).filter(d => {
    if (d.deletedAt) return false;
    if (d.ownerId !== me.id) return false;
    if (!(me.isAdmin || (me.workspaces || []).includes(d.workspaceId))) return false;
    return true;
  });
}
function renderMine() {
  // Aplica a view salva (list/cal) — importante pra 1ª pintura + após navegar.
  setMineView(mineView);
  const fq = $('mine-f-quick').value;
  applyFilterDropdown('mine-f-quick');
  const list = myDemands().filter(d => {
    if (fq === 'late') return isLate(d);
    if (fq === 'open') return !isDone(d);
    if (fq === 'done') return isDone(d);
    return true;
  }).sort((a,b) => {
    let va, vb;
    if (mineSortKey === 'name')            { va = norm(a.name); vb = norm(b.name); }
    else if (mineSortKey === 'workspace')  { va = norm(wsById(a.workspaceId)?.name || ''); vb = norm(wsById(b.workspaceId)?.name || ''); }
    else if (mineSortKey === 'client')     { va = norm(projectById(a.projectId)?.client || ''); vb = norm(projectById(b.projectId)?.client || ''); }
    else if (mineSortKey === 'project')    { va = norm(projectById(a.projectId)?.name || ''); vb = norm(projectById(b.projectId)?.name || ''); }
    else if (mineSortKey === 'status')     { const fa = flowById(a.flowId), fb = flowById(b.flowId); const ea = fa ? activeStagesOf(a, fa) : []; const eb = fb ? activeStagesOf(b, fb) : []; va = ea.findIndex(s => s.id === a.status); vb = eb.findIndex(s => s.id === b.status); if (va === -1) va = 999; if (vb === -1) vb = 999; }
    else                                   { va = effDue(a) || '9999'; vb = effDue(b) || '9999'; }
    return (va < vb ? -1 : va > vb ? 1 : 0) * (mineSortAsc ? 1 : -1);
  });

  $('mine-table-body').innerHTML = list.length ? list.map(d => {
    const p = projectById(d.projectId);
    const ws = wsById(d.workspaceId);
    // Pill de workspace com cor — mesmo padrão usado na tela de Workspaces.
    const wsCell = ws
      ? `<span class="pill" style="color:${ws.color || '#7A00FF'};background:${hexDim(ws.color)}"><span class="pill-dot" style="background:${ws.color || '#7A00FF'}"></span>${esc(ws.name)}</span>`
      : '<span class="pill pill-muted">—</span>';
    return `<tr class="demand-row" onclick="showDetail('${d.id}')">
      <td><span class="demand-name">${esc(d.name)}</span></td>
      <td>${wsCell}</td>
      <td>${esc(p?.client || '—')}</td>
      <td>${esc(p?.name || '—')}</td>
      <td>${statusPill(d)}</td>
      <td>${qtyCell(d)}</td>
      <td>${deadlineCell(d)}</td>
    </tr>`;
  }).join('')
    : `<tr><td colspan="7">${emptyState('Nenhuma demanda encontrada', 'Você não tem demandas neste filtro.', 'inbox')}</td></tr>`;
  paintIcons(); // ícones de urgência de prazo
  // Calendário e Agenda embed ficam sempre visíveis abaixo da tabela em
  // "Minhas Demandas". Re-render junto pra refletir mudanças imediato.
  if ($('cal-mine-body')) renderCalendar('mine');
  if (typeof renderAgenda === 'function') renderAgenda();
}
function sortMine(key) {
  if (mineSortKey === key) mineSortAsc = !mineSortAsc; else { mineSortKey = key; mineSortAsc = true; }
  renderMine();
}

/* ─── CALENDÁRIOS ─── */
function calNav(which, dir) {
  calState[which].setMonth(calState[which].getMonth() + dir);
  renderCalendar(which);
}
function calToday(which) { calState[which] = new Date(); renderCalendar(which); }


/* ─── CAPACIDADE DA EQUIPE ─── */
let capacityView = 'team'; // 'team' | 'project' | 'client'
function setCapacityView(v) {
  capacityView = v;
  renderCapacity();
}

/* ─── RELATÓRIOS / SLA ───
   Consome /api/reports/sla (tempo médio por etapa, lead time, pontualidade,
   retrabalho, mais lentas). O backend já calcula tudo a partir do stageHistory de
   cada demanda — aqui é só apresentação. Filtra por workspace ativo + período. */

// Humaniza horas em "Xd Yh" / "Yh" / "Zmin". Lead times chegam a centenas de horas,
// então 168h vira "7d"; abaixo de 1h mostra minutos.
function fmtDur(hours) {
  const h = Number(hours) || 0;
  if (h <= 0) return '—';
  if (h < 1) return Math.max(1, Math.round(h * 60)) + 'min';
  if (h < 24) { const v = Math.round(h * 10) / 10; return (Number.isInteger(v) ? v : v.toFixed(1).replace('.', ',')) + 'h'; }
  const days = Math.floor(h / 24);
  const rem = Math.round(h - days * 24);
  return rem ? `${days}d ${rem}h` : `${days}d`;
}

let _reportsReqSeq = 0; // descarta respostas obsoletas (troca rápida de período)

// Popula os selects Workspace/Cliente/Projeto em cascata (cada um recorta o
// seguinte), espelhando o cross-filter de Demandas. Na primeira entrada, trava o
// Workspace no atual (activeWs). Reaproveita o auto-cdrop (não precisa applyFilterDropdown).
function populateReportFilters(firstEnter) {
  const wsInp = $('reports-ws'), cSel = $('reports-client'), pSel = $('reports-project');
  if (!wsInp || !cSel || !pSel) return;

  const accessibleWs = (workspaces || []).filter(w => me.isAdmin || (me.workspaces || []).includes(w.id));
  // Primeira entrada sem seleção salva → default no workspace atual.
  if (firstEnter && !wsInp.value && activeWs) wsInp.value = activeWs;
  // Sanitiza o CSV do hidden input (ids que deixaram de existir/perder acesso caem fora).
  const wsSet = new Set((wsInp.value || '').split(',').filter(Boolean)
    .filter(id => accessibleWs.some(w => w.id === id)));
  wsInp.value = [...wsSet].join(',');
  renderReportSquadChips(accessibleWs, wsSet);
  const wsInScope = id => !wsSet.size || wsSet.has(id);

  const accClients = (clients || []).filter(c => c.active !== false
    && (me.isAdmin || (me.workspaces || []).includes(c.workspaceId)) && wsInScope(c.workspaceId));
  const cPrev = cSel.value;
  const cValid = !cPrev || accClients.some(c => c.id === cPrev);
  fillSelect(cSel, accClients.map(c => ({ value: c.id, label: c.name })), cValid ? cPrev : '', 'Todos os clientes');
  const clientPick = cSel.value;

  const accProjects = (projects || []).filter(p => (me.isAdmin || (me.workspaces || []).includes(p.workspaceId))
    && wsInScope(p.workspaceId) && (!clientPick || p.clientId === clientPick));
  const pPrev = pSel.value;
  const pValid = !pPrev || accProjects.some(p => p.id === pPrev);
  fillSelect(pSel, accProjects.map(p => ({ value: p.id, label: p.name })), pValid ? pPrev : '', 'Todos os projetos');
}

// Chips de squad (workspaces) — multi-select estilo Usuários. Estado vive no
// hidden #reports-ws como CSV (persistência via FILTER_KEYS continua igual).
function renderReportSquadChips(accessibleWs, wsSet) {
  const host = $('reports-squad-filter'); if (!host) return;
  const chips = accessibleWs.map(w => {
    const on = wsSet.has(w.id);
    return `<button type="button" class="uws-chip${on ? ' is-active' : ''}" onclick="toggleReportSquad('${esc(w.id)}')">
      <span class="uws-chip-dot" style="background:${esc(w.color || 'var(--accent)')}"></span>${esc(w.name)}
    </button>`;
  }).join('');
  const clear = wsSet.size ? `<button type="button" class="uws-clear" onclick="clearReportSquads()">Limpar</button>` : '';
  host.innerHTML = chips + clear;
}
function toggleReportSquad(id) {
  const inp = $('reports-ws'); if (!inp) return;
  const set = new Set((inp.value || '').split(',').filter(Boolean));
  if (set.has(id)) set.delete(id); else set.add(id);
  inp.value = [...set].join(',');
  renderReports();
}
function clearReportSquads() {
  const inp = $('reports-ws'); if (inp) inp.value = '';
  renderReports();
}

function clearReportFilters() {
  ['reports-ws', 'reports-client', 'reports-project'].forEach(id => { const el = $(id); if (el) el.value = ''; });
  const per = $('reports-period'); if (per) per.value = '90';
  renderReports();
}

async function renderReports() {
  const host = $('reports-body');
  if (!host) return;
  const firstEnter = !_filtersRestored['reports'];
  restoreFilters('reports');
  populateReportFilters(firstEnter);
  const period = ($('reports-period') && $('reports-period').value) || '90';
  const wsPick     = ($('reports-ws') && $('reports-ws').value) || '';
  const clientPick = ($('reports-client') && $('reports-client').value) || '';
  const projPick   = ($('reports-project') && $('reports-project').value) || '';
  saveFilters('reports');

  const seq = ++_reportsReqSeq;
  host.innerHTML = '<div class="rep-loading">Carregando métricas…</div>';

  let data;
  try {
    const qs = new URLSearchParams({ period });
    if (wsPick)     qs.set('workspaceId', wsPick);
    if (clientPick) qs.set('clientId', clientPick);
    if (projPick)   qs.set('projectId', projPick);
    data = await api('/reports/sla?' + qs.toString());
  } catch (err) {
    if (seq !== _reportsReqSeq || currentPage !== 'analytics' || _anTab !== 'reports') return;
    host.innerHTML = `<div class="rep-error">${esc(err.message || 'Erro ao carregar métricas.')}</div>`;
    return;
  }
  if (seq !== _reportsReqSeq || currentPage !== 'analytics' || _anTab !== 'reports') return; // resposta obsoleta — usuário já saiu/trocou

  host.innerHTML = buildReportsHTML(data);
  paintIcons();
}

function buildReportsHTML(data) {
  const t = data.totals || {};

  const kpis = kpiTiles([
    { label: 'Lead time médio', value: t.completedCount ? fmtDur(t.avgTotalHours) : '—',
      sub: 'criação → conclusão', tone: 'accent', icon: 'clock' },
    { label: 'Pontualidade', value: t.completedCount ? Math.round(t.punctualityRate) + '%' : '—',
      sub: 'concluídas no prazo',
      tone: (t.punctualityRate >= 80 ? 'success' : (t.punctualityRate >= 50 ? 'warn' : 'danger')), icon: 'check-circle' },
    { label: 'Retrabalho', value: t.demandsTotal ? Math.round(t.reworkRate) + '%' : '—',
      sub: `${t.reworkedCount || 0} voltaram de etapa`,
      tone: (t.reworkRate > 25 ? 'danger' : 'default'), icon: 'rotate-ccw' },
    { label: 'Concluídas', value: String(t.completedCount || 0),
      sub: `de ${t.demandsTotal || 0} no período`, tone: 'default', icon: 'check-check' },
  ]);

  // ── Tempo médio por etapa — já vem ordenado desc pelo server. Etapas com
  //    mesmo nome (mesmo em fluxos/clientes diferentes) vêm unificadas do server.
  const stages = (data.stageStats || []).filter(s => s.samples > 0);
  const maxStage = stages.length ? stages[0].avgHours : 0;
  const stageBars = stages.length ? stages.map((s) => {
    const pct = maxStage ? Math.max(3, (s.avgHours / maxStage) * 100) : 0;
    return `<div class="rep-bar-row">
      <div class="rep-bar-head">
        <span class="rep-bar-name">${esc(s.stageName)}</span>
        <span class="rep-bar-val">${fmtDur(s.avgHours)}</span>
      </div>
      <div class="rep-bar-track"><div class="rep-bar-fill" style="width:${pct}%;background:${s.stageColor || 'var(--accent)'}"></div></div>
      <div class="rep-bar-sub">${esc(s.flowName || '—')} · ${s.samples} ${s.samples === 1 ? 'passagem' : 'passagens'}</div>
    </div>`;
  }).join('') : emptyMini('Sem histórico de etapas no período.');

  // ── Demandas mais lentas (criação → conclusão) ──
  const slowest = data.slowest || [];
  const slowRows = slowest.length ? slowest.map(d => `
    <button type="button" class="rep-slow-row" onclick="showDetail('${esc(d.id)}')">
      <span class="rep-slow-name">${esc(d.name)}</span>
      <span class="rep-slow-proj">${esc(d.projectName || '—')}</span>
      <span class="rep-slow-dur">${fmtDur(d.hours)}</span>
    </button>`).join('') : emptyMini('Nenhuma demanda concluída no período.');

  // ── Tempo médio por tipo de demanda ──
  const types = data.typeStats || [];
  const maxType = types.length ? Math.max(...types.map(x => x.avgHours)) : 0;
  const typeRows = types.length ? types.map(x => {
    const pct = maxType ? Math.max(3, (x.avgHours / maxType) * 100) : 0;
    return `<div class="rep-bar-row">
      <div class="rep-bar-head">
        <span class="rep-bar-name">${esc(x.type)} <span class="rep-muted">· ${x.count}</span></span>
        <span class="rep-bar-val">${fmtDur(x.avgHours)}</span>
      </div>
      <div class="rep-bar-track"><div class="rep-bar-fill" style="width:${pct}%;background:var(--accent)"></div></div>
    </div>`;
  }).join('') : emptyMini('Nenhuma demanda concluída no período.');

  // ── Esforço apontado (horas lançadas pelos usuários) — distinto do calendário ──
  const effort = data.effort || {};
  const effStages = effort.byStage || [];
  const maxEffStage = effStages.length ? Math.max(...effStages.map(s => s.avgHours)) : 0;
  const effStageBars = effStages.length ? effStages.map(s => {
    const pct = maxEffStage ? Math.max(3, (s.avgHours / maxEffStage) * 100) : 0;
    return `<div class="rep-bar-row">
      <div class="rep-bar-head">
        <span class="rep-bar-name">${esc(s.stageName)}</span>
        <span class="rep-bar-val">${fmtHours(s.avgHours)}<span class="rep-muted"> · ${fmtHours(s.hours)} tot.</span></span>
      </div>
      <div class="rep-bar-track"><div class="rep-bar-fill" style="width:${pct}%;background:${s.stageColor || 'var(--accent)'}"></div></div>
      <div class="rep-bar-sub">${esc(s.flowName || '—')} · ${s.demands} ${s.demands === 1 ? 'demanda' : 'demandas'}</div>
    </div>`;
  }).join('') : emptyMini('Nenhuma hora apontada no período.');

  const effUsers = effort.byUser || [];
  const maxEffUser = effUsers.length ? Math.max(...effUsers.map(u => u.hours)) : 0;
  const effUserRows = effUsers.length ? effUsers.map(u => {
    const pct = maxEffUser ? Math.max(3, (u.hours / maxEffUser) * 100) : 0;
    return `<div class="rep-bar-row">
      <div class="rep-bar-head">
        <span class="rep-bar-name">${esc(u.name)}</span>
        <span class="rep-bar-val">${fmtHours(u.hours)}<span class="rep-muted"> · ${u.entries} ${u.entries === 1 ? 'lançamento' : 'lançamentos'}</span></span>
      </div>
      <div class="rep-bar-track"><div class="rep-bar-fill" style="width:${pct}%;background:var(--accent)"></div></div>
    </div>`;
  }).join('') : emptyMini('Nenhuma hora apontada no período.');

  const effHeader = effort.demandsWithLog ? `<div class="rep-effort-stats">
      <span><strong>${fmtHours(effort.totalHours)}</strong> apontadas</span>
      <span><strong>${effort.demandsWithLog}</strong> ${effort.demandsWithLog === 1 ? 'demanda' : 'demandas'}</span>
      <span>média <strong>${fmtHours(effort.avgPerDemand)}</strong>/demanda</span>
    </div>` : '';

  return `
    <div class="rep-kpis">${kpis}</div>
    <div class="rep-card">
      <div class="rep-card-title"><i data-lucide="bar-chart-3" class="ic-sm"></i> Tempo médio por etapa</div>
      <div class="rep-card-hint">Tempo de calendário (entrada → saída da etapa). Etapas com mesmo nome — em fluxos ou clientes diferentes — vêm agrupadas.</div>
      <div class="rep-bars">${stageBars}</div>
    </div>
    <div class="rep-card">
      <div class="rep-card-title"><i data-lucide="timer" class="ic-sm"></i> Horas apontadas por etapa</div>
      <div class="rep-card-hint">Esforço médio lançado pelos usuários em cada etapa — diferente do tempo de calendário acima.</div>
      ${effHeader}
      <div class="rep-bars">${effStageBars}</div>
    </div>
    <div class="rep-grid">
      <div class="rep-card">
        <div class="rep-card-title"><i data-lucide="users" class="ic-sm"></i> Horas apontadas por pessoa</div>
        <div class="rep-card-hint">Total de horas que cada usuário lançou no período.</div>
        <div class="rep-bars">${effUserRows}</div>
      </div>
      <div class="rep-card">
        <div class="rep-card-title"><i data-lucide="tag" class="ic-sm"></i> Tempo médio por tipo</div>
        <div class="rep-card-hint">Lead time médio por tipo de demanda.</div>
        <div class="rep-bars">${typeRows}</div>
      </div>
    </div>
    <div class="rep-card">
      <div class="rep-card-title"><i data-lucide="clock" class="ic-sm"></i> Demandas mais lentas</div>
      <div class="rep-card-hint">Da criação até a conclusão. Clique pra abrir.</div>
      <div class="rep-slow-list">${slowRows}</div>
    </div>`;
}

/* ─── PÁGINA ANÁLISES — abas Capacidade | Relatórios ───
   Une as duas telas num tab menu (estilo Listas de tarefas). Cada aba mantém sua
   própria render (renderCapacity / renderReports) e seus próprios filtros. */
let _anTab = localStorage.getItem('kastor-an-tab') || 'capacity';

function syncAnalyticsTab() {
  document.querySelectorAll('#page-analytics .an-tab')
    .forEach(t => t.classList.toggle('is-active', t.dataset.tab === _anTab));
  const cap = $('an-tab-capacity'), rep = $('an-tab-reports');
  if (cap) cap.style.display = _anTab === 'capacity' ? '' : 'none';
  if (rep) rep.style.display = _anTab === 'reports' ? '' : 'none';
}
function renderAnalyticsActive() {
  if (_anTab === 'reports') renderReports();
  else renderCapacity();
}
function setAnalyticsTab(tab) {
  if (tab !== 'capacity' && tab !== 'reports') tab = 'capacity';
  _anTab = tab;
  try { localStorage.setItem('kastor-an-tab', tab); } catch {}
  syncAnalyticsTab();
  navPush(tab === 'reports' ? '/analytics/reports' : '/analytics/capacity');
  renderAnalyticsActive();
}
function renderAnalytics() {
  syncAnalyticsTab();
  renderAnalyticsActive();
}

/* Resolve o período da Capacidade (preset ou range custom do cap-pfp) em duas
   janelas de Date: capacidade (frente, mapa de prazos) e apontamentos (trás).
   - Numérico (7/14/30): capacidade = próximos N dias, apontadas = últimos N dias.
   - Este mês: capacidade = mês inteiro, apontadas = início do mês até hoje.
   - Custom [s,e]: capacidade = [s,e]; apontadas = [s, min(e, hoje)] (não há horas
     apontadas no futuro, então o fim da janela de horas trava em hoje). */
function capResolveWindow() {
  const period = $('capacity-period').value || '7';
  const cs = $('capacity-period-start')?.value || '';
  const ce = $('capacity-period-end')?.value || '';
  const today = new Date(); today.setHours(0,0,0,0);
  let capStart, capEnd, logStart, logEnd;
  if (period === 'custom' && cs && ce) {
    capStart = new Date(cs + 'T00:00:00');
    capEnd   = new Date(ce + 'T00:00:00');
    // Trava a largura (defesa pra ranges persistidos/antigos que passem do limite).
    const maxEnd = new Date(capStart); maxEnd.setDate(maxEnd.getDate() + CAP_MAX_RANGE_DAYS - 1);
    if (capEnd > maxEnd) capEnd = maxEnd;
    logStart = new Date(capStart);
    logEnd   = new Date(Math.min(capEnd.getTime(), today.getTime()));
  } else if (period === 'month') {
    capStart = new Date(today.getFullYear(), today.getMonth(), 1);
    capEnd   = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    logStart = new Date(capStart);
    logEnd   = new Date(today);
  } else {
    const days = parseInt(period, 10) || 7;
    capStart = new Date(today);
    capEnd   = new Date(today); capEnd.setDate(capEnd.getDate() + days - 1);
    logEnd   = new Date(today);
    logStart = new Date(today); logStart.setDate(logStart.getDate() - (days - 1));
  }
  return { capStart, capEnd, logStart, logEnd };
}
/* ─── Filtro de squads da Capacidade (multi, estilo Usuários) ───
   Estado no hidden #capacity-squads (CSV) → persistido via FILTER_KEYS.
   Semântica: vazio = workspace ativo (comportamento clássico); com seleção,
   os dados (pessoas, demandas, horas, mapa) agregam os squads escolhidos. */
let capSquadFilter = new Set();
function capScopeWsIds() { return capSquadFilter.size ? [...capSquadFilter] : [activeWs]; }
function capScopeDemands() {
  const ids = new Set(capScopeWsIds());
  return demands.filter(d => ids.has(d.workspaceId));
}
function capScopeUsers() {
  const ids = capScopeWsIds();
  return users.filter(u => u.active !== false && (u.isAdmin || (u.workspaces || []).some(w => ids.includes(w))));
}
function capScopeProjects() {
  const ids = new Set(capScopeWsIds());
  return projects.filter(p => ids.has(p.workspaceId));
}
function renderCapSquadFilter() {
  const host = $('capacity-squad-filter'); if (!host) return;
  const accessibleWs = (workspaces || []).filter(w => me.isAdmin || (me.workspaces || []).includes(w.id));
  // Com 1 workspace só, o filtro não tem o que filtrar — esconde.
  if (accessibleWs.length <= 1) { host.innerHTML = ''; return; }
  const chips = accessibleWs.map(w => {
    const on = capSquadFilter.has(w.id);
    return `<button type="button" class="uws-chip${on ? ' is-active' : ''}" onclick="toggleCapSquad('${esc(w.id)}')">
      <span class="uws-chip-dot" style="background:${esc(w.color || 'var(--accent)')}"></span>${esc(w.name)}
    </button>`;
  }).join('');
  const clear = capSquadFilter.size ? `<button type="button" class="uws-clear" onclick="clearCapSquadFilter()">Limpar</button>` : '';
  const hint = capSquadFilter.size ? '' : `<span class="uws-hint">Vazio = workspace ativo</span>`;
  host.innerHTML = `<span class="uws-label">Squads</span>${chips}${clear}${hint}`;
}
function toggleCapSquad(id) {
  if (capSquadFilter.has(id)) capSquadFilter.delete(id); else capSquadFilter.add(id);
  const inp = $('capacity-squads'); if (inp) inp.value = [...capSquadFilter].join(',');
  renderCapacity();
}
function clearCapSquadFilter() {
  capSquadFilter.clear();
  const inp = $('capacity-squads'); if (inp) inp.value = '';
  renderCapacity();
}
function renderCapacity() {
  restoreFilters('capacity');
  capPfpSync();
  // Sincroniza o Set a partir do hidden persistido (sanitizando ids sem acesso).
  const rawSquads = ($('capacity-squads')?.value || '').split(',').filter(Boolean);
  capSquadFilter = new Set(rawSquads.filter(id =>
    (workspaces || []).some(w => w.id === id && (me.isAdmin || (me.workspaces || []).includes(w.id)))));
  renderCapSquadFilter();
  const { capStart, capEnd, logStart, logEnd } = capResolveWindow();
  const startYmd = capStart.toISOString().slice(0,10);
  const endYmd   = capEnd.toISOString().slice(0,10);
  const logStartYmd = logStart.toISOString().slice(0,10);
  const logEndYmd   = logEnd.toISOString().slice(0,10);

  // Conta dias úteis (seg–sex, exclui sáb 6 e dom 0) entre capStart e capEnd inclusive.
  // 5 dias úteis × 8h = 40h por semana cheia.
  const capPeriodDays = Math.round((capEnd - capStart) / 86400000) + 1;
  let businessDays = 0;
  for (let i = 0; i < capPeriodDays; i++) {
    const d = new Date(capStart); d.setDate(d.getDate() + i);
    const dow = d.getDay();
    if (dow !== 0 && dow !== 6) businessDays++;
  }
  const capacityHours = businessDays * 8;

  // Atualiza estado visual dos botões de view
  ['team', 'project', 'client'].forEach(v => {
    const btn = $('capacity-view-' + v);
    if (btn) btn.classList.toggle('active', capacityView === v);
  });

  // Esconde o cabeçalho ("Capacidade da Equipe") com base no modo
  const heading = $('capacity-heading');
  if (heading) heading.textContent = capacityView === 'team' ? 'Capacidade da Equipe' : (capacityView === 'project' ? 'Horas por Projeto' : 'Horas por Cliente');

  const hint = $('capacity-hint');
  if (hint) hint.textContent = capacityView === 'team'
    ? 'Distribuição de demandas em aberto por responsável. Carga estimada com base nas demandas atribuídas e nas horas já apontadas.'
    : (capacityView === 'project'
        ? 'Total de horas apontadas em cada projeto, somando os apontamentos de todos os usuários no período.'
        : 'Total de horas apontadas para cada cliente, somando todos os projetos do cliente no período.');

  saveFilters('capacity');
  if (capacityView === 'team') return renderCapacityTeam(startYmd, endYmd, businessDays, capacityHours, logStartYmd, logEndYmd);
  if (capacityView === 'project') return renderCapacityAggregate('project', startYmd, endYmd, businessDays, capacityHours);
  return renderCapacityAggregate('client', startYmd, endYmd, businessDays, capacityHours);
}

/* Heatmap pessoa × dia: nº de demandas em aberto com prazo em cada dia da janela.
   Mostra onde a pressão de prazo se concentra por pessoa. Usa ymd LOCAL pra bater
   com o formato de deadline ('YYYY-MM-DD') sem deslocar por fuso. */
// Toggle do mapa de prazos: 'prazos' (prazo efetivo por dia) | 'previstas'
// (quando a demanda deve CHEGAR na etapa da pessoa, via SLA das etapas).
let _capHeatMode = 'prazos';
function setCapHeatMode(m) {
  _capHeatMode = (m === 'previstas') ? 'previstas' : 'prazos';
  renderCapacity();
}
function capacityHeatmapHTML(rows, startYmd, endYmd) {
  const mode = _capHeatMode === 'previstas' ? 'previstas' : 'prazos';
  const ymdOf = (dt) => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
  const days = [];
  let cur = new Date(startYmd + 'T00:00:00');
  const end = new Date(endYmd + 'T00:00:00');
  let guard = 0;
  while (cur <= end && guard < 62) { days.push(new Date(cur)); cur.setDate(cur.getDate() + 1); guard++; }
  const todayYmd = todayStr();
  const WD = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S']; // dom..sáb
  // Cor da célula = nº de demandas NAQUELE dia (por pessoa). Faixas:
  // 0 sem cor · 1–3 verde · 4–6 amarelo · 7–10 laranja · >10 vermelho.
  const loadLevel = n => n === 0 ? 0 : n <= 3 ? 1 : n <= 6 ? 2 : n <= 10 ? 3 : 4;
  // Modo "previstas": agrega, numa passada, a chegada prevista por (usuário, dia)
  // de TODAS as demandas do workspace (não só as que a pessoa já é dona hoje).
  let arrivalsByUserDay = null;
  if (mode === 'previstas') {
    arrivalsByUserDay = new Map();
    const winStart = ymdOf(days[0]);
    const winEnd = ymdOf(days[days.length - 1]);
    capScopeDemands().forEach(d => {
      forecastArrivalsByUser(d).forEach((info, uid) => {
        if (info.ymd < winStart || info.ymd > winEnd) return;
        let m = arrivalsByUserDay.get(uid);
        if (!m) { m = new Map(); arrivalsByUserDay.set(uid, m); }
        m.set(info.ymd, (m.get(info.ymd) || 0) + 1);
      });
    });
  }
  const grid = rows.map(r => ({
    u: r.u,
    counts: days.map(day => {
      const dk = ymdOf(day);
      if (mode === 'previstas') return (arrivalsByUserDay.get(r.u.id) && arrivalsByUserDay.get(r.u.id).get(dk)) || 0;
      return r.userDemands.filter(dm => effDue(dm) === dk).length;
    })
  }));
  const total = grid.reduce((s, g) => s + g.counts.reduce((a, b) => a + b, 0), 0);
  const colHead = days.map(day => {
    const dow = day.getDay(), weekend = dow === 0 || dow === 6, isToday = ymdOf(day) === todayYmd;
    return `<div class="cap-heat-colhead ${weekend ? 'is-weekend' : ''} ${isToday ? 'is-today' : ''}">
      <span class="cap-heat-dow">${WD[dow]}</span><span class="cap-heat-dom">${day.getDate()}</span></div>`;
  }).join('');
  const body = grid.map(g => {
    const cells = g.counts.map((n, i) => {
      const day = days[i], dow = day.getDay(), weekend = dow === 0 || dow === 6, isToday = ymdOf(day) === todayYmd;
      const fill = n > 0 ? `load-${loadLevel(n)}` : '';
      return `<div class="cap-heat-cell ${fill} ${weekend ? 'is-weekend' : ''} ${isToday ? 'is-today' : ''}">${n || ''}</div>`;
    }).join('');
    return `
    <div class="cap-heat-row">
      <div class="cap-heat-user">${avatarHTML(g.u, 'avatar avatar-xs')}<span>${esc(g.u.name.split(' ')[0])}</span></div>
      <div class="cap-heat-cells">${cells}</div>
    </div>`;
  }).join('');
  const title = mode === 'previstas' ? 'Demandas previstas por pessoa' : 'Mapa de prazos por pessoa';
  // Em "previstas" a MESMA demanda pode cair em várias pessoas/dias — então
  // contamos chegadas previstas (ocorrências no mapa), não demandas distintas.
  const sub = mode === 'previstas'
    ? `${total} chegada${total === 1 ? '' : 's'} prevista${total === 1 ? '' : 's'} na janela`
    : `${total} demanda${total === 1 ? '' : 's'} com prazo na janela`;
  return `<div class="cap-heat">
    <div class="cap-heat-head-row">
      <div class="cap-heat-head-left">
        <div class="cap-heat-title">${title}</div>
        <div class="cap-heat-sub">${sub}</div>
      </div>
      <div class="cap-heat-toggle">
        <button type="button" class="cap-heat-toggle-btn ${mode === 'prazos' ? 'is-active' : ''}" onclick="setCapHeatMode('prazos')">Prazos</button>
        <button type="button" class="cap-heat-toggle-btn ${mode === 'previstas' ? 'is-active' : ''}" onclick="setCapHeatMode('previstas')">Previstas</button>
      </div>
    </div>
    <div class="cap-heat-grid">
      <div class="cap-heat-row cap-heat-headrow"><div class="cap-heat-user"></div><div class="cap-heat-cells">${colHead}</div></div>
      ${body}
    </div>
  </div>`;
}

function renderCapacityTeam(startYmd, endYmd, businessDays, capacityHours, logStartYmd, logEndYmd) {
  const wsdemands = capScopeDemands().filter(d => !isDone(d));
  const wsusers = capScopeUsers();

  // Horas apontadas: janela definida no renderCapacity (próximos/últimos N dias
  // pros períodos numéricos, ou início do mês até hoje quando "Este mês").
  const inLookback = (e) => {
    const when = ((e.start || e.createdAt || '') + '').slice(0,10);
    return when >= logStartYmd && when <= logEndYmd;
  };
  // Janela de "entregas": considera a demanda no período se:
  //   - foi CONCLUÍDA dentro da janela (completedAt no período)
  //   - OU está EM ABERTO e atribuída ao usuário (em produção agora)
  // Isso evita que o "0 0 0" apareça enquanto a demanda ainda está em execução.
  const deliveredInWindow = (d) => {
    if (d.completedAt) {
      const day = String(d.completedAt).slice(0, 10);
      return day >= logStartYmd && day <= logEndYmd;
    }
    return !isDone(d); // em aberto = conta como volume previsto
  };

  const rows = wsusers.map(u => {
    const userDemands = wsdemands.filter(d => d.ownerId === u.id);
    const inPeriod = userDemands.filter(d => {
      const due = effDue(d);
      return due && due >= startYmd && due <= endYmd;
    });
    const lateCount = userDemands.filter(d => isLate(d)).length;
    // Horas apontadas pelo usuário NOS ÚLTIMOS N dias (independente da demanda estar em aberto ou não)
    const hoursLogged = capScopeDemands().reduce((s, d) => {
      return s + (d.timeEntries || [])
        .filter(e => e.userId === u.id && inLookback(e))
        .reduce((a, e) => a + (Number(e.hours) || 0), 0);
    }, 0);
    // Entregáveis: soma das 3 contagens em demandas DESTE usuário (concluídas no período OU ativas).
    // Usa deliverableUserId (quem executou as artes) como prioridade; se vazio, cai pro ownerId atual.
    const deliveredDemands = capScopeDemands().filter(d => (d.deliverableUserId || d.ownerId) === u.id && deliveredInWindow(d));
    const totalPieces     = deliveredDemands.reduce((s, d) => s + (Number(d.qtyPieces) || 0), 0);
    const totalArts       = deliveredDemands.reduce((s, d) => s + (Number(d.qtyArts) || 0), 0);
    const totalVariations = deliveredDemands.reduce((s, d) => s + (Number(d.qtyVariations) || 0), 0);
    const estimatedLoad = userDemands.reduce((s, d) => s + (Number(d.estimatedHours) > 0 ? Number(d.estimatedHours) : 4), 0);
    // Preenchimento da barra: horas apontadas no período / capacidade do período
    const pct = capacityHours > 0 ? Math.min(150, Math.round(hoursLogged / capacityHours * 100)) : 0;
    const status = pct >= 100 ? 'overload' : pct >= 75 ? 'high' : pct >= 40 ? 'medium' : 'low';
    return { u, userDemands, inPeriod, lateCount, hoursLogged, totalPieces, totalArts, totalVariations, estimatedLoad, pct, status };
  }).sort((a, b) => {
    // 1º critério: horas apontadas (decrescente) — quem mais trabalhou no topo
    if (b.hoursLogged !== a.hoursLogged) return b.hoursLogged - a.hoursLogged;
    // 2º critério: nome do usuário em ordem alfabética (A-Z)
    return norm(a.u.name).localeCompare(norm(b.u.name));
  });

  // Totais do workspace (somatório de todas as rows) — visão global de produção
  const wsTotal = rows.reduce((acc, r) => ({
    pieces: acc.pieces + r.totalPieces,
    arts: acc.arts + r.totalArts,
    variations: acc.variations + r.totalVariations,
    hours: acc.hours + r.hoursLogged
  }), { pieces: 0, arts: 0, variations: 0, hours: 0 });

  $('capacity-list').innerHTML = `
    <div class="capacity-summary">
      <div class="capacity-summary-item"><div class="capacity-summary-label">Capacidade no período</div><div class="capacity-summary-value">${capacityHours}h</div><div class="capacity-summary-sub">${businessDays} dias úteis × 8h</div></div>
      <div class="capacity-summary-item"><div class="capacity-summary-label">Demandas em aberto</div><div class="capacity-summary-value">${wsdemands.length}</div><div class="capacity-summary-sub">${capSquadFilter.size ? `em ${capSquadFilter.size} squad${capSquadFilter.size === 1 ? '' : 's'}` : `no workspace ${esc(wsById(activeWs)?.name || '')}`}</div></div>
      <div class="capacity-summary-item"><div class="capacity-summary-label">Pessoas ativas</div><div class="capacity-summary-value">${wsusers.length}</div><div class="capacity-summary-sub">com acesso ao squad</div></div>
    </div>
    <!-- Banner de produção total — soma de todas as pessoas no período -->
    <div class="capacity-prod-banner">
      <div class="capacity-prod-title">Produção do squad no período</div>
      <div class="capacity-prod-stats">
        <div class="capacity-prod-stat"><span class="capacity-prod-value">${fmtHours(wsTotal.hours)}</span><span class="capacity-prod-label">horas apontadas</span></div>
        <div class="capacity-prod-divider"></div>
        <div class="capacity-prod-stat"><span class="capacity-prod-value">${wsTotal.pieces}</span><span class="capacity-prod-label">peças únicas</span></div>
        <div class="capacity-prod-stat"><span class="capacity-prod-value">${wsTotal.arts}</span><span class="capacity-prod-label">artes individuais</span></div>
        <div class="capacity-prod-stat"><span class="capacity-prod-value">${wsTotal.variations}</span><span class="capacity-prod-label">variações</span></div>
      </div>
    </div>
    ${rows.length ? capacityHeatmapHTML(rows, startYmd, endYmd) : ''}
    <div class="capacity-rows">
    ${rows.map(r => `
      <div class="capacity-row ${r.status}">
        <div class="capacity-user">
          ${avatarHTML(r.u)}
          <div>
            <div class="capacity-user-name">${esc(r.u.name)}</div>
            <div class="capacity-user-role">${esc(r.u.role || '—')}</div>
          </div>
        </div>
        <div class="capacity-stats">
          <div class="capacity-stat"><span class="capacity-stat-value">${r.userDemands.length}</span><span class="capacity-stat-label">em aberto</span></div>
          <div class="capacity-stat"><span class="capacity-stat-value">${r.inPeriod.length}</span><span class="capacity-stat-label">no período</span></div>
          <div class="capacity-stat ${r.lateCount > 0 ? 'late' : ''}"><span class="capacity-stat-value">${r.lateCount}</span><span class="capacity-stat-label">atrasadas</span></div>
          <div class="capacity-stat"><span class="capacity-stat-value">${fmtHours(r.hoursLogged)}</span><span class="capacity-stat-label">apontadas</span></div>
          <div class="capacity-stat-divider"></div>
          <div class="capacity-stat" title="Peças únicas entregues no período"><span class="capacity-stat-value">${r.totalPieces}</span><span class="capacity-stat-label">peças</span></div>
          <div class="capacity-stat" title="Artes individuais entregues no período"><span class="capacity-stat-value">${r.totalArts}</span><span class="capacity-stat-label">artes</span></div>
          <div class="capacity-stat" title="Variações/exportações entregues no período"><span class="capacity-stat-value">${r.totalVariations}</span><span class="capacity-stat-label">variações</span></div>
        </div>
        <div class="capacity-bar-wrap">
          <div class="capacity-bar-track">
            <div class="capacity-bar-fill ${r.status}" style="width:${Math.min(100, r.pct)}%"></div>
            ${r.pct > 100 ? `<div class="capacity-bar-over" style="width:${Math.min(100, r.pct - 100)}%"></div>` : ''}
          </div>
          <div class="capacity-bar-label">${r.pct}%<span class="capacity-bar-sub"> · ${fmtHours(r.hoursLogged)} / ${capacityHours}h</span></div>
        </div>
      </div>
    `).join('')}
    </div>
  `;
  if (!rows.length) $('capacity-list').innerHTML = emptyState('Sem usuários ativos', 'Cadastre usuários e atribua-os a este squad.', 'users');
}

function renderCapacityAggregate(kind, startYmd, endYmd, businessDays, capacityHours) {
  // Período retroativo: considera apontamentos do início do período até hoje
  // (o filtro de "próximos N dias" passa a significar "últimos N dias" para os modos de horas apontadas)
  // Janela retroativa de apontamentos = mesma janela de horas do capResolveWindow
  // (últimos N / mês corrente / range custom travado em hoje).
  const { logStart, logEnd } = capResolveWindow();
  const backStartYmd = logStart.toISOString().slice(0,10);
  const todayYmd = logEnd.toISOString().slice(0,10);

  // Junta todos os apontamentos de demandas do escopo (squads selecionados ou ws ativo)
  const wsdemands = capScopeDemands();
  const allEntries = [];
  wsdemands.forEach(d => {
    (d.timeEntries || []).forEach(e => {
      const ymd = (e.createdAt || '').slice(0, 10);
      if (ymd >= backStartYmd && ymd <= todayYmd) allEntries.push({ d, e });
    });
  });

  // Agrupa por projeto ou por cliente
  const groups = new Map();
  allEntries.forEach(({ d, e }) => {
    const proj = projectById(d.projectId);
    let key, label, sub, projects;
    if (kind === 'project') {
      key = proj?.id || '__none__';
      label = proj?.name || '— Sem projeto —';
      sub = proj?.client || '';
      projects = proj ? [proj] : [];
    } else {
      // por cliente — se projeto sem cliente, agrupa em "Sem cliente"
      key = (proj?.client || '__none__').toLowerCase();
      label = proj?.client || '— Sem cliente —';
      sub = '';
      projects = capScopeProjects().filter(p => (p.client || '').toLowerCase() === key);
    }
    const cur = groups.get(key) || {
      key, label, sub, projects, color: proj?.color || '#7A00FF',
      hours: 0, demands: new Set(), users: new Set(), entries: 0,
      pieces: 0, arts: 0, variations: 0
    };
    cur.hours += Number(e.hours) || 0;
    cur.demands.add(d.id);
    if (e.userId) cur.users.add(e.userId);
    cur.entries++;
    if (kind === 'client') cur.projects = projects;
    groups.set(key, cur);
  });

  // Segundo loop: soma entregáveis (peças/artes/variações) por grupo.
  // Critério = demanda concluída no período OU em aberto (mesma regra da Equipe).
  // Itera UMA vez por demanda (evita dupla-contagem que viria de iterar por entries).
  const isInWindow = (d) => {
    if (d.completedAt) {
      const day = String(d.completedAt).slice(0, 10);
      return day >= backStartYmd && day <= todayYmd;
    }
    return !isDone(d);
  };
  wsdemands.forEach(d => {
    if (!isInWindow(d)) return;
    if (!(d.qtyPieces || d.qtyArts || d.qtyVariations)) return;
    const proj = projectById(d.projectId);
    let key;
    if (kind === 'project') key = proj?.id || '__none__';
    else key = (proj?.client || '__none__').toLowerCase();
    const g = groups.get(key);
    if (!g) return; // grupo só existe se houver apontamentos — sem horas, sem linha
    g.pieces += Number(d.qtyPieces) || 0;
    g.arts += Number(d.qtyArts) || 0;
    g.variations += Number(d.qtyVariations) || 0;
  });

  const rows = [...groups.values()].sort((a, b) => b.hours - a.hours);
  const totalHours = rows.reduce((s, r) => s + r.hours, 0);
  const maxHours = Math.max(1, ...rows.map(r => r.hours));

  // Resumo
  const summary = `
    <div class="capacity-summary">
      <div class="capacity-summary-item"><div class="capacity-summary-label">Total apontado</div><div class="capacity-summary-value">${fmtHours(totalHours)}</div><div class="capacity-summary-sub">no período (${businessDays} dias úteis)</div></div>
      <div class="capacity-summary-item"><div class="capacity-summary-label">${kind === 'project' ? 'Projetos com horas' : 'Clientes com horas'}</div><div class="capacity-summary-value">${rows.length}</div><div class="capacity-summary-sub">${capSquadFilter.size ? `em ${capSquadFilter.size} squad${capSquadFilter.size === 1 ? '' : 's'}` : `no workspace ${esc(wsById(activeWs)?.name || '')}`}</div></div>
      <div class="capacity-summary-item"><div class="capacity-summary-label">Apontamentos</div><div class="capacity-summary-value">${allEntries.length}</div><div class="capacity-summary-sub">registros no período</div></div>
    </div>`;

  if (!rows.length) {
    $('capacity-list').innerHTML = summary + emptyState(
      kind === 'project' ? 'Sem horas apontadas em projetos no período' : 'Sem horas apontadas em clientes no período',
      'Os apontamentos das demandas aparecerão aqui quando registrados.'
    );
    return;
  }

  $('capacity-list').innerHTML = summary + `
    <div class="capacity-rows">
    ${rows.map(r => {
      const pct = Math.round(r.hours / maxHours * 100);
      const share = totalHours > 0 ? Math.round(r.hours / totalHours * 100) : 0;
      return `<div class="capacity-row">
        <div class="capacity-user">
          <span class="capacity-color-dot" style="background:${r.color}"></span>
          <div>
            <div class="capacity-user-name">${esc(r.label)}</div>
            <div class="capacity-user-role">${kind === 'project' ? (r.sub ? esc(r.sub) : 'Sem cliente') : (r.projects.length + ' projeto' + (r.projects.length === 1 ? '' : 's'))}</div>
          </div>
        </div>
        <div class="capacity-stats">
          <div class="capacity-stat"><span class="capacity-stat-value">${fmtHours(r.hours)}</span><span class="capacity-stat-label">apontadas</span></div>
          <div class="capacity-stat"><span class="capacity-stat-value">${r.demands.size}</span><span class="capacity-stat-label">demanda${r.demands.size === 1 ? '' : 's'}</span></div>
          <div class="capacity-stat"><span class="capacity-stat-value">${r.users.size}</span><span class="capacity-stat-label">pessoa${r.users.size === 1 ? '' : 's'}</span></div>
          <div class="capacity-stat"><span class="capacity-stat-value">${r.entries}</span><span class="capacity-stat-label">apontamento${r.entries === 1 ? '' : 's'}</span></div>
          <div class="capacity-stat-divider"></div>
          <div class="capacity-stat" title="Peças únicas entregues no período"><span class="capacity-stat-value">${r.pieces}</span><span class="capacity-stat-label">peças</span></div>
          <div class="capacity-stat" title="Artes individuais entregues no período"><span class="capacity-stat-value">${r.arts}</span><span class="capacity-stat-label">artes</span></div>
          <div class="capacity-stat" title="Variações/exportações entregues no período"><span class="capacity-stat-value">${r.variations}</span><span class="capacity-stat-label">variações</span></div>
        </div>
        <div class="capacity-bar-wrap">
          <div class="capacity-bar-track">
            <div class="capacity-bar-fill medium" style="width:${pct}%;background:${r.color}"></div>
          </div>
          <div class="capacity-bar-label">${share}%<span class="capacity-bar-sub"> · do total apontado</span></div>
        </div>
      </div>`;
    }).join('')}
    </div>
  `;
}

function renderCalendar(which) {
  const ref = calState[which];
  const y = ref.getFullYear(), m = ref.getMonth();
  $('cal-' + which + '-title').textContent = MONTHS[m] + ' ' + y;
  const source = which === 'mine' ? myDemands() : listFilteredDemands();
  const first = new Date(y, m, 1).getDay();
  const days = new Date(y, m + 1, 0).getDate();
  let html = '';
  for (let i = 0; i < first; i++) html += '<div class="cal-day" style="visibility:hidden"></div>';
  for (let day = 1; day <= days; day++) {
    const ymd = fmtYMD(y, m, day);
    const evs = source.filter(d => effDue(d) === ymd);
    const isToday = ymd === todayStr();
    // Sábado (6) e domingo (0) recebem .weekend pra ganhar visual atenuado no CSS.
    const dow = new Date(y, m, day).getDay();
    const isWeekend = dow === 0 || dow === 6;
    html += `<div class="cal-day ${isToday ? 'today' : ''} ${isWeekend ? 'weekend' : ''}">
      <div class="cal-day-num">${isToday ? `<span class="cal-today-pill">${day}</span>` : day}</div>
      ${evs.slice(0,4).map(d => {
        const s = stageOf(d);
        const late = isLate(d);
        const owner = userById(d.ownerId);
        const bg = late ? 'var(--danger-dim)' : hexDim(s?.color);
        const fg = late ? 'var(--danger)' : (s?.color || 'var(--text)');
        const avatarHtml = owner
          ? avatarHTML(owner, 'avatar cal-event-avatar')
          : `<span class="cal-event-dot" style="background:${fg}"></span>`;
        return `<div class="cal-event" onclick="showDetail('${d.id}')" data-tooltip="${esc(d.name)}${owner ? ' · ' + esc(owner.name) : ''}" style="background:${bg};color:${fg}">
          ${avatarHtml}
          <span class="cal-event-name">${esc(d.name)}</span>
        </div>`;
      }).join('')}
      ${evs.length > 4 ? `<div class="cal-day-more">+${evs.length - 4} mais</div>` : ''}
    </div>`;
  }
  $('cal-' + which + '-body').innerHTML = html;
}
function fmtYMD(y, m, d) {
  return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}

/* ─── MODAL: NOVA / EDITAR DEMANDA ─── */
/* Fluxos disponíveis pra um cliente — CROSS-WORKSPACE.
   Fluxos pertencem ao CLIENTE (não ao projeto/workspace). O filtro é só
   permissão (workspaces acessíveis pro usuário logado).
   Match: (a) f.clientId === clientId, (b) legado f.client string, (c) geral. */
function flowsForClient(clientId) {
  const c = clientId ? clientById(clientId) : null;
  const cName = (c?.name || '').trim().toLowerCase();
  return (flows || []).filter(f => {
    if (!(me.isAdmin || (me.workspaces || []).includes(f.workspaceId))) return false;
    if (clientId && f.clientId === clientId) return true;
    if (cName && !f.clientId && (f.client || '').trim().toLowerCase() === cName) return true;
    if (!f.clientId && !(f.client || '').trim()) return true; // geral
    return false;
  });
}
/* Wrapper legado — mantém contratos antigos que passavam projectId. */
function flowsForProject(projectId) {
  const proj = projectById(projectId);
  return flowsForClient(proj?.clientId || null);
}
function onDemandProjectChange() {
  const pid = $('f-project').value;
  const fl = (pid ? flowsForProject(pid) : wsFlows())
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const prev = $('f-flow').value;
  $('f-flow').innerHTML = fl.map(f => `<option value="${f.id}">${esc(f.name)}${f.demandType ? ' · ' + esc(f.demandType) : ''}</option>`).join('');
  if ([...$('f-flow').options].some(o => o.value === prev)) $('f-flow').value = prev;
  syncStatusOptions();
}
/* Responsável pré-preenchido do responsável inicial no wizard.
   Resolve a cadeia completa (mesma lógica do backend):
   1) customização feita no passo "Customizar" (stageResponsibles)
   2) responsibleId fixo da etapa no fluxo
   3) responsibleRole → project.roleAssignments → client.roleAssignments (padrão do cliente). */
function wizardAutoOwnerFor(stage) {
  if (!stage) return null;
  const synthetic = {
    projectId: $('f-project').value || null,
    stageResponsibles: (wizardState && wizardState.customization && wizardState.customization.stageResponsibles) || {}
  };
  return resolveStageOwnerId(synthetic, stage);
}
function syncStatusOptions(selectedStageId) {
  const flow = flowById($('f-flow').value);
  $('f-status').innerHTML = flow
    ? flow.stages.map(s => `<option value="${s.id}">${esc(s.label)}</option>`).join('')
    : '';
  if (selectedStageId && flow && flow.stages.some(s => s.id === selectedStageId)) $('f-status').value = selectedStageId;
  // Auto-atribui responsável da etapa ao criar nova demanda
  if (!editingId && flow) {
    const stageId = $('f-status').value;
    const stage = flow.stages.find(s => s.id === stageId);
    const autoOwner = wizardAutoOwnerFor(stage);
    buildUserSelect($('f-owner-select'), wsUsers(), autoOwner, null);
    // Defaults herdados do fluxo: só aplica em NOVA demanda e se o usuário ainda
    // não digitou nada nos campos (não sobrescreve mudanças manuais).
    const curDesc = (getRichValue('f-description') || '').replace(/<[^>]+>/g, '').trim();
    if (!curDesc && flow.defaultDescription) {
      setRichValue('f-description', flow.defaultDescription);
    }
    // Checklist herdado — só popula se ainda tá zerado (evita resetar edições)
    if (!demandChecklistDraft.length && Array.isArray(flow.defaultChecklist)) {
      demandChecklistDraft = flow.defaultChecklist.map(it => ({ text: String(it.text || ''), ownerId: it.ownerId || null }));
    }
    renderDemandChecklist();
  }
}
function onDemandStatusChange() {
  if (!editingId) {
    const flow = flowById($('f-flow').value);
    if (flow) {
      const stage = flow.stages.find(s => s.id === $('f-status').value);
      buildUserSelect($('f-owner-select'), wsUsers(), wizardAutoOwnerFor(stage), null);
    }
  }
}

/* Draft do checklist a ser criado junto com a demanda nova.
   Inicializado pelo defaultChecklist do fluxo em syncStatusOptions().
   Editável aqui — usuário pode adicionar/remover/editar texto antes de salvar. */
let demandChecklistDraft = [];
// Opções de usuário do workspace pra o <select> de responsável do item.
function wsUserOptions(selectedId) {
  return wsUsers().slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)))
    .map(u => `<option value="${u.id}" ${u.id === selectedId ? 'selected' : ''}>${esc(u.name)}</option>`).join('');
}
// HTML de um item do checklist no wizard (texto + responsável + remover).
// `removeFn` difere entre o passo de infos e o de customizar (compartilham a draft).
function chkItemHTML(it, i, removeFn) {
  return `<div class="chk-item">
    <input class="form-control chk-item-text" value="${esc(it.text || '')}" placeholder="Item do checklist" oninput="demandChecklistDraft[${i}].text=this.value">
    <select class="form-control chk-item-owner" onchange="demandChecklistDraft[${i}].ownerId=this.value||null">
      <option value="">— Responsável —</option>
      ${wsUserOptions(it.ownerId)}
    </select>
    <button type="button" class="detail-icon-btn danger chk-item-del" title="Remover" onclick="${removeFn}(${i})"><i data-lucide="x" class="ic-sm"></i></button>
  </div>`;
}
function renderDemandChecklist() {
  const wrap = $('f-checklist-list');
  const group = $('f-checklist-group');
  if (!wrap || !group) return;
  // Em edição, o checklist é editado pela aba de detalhe (com estado de conclusão).
  if (editingId) { group.style.display = 'none'; return; }
  // Na criação, fica sempre visível — estado vazio quando não há itens.
  group.style.display = '';
  wrap.innerHTML = demandChecklistDraft.length
    ? demandChecklistDraft.map((it, i) => chkItemHTML(it, i, 'removeDemandChecklistItem')).join('')
    : '<div class="chk-empty">Nenhum item.</div>';
  paintIcons();
}
function addDemandChecklistItem() {
  demandChecklistDraft.push({ text: '', ownerId: null });
  renderDemandChecklist();
  const inputs = $('f-checklist-list').querySelectorAll('input.chk-item-text');
  if (inputs.length) inputs[inputs.length - 1].focus();
}
function removeDemandChecklistItem(i) {
  demandChecklistDraft.splice(i, 1);
  renderDemandChecklist();
}
function fillDemandSelectors(d) {
  // Cross-workspace — projetos de todos os workspaces acessíveis pro usuário.
  // Sem isso, quando o wizard escolhe cliente de outro workspace, o projeto
  // vira "opção fantasma" e o save falha com "Selecione um projeto válido".
  const projs = (projects || [])
    .filter(p => me.isAdmin || (me.workspaces || []).includes(p.workspaceId))
    .filter(p => p.active !== false || (d && d.projectId === p.id))
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  $('f-project').innerHTML = '<option value="">— Selecione um projeto —</option>' +
    projs.map(p => `<option value="${p.id}">${esc(p.name)}${p.client ? ' · ' + esc(p.client) : ''}</option>`).join('');
}
function fillTemplateSelector() {
  const wsTemplates = templates.filter(t => t.workspaceId === activeWs)
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const sel = $('f-template');
  sel.innerHTML = '<option value="">— Em branco —</option>' +
    wsTemplates.map(t => `<option value="${t.id}">${esc(t.name)}</option>`).join('');
  $('f-template-group').style.display = wsTemplates.length ? '' : 'none';
}
function applyDemandTemplate() {
  const tid = $('f-template').value;
  if (!tid) return;
  const t = templates.find(x => x.id === tid); if (!t) return;
  if ($('f-name').value.trim() === '') $('f-name').value = t.name || '';
  setRichValue('f-description', t.description || '');
  $('f-briefing').value = t.briefing || '';
  $('f-estimated').value = t.estimatedHours || '';
  $('f-priority').value = t.priority || 3;
  if (t.projectId && projects.some(p => p.id === t.projectId)) {
    $('f-project').value = t.projectId;
    onDemandProjectChange();
  }
  if (t.flowId && flows.some(f => f.id === t.flowId)) {
    $('f-flow').value = t.flowId;
    syncStatusOptions();
  }
  if (t.ownerId) buildUserSelect($('f-owner-select'), wsUsers(), t.ownerId, null);
  demandAttachments = (t.attachments || []).map(a => ({ ...a, id: 'a' + Math.random().toString(36).slice(2,10) }));
  refreshFormAttList('f-attachments-list');
  toast('Template "' + t.name + '" aplicado!');
}

function openNewDemand() {
  editingId = null;
  // Zera o contexto de "vindo de tarefa" — só é setado por openNewDemandFromTask
  // logo depois desta chamada. Sem isso, fechar sem salvar deixa lixo pra próxima.
  _creatingFromTaskId = null;
  $('modal-title').textContent = 'Nova demanda';
  $('demand-delete-btn').style.display = 'none';
  fillDemandSelectors(null);
  fillTemplateSelector();
  $('f-template').value = '';
  $('f-name').value = '';
  mountRichEditor('f-description', { placeholder: 'Detalhe o que precisa ser feito, referências, contexto…', minHeight: '120px' });
  setRichValue('f-description', '');
  $('f-briefing').value = ''; $('f-deadline').value = '';
  $('f-estimated').value = ''; $('f-priority').value = '3';
  $('f-qty-pieces').value = ''; $('f-qty-arts').value = ''; $('f-qty-variations').value = '';
  fillDeliverableUserSelect('f-deliverable-user', null);
  demandChecklistDraft = [];
  renderDemandChecklist();
  $('f-rec-enabled').checked = false; $('f-rec-config').style.display = 'none';
  $('f-rec-card')?.classList.remove('on');
  $('f-rec-pattern').value = 'weekly'; $('f-rec-interval').value = '1';
  $('f-rec-monthday').value = '1'; $('f-rec-start').value = ''; $('f-rec-end').value = '';
  renderRecWeekdayChips([new Date().getDay()]);
  $('f-rec-weekday-g').style.display = ''; $('f-rec-monthday-g').style.display = 'none';
  updateRecPreview();
  $('f-project').value = '';
  demandAttachments = [];
  refreshFormAttList('f-attachments-list');
  applyPriorityDropdown('f-priority');
  // Inicia o wizard no step 1 (cliente). Reset completo do estado (inclui customização).
  wizardState = { step: 1, clientId: null, projectId: null, flowId: null };
  _dwFlowType = '';
  resetWizardCustomization();
  wizardLastFlowApplied = null;
  // Congela os recentes pra a duração deste modal — evita reordenar cards
  // enquanto o usuário navega/duplo-clica.
  wizardSnapshotRecents();
  wizardGoTo(1);
  openModal('demand-modal');
  navPush('/demands/new');
  setTimeout(() => setupDragDrop('#demand-modal .modal-content', 'f-attachments-list', processDroppedFiles), 60);
}
function openEditDemand(id) {
  const d = demands.find(x => x.id === id); if (!d) return;
  editingId = id;
  $('modal-title').textContent = 'Editar demanda';
  $('demand-delete-btn').style.display = '';
  fillDemandSelectors(d);
  fillTemplateSelector();
  $('f-template-group').style.display = 'none';
  // Em edição, pula o wizard — vai direto pro form (step 4) com seleção pronta
  wizardState = { step: 4, clientId: projectById(d.projectId)?.clientId || null, projectId: d.projectId, flowId: d.flowId };
  // Marca o flow como "já aplicado" pra evitar reset dos campos preenchidos pela demanda
  wizardLastFlowApplied = d.flowId;
  wizardGoTo(4);
  $('f-name').value = d.name;
  mountRichEditor('f-description', { placeholder: 'Detalhe o que precisa ser feito, referências, contexto…', minHeight: '120px' });
  setRichValue('f-description', d.description || '');
  $('f-briefing').value = d.briefing || '';
  $('f-deadline').value = d.deadline || '';
  $('f-estimated').value = d.estimatedHours || '';
  $('f-priority').value = d.priority || 3;
  $('f-qty-pieces').value = d.qtyPieces || '';
  $('f-qty-arts').value = d.qtyArts || '';
  $('f-qty-variations').value = d.qtyVariations || '';
  fillDeliverableUserSelect('f-deliverable-user', d.deliverableUserId || '', d.workspaceId);
  // Em edição, o checklist é gerenciado pelo painel de detalhe (não aqui)
  demandChecklistDraft = [];
  renderDemandChecklist();
  // Recurrence
  const rec = d.recurrence;
  $('f-rec-enabled').checked = !!(rec && rec.enabled);
  $('f-rec-config').style.display = rec?.enabled ? '' : 'none';
  $('f-rec-card')?.classList.toggle('on', !!(rec && rec.enabled));
  $('f-rec-pattern').value = rec?.pattern || 'weekly';
  $('f-rec-interval').value = rec?.interval || 1;
  renderRecWeekdayChips((rec?.weekDays && rec.weekDays.length) ? rec.weekDays : (rec?.weekDay != null ? [rec.weekDay] : [new Date().getDay()]));
  if ($('f-rec-monthday')) $('f-rec-monthday').value = rec?.monthDay || 1;
  $('f-rec-start').value = rec?.startDate || '';
  $('f-rec-end').value = rec?.endDate || '';
  $('f-rec-weekday-g').style.display = (rec?.pattern || 'weekly') === 'weekly' ? '' : 'none';
  $('f-rec-monthday-g').style.display = rec?.pattern === 'monthly' ? '' : 'none';
  updateRecPreview();
  $('f-project').value = d.projectId || '';
  demandAttachments = (d.attachments || []).slice();
  refreshFormAttList('f-attachments-list');
  onDemandProjectChange();
  $('f-flow').value = d.flowId;
  syncStatusOptions(d.status);
  buildUserSelect($('f-owner-select'), wsUsers(), d.ownerId, null);
  applyPriorityDropdown('f-priority');
  openModal('demand-modal');
  navPush(demandPath(id) + '/edit');
  setTimeout(() => setupDragDrop('#demand-modal .modal-content', 'f-attachments-list', processDroppedFiles), 60);
}
async function saveDemand() {
  const recEnabled = $('f-rec-enabled').checked;
  // Lê valores brutos pra log diagnóstico — se algum vier "" ou NaN sabemos por aí
  const _rawQty = {
    p: $('f-qty-pieces')?.value,
    a: $('f-qty-arts')?.value,
    v: $('f-qty-variations')?.value
  };
  const payload = {
    name: $('f-name').value,
    description: getRichValue('f-description'),
    projectId: $('f-project').value,
    flowId: $('f-flow').value,
    briefing: normalizeUrl($('f-briefing').value),
    deadline: $('f-deadline').value || null,
    estimatedHours: $('f-estimated').value ? Number($('f-estimated').value) : null,
    priority: Number($('f-priority').value) || 3,
    qtyPieces: Number($('f-qty-pieces').value) || 0,
    qtyArts: Number($('f-qty-arts').value) || 0,
    qtyVariations: Number($('f-qty-variations').value) || 0,
    deliverableUserId: $('f-deliverable-user')?.value || null,
    // Checklist inicial — só faz sentido em CRIAÇÃO. Em edição ignora (o user
    // edita pela aba detail). Filtra itens vazios.
    checklist: editingId ? undefined : demandChecklistDraft.filter(it => (it.text || '').trim()).map(it => ({ text: it.text.trim(), ownerId: it.ownerId || null })),
    status: $('f-status').value,
    ownerId: $('f-owner-select').dataset.value || null,
    attachments: demandAttachments.slice(),
    recurrence: recEnabled ? {
      enabled: true,
      pattern: $('f-rec-pattern').value,
      interval: Math.max(1, parseInt($('f-rec-interval').value, 10) || 1),
      weekDays: getRecWeekdays(),
      monthDay: parseInt(($('f-rec-monthday')?.value) || '1', 10),
      startDate: $('f-rec-start').value || null,
      endDate: $('f-rec-end').value || null
    } : { enabled: false }
  };
  // Customização de etapas por instância (do step "cust" do wizard).
  // Só envia em criação — edição segue por rotas dedicadas (/skipped-stages etc).
  if (!editingId && wizardState.customization) {
    const c = wizardState.customization;
    if (c.skippedStages?.length)                 payload.skippedStages = c.skippedStages;
    if (c.stageResponsibles && Object.keys(c.stageResponsibles).length) payload.stageResponsibles = c.stageResponsibles;
    if (c.stageLabels && Object.keys(c.stageLabels).length) payload.stageLabels = c.stageLabels;
    if (c.stageOverrides && Object.keys(c.stageOverrides).length) payload.stageOverrides = c.stageOverrides;
    if (c.stageAdditions?.length)                payload.stageAdditions = c.stageAdditions;
    if (Array.isArray(c.stageOrder) && c.stageOrder.length) payload.stageOrder = c.stageOrder;
  }
  try {
    let result;
    if (editingId) result = await api('/demands/' + editingId, 'PUT', payload);
    else result = await api('/demands', 'POST', payload);
    const wasCreate = !editingId;
    const newId = result && result.id;
    closeModal('demand-modal');
    await refreshData();
    if (detailId && editingId === detailId) renderDetail();
    if (wasCreate && newId) {
      // Se veio de uma tarefa da lista, vincula a demanda recém-criada.
      // Sem await no toast/refresh — o link não pode bloquear a UX.
      if (_creatingFromTaskId) {
        const tid = _creatingFromTaskId;
        _creatingFromTaskId = null;
        api('/tasks/' + tid + '/link-demand', 'POST', { demandId: newId })
          .then(async () => {
            try { tasks = await api('/tasks'); } catch {}
            renderCurrent();
          })
          .catch(err => console.warn('[task-link] falha ao vincular tarefa:', err.message));
      }
      toast('Demanda criada!', 'success', { label: 'Abrir', fn: () => showDetail(newId) });
    } else {
      toast(editingId ? 'Demanda atualizada!' : 'Demanda criada!');
    }
  } catch (e) {
    console.error('[saveDemand] erro:', e);
    toast(e.message, 'error');
  }
}
// Estado do link tarefa→demanda: setado por openNewDemandFromTask, limpo em
// saveDemand (sucesso) OU quando o modal é fechado sem salvar (openNewDemand).
let _creatingFromTaskId = null;
// Abre o wizard de nova demanda a partir de uma tarefa: pula os steps de
// cliente e projeto (já sabidos do task.projectId/clientId), pré-preenche o
// nome com o título da tarefa, e após salvar vincula a demanda à tarefa.
function openNewDemandFromTask(taskId) {
  const t = (tasks || []).find(x => x.id === taskId);
  if (!t) return toast('Tarefa não encontrada', 'error');
  const project = projectById(t.projectId);
  if (!project) return toast('Projeto da tarefa não encontrado', 'error');
  // Ativa o wizard limpo (mesmo caminho do openNewDemand), depois pula pra step 3
  // (fluxo) com cliente/projeto pré-definidos. O nome vai pré-preenchido no step 4.
  openNewDemand();
  _creatingFromTaskId = t.id;
  // Ajusta o wizard state — precisa ir DEPOIS do openNewDemand (que zera tudo).
  wizardState = { step: 3, clientId: project.clientId || null, projectId: project.id, flowId: null };
  // Tipo da tarefa vira só pré-filtro informativo no step 3 — user SEMPRE escolhe
  // o fluxo manualmente (mesmo com só 1 opção). Isso evita erros silenciosos
  // com fluxos criados errados por tipo.
  _dwFlowType = t.demandType || '';
  setTimeout(() => {
    if ($('f-name')) $('f-name').value = t.name || '';
    wizardGoTo(3);
  }, 0);
}
// Aplica uma lista (kind='todo') a um PROJETO (só projeto — cliente direto
// foi removido do modelo). Cada aplicação gera um bloco novo, mesmo se a
// mesma lista já foi aplicada antes (o backend gera um applicationId único).
async function openApplyListaToProjectModal(listaId) {
  const lista = listas.find(l => l.id === listaId);
  if (!lista) return toast('Lista não encontrada', 'error');
  if (lista.kind !== 'todo') return toast('Só listas do modelo novo (to-do) podem ser aplicadas por aqui.', 'warn');
  // Projetos ativos de TODOS os clientes do squad — lista é global mas cria
  // tasks no squad do projeto de destino.
  const wsProjs = projects.filter(p => p.workspaceId === activeWs && p.active !== false && !p.deletedAt)
    .slice().sort((a, b) => {
      const ca = clientById(a.clientId)?.name || '';
      const cb = clientById(b.clientId)?.name || '';
      const cmp = norm(ca).localeCompare(norm(cb));
      return cmp !== 0 ? cmp : norm(a.name).localeCompare(norm(b.name));
    });
  if (!wsProjs.length) return toast('Nenhum projeto ativo neste squad', 'warn');
  const opts = wsProjs.map(p => {
    const c = clientById(p.clientId);
    return { value: p.id, label: c ? `${c.name} · ${p.name}` : p.name };
  });
  const nItems = (lista.items || []).length;
  showCustomPicker(
    `Aplicar "${lista.name}"`,
    `Escolha o projeto onde as ${nItems} tarefa(s) vão ficar pendentes:`,
    opts,
    async (projectId) => {
      try {
        const r = await api('/apply-lista', 'POST', { listaId, projectId });
        toast(`${r.created} tarefa${r.created === 1 ? '' : 's'} aplicada${r.created === 1 ? '' : 's'}!`, 'success');
        try { tasks = await api('/tasks'); } catch {}
        renderCurrent();
      } catch (e) { toast(e.message, 'error'); }
    }
  );
}

/* ── Salvar como template ── */
