/* ── EDITOR COMPLETO DE FLUXO DO MODELO ──
   Um único modal (#template-flow-modal) usado pra criar E editar. Diferença
   é só se fIdx === null (criar → POST) ou é número (editar → PUT). */
let _tflCtx = null; // { tplId, pIdx, fIdx (null se novo), stages: [], checklist: [], icon: string|null }
function openTemplateFlowModal(tplId, pIdx, fIdx) {
  const t = clientTemplates.find(x => x.id === tplId);
  const proj = t?.projects?.[pIdx];
  if (!t || !proj) return;
  const isEdit = fIdx !== null && fIdx !== undefined;
  const flow = isEdit ? proj.flows?.[fIdx] : null;
  if (isEdit && !flow) return;
  _tflCtx = {
    tplId, pIdx, fIdx: isEdit ? fIdx : null,
    // Cópias locais editáveis — só persiste no Save.
    // Sem responsibleRole aqui: modelo não decide área (decidido no cliente via matriz Área×Cargo).
    stages: isEdit ? flow.stages.map(s => ({ ...s })) : [
      { label: 'A fazer',      color: '#64748B', done: false, deadlineDays: null },
      { label: 'Em andamento', color: '#38BDF8', done: false, deadlineDays: null },
      { label: 'Concluída',    color: '#22D3A5', done: true,  deadlineDays: null }
    ],
    checklist: isEdit ? [...(flow.defaultChecklist || [])] : [],
    icon: flow?.icon || null
  };
  $('tfl-title').textContent = isEdit ? `Editar fluxo em "${proj.name}"` : `Novo fluxo em "${proj.name}"`;
  $('tfl-name').value = flow?.name || '';
  $('tfl-type').value = flow?.demandType || '';
  mountRichEditor('tfl-description', { placeholder: 'Ex.: Sempre incluir CTA no final. Formato 1080x1350.', minHeight: '90px' });
  setRichValue('tfl-description', flow?.defaultDescription || '');
  // Datalist de tipos: modelo é global, junta tipos de TODOS os fluxos acessíveis
  // pro usuário — mais completo que restringir por 1 workspace só.
  const accessibleWs = new Set(me.isAdmin
    ? (workspaces || []).map(w => w.id)
    : (me.workspaces || []));
  initTypeCombo('tfl-type', 'tfl-type-menu');
  $('tfl-delete-btn').style.display = isEdit ? '' : 'none';
  refreshTflIconPreview();
  renderTflStages();
  renderTflChecklist();
  openModal('template-flow-modal');
}
function refreshTflIconPreview() {
  const el = $('tfl-icon-preview');
  if (!el) return;
  el.style.backgroundImage = '';
  el.classList.remove('has-icon');
  const icon = _tflCtx?.icon;
  if (!icon) { el.innerHTML = '<span class="flow-icon-label">ícone</span>'; return; }
  if (typeof icon === 'string' && icon.startsWith('lucide:')) {
    el.classList.add('has-icon');
    el.innerHTML = `<i data-lucide="${esc(icon.slice(7))}" class="ic-md"></i>`;
    paintIcons();
  } else {
    el.classList.add('has-icon');
    el.innerHTML = '';
    el.style.backgroundImage = `url('${icon}')`;
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
  }
}
function openTflIconPicker() {
  if (!_tflCtx) return;
  openLucidePicker(_tflCtx.icon, (val) => {
    _tflCtx.icon = val;
    refreshTflIconPreview();
  });
}
function renderTflStages() {
  const wrap = $('tfl-stages-list');
  if (!wrap || !_tflCtx) return;
  // Sem select de área: modelo só define a forma do fluxo. Área/cargo/responsável
  // ficam a cargo do cliente (matriz Área × Cargo no painel Pessoas).
  wrap.innerHTML = _tflCtx.stages.map((s, i) => {
    const color = s.color || '#7A00FF';
    return `<div class="tfl-stage-row" data-idx="${i}"
         ondragover="tflStageDragOver(event,${i})" ondragleave="tflStageDragLeave(event)"
         ondrop="tflStageDrop(event,${i})" ondragend="tflStageDragEnd()">
      <div class="tfl-stage-grip" draggable="true" ondragstart="tflStageDragStart(event,${i})" title="Arraste para reordenar"><i data-lucide="grip-vertical" class="ic-sm"></i></div>
      <button type="button" class="color-swatch-trigger tfl-stage-color" style="background:${esc(color)}" onclick="openColorPicker(this, (c) => { tflSetStage(${i}, 'color', c); this.style.background = c; }, '${esc(color)}')" title="Cor da etapa"></button>
      <input type="text" class="wizard-cust-name" placeholder="Nome da etapa" value="${esc(s.label || '')}" oninput="tflSetStage(${i}, 'label', this.value)">
      <div class="wizard-cust-days-inline" title="Prazo da etapa (em dias)">
        <input type="number" class="wizard-cust-days" min="0" step="1" placeholder="—" value="${s.deadlineDays ?? ''}" oninput="tflSetStage(${i}, 'deadlineDays', this.value === '' ? null : Number(this.value))">
        <span class="wizard-cust-days-unit">d</span>
      </div>
      <button type="button" class="cust-icon-toggle cust-toggle-done ${s.done ? 'on' : ''}" title="${s.done ? 'Etapa final — conclui a demanda' : 'Marcar como etapa final (conclui a demanda)'}" onclick="tflToggleDone(${i})"><i data-lucide="flag" class="ic-sm"></i></button>
      <button type="button" class="cust-icon-toggle tfl-remove-btn" title="Excluir etapa" onclick="tflRemoveStage(${i})"><i data-lucide="trash-2" class="ic-sm"></i></button>
    </div>`;
  }).join('');
  paintIcons();
}
/* Drag-reorder das etapas no editor de fluxo do modelo. Mesma mecânica do
   editor de fluxo normal (stageDrag*), mas opera em _tflCtx.stages. */
let _tflDragIdx = null;
function tflStageDragStart(e, i) {
  _tflDragIdx = i;
  e.dataTransfer.effectAllowed = 'move';
  const row = e.currentTarget.closest('.tfl-stage-row') || e.currentTarget;
  row.classList.add('dragging');
}
function tflStageDragOver(e, i) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  e.currentTarget.classList.add('drag-over');
}
function tflStageDragLeave(e) { e.currentTarget.classList.remove('drag-over'); }
function tflStageDrop(e, i) {
  e.preventDefault();
  if (_tflDragIdx === null || _tflDragIdx === i) { renderTflStages(); return; }
  const [moved] = _tflCtx.stages.splice(_tflDragIdx, 1);
  _tflCtx.stages.splice(i, 0, moved);
  _tflDragIdx = null;
  renderTflStages();
}
function tflStageDragEnd() {
  _tflDragIdx = null;
  document.querySelectorAll('.tfl-stage-row').forEach(r => r.classList.remove('dragging', 'drag-over'));
}
function tflSetStage(idx, field, value) {
  if (!_tflCtx || !_tflCtx.stages[idx]) return;
  _tflCtx.stages[idx][field] = value;
  // Não re-renderiza — os inputs já refletem o próprio valor. Cor é atualizada
  // inline via oninput no elemento (evita perder o foco enquanto edita).
}
// "Final" agora é botão-ícone (bandeira) — re-renderiza pra atualizar o estado visual.
function tflToggleDone(idx) {
  if (!_tflCtx || !_tflCtx.stages[idx]) return;
  _tflCtx.stages[idx].done = !_tflCtx.stages[idx].done;
  renderTflStages();
}
function tflAddStage() {
  if (!_tflCtx) return;
  _tflCtx.stages.push({ label: '', color: '#7A00FF', done: false, deadlineDays: null, responsibleRole: null });
  renderTflStages();
}
function tflRemoveStage(idx) {
  if (!_tflCtx) return;
  if (_tflCtx.stages.length <= 2) { toast('O fluxo precisa ter pelo menos 2 etapas.', 'warn'); return; }
  _tflCtx.stages.splice(idx, 1);
  renderTflStages();
}
function renderTflChecklist() {
  const wrap = $('tfl-checklist-list');
  if (!wrap || !_tflCtx) return;
  wrap.innerHTML = _tflCtx.checklist.map((it, i) => `
    <div class="flow-checklist-item">
      <input type="text" class="form-control" placeholder="Ex.: Aprovar copy" value="${esc(it.text || '')}" oninput="tflSetChecklist(${i}, this.value)">
      <button type="button" class="detail-icon-btn danger" onclick="tflRemoveChecklist(${i})" title="Remover"><i data-lucide="x" class="ic-sm"></i></button>
    </div>`).join('');
  paintIcons();
}
function tflSetChecklist(idx, value) {
  if (!_tflCtx || !_tflCtx.checklist[idx]) return;
  _tflCtx.checklist[idx].text = value;
}
function tflAddChecklist() {
  if (!_tflCtx) return;
  _tflCtx.checklist.push({ text: '' });
  renderTflChecklist();
}
function tflRemoveChecklist(idx) {
  if (!_tflCtx) return;
  _tflCtx.checklist.splice(idx, 1);
  renderTflChecklist();
}
async function tflSave() {
  if (!_tflCtx) return;
  const name = $('tfl-name').value.trim();
  if (!name) { toast('Nome do fluxo é obrigatório.', 'error'); return; }
  const validStages = _tflCtx.stages.filter(s => (s.label || '').trim());
  if (validStages.length < 2) { toast('O fluxo precisa de pelo menos 2 etapas com nome.', 'error'); return; }
  const payload = {
    name,
    icon: _tflCtx.icon || null,
    demandType: $('tfl-type').value.trim(),
    defaultDescription: getRichValue('tfl-description'),
    defaultChecklist: _tflCtx.checklist.filter(it => (it.text || '').trim()),
    stages: validStages.map(s => ({
      label: (s.label || '').trim(),
      color: /^#[0-9a-f]{6}$/i.test(s.color || '') ? s.color : '#7A00FF',
      done: !!s.done,
      deadlineDays: Number.isInteger(s.deadlineDays) ? s.deadlineDays : null
    }))
  };
  const { tplId, pIdx, fIdx } = _tflCtx;
  const t = clientTemplates.find(x => x.id === tplId);
  try {
    if (fIdx === null) {
      // Criar novo fluxo — endpoint replica em clientes vinculados.
      const r = await api(`/client-templates/${tplId}/projects/${pIdx}/flows`, 'POST', payload);
      Object.assign(t, r.template);
      if (r.replicatedIn > 0) {
        flows = await api('/flows');
        toast(`Fluxo criado e replicado em ${r.replicatedIn} cliente${r.replicatedIn === 1 ? '' : 's'}.`);
      } else {
        toast('Fluxo criado no modelo.');
      }
    } else {
      const upd = await api(`/client-templates/${tplId}/projects/${pIdx}/flows/${fIdx}`, 'PUT', payload);
      Object.assign(t, upd);
      toast('Fluxo atualizado. Clientes existentes NÃO recebem essa alteração — só fluxos novos são replicados.');
    }
    closeModal('template-flow-modal');
    renderClientsModels();
  } catch (e) { toast(e.message, 'error'); }
}
async function tflDelete() {
  if (!_tflCtx || _tflCtx.fIdx === null) return;
  const { tplId, pIdx, fIdx } = _tflCtx;
  const t = clientTemplates.find(x => x.id === tplId);
  const flow = t?.projects?.[pIdx]?.flows?.[fIdx];
  if (!flow) return;
  const ok = await showConfirm({
    title: 'Excluir fluxo do modelo?',
    message: `O fluxo "${esc(flow.name)}" será removido do modelo. Clientes já criados a partir dele NÃO são afetados.`,
    okLabel: 'Excluir', danger: true
  });
  if (!ok) return;
  try {
    const upd = await api(`/client-templates/${tplId}/projects/${pIdx}/flows/${fIdx}`, 'DELETE');
    Object.assign(t, upd);
    closeModal('template-flow-modal');
    renderClientsModels();
    toast('Fluxo removido do modelo.', 'warn');
  } catch (e) { toast(e.message, 'error'); }
}
async function confirmDeleteTemplateFlow(tplId, pIdx, fIdx) {
  const t = clientTemplates.find(x => x.id === tplId);
  const flow = t?.projects?.[pIdx]?.flows?.[fIdx];
  if (!flow) return;
  const ok = await showConfirm({
    title: 'Excluir fluxo do modelo?',
    message: `O fluxo "${esc(flow.name)}" será removido do modelo. Clientes já criados a partir dele NÃO são afetados.`,
    okLabel: 'Excluir', danger: true
  });
  if (!ok) return;
  try {
    const upd = await api(`/client-templates/${tplId}/projects/${pIdx}/flows/${fIdx}`, 'DELETE');
    Object.assign(t, upd);
    renderClientsModels();
    toast('Fluxo removido do modelo.', 'warn');
  } catch (e) { toast(e.message, 'error'); }
}
