// ─── PROJETO: view de detalhe (dentro de page-clients) ──────────────────
function openProjectDetail(id) {
  const p = projectById(id);
  if (!p) { toast('Projeto não encontrado', 'error'); return; }
  // Garante que estamos na página certa (URL direta pode entrar por outro tab).
  if (currentPage !== 'clients') goPage('clients');
  currentProjectId = id;
  currentClientId = p.clientId || null; // pra facilitar o "voltar" pro cliente
  showProjectDetailView();
  renderProjectDetail(id);
  navPush(projectPath(id));
}
function closeProjectDetail() {
  const backToClientId = currentClientId;
  currentProjectId = null;
  if (backToClientId && clientById(backToClientId)) {
    showClientDetailView();
    renderClientDetail(backToClientId);
    navPush(clientPath(backToClientId));
  } else {
    $('clients-view-grid').style.display = '';
    $('clients-view-detail').style.display = 'none';
    const pvd = $('projects-view-detail'); if (pvd) pvd.style.display = 'none';
    navPush('/clients');
    renderClients();
  }
}
function openProjectModalEdit() {
  if (!currentProjectId) return;
  openProjectModal(currentProjectId);
}

/* ─── Galeria de anexos (cliente + projeto) ───
   Agrega anexos de demandas e comentários no escopo dado, com busca + chips
   de filtro por tipo. Reusa openAttPreview pra visualização. */
const _attGalState = {
  client:  { search: '', kind: '' },
  project: { search: '', kind: '' }
};
const _attGalKindLabels = [
  { k: '',      label: 'Todos' },
  { k: 'image', label: 'Imagens' },
  { k: 'pdf',   label: 'PDFs' },
  { k: 'video', label: 'Vídeos' },
  { k: 'audio', label: 'Áudios' },
  { k: 'link',  label: 'Links' },
  { k: 'other', label: 'Outros' }
];
function attGalKindOf(a) {
  if (a.kind === 'link') return 'link';
  return attPreviewKind(a.type);
}
function collectClientAttachments(clientId) {
  const projIds = new Set((projects || []).filter(p => p.clientId === clientId).map(p => p.id));
  const dds = (demands || []).filter(d => projIds.has(d.projectId) && !d.deletedAt);
  return collectAttachmentsFromDemands(dds);
}
function collectProjectAttachments(projectId) {
  const dds = (demands || []).filter(d => d.projectId === projectId && !d.deletedAt);
  return collectAttachmentsFromDemands(dds);
}
function collectAttachmentsFromDemands(dds) {
  const items = [];
  dds.forEach(d => {
    (d.attachments || []).forEach(a => {
      items.push({ ...a, demandId: d.id, demandName: d.name, addedAt: d.updatedAt || d.createdAt || '' });
    });
    (d.comments || []).forEach(c => {
      (c.attachments || []).forEach(a => {
        items.push({ ...a, demandId: d.id, demandName: d.name, addedAt: c.at || c.createdAt || '' });
      });
    });
  });
  // Ordem: mais recentes primeiro (fallback zero se sem timestamp).
  return items.sort((a, b) => (b.addedAt || '').localeCompare(a.addedAt || ''));
}
function renderAttGallery(ctx) {
  const wrap = $('att-gallery-' + ctx);
  if (!wrap) return;
  const items = ctx === 'client'
    ? collectClientAttachments(currentClientId)
    : collectProjectAttachments(currentProjectId);
  const st = _attGalState[ctx];
  const q = (st.search || '').toLowerCase();
  const filtered = items.filter(a => {
    if (st.kind && attGalKindOf(a) !== st.kind) return false;
    if (q) {
      const n = (a.name || '').toLowerCase();
      const dn = (a.demandName || '').toLowerCase();
      if (!n.includes(q) && !dn.includes(q)) return false;
    }
    return true;
  });
  // Contagem por tipo pra mostrar no chip.
  const counts = { '': items.length };
  items.forEach(a => {
    const k = attGalKindOf(a);
    counts[k] = (counts[k] || 0) + 1;
  });
  const chipsHtml = _attGalKindLabels.map(({ k, label }) => {
    const n = counts[k] || 0;
    if (k && n === 0) return ''; // esconde chip vazio (exceto "Todos")
    return `<button type="button" class="att-gal-chip ${k === st.kind ? 'is-active' : ''}" onclick="attGalPickKind('${ctx}', '${k}')">${esc(label)}<span class="att-gal-chip-count">${n}</span></button>`;
  }).join('');
  const gridHtml = filtered.length
    ? filtered.map(a => attGalTileHtml(a)).join('')
    : `<div class="att-gal-empty">${items.length ? 'Nenhum anexo bate com o filtro.' : 'Nenhum anexo neste ' + (ctx === 'client' ? 'cliente' : 'projeto') + ' ainda.'}</div>`;
  wrap.innerHTML = `
    <div class="att-gal-toolbar">
      <div class="filter-input-wrap att-gal-search">
        <i data-lucide="search" class="filter-input-icon ic-sm"></i>
        <input class="filter-input filter-input--with-icon" placeholder="Buscar anexo ou demanda…" value="${esc(st.search)}" oninput="attGalSearch('${ctx}', this.value)">
      </div>
      <div class="att-gal-chips">${chipsHtml}</div>
    </div>
    <div class="att-gal-grid">${gridHtml}</div>
  `;
  paintIcons();
}
function attGalTileHtml(a) {
  const kind = attGalKindOf(a);
  const nameEsc = esc(a.name || (kind === 'link' ? (a.url || 'Link') : 'Arquivo'));
  const demandEsc = esc(a.demandName || 'Demanda');
  const src = a.data || a.url || '';
  const srcEsc = esc(src);
  const previewable = kind !== 'other' && kind !== 'link';
  const openCall = kind === 'link'
    ? `window.open('${esc(normalizeUrl(a.url || a.name))}', '_blank')`
    : previewable
      ? `openAttPreview('${srcEsc}', '${esc(a.type || '')}', '${esc(a.name || '')}')`
      : `window.open('${srcEsc}', '_blank')`;
  const openDemandCall = `event.stopPropagation();showDetail('${esc(a.demandId)}')`;
  const thumb = kind === 'image' && src
    ? `<div class="att-gal-thumb att-gal-thumb-image" style="background-image:url('${srcEsc}')"></div>`
    : `<div class="att-gal-thumb att-gal-thumb-icon"><i data-lucide="${attIcon(kind)}"></i></div>`;
  return `<div class="att-gal-tile" title="${nameEsc}" onclick="${openCall}">
    ${thumb}
    <div class="att-gal-tile-body">
      <div class="att-gal-tile-name">${nameEsc}</div>
      <button type="button" class="att-gal-tile-demand" title="Abrir demanda" onclick="${openDemandCall}">${demandEsc}</button>
    </div>
  </div>`;
}
function attGalSearch(ctx, val) {
  _attGalState[ctx].search = val || '';
  // Re-render debounced pra não rebuildar em cada tecla.
  clearTimeout(_attGalState[ctx]._t);
  _attGalState[ctx]._t = setTimeout(() => renderAttGallery(ctx), 120);
}
function attGalPickKind(ctx, kind) {
  _attGalState[ctx].kind = kind || '';
  renderAttGallery(ctx);
}

/* Link de info (Drive/Ativos) — mostra o título salvo da página (resolvido no
   save, server-side) e cai pra URL crua quando ainda não há título. Sem fetch:
   a visualização só lê o valor persistido em driveFilesTitle/brandAssetsTitle. */
function renderInfoLink(raw, title, emptyLabel) {
  const url = (raw || '').trim();
  if (!url) return `<div class="client-info-empty">${emptyLabel}</div>`;
  const label = (title && String(title).trim())
    ? String(title).trim()
    : url.replace(/^https?:\/\//i, '').replace(/\/$/, '');
  return `<a class="client-info-link" href="${esc(url)}" target="_blank" rel="noopener" title="${esc(url)}">
    <i data-lucide="external-link" class="ic-sm"></i>
    <span class="client-info-link-label">${esc(label)}</span>
  </a>`;
}

function renderClientDetail(id) {
  const c = clientById(id);
  if (!c) return;

  // Breadcrumb
  const bc = $('client-detail-breadcrumb');
  if (bc) {
    bc.innerHTML = `<span style="color:var(--text-muted);font-weight:500;text-transform:uppercase;letter-spacing:0.05em;font-size:11px">Clientes cadastrados · </span><span>${esc(c.name)}</span>`;
  }

  // KPIs — demandas de todos os projetos deste cliente
  renderDetailKpis('client-detail-kpis', projects.filter(p => p.clientId === id).map(p => p.id));

  // PROJETOS
  const projs = projects.filter(p => p.clientId === id);
  const projGrid = $('client-detail-projects');
  if (!projs.length) {
    projGrid.innerHTML = `<div style="grid-column:1/-1">${emptyState('Nenhum projeto', 'Crie o primeiro projeto deste cliente.', 'inbox')}</div>`;
  } else {
    projGrid.innerHTML = projs.map(p => {
      const statusLabel = p.active === false ? 'Arquivado' : 'Ativo';
      const statusClass = p.active === false ? 'client-card-status--archived' : 'client-card-status--active';
      const avatar = p.avatar
        ? `<div class="client-card-avatar" style="background-image:url('${p.avatar}');background-size:cover;background-position:center"></div>`
        : `<div class="client-card-avatar" style="background:${hexDim(p.color || '#7A00FF')};color:${p.color || '#7A00FF'}">${esc((p.name || 'P').charAt(0).toUpperCase())}</div>`;
      return `<div class="flow-card" onclick="openProjectDetail('${p.id}')">
        ${avatar}
        <div class="flow-card-name">${esc(p.name)}</div>
        <div class="flow-card-sub">${esc(statusLabel)}</div>
      </div>`;
    }).join('');
  }

  // SOBRE — descrição (guidelines), link do drive (driveFiles), ativos (brandAssets).
  // Edição fica no modal do cliente. Aqui é só visualização.
  const descEl = $('client-detail-description');
  const driveEl = $('client-detail-drive');
  const assetsEl = $('client-detail-assets');
  if (descEl) {
    const g = (c.guidelines || '').trim();
    descEl.innerHTML = g
      ? `<div class="client-info-text">${esc(g).replace(/\n/g, '<br>')}</div>`
      : `<div class="client-info-empty">Sem descrição cadastrada.</div>`;
  }
  if (driveEl)  driveEl.innerHTML  = renderInfoLink(c.driveFiles,  c.driveFilesTitle,  'Nenhum link do drive.');
  if (assetsEl) assetsEl.innerHTML = renderInfoLink(c.brandAssets, c.brandAssetsTitle, 'Nenhum link de ativos.');

  // PESSOAS — matriz Área × Cargo. Para cada área com usuários no workspace,
  // renderiza um card com uma linha por Cargo presente nos users daquela área.
  // Persiste em c.roleAssignments: { [area]: { [cargo]: userId } | userId(legado) }.
  renderRoleCargoMatrix('client-detail-people', c, 'setClientRoleCargoAssignment', id);

  // TEMPO DEDICADO
  renderClientTimeBlock(id);
  // GALERIA DE ANEXOS
  renderAttGallery('client');
  paintIcons();
}

function setClientTimePeriod(p) {
  currentClientPeriod = p;
  document.querySelectorAll('.client-time-period').forEach(b => b.classList.toggle('active', b.dataset.period === p));
  if (currentClientId) renderClientTimeBlock(currentClientId);
}

async function setClientRoleAssignment(clientId, roleName, userId) {
  const c = clientById(clientId);
  if (!c) return;
  const next = Object.assign({}, c.roleAssignments || {});
  next[roleName] = userId || null;
  try {
    await api('/clients/' + clientId, 'PUT', { roleAssignments: next });
    // Atualiza cache local sem refetch completo (mudança trivial)
    c.roleAssignments = next;
    renderClientDetail(clientId);
    toast('Responsável padrão atualizado.');
  } catch (e) { toast(e.message, 'error'); }
}

/* ─── Matriz Área × Cargo (Painel Pessoas) ───────────────────────
   entity = client OU project. Persiste em entity.roleAssignments:
     { [area]: { [cargo]: userId } | userId (legado, string) }
   O renderer só mostra combinações (área × cargo) presentes nos usuários do
   workspace daquele entity — evita poluir com cargos vazios. */
function _entityAssignmentValue(entity, area, cargo) {
  const a = entity.roleAssignments && entity.roleAssignments[area];
  if (!a) return '';
  if (typeof a === 'string') {
    // Legado: 1 user pra área sem distinção de cargo. Considera valor pra "qualquer cargo".
    return a;
  }
  return a[cargo] || '';
}
function renderRoleCargoMatrix(elId, entity, handlerName, entityId) {
  const el = document.getElementById(elId);
  if (!el) return;
  const allRoles = (roles || []).slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const allPositions = (positions || []).slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const wsU = (users || []).filter(u => u.active !== false && ((u.workspaces || []).includes(entity.workspaceId) || u.isAdmin));

  if (!allRoles.length) {
    el.innerHTML = `<div class="client-people-empty">Nenhuma área cadastrada. Crie áreas em <a href="#" onclick="event.preventDefault(); goPage('users');">Usuários</a> para definir responsáveis.</div>`;
    return;
  }

  // Pra cada área, quais cargos aparecem nos users daquela área do workspace.
  const cards = allRoles.map(role => {
    const candidatesAll = wsU.filter(u => (u.role || '') === role.name);
    if (!candidatesAll.length) return null; // esconde áreas sem usuário no workspace
    const cargosPresent = allPositions.filter(p => candidatesAll.some(u => (u.position || '') === p.name));
    // Se ninguém tem cargo definido, mostra 1 linha "— Sem cargo —" com o pool inteiro.
    const rows = cargosPresent.length ? cargosPresent.map(p => {
      const cand = candidatesAll.filter(u => (u.position || '') === p.name);
      return _matrixRow(role.name, p.name, cand, entity, handlerName, entityId);
    }).join('') : _matrixRow(role.name, '', candidatesAll, entity, handlerName, entityId);
    return `<div class="rca-card">
      <div class="rca-card-head">${esc(role.name).toUpperCase()}</div>
      <div class="rca-card-body">${rows}</div>
    </div>`;
  }).filter(Boolean).join('');

  el.innerHTML = cards || `<div class="client-people-empty">Nenhum usuário no squad deste cliente tem área definida.</div>`;
  paintIcons();
}
function _matrixRow(area, cargo, candidates, entity, handlerName, entityId) {
  const cur = _entityAssignmentValue(entity, area, cargo);
  const opts = [`<option value="">— Sem responsável —</option>`]
    .concat(candidates.map(u => `<option value="${u.id}" ${u.id === cur ? 'selected' : ''}>${esc(u.name)}</option>`))
    .join('');
  const curUser = cur ? userById(cur) : null;
  const previewAvatar = curUser
    ? avatarHTML(curUser, 'avatar avatar-sm')
    : `<div class="avatar avatar-sm" style="background:var(--surface-2);color:var(--text-muted);display:flex;align-items:center;justify-content:center"><i data-lucide="user" class="ic-xs"></i></div>`;
  const areaEsc = area.replace(/'/g, "\\'");
  const cargoEsc = cargo.replace(/'/g, "\\'");
  return `<div class="rca-row">
    <div class="rca-cargo">${cargo ? esc(cargo).toUpperCase() : '<span style="color:var(--text-muted);font-weight:400">Sem cargo</span>'}</div>
    <div class="rca-avatar">${previewAvatar}</div>
    <select class="form-control rca-select" onchange="${handlerName}('${entityId}', '${areaEsc}', '${cargoEsc}', this.value)">${opts}</select>
  </div>`;
}
async function setClientRoleCargoAssignment(clientId, area, cargo, userId) {
  const c = clientById(clientId);
  if (!c) return;
  const nextRA = Object.assign({}, c.roleAssignments || {});
  // Se o valor atual da área é string (legado), migra pra objeto na primeira mudança.
  let areaMap = nextRA[area];
  if (typeof areaMap === 'string') areaMap = { __legacy__: areaMap };
  if (!areaMap || typeof areaMap !== 'object') areaMap = {};
  else areaMap = Object.assign({}, areaMap);
  if (userId) areaMap[cargo || '__any__'] = userId;
  else delete areaMap[cargo || '__any__'];
  // Se ficou vazio, remove a área do mapa
  if (Object.keys(areaMap).length === 0) delete nextRA[area];
  else nextRA[area] = areaMap;
  try {
    await api('/clients/' + clientId, 'PUT', { roleAssignments: nextRA });
    c.roleAssignments = nextRA;
    renderClientDetail(clientId);
    toast('Responsável atualizado.');
  } catch (e) { toast(e.message, 'error'); }
}
async function setProjectRoleCargoAssignment(projectId, area, cargo, userId) {
  const p = projectById(projectId);
  if (!p) return;
  const nextRA = Object.assign({}, p.roleAssignments || {});
  let areaMap = nextRA[area];
  if (typeof areaMap === 'string') areaMap = { __legacy__: areaMap };
  if (!areaMap || typeof areaMap !== 'object') areaMap = {};
  else areaMap = Object.assign({}, areaMap);
  if (userId) areaMap[cargo || '__any__'] = userId;
  else delete areaMap[cargo || '__any__'];
  if (Object.keys(areaMap).length === 0) delete nextRA[area];
  else nextRA[area] = areaMap;
  try {
    await api('/projects/' + projectId, 'PUT', { roleAssignments: nextRA });
    p.roleAssignments = nextRA;
    renderProjectDetail(projectId);
    toast('Responsável atualizado.');
  } catch (e) { toast(e.message, 'error'); }
}

function renderClientTimeBlock(clientId) {
  const projs = projects.filter(p => p.clientId === clientId);
  const projIds = new Set(projs.map(p => p.id));
  // Filtra time entries
  const today0 = new Date(); today0.setHours(0,0,0,0);
  let fromYmd = null;
  if (currentClientPeriod !== 'all') {
    const days = parseInt(currentClientPeriod, 10) || 90;
    const from = new Date(today0); from.setDate(from.getDate() - (days - 1));
    fromYmd = from.toISOString().slice(0,10);
  }
  const inRange = (e) => {
    if (!fromYmd) return true;
    const when = ((e.start || e.createdAt || '') + '').slice(0,10);
    return when >= fromYmd;
  };
  let totalHours = 0;
  const byUser = new Map();
  const byDay = new Map();
  demands.forEach(d => {
    if (!projIds.has(d.projectId)) return;
    (d.timeEntries || []).forEach(e => {
      if (!inRange(e)) return;
      const h = Number(e.hours) || 0;
      totalHours += h;
      if (e.userId) byUser.set(e.userId, (byUser.get(e.userId) || 0) + h);
      const day = ((e.start || e.createdAt || '') + '').slice(0,10);
      if (day) byDay.set(day, (byDay.get(day) || 0) + h);
    });
  });

  $('client-time-value').textContent = fmtHours(totalHours);

  // Lista de usuários — ordenado por horas (decrescente) + barra de progresso
  const days = currentClientPeriod === 'all' ? 30 : parseInt(currentClientPeriod, 10);
  let businessDays = 0;
  for (let i = 0; i < days; i++) {
    const d = new Date(today0); d.setDate(d.getDate() - i);
    if (d.getDay() !== 0 && d.getDay() !== 6) businessDays++;
  }
  const capacity = businessDays * 8;
  const rows = [...byUser.entries()]
    .map(([uid, h]) => ({ u: userById(uid), hours: h }))
    .filter(r => r.u)
    .sort((a, b) => b.hours - a.hours);
  const rowsEl = $('client-time-rows');
  if (!rows.length) {
    rowsEl.innerHTML = `<div class="client-people-empty">Ninguém apontou horas nos projetos deste cliente no período selecionado.</div>`;
  } else {
    rowsEl.innerHTML = rows.map(r => {
      const pct = capacity > 0 ? Math.min(150, Math.round((r.hours / capacity) * 100)) : 0;
      const status = pct >= 100 ? 'overload' : pct >= 75 ? 'high' : pct >= 40 ? 'medium' : 'low';
      return `<div class="client-time-row">
        <div class="client-time-user">
          ${avatarHTML(r.u, 'avatar')}
          <div>
            <div class="client-time-user-name">${esc(r.u.name)}</div>
            <div class="client-time-user-role">${esc(r.u.role || '—')}</div>
          </div>
        </div>
        <div class="client-time-meta">
          <span class="client-time-pct">${pct}%</span>
          <span class="client-time-hh">${fmtHours(r.hours)} / ${capacity}h</span>
        </div>
        <div class="capacity-bar-track" style="flex:1;max-width:none">
          <div class="capacity-bar-fill ${status}" style="width:${Math.min(100, pct)}%"></div>
        </div>
      </div>`;
    }).join('');
  }

  // Chart: linha de horas por dia (últimos N dias)
  const chartEl = $('client-time-chart');
  if (chartEl) {
    // Sem apontamentos no período → esconde o gráfico "linha morta" e mostra
    // empty state proporcional. Reaproveita o helper unificado.
    if (totalHours === 0) {
      chartEl.innerHTML = `<div class="client-chart-wrap client-chart-wrap--empty">
        ${emptyState('Sem apontamentos no período', 'Quando alguém apontar horas em demandas deste cliente, o gráfico aparece aqui.', 'calendar')}
      </div>`;
      paintIcons();
      return;
    }
    const buckets = [];
    const dayCount = currentClientPeriod === 'all' ? 30 : Math.min(90, parseInt(currentClientPeriod, 10) || 30);
    for (let i = dayCount - 1; i >= 0; i--) {
      const d = new Date(today0); d.setDate(d.getDate() - i);
      const ymd = d.toISOString().slice(0,10);
      buckets.push({ ymd, hours: byDay.get(ymd) || 0, day: d });
    }
    const max = Math.max(1, ...buckets.map(b => b.hours));
    const w = 760, h = 180, padL = 30, padR = 16, padT = 14, padB = 22;
    const innerW = w - padL - padR;
    const innerH = h - padT - padB;
    const xStep = innerW / Math.max(1, buckets.length - 1);
    const points = buckets.map((b, i) => [padL + i * xStep, padT + innerH - (b.hours / max) * innerH]);
    const linePath = points.length ? 'M ' + points.map(p => `${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(' L ') : '';
    const areaPath = points.length ? `${linePath} L ${points[points.length-1][0].toFixed(1)} ${padT + innerH} L ${points[0][0].toFixed(1)} ${padT + innerH} Z` : '';
    const peak = Math.ceil(max);
    // preserveAspectRatio="none" estica X e Y independentemente — <text> nativo
    // dentro do SVG sai deformado. Labels do eixo Y ficam em HTML absoluto sobre
    // o wrap, com posições em % (invariantes à escala do SVG).
    const yTopPct  = (padT / h) * 100;
    const yMidPct  = ((padT + innerH/2) / h) * 100;
    const yBotPct  = ((padT + innerH) / h) * 100;
    chartEl.innerHTML = `<div class="client-chart-wrap">
      <div class="client-chart-head">
        <div class="client-chart-title">Horas</div>
        <div class="client-chart-value">${fmtHours(totalHours)} <span class="client-chart-delta">no período</span></div>
      </div>
      <div class="chart-hover-host chart-with-axis" id="cli-chart-host">
        <div class="chart-y-axis">
          <span class="chart-y-tick" style="top:${yTopPct.toFixed(2)}%">${peak}h</span>
          <span class="chart-y-tick" style="top:${yMidPct.toFixed(2)}%">${Math.round(peak/2)}h</span>
          <span class="chart-y-tick" style="top:${yBotPct.toFixed(2)}%">0</span>
        </div>
        <svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" style="width:100%;height:200px;display:block">
          <defs>
            <linearGradient id="clientHoursGrad" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stop-color="#3CE3A0" stop-opacity="0.35"/>
              <stop offset="100%" stop-color="#3CE3A0" stop-opacity="0"/>
            </linearGradient>
          </defs>
          <g stroke="rgba(255,255,255,0.05)" stroke-width="1" vector-effect="non-scaling-stroke">
            <line x1="${padL}" y1="${padT}" x2="${w - padR}" y2="${padT}"/>
            <line x1="${padL}" y1="${padT + innerH/2}" x2="${w - padR}" y2="${padT + innerH/2}"/>
            <line x1="${padL}" y1="${padT + innerH}" x2="${w - padR}" y2="${padT + innerH}"/>
          </g>
          ${areaPath ? `<path d="${areaPath}" fill="url(#clientHoursGrad)"/>` : ''}
          ${linePath ? `<path d="${linePath}" fill="none" stroke="#3CE3A0" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>` : ''}
          <line id="cli-chart-guide" class="chart-guide" x1="0" y1="${padT}" x2="0" y2="${padT + innerH}" stroke="rgba(255,255,255,0.35)" stroke-width="1" vector-effect="non-scaling-stroke" style="opacity:0;pointer-events:none"/>
          <circle id="cli-chart-marker" r="4" fill="#3CE3A0" stroke="#fff" stroke-width="1.5" vector-effect="non-scaling-stroke" style="opacity:0;pointer-events:none"/>
        </svg>
        <div class="chart-tooltip" id="cli-chart-tooltip"></div>
      </div>
    </div>`;
    // Wire hover
    const host = $('cli-chart-host');
    if (host && points.length) {
      const tipPoints = buckets.map((b, i) => ({
        x: points[i][0], label: new Date(b.ymd + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' }),
        series: [{ name: 'Horas', value: b.hours, y: points[i][1], color: '#3CE3A0' }]
      }));
      attachChartHover(host, {
        viewBox: { w, h, padL, padR, padT, innerH },
        points: tipPoints,
        lineEls: $('cli-chart-guide'),
        markerEls: [$('cli-chart-marker')],
        tooltipEl: $('cli-chart-tooltip'),
        format: (v) => v > 0 ? fmtHours(v) : '0h'
      });
    }
  }
}

/* ─── PROJETO: detalhe (view compartilhando page-clients) ─────────────
   Segue a mesma estrutura do detalhe de cliente:
   - SOBRE (descrição, drive, ativos) — vindo de project.driveFiles/brandAssets/guidelines
   - PESSOAS (usuário padrão por função) — vindo de project.roleAssignments
     Herdado do cliente na criação, edições INDEPENDENTES daqui pra frente.
   - TEMPO DEDICADO — só demandas do próprio projeto. */
function renderProjectDetail(id) {
  const p = projectById(id);
  if (!p) return;
  const c = p.clientId ? clientById(p.clientId) : null;

  // Breadcrumb: "Cliente · Projeto"
  const bc = $('project-detail-breadcrumb');
  if (bc) {
    const clientPart = c
      ? `<a href="#" onclick="event.preventDefault(); openClient('${c.id}')" style="color:var(--text-muted);font-weight:500;text-transform:uppercase;letter-spacing:0.05em;font-size:11px;text-decoration:none">${esc(c.name)}</a>`
      : `<span style="color:var(--text-muted);font-weight:500;text-transform:uppercase;letter-spacing:0.05em;font-size:11px">Sem cliente</span>`;
    bc.innerHTML = `${clientPart}<span style="color:var(--text-muted);font-weight:500;font-size:11px"> · </span><span>${esc(p.name)}</span>`;
  }

  // KPIs — demandas deste projeto
  renderDetailKpis('project-detail-kpis', [id]);

  // SOBRE
  const descEl = $('project-detail-description');
  const driveEl = $('project-detail-drive');
  const assetsEl = $('project-detail-assets');
  if (descEl) {
    const g = (p.guidelines || '').trim();
    descEl.innerHTML = g
      ? `<div class="client-info-text">${esc(g).replace(/\n/g, '<br>')}</div>`
      : `<div class="client-info-empty">Sem descrição cadastrada.</div>`;
  }
  if (driveEl)  driveEl.innerHTML  = renderInfoLink(p.driveFiles,  p.driveFilesTitle,  'Nenhum link do drive.');
  if (assetsEl) assetsEl.innerHTML = renderInfoLink(p.brandAssets, p.brandAssetsTitle, 'Nenhum link de ativos.');

  // PESSOAS — matriz Área × Cargo (mesmo helper do cliente, agora com project.roleAssignments).
  renderRoleCargoMatrix('project-detail-people', p, 'setProjectRoleCargoAssignment', id);

  renderProjectTimeBlock(id);
  // GALERIA DE ANEXOS
  renderAttGallery('project');
  paintIcons();
}

// Helpers de tarefa (usados pela tab Demandas de Listas de Tarefas).
// Ciclo de vida: sem demandId ou demanda excluída → pode gerar; ativa → abrir;
// concluída no fluxo → mostra ✓ + abrir.
function _taskLinkedDemand(t) {
  if (!t.demandId) return null;
  const d = demandById(t.demandId);
  if (!d || d.deletedAt) return null;
  return d;
}
function _taskIsDone(t) {
  const d = _taskLinkedDemand(t);
  return !!(d && isDone(d));
}
async function confirmDeleteTask(taskId) {
  const t = (tasks || []).find(x => x.id === taskId);
  if (!t) return;
  const ok = await showConfirm({
    title: 'Remover tarefa?',
    message: `Remover <strong>${esc(t.name)}</strong> da lista de tarefas?<br><br>A demanda vinculada (se houver) não é afetada.`,
    okLabel: 'Remover',
    danger: true
  });
  if (!ok) return;
  try {
    await api('/tasks/' + t.id, 'DELETE');
    tasks = tasks.filter(x => x.id !== t.id);
    renderCurrent();
  } catch (e) { toast(e.message, 'error'); }
}

function setProjectTimePeriod(period) {
  currentProjectPeriod = period;
  document.querySelectorAll('.project-time-period').forEach(b => b.classList.toggle('active', b.dataset.period === period));
  if (currentProjectId) renderProjectTimeBlock(currentProjectId);
}

async function setProjectRoleAssignment(projectId, roleName, userId) {
  const p = projectById(projectId);
  if (!p) return;
  const next = Object.assign({}, p.roleAssignments || {});
  next[roleName] = userId || null;
  try {
    await api('/projects/' + projectId, 'PUT', { roleAssignments: next });
    p.roleAssignments = next;
    renderProjectDetail(projectId);
    toast('Responsável padrão do projeto atualizado.');
  } catch (e) { toast(e.message, 'error'); }
}

function renderProjectTimeBlock(projectId) {
  const today0 = new Date(); today0.setHours(0,0,0,0);
  let fromYmd = null;
  if (currentProjectPeriod !== 'all') {
    const days = parseInt(currentProjectPeriod, 10) || 90;
    const from = new Date(today0); from.setDate(from.getDate() - (days - 1));
    fromYmd = from.toISOString().slice(0,10);
  }
  const inRange = (e) => {
    if (!fromYmd) return true;
    const when = ((e.start || e.createdAt || '') + '').slice(0,10);
    return when >= fromYmd;
  };
  let totalHours = 0;
  const byUser = new Map();
  const byDay = new Map();
  demands.forEach(d => {
    if (d.projectId !== projectId) return;
    (d.timeEntries || []).forEach(e => {
      if (!inRange(e)) return;
      const h = Number(e.hours) || 0;
      totalHours += h;
      if (e.userId) byUser.set(e.userId, (byUser.get(e.userId) || 0) + h);
      const day = ((e.start || e.createdAt || '') + '').slice(0,10);
      if (day) byDay.set(day, (byDay.get(day) || 0) + h);
    });
  });

  $('project-time-value').textContent = fmtHours(totalHours);

  // Lista de usuários — mesmo layout do cliente.
  const days = currentProjectPeriod === 'all' ? 30 : parseInt(currentProjectPeriod, 10);
  let businessDays = 0;
  for (let i = 0; i < days; i++) {
    const d = new Date(today0); d.setDate(d.getDate() - i);
    if (d.getDay() !== 0 && d.getDay() !== 6) businessDays++;
  }
  const capacity = businessDays * 8;
  const rows = [...byUser.entries()]
    .map(([uid, h]) => ({ u: userById(uid), hours: h }))
    .filter(r => r.u)
    .sort((a, b) => b.hours - a.hours);
  const rowsEl = $('project-time-rows');
  if (!rows.length) {
    rowsEl.innerHTML = `<div class="client-people-empty">Ninguém apontou horas neste projeto no período selecionado.</div>`;
  } else {
    rowsEl.innerHTML = rows.map(r => {
      const pct = capacity > 0 ? Math.min(150, Math.round((r.hours / capacity) * 100)) : 0;
      const status = pct >= 100 ? 'overload' : pct >= 75 ? 'high' : pct >= 40 ? 'medium' : 'low';
      return `<div class="client-time-row">
        <div class="client-time-user">
          ${avatarHTML(r.u, 'avatar')}
          <div>
            <div class="client-time-user-name">${esc(r.u.name)}</div>
            <div class="client-time-user-role">${esc(r.u.role || '—')}</div>
          </div>
        </div>
        <div class="client-time-meta">
          <span class="client-time-pct">${pct}%</span>
          <span class="client-time-hh">${fmtHours(r.hours)} / ${capacity}h</span>
        </div>
        <div class="capacity-bar-track" style="flex:1;max-width:none">
          <div class="capacity-bar-fill ${status}" style="width:${Math.min(100, pct)}%"></div>
        </div>
      </div>`;
    }).join('');
  }

  // Gráfico de horas por dia — mesmo layout do cliente.
  const chartEl = $('project-time-chart');
  if (chartEl) {
    if (totalHours === 0) {
      chartEl.innerHTML = `<div class="client-chart-wrap client-chart-wrap--empty">
        ${emptyState('Sem apontamentos no período', 'Quando alguém apontar horas em demandas deste projeto, o gráfico aparece aqui.', 'calendar')}
      </div>`;
      paintIcons();
      return;
    }
    const buckets = [];
    const dayCount = currentProjectPeriod === 'all' ? 30 : Math.min(90, parseInt(currentProjectPeriod, 10) || 30);
    for (let i = dayCount - 1; i >= 0; i--) {
      const d = new Date(today0); d.setDate(d.getDate() - i);
      const ymd = d.toISOString().slice(0,10);
      buckets.push({ ymd, hours: byDay.get(ymd) || 0, day: d });
    }
    const max = Math.max(1, ...buckets.map(b => b.hours));
    const w = 760, h = 180, padL = 30, padR = 16, padT = 14, padB = 22;
    const innerW = w - padL - padR;
    const innerH = h - padT - padB;
    const xStep = innerW / Math.max(1, buckets.length - 1);
    const points = buckets.map((b, i) => [padL + i * xStep, padT + innerH - (b.hours / max) * innerH]);
    const linePath = points.length ? 'M ' + points.map(pt => `${pt[0].toFixed(1)} ${pt[1].toFixed(1)}`).join(' L ') : '';
    const areaPath = points.length ? `${linePath} L ${points[points.length-1][0].toFixed(1)} ${padT + innerH} L ${points[0][0].toFixed(1)} ${padT + innerH} Z` : '';
    const peak = Math.ceil(max);
    // Labels do eixo Y em HTML (fora do SVG stretchado — evita texto deformado).
    const yTopPct = (padT / h) * 100;
    const yMidPct = ((padT + innerH/2) / h) * 100;
    const yBotPct = ((padT + innerH) / h) * 100;
    chartEl.innerHTML = `<div class="client-chart-wrap">
      <div class="client-chart-head">
        <div class="client-chart-title">Horas</div>
        <div class="client-chart-value">${fmtHours(totalHours)} <span class="client-chart-delta">no período</span></div>
      </div>
      <div class="chart-hover-host chart-with-axis" id="proj-chart-host">
        <div class="chart-y-axis">
          <span class="chart-y-tick" style="top:${yTopPct.toFixed(2)}%">${peak}h</span>
          <span class="chart-y-tick" style="top:${yMidPct.toFixed(2)}%">${Math.round(peak/2)}h</span>
          <span class="chart-y-tick" style="top:${yBotPct.toFixed(2)}%">0</span>
        </div>
        <svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" style="width:100%;height:200px;display:block">
          <defs>
            <linearGradient id="projectHoursGrad" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stop-color="#3CE3A0" stop-opacity="0.35"/>
              <stop offset="100%" stop-color="#3CE3A0" stop-opacity="0"/>
            </linearGradient>
          </defs>
          <g stroke="rgba(255,255,255,0.05)" stroke-width="1" vector-effect="non-scaling-stroke">
            <line x1="${padL}" y1="${padT}" x2="${w - padR}" y2="${padT}"/>
            <line x1="${padL}" y1="${padT + innerH/2}" x2="${w - padR}" y2="${padT + innerH/2}"/>
            <line x1="${padL}" y1="${padT + innerH}" x2="${w - padR}" y2="${padT + innerH}"/>
          </g>
          ${areaPath ? `<path d="${areaPath}" fill="url(#projectHoursGrad)"/>` : ''}
          ${linePath ? `<path d="${linePath}" fill="none" stroke="#3CE3A0" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>` : ''}
          <line id="proj-chart-guide" x1="0" y1="${padT}" x2="0" y2="${padT + innerH}" stroke="var(--text-muted)" stroke-width="1" stroke-dasharray="3 3" opacity="0" vector-effect="non-scaling-stroke"/>
          <circle id="proj-chart-marker" cx="0" cy="0" r="4" fill="#3CE3A0" opacity="0"/>
        </svg>
        <div class="chart-tooltip" id="proj-chart-tooltip"></div>
      </div>
    </div>`;
    const host = $('proj-chart-host');
    if (host && points.length) {
      const tipPoints = buckets.map((b, i) => ({
        x: points[i][0], label: new Date(b.ymd + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' }),
        series: [{ name: 'Horas', value: b.hours, y: points[i][1], color: '#3CE3A0' }]
      }));
      attachChartHover(host, {
        viewBox: { w, h, padL, padR, padT, innerH },
        points: tipPoints,
        lineEls: $('proj-chart-guide'),
        markerEls: [$('proj-chart-marker')],
        tooltipEl: $('proj-chart-tooltip'),
        format: (v) => v > 0 ? fmtHours(v) : '0h'
      });
    }
  }
}

/* ─── RELATÓRIO MENSAL DO CLIENTE ───────────────────────────────────
   View print-friendly agregando o que foi feito no mês:
   demandas entregues, horas por função, horas por responsável, dados do cliente.
   Estado independente (currentReportMonth) — o mês pode ser trocado sem sair. */
let currentReportMonth = null; // 'YYYY-MM'
let currentProjectReportMonth = null; // idem, escopo por projeto

function openClientReport() {
  if (!currentClientId) { toast('Nenhum cliente selecionado', 'warn'); return; }
  if (!currentReportMonth) currentReportMonth = new Date().toISOString().slice(0,7);
  showClientReportView();
  renderClientReport(currentClientId);
  navPush(clientPath(currentClientId) + '/report');
}
function closeClientReport() {
  const cid = currentClientId;
  if (cid && clientById(cid)) {
    showClientDetailView();
    renderClientDetail(cid);
    navPush(clientPath(cid));
  } else {
    closeClientDetail();
  }
}
function setReportMonth(ym) {
  currentReportMonth = ym;
  if (currentClientId) renderClientReport(currentClientId);
}
// Carrega jsPDF sob demanda — ~365KB no boot pra um recurso raro.
// Servido local em /vendor/ pra não bater no CSP ('self' only).
// UMD do jsPDF expõe window.jspdf.jsPDF. Cachea a Promise pra concorrência.
let _jspdfPromise = null;
function loadJsPDF() {
  if (window.jspdf && window.jspdf.jsPDF) return Promise.resolve(window.jspdf.jsPDF);
  if (_jspdfPromise) return _jspdfPromise;
  _jspdfPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = '/vendor/jspdf.umd.min.js';
    s.onload  = () => {
      if (window.jspdf && window.jspdf.jsPDF) resolve(window.jspdf.jsPDF);
      else reject(new Error('jsPDF carregou mas não expôs a API esperada'));
    };
    s.onerror = () => reject(new Error('Falha ao carregar gerador de PDF'));
    document.head.appendChild(s);
  });
  return _jspdfPromise;
}

// Download do PDF gerado PROGRAMATICAMENTE via jsPDF (bundled em html2pdf.bundle).
// Diferente do fluxo antigo (screenshot com html2canvas), aqui construímos cada
// bloco por API — texto selecionável, tamanho pequeno, paginação previsível,
// não depende de viewport / CSS ativo.
async function downloadClientReport() {
  if (!currentClientId) return;
  const c = clientById(currentClientId);
  if (!c) return;
  const ym = currentReportMonth || new Date().toISOString().slice(0,7);
  const [year, mon] = ym.split('-').map(Number);
  const monthNum = ym.split('-')[1] || '';
  const monthLabel = `${MONTHS[mon - 1]} de ${year}`;
  const sanitize = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '').trim();
  const filename = `Relatório Mensal ${monthNum} - ${sanitize(c.name)} - reWork.pdf`;

  toast('Gerando PDF…');
  try {
    const jsPDF = await loadJsPDF();

    // ── Agregações do período (mesma lógica do renderClientReport) ──
    const projs = projects.filter(p => p.clientId === c.id);
    const projIds = new Set(projs.map(p => p.id));
    const projectsActive = projs.filter(p => p.active !== false).length;
    const clientDemands = demands.filter(d => projIds.has(d.projectId));
    const delivered = clientDemands.filter(d => d.completedAt && d.completedAt.slice(0,7) === ym);
    const inProgress = clientDemands.filter(d => !isDone(d));
    let totalHours = 0;
    const hoursByRole = new Map();
    const hoursByUser = new Map();
    clientDemands.forEach(d => {
      (d.timeEntries || []).forEach(e => {
        const when = ((e.start || e.createdAt || '') + '').slice(0,7);
        if (when !== ym) return;
        const h = Number(e.hours) || 0;
        totalHours += h;
        if (e.userId) hoursByUser.set(e.userId, (hoursByUser.get(e.userId) || 0) + h);
        const u = e.userId ? userById(e.userId) : null;
        const role = u?.role || '—';
        hoursByRole.set(role, (hoursByRole.get(role) || 0) + h);
      });
    });

    // ── Setup do doc ──
    const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
    const PAGE_W = 210, PAGE_H = 297;
    const MARGIN = 15;
    const CONTENT_W = PAGE_W - MARGIN * 2;
    const FOOT_RESERVED = 12; // espaço reservado no rodapé pra footer

    // Paleta consistente com o resto do app.
    const ACCENT = [122, 0, 255];     // #7A00FF
    const TEXT   = [24, 24, 27];       // #18181B
    const MUTED  = [82, 82, 91];       // #52525B
    const BORDER = [228, 228, 231];    // #E4E4E7
    const BG     = [249, 250, 251];    // #F9FAFB
    const HEADBG = [244, 244, 245];    // #F4F4F5
    const RED    = [239, 68, 68];      // #EF4444
    const RED_BG = [254, 226, 226];    // #FEE2E2

    let cursor = MARGIN;
    let pageIdx = 1;

    // ── Utilidades ──
    const truncate = (s, n) => {
      s = String(s || '—');
      return s.length > n ? s.slice(0, n - 1) + '…' : s;
    };
    const setColor = (rgb, kind = 'text') => {
      if (kind === 'text') doc.setTextColor(rgb[0], rgb[1], rgb[2]);
      if (kind === 'fill') doc.setFillColor(rgb[0], rgb[1], rgb[2]);
      if (kind === 'draw') doc.setDrawColor(rgb[0], rgb[1], rgb[2]);
    };
    const ensureSpace = (needed) => {
      if (cursor + needed > PAGE_H - MARGIN - FOOT_RESERVED) {
        doc.addPage();
        pageIdx++;
        cursor = MARGIN;
      }
    };

    // ── Header ──
    const headerH = 30;
    setColor(BG, 'fill');
    setColor(BORDER, 'draw');
    doc.roundedRect(MARGIN, cursor, CONTENT_W, headerH, 2, 2, 'FD');
    // Eyebrow accent
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8);
    setColor(ACCENT);
    doc.text('RELATÓRIO MENSAL', MARGIN + 8, cursor + 9);
    // Nome do cliente
    doc.setFontSize(20);
    setColor(TEXT);
    doc.text(truncate(c.name, 45), MARGIN + 8, cursor + 19, { maxWidth: CONTENT_W - 16 });
    // Mês por extenso
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    setColor(MUTED);
    doc.text(monthLabel, MARGIN + 8, cursor + 26);
    cursor += headerH + 8;

    // ── KPIs (4 cards em uma linha) ──
    const kpis = [
      { label: 'ENTREGUES NO MÊS',  value: String(delivered.length) },
      { label: 'EM ANDAMENTO',      value: String(inProgress.length) },
      { label: 'HORAS APONTADAS',   value: fmtHours(totalHours) },
      { label: 'PROJETOS ATIVOS',   value: String(projectsActive) }
    ];
    const kpiGap = 4;
    const kpiW = (CONTENT_W - kpiGap * 3) / 4;
    const kpiH = 22;
    kpis.forEach((k, i) => {
      const x = MARGIN + i * (kpiW + kpiGap);
      setColor([255,255,255], 'fill');
      setColor(BORDER, 'draw');
      doc.roundedRect(x, cursor, kpiW, kpiH, 2, 2, 'FD');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7);
      setColor(MUTED);
      doc.text(k.label, x + 4, cursor + 6.5);
      doc.setFontSize(16);
      setColor(TEXT);
      doc.text(k.value, x + 4, cursor + 17);
    });
    cursor += kpiH + 10;

    // ── Helper: título de seção ──
    const drawSectionTitle = (title) => {
      ensureSpace(10);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      setColor(MUTED);
      doc.text(title, MARGIN, cursor);
      cursor += 5;
    };
    // Helper: box vazio ("nenhuma demanda...", etc)
    const drawEmptyBox = (msg) => {
      ensureSpace(14);
      setColor(BG, 'fill');
      setColor(BORDER, 'draw');
      doc.roundedRect(MARGIN, cursor, CONTENT_W, 12, 2, 2, 'FD');
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(9);
      setColor(MUTED);
      doc.text(msg, PAGE_W / 2, cursor + 7.5, { align: 'center' });
      cursor += 16;
    };

    // ── Demandas entregues ──
    drawSectionTitle('DEMANDAS ENTREGUES');

    if (!delivered.length) {
      drawEmptyBox(`Nenhuma demanda entregue em ${monthLabel.toLowerCase()}.`);
    } else {
      const cols = [
        { label: 'DEMANDA',      w: 55 },
        { label: 'PROJETO',      w: 32 },
        { label: 'RESPONSÁVEL',  w: 30 },
        { label: 'PRAZO',        w: 20 },
        { label: 'ENTREGA',      w: 26 },
        { label: 'HORAS',        w: 17, align: 'right' }
      ]; // soma = 180
      const rowH = 8;

      const drawTableHeader = () => {
        setColor(HEADBG, 'fill');
        setColor(BORDER, 'draw');
        doc.rect(MARGIN, cursor, CONTENT_W, rowH, 'FD');
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(7);
        setColor(MUTED);
        let cx = MARGIN;
        cols.forEach(col => {
          const tx = col.align === 'right' ? cx + col.w - 3 : cx + 3;
          doc.text(col.label, tx, cursor + 5, { align: col.align || 'left' });
          cx += col.w;
        });
        cursor += rowH;
      };

      drawTableHeader();
      const sorted = delivered.slice().sort((a, b) => (a.completedAt || '').localeCompare(b.completedAt || ''));
      for (const d of sorted) {
        // Paginação: se não couber, addPage + redesenha o header
        if (cursor + rowH > PAGE_H - MARGIN - FOOT_RESERVED) {
          doc.addPage(); pageIdx++; cursor = MARGIN;
          drawTableHeader();
        }
        const proj = projectById(d.projectId);
        const owner = d.ownerId ? userById(d.ownerId) : null;
        const dh = (d.timeEntries || []).reduce((sum, e) => sum + (Number(e.hours) || 0), 0);
        const late = wasLate(d);

        // Linha
        setColor([255,255,255], 'fill');
        setColor(BORDER, 'draw');
        doc.rect(MARGIN, cursor, CONTENT_W, rowH, 'FD');
        let cx = MARGIN;
        doc.setFontSize(9);
        // Demanda (bold)
        doc.setFont('helvetica', 'bold');
        setColor(TEXT);
        doc.text(truncate(d.name, 34), cx + 3, cursor + 5.3);
        cx += cols[0].w;
        // Projeto
        doc.setFont('helvetica', 'normal');
        doc.text(truncate(proj?.name || '—', 18), cx + 3, cursor + 5.3);
        cx += cols[1].w;
        // Responsável
        doc.text(owner ? truncate(owner.name, 16) : '—', cx + 3, cursor + 5.3);
        cx += cols[2].w;
        // Prazo
        doc.text(d.deadline ? fmtDate(d.deadline) : '—', cx + 3, cursor + 5.3);
        cx += cols[3].w;
        // Entrega (com tag ATRASADA)
        if (late) setColor(RED); else setColor(TEXT);
        doc.text(d.completedAt ? fmtDate(d.completedAt) : '—', cx + 3, cursor + 5.3);
        if (late) {
          doc.setFontSize(6);
          const tw = doc.getTextWidth('ATRASADA') + 2;
          setColor(RED_BG, 'fill');
          doc.roundedRect(cx + 15, cursor + 1.8, tw, 4, 0.5, 0.5, 'F');
          setColor(RED);
          doc.text('ATRASADA', cx + 16, cursor + 4.9);
          doc.setFontSize(9);
        }
        cx += cols[4].w;
        // Horas (right)
        setColor(TEXT);
        doc.setFont('helvetica', 'bold');
        doc.text(fmtHours(dh), cx + cols[5].w - 3, cursor + 5.3, { align: 'right' });
        cursor += rowH;
      }
      cursor += 6;
    }

    // ── Helper: seção de barras horizontais ──
    const drawBarSection = (title, entries, emptyMsg, labelResolver) => {
      drawSectionTitle(title);
      if (!entries.length) {
        drawEmptyBox(emptyMsg);
        return;
      }
      const rowH = 9;
      const labelW = 55;
      const valueW = 22;
      const barW = CONTENT_W - labelW - valueW - 6;
      const barH = 4;
      const max = Math.max(...entries.map(([, h]) => h));
      for (const [key, h] of entries) {
        ensureSpace(rowH);
        const label = labelResolver ? labelResolver(key) : String(key);
        // Label
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(9);
        setColor(TEXT);
        doc.text(truncate(label, 30), MARGIN, cursor + 5);
        // Bar track
        const barX = MARGIN + labelW;
        const barY = cursor + 3;
        setColor([230, 230, 234], 'fill');
        doc.roundedRect(barX, barY, barW, barH, 1, 1, 'F');
        // Bar fill
        const pct = max > 0 ? (h / max) : 0;
        setColor(ACCENT, 'fill');
        doc.roundedRect(barX, barY, Math.max(0.5, barW * pct), barH, 1, 1, 'F');
        // Value
        doc.setFontSize(9);
        setColor(TEXT);
        doc.text(fmtHours(h), MARGIN + CONTENT_W, cursor + 5, { align: 'right' });
        cursor += rowH;
      }
      cursor += 6;
    };

    const roleEntries = [...hoursByRole.entries()].sort((a, b) => b[1] - a[1]);
    drawBarSection('HORAS POR FUNÇÃO', roleEntries, 'Sem horas apontadas neste mês.');

    const userEntries = [...hoursByUser.entries()]
      .filter(([uid]) => userById(uid))
      .sort((a, b) => b[1] - a[1]);
    drawBarSection('HORAS POR RESPONSÁVEL', userEntries, 'Ninguém apontou horas neste mês.',
      (uid) => userById(uid)?.name || 'Usuário');

    // ── Footer em cada página ──
    const totalPages = doc.internal.getNumberOfPages();
    const genLabel = `Gerado em ${new Date().toLocaleString('pt-BR')} · reWork`;
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      setColor(MUTED);
      doc.text(genLabel, MARGIN, PAGE_H - MARGIN + 4);
      doc.text(`${i} / ${totalPages}`, PAGE_W - MARGIN, PAGE_H - MARGIN + 4, { align: 'right' });
    }

    doc.save(filename);
    toast('Relatório baixado!');
  } catch (e) {
    console.error('[downloadClientReport]', e);
    toast(e.message || 'Erro ao gerar PDF', 'error');
  }
}

// ── Month picker (popover com grid + navegação de ano) ─────────────
// Reutilizável: cada "kind" (client, project) tem seus IDs de DOM e uma
// dupla getMonth/setMonth. Só uma instância pode estar aberta por vez —
// _mpState guarda kind ativo + ano em exibição.
const MONTHS_SHORT = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
const MP_KIND = {
  client: {
    pickerId: 'report-month-picker',
    popoverId: 'mp-popover',
    labelId:   'mp-label',
    yearId:    'mp-year',
    gridId:    'mp-months',
    getMonth: () => currentReportMonth,
    setMonth: (ym) => { setReportMonth(ym); }
  },
  project: {
    pickerId: 'preport-month-picker',
    popoverId: 'pmp-popover',
    labelId:   'pmp-label',
    yearId:    'pmp-year',
    gridId:    'pmp-months',
    getMonth: () => currentProjectReportMonth,
    setMonth: (ym) => { setProjectReportMonth(ym); }
  }
};
let _mpState = null; // null = fechado | { kind, yearShown }

function toggleMp(kind, e) {
  if (e) e.stopPropagation();
  if (_mpState?.kind === kind) closeMp();
  else openMp(kind);
}
function openMp(kind) {
  const cfg = MP_KIND[kind]; if (!cfg) return;
  const pop = $(cfg.popoverId); if (!pop) return;
  // Fecha qualquer outro que estivesse aberto (guarda de sanidade)
  if (_mpState && _mpState.kind !== kind) closeMp();
  const ym = cfg.getMonth() || new Date().toISOString().slice(0,7);
  _mpState = { kind, yearShown: parseInt(ym.split('-')[0], 10) };
  pop.classList.add('open');
  renderMpGrid();
}
function closeMp() {
  if (!_mpState) return;
  const cfg = MP_KIND[_mpState.kind];
  const pop = $(cfg.popoverId);
  if (pop) pop.classList.remove('open');
  _mpState = null;
}
function mpChangeYear(delta) {
  if (!_mpState) return;
  _mpState.yearShown += delta;
  renderMpGrid();
}
function mpSelectMonth(m) {
  if (!_mpState) return;
  const cfg = MP_KIND[_mpState.kind];
  const y = _mpState.yearShown;
  const ym = `${y}-${String(m).padStart(2,'0')}`;
  cfg.setMonth(ym);
  closeMp();
}
function mpJumpToday() {
  if (!_mpState) return;
  const now = new Date();
  _mpState.yearShown = now.getFullYear();
  mpSelectMonth(now.getMonth() + 1);
}
document.addEventListener('click', (e) => {
  if (!_mpState) return;
  const cfg = MP_KIND[_mpState.kind];
  const wrap = $(cfg.pickerId);
  if (wrap && !wrap.contains(e.target)) closeMp();
});
document.addEventListener('keydown', (e) => {
  if (_mpState && e.key === 'Escape') { e.preventDefault(); closeMp(); }
});

// Sincroniza label do trigger + grid (se estiver aberto naquele kind).
function renderMp(kind) {
  const cfg = MP_KIND[kind]; if (!cfg) return;
  const ym = cfg.getMonth() || new Date().toISOString().slice(0,7);
  const [y, m] = ym.split('-').map(Number);
  const lbl = $(cfg.labelId);
  if (lbl) lbl.textContent = `${MONTHS[m - 1]} de ${y}`;
  if (_mpState?.kind === kind) renderMpGrid();
}
function renderMpGrid() {
  if (!_mpState) return;
  const cfg = MP_KIND[_mpState.kind];
  const yearEl = $(cfg.yearId);
  const gridEl = $(cfg.gridId);
  if (!yearEl || !gridEl) return;
  const y = _mpState.yearShown;
  yearEl.textContent = String(y);
  const ymSel = cfg.getMonth() || new Date().toISOString().slice(0,7);
  const [ySel, mSel] = ymSel.split('-').map(Number);
  const now = new Date();
  const yNow = now.getFullYear(), mNow = now.getMonth() + 1;
  gridEl.innerHTML = MONTHS_SHORT.map((label, i) => {
    const m = i + 1;
    const isSelected = y === ySel && m === mSel;
    const isCurrent  = y === yNow && m === mNow;
    const classes = ['mp-month'];
    if (isSelected) classes.push('is-selected');
    else if (isCurrent) classes.push('is-current');
    return `<button type="button" class="${classes.join(' ')}" onclick="mpSelectMonth(${m})">${label}</button>`;
  }).join('');
}

function renderClientReport(clientId) {
  const c = clientById(clientId);
  if (!c) return;
  const ym = currentReportMonth || new Date().toISOString().slice(0,7);
  const [y, m] = ym.split('-').map(Number);
  const monthLabel = `${MONTHS[m - 1]} de ${y}`;

  // Popula seletor de mês (label + grid do popover).
  renderMp('client');

  // Header
  $('report-client-name').textContent = c.name;
  $('report-period-label').textContent = monthLabel;
  $('report-generated-at').textContent = new Date().toLocaleString('pt-BR');

  // Escopo: projetos do cliente + demandas desses projetos.
  const projs = projects.filter(p => p.clientId === c.id);
  const projIds = new Set(projs.map(p => p.id));
  const projectsActive = projs.filter(p => p.active !== false).length;
  const clientDemands = demands.filter(d => projIds.has(d.projectId));

  // Demandas entregues no mês = completedAt dentro do intervalo YYYY-MM.
  const monthPrefix = ym;
  const delivered = clientDemands.filter(d => d.completedAt && d.completedAt.slice(0,7) === monthPrefix);
  const inProgress = clientDemands.filter(d => !isDone(d));

  // Horas apontadas no mês (agrega por dia YYYY-MM).
  let totalHours = 0;
  const hoursByRole = new Map();
  const hoursByUser = new Map();
  clientDemands.forEach(d => {
    (d.timeEntries || []).forEach(e => {
      const when = ((e.start || e.createdAt || '') + '').slice(0,7);
      if (when !== monthPrefix) return;
      const h = Number(e.hours) || 0;
      totalHours += h;
      if (e.userId) hoursByUser.set(e.userId, (hoursByUser.get(e.userId) || 0) + h);
      const u = e.userId ? userById(e.userId) : null;
      const role = u?.role || '—';
      hoursByRole.set(role, (hoursByRole.get(role) || 0) + h);
    });
  });

  // KPIs (4 cards)
  $('report-kpis').innerHTML = `
    <div class="report-kpi">
      <div class="report-kpi-label">Entregues no mês</div>
      <div class="report-kpi-value">${delivered.length}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Em andamento</div>
      <div class="report-kpi-value">${inProgress.length}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Horas apontadas</div>
      <div class="report-kpi-value">${fmtHours(totalHours)}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Projetos ativos</div>
      <div class="report-kpi-value">${projectsActive}</div>
    </div>
  `;

  // Demandas entregues — tabela com projeto, responsável, prazo, entrega, horas.
  const deliveredEl = $('report-delivered');
  if (!delivered.length) {
    deliveredEl.innerHTML = `<div class="client-people-empty">Nenhuma demanda entregue em ${monthLabel.toLowerCase()}.</div>`;
  } else {
    const sorted = delivered.slice().sort((a, b) => (a.completedAt || '').localeCompare(b.completedAt || ''));
    deliveredEl.innerHTML = `<table class="report-table">
      <thead>
        <tr>
          <th>Demanda</th>
          <th>Projeto</th>
          <th>Responsável</th>
          <th>Prazo</th>
          <th>Entrega</th>
          <th class="num">Horas</th>
        </tr>
      </thead>
      <tbody>
        ${sorted.map(d => {
          const proj = projectById(d.projectId);
          const owner = d.ownerId ? userById(d.ownerId) : null;
          const dh = (d.timeEntries || []).reduce((sum, e) => sum + (Number(e.hours) || 0), 0);
          const late = wasLate(d);
          return `<tr>
            <td class="report-td-name">${esc(d.name || '—')}</td>
            <td>${esc(proj?.name || '—')}</td>
            <td>${owner ? esc(owner.name) : '<span class="report-muted">—</span>'}</td>
            <td>${d.deadline ? fmtDate(d.deadline) : '<span class="report-muted">—</span>'}</td>
            <td class="${late ? 'report-late' : ''}">${d.completedAt ? fmtDate(d.completedAt) : '—'}${late ? ' <span class="report-late-tag">atrasada</span>' : ''}</td>
            <td class="num">${fmtHours(dh)}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>`;
  }

  // Horas por função — barras horizontais.
  const roleRowsEl = $('report-hours-role');
  const roleEntries = [...hoursByRole.entries()].sort((a, b) => b[1] - a[1]);
  if (!roleEntries.length) {
    roleRowsEl.innerHTML = `<div class="client-people-empty">Sem horas apontadas neste mês.</div>`;
  } else {
    const maxRole = Math.max(...roleEntries.map(([, h]) => h));
    roleRowsEl.innerHTML = roleEntries.map(([role, h]) => {
      const pct = maxRole > 0 ? Math.round((h / maxRole) * 100) : 0;
      return `<div class="report-bar-row">
        <div class="report-bar-label">${esc(role)}</div>
        <div class="report-bar-track"><div class="report-bar-fill" style="width:${pct}%"></div></div>
        <div class="report-bar-value">${fmtHours(h)}</div>
      </div>`;
    }).join('');
  }

  // Horas por responsável — mesmo padrão, com avatar.
  const userRowsEl = $('report-hours-user');
  const userEntries = [...hoursByUser.entries()]
    .map(([uid, h]) => ({ u: userById(uid), hours: h }))
    .filter(x => x.u)
    .sort((a, b) => b.hours - a.hours);
  if (!userEntries.length) {
    userRowsEl.innerHTML = `<div class="client-people-empty">Ninguém apontou horas neste mês.</div>`;
  } else {
    const maxUser = Math.max(...userEntries.map(x => x.hours));
    userRowsEl.innerHTML = userEntries.map(x => {
      const pct = maxUser > 0 ? Math.round((x.hours / maxUser) * 100) : 0;
      return `<div class="report-bar-row report-bar-row--user">
        <div class="report-bar-user">${avatarHTML(x.u, 'avatar')} <span>${esc(x.u.name)}</span></div>
        <div class="report-bar-track"><div class="report-bar-fill" style="width:${pct}%"></div></div>
        <div class="report-bar-value">${fmtHours(x.hours)}</div>
      </div>`;
    }).join('');
  }

  paintIcons();
}

/* ─── RELATÓRIO MENSAL DO PROJETO ───────────────────────────────────
   Espelha a lógica do relatório do cliente mas escopa por projectId.
   4º KPI muda pra "Em atraso" (mais acionável que "projetos ativos" quando
   o escopo já é um projeto único). */
function openProjectReport() {
  if (!currentProjectId) { toast('Nenhum projeto selecionado', 'warn'); return; }
  if (!currentProjectReportMonth) currentProjectReportMonth = new Date().toISOString().slice(0,7);
  showProjectReportView();
  renderProjectReport(currentProjectId);
  navPush(projectPath(currentProjectId) + '/report');
}
function closeProjectReport() {
  const pid = currentProjectId;
  if (pid && projectById(pid)) {
    showProjectDetailView();
    renderProjectDetail(pid);
    navPush(projectPath(pid));
  } else {
    closeClientDetail();
  }
}
function setProjectReportMonth(ym) {
  currentProjectReportMonth = ym;
  if (currentProjectId) renderProjectReport(currentProjectId);
}

function renderProjectReport(projectId) {
  const p = projectById(projectId);
  if (!p) return;
  const c = p.clientId ? clientById(p.clientId) : null;
  const ym = currentProjectReportMonth || new Date().toISOString().slice(0,7);
  const [y, m] = ym.split('-').map(Number);
  const monthLabel = `${MONTHS[m - 1]} de ${y}`;

  renderMp('project');

  // Header
  $('preport-eyebrow').textContent = c ? `RELATÓRIO MENSAL · PROJETO DE ${c.name.toUpperCase()}` : 'RELATÓRIO MENSAL · PROJETO';
  $('preport-title').textContent = p.name;
  $('preport-period-label').textContent = monthLabel;
  $('preport-generated-at').textContent = new Date().toLocaleString('pt-BR');

  // Escopo: só demandas deste projeto.
  const projectDemands = demands.filter(d => d.projectId === projectId);
  const monthPrefix = ym;
  const delivered = projectDemands.filter(d => d.completedAt && d.completedAt.slice(0,7) === monthPrefix);
  const inProgress = projectDemands.filter(d => !isDone(d));
  // Em atraso = deadline passou e não concluída.
  const today = todayStr();
  const overdue = projectDemands.filter(d => d.deadline && !isDone(d) && d.deadline < today);

  // Horas do período.
  let totalHours = 0;
  const hoursByRole = new Map();
  const hoursByUser = new Map();
  projectDemands.forEach(d => {
    (d.timeEntries || []).forEach(e => {
      const when = ((e.start || e.createdAt || '') + '').slice(0,7);
      if (when !== monthPrefix) return;
      const h = Number(e.hours) || 0;
      totalHours += h;
      if (e.userId) hoursByUser.set(e.userId, (hoursByUser.get(e.userId) || 0) + h);
      const u = e.userId ? userById(e.userId) : null;
      const role = u?.role || '—';
      hoursByRole.set(role, (hoursByRole.get(role) || 0) + h);
    });
  });

  // KPIs — troca "Projetos ativos" por "Em atraso" (mais útil no escopo projeto).
  $('preport-kpis').innerHTML = `
    <div class="report-kpi">
      <div class="report-kpi-label">Entregues no mês</div>
      <div class="report-kpi-value">${delivered.length}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Em andamento</div>
      <div class="report-kpi-value">${inProgress.length}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Horas apontadas</div>
      <div class="report-kpi-value">${fmtHours(totalHours)}</div>
    </div>
    <div class="report-kpi">
      <div class="report-kpi-label">Em atraso</div>
      <div class="report-kpi-value ${overdue.length ? 'report-kpi-danger' : ''}">${overdue.length}</div>
    </div>
  `;

  // Demandas entregues — tabela (sem coluna Projeto já que é o próprio escopo).
  const deliveredEl = $('preport-delivered');
  if (!delivered.length) {
    deliveredEl.innerHTML = `<div class="client-people-empty">Nenhuma demanda entregue em ${monthLabel.toLowerCase()}.</div>`;
  } else {
    const sorted = delivered.slice().sort((a, b) => (a.completedAt || '').localeCompare(b.completedAt || ''));
    deliveredEl.innerHTML = `<table class="report-table">
      <thead>
        <tr>
          <th>Demanda</th>
          <th>Responsável</th>
          <th>Prazo</th>
          <th>Entrega</th>
          <th class="num">Horas</th>
        </tr>
      </thead>
      <tbody>
        ${sorted.map(d => {
          const owner = d.ownerId ? userById(d.ownerId) : null;
          const dh = (d.timeEntries || []).reduce((sum, e) => sum + (Number(e.hours) || 0), 0);
          const late = wasLate(d);
          return `<tr>
            <td class="report-td-name">${esc(d.name || '—')}</td>
            <td>${owner ? esc(owner.name) : '<span class="report-muted">—</span>'}</td>
            <td>${d.deadline ? fmtDate(d.deadline) : '<span class="report-muted">—</span>'}</td>
            <td class="${late ? 'report-late' : ''}">${d.completedAt ? fmtDate(d.completedAt) : '—'}${late ? ' <span class="report-late-tag">atrasada</span>' : ''}</td>
            <td class="num">${fmtHours(dh)}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>`;
  }

  // Horas por função.
  const roleRowsEl = $('preport-hours-role');
  const roleEntries = [...hoursByRole.entries()].sort((a, b) => b[1] - a[1]);
  if (!roleEntries.length) {
    roleRowsEl.innerHTML = `<div class="client-people-empty">Sem horas apontadas neste mês.</div>`;
  } else {
    const maxRole = Math.max(...roleEntries.map(([, h]) => h));
    roleRowsEl.innerHTML = roleEntries.map(([role, h]) => {
      const pct = maxRole > 0 ? Math.round((h / maxRole) * 100) : 0;
      return `<div class="report-bar-row">
        <div class="report-bar-label">${esc(role)}</div>
        <div class="report-bar-track"><div class="report-bar-fill" style="width:${pct}%"></div></div>
        <div class="report-bar-value">${fmtHours(h)}</div>
      </div>`;
    }).join('');
  }

  // Horas por responsável.
  const userRowsEl = $('preport-hours-user');
  const userEntries = [...hoursByUser.entries()]
    .map(([uid, h]) => ({ u: userById(uid), hours: h }))
    .filter(x => x.u)
    .sort((a, b) => b.hours - a.hours);
  if (!userEntries.length) {
    userRowsEl.innerHTML = `<div class="client-people-empty">Ninguém apontou horas neste mês.</div>`;
  } else {
    const maxUser = Math.max(...userEntries.map(x => x.hours));
    userRowsEl.innerHTML = userEntries.map(x => {
      const pct = maxUser > 0 ? Math.round((x.hours / maxUser) * 100) : 0;
      return `<div class="report-bar-row report-bar-row--user">
        <div class="report-bar-user">${avatarHTML(x.u, 'avatar')} <span>${esc(x.u.name)}</span></div>
        <div class="report-bar-track"><div class="report-bar-fill" style="width:${pct}%"></div></div>
        <div class="report-bar-value">${fmtHours(x.hours)}</div>
      </div>`;
    }).join('');
  }

  paintIcons();
}

// Download programático — mesma estrutura do cliente mas escopado ao projeto.
async function downloadProjectReport() {
  if (!currentProjectId) return;
  const p = projectById(currentProjectId);
  if (!p) return;
  const c = p.clientId ? clientById(p.clientId) : null;
  const ym = currentProjectReportMonth || new Date().toISOString().slice(0,7);
  const [year, mon] = ym.split('-').map(Number);
  const monthNum = ym.split('-')[1] || '';
  const monthLabel = `${MONTHS[mon - 1]} de ${year}`;
  const sanitize = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '').trim();
  const clientPart = c ? ` - ${sanitize(c.name)}` : '';
  const filename = `Relatório Mensal ${monthNum} - ${sanitize(p.name)}${clientPart} - reWork.pdf`;

  toast('Gerando PDF…');
  try {
    const jsPDF = await loadJsPDF();

    // Agregações.
    const projectDemands = demands.filter(d => d.projectId === p.id);
    const delivered = projectDemands.filter(d => d.completedAt && d.completedAt.slice(0,7) === ym);
    const inProgress = projectDemands.filter(d => !isDone(d));
    const today = todayStr();
    const overdue = projectDemands.filter(d => d.deadline && !isDone(d) && d.deadline < today);
    let totalHours = 0;
    const hoursByRole = new Map();
    const hoursByUser = new Map();
    projectDemands.forEach(d => {
      (d.timeEntries || []).forEach(e => {
        const when = ((e.start || e.createdAt || '') + '').slice(0,7);
        if (when !== ym) return;
        const h = Number(e.hours) || 0;
        totalHours += h;
        if (e.userId) hoursByUser.set(e.userId, (hoursByUser.get(e.userId) || 0) + h);
        const u = e.userId ? userById(e.userId) : null;
        const role = u?.role || '—';
        hoursByRole.set(role, (hoursByRole.get(role) || 0) + h);
      });
    });

    const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
    const PAGE_W = 210, PAGE_H = 297;
    const MARGIN = 15;
    const CONTENT_W = PAGE_W - MARGIN * 2;
    const FOOT_RESERVED = 12;
    const ACCENT = [122, 0, 255];
    const TEXT   = [24, 24, 27];
    const MUTED  = [82, 82, 91];
    const BORDER = [228, 228, 231];
    const BG     = [249, 250, 251];
    const HEADBG = [244, 244, 245];
    const RED    = [239, 68, 68];
    const RED_BG = [254, 226, 226];

    let cursor = MARGIN;
    const truncate = (s, n) => { s = String(s || '—'); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
    const setColor = (rgb, kind = 'text') => {
      if (kind === 'text') doc.setTextColor(rgb[0], rgb[1], rgb[2]);
      if (kind === 'fill') doc.setFillColor(rgb[0], rgb[1], rgb[2]);
      if (kind === 'draw') doc.setDrawColor(rgb[0], rgb[1], rgb[2]);
    };
    const ensureSpace = (needed) => {
      if (cursor + needed > PAGE_H - MARGIN - FOOT_RESERVED) {
        doc.addPage(); cursor = MARGIN;
      }
    };

    // ── Header ──
    const headerH = 32;
    setColor(BG, 'fill'); setColor(BORDER, 'draw');
    doc.roundedRect(MARGIN, cursor, CONTENT_W, headerH, 2, 2, 'FD');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8);
    setColor(ACCENT);
    const eyebrow = c ? `RELATÓRIO MENSAL · PROJETO DE ${c.name.toUpperCase()}` : 'RELATÓRIO MENSAL · PROJETO';
    doc.text(truncate(eyebrow, 60), MARGIN + 8, cursor + 9);
    doc.setFontSize(20);
    setColor(TEXT);
    doc.text(truncate(p.name, 45), MARGIN + 8, cursor + 20, { maxWidth: CONTENT_W - 16 });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    setColor(MUTED);
    doc.text(monthLabel, MARGIN + 8, cursor + 28);
    cursor += headerH + 8;

    // ── KPIs ──
    const kpis = [
      { label: 'ENTREGUES NO MÊS', value: String(delivered.length), danger: false },
      { label: 'EM ANDAMENTO',     value: String(inProgress.length), danger: false },
      { label: 'HORAS APONTADAS',  value: fmtHours(totalHours), danger: false },
      { label: 'EM ATRASO',        value: String(overdue.length), danger: overdue.length > 0 }
    ];
    const kpiGap = 4;
    const kpiW = (CONTENT_W - kpiGap * 3) / 4;
    const kpiH = 22;
    kpis.forEach((k, i) => {
      const x = MARGIN + i * (kpiW + kpiGap);
      setColor([255,255,255], 'fill'); setColor(BORDER, 'draw');
      doc.roundedRect(x, cursor, kpiW, kpiH, 2, 2, 'FD');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7);
      setColor(MUTED);
      doc.text(k.label, x + 4, cursor + 6.5);
      doc.setFontSize(16);
      setColor(k.danger ? RED : TEXT);
      doc.text(k.value, x + 4, cursor + 17);
    });
    cursor += kpiH + 10;

    const drawSectionTitle = (title) => {
      ensureSpace(10);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
      setColor(MUTED);
      doc.text(title, MARGIN, cursor);
      cursor += 5;
    };
    const drawEmptyBox = (msg) => {
      ensureSpace(14);
      setColor(BG, 'fill'); setColor(BORDER, 'draw');
      doc.roundedRect(MARGIN, cursor, CONTENT_W, 12, 2, 2, 'FD');
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      setColor(MUTED);
      doc.text(msg, PAGE_W / 2, cursor + 7.5, { align: 'center' });
      cursor += 16;
    };

    // ── Demandas entregues (sem coluna Projeto) ──
    drawSectionTitle('DEMANDAS ENTREGUES');
    if (!delivered.length) {
      drawEmptyBox(`Nenhuma demanda entregue em ${monthLabel.toLowerCase()}.`);
    } else {
      // 5 colunas: Demanda 65 | Responsável 40 | Prazo 25 | Entrega 32 | Horas 18 = 180
      const cols = [
        { label: 'DEMANDA',     w: 65 },
        { label: 'RESPONSÁVEL', w: 40 },
        { label: 'PRAZO',       w: 25 },
        { label: 'ENTREGA',     w: 32 },
        { label: 'HORAS',       w: 18, align: 'right' }
      ];
      const rowH = 8;
      const drawTableHeader = () => {
        setColor(HEADBG, 'fill'); setColor(BORDER, 'draw');
        doc.rect(MARGIN, cursor, CONTENT_W, rowH, 'FD');
        doc.setFont('helvetica', 'bold'); doc.setFontSize(7);
        setColor(MUTED);
        let cx = MARGIN;
        cols.forEach(col => {
          const tx = col.align === 'right' ? cx + col.w - 3 : cx + 3;
          doc.text(col.label, tx, cursor + 5, { align: col.align || 'left' });
          cx += col.w;
        });
        cursor += rowH;
      };
      drawTableHeader();
      const sorted = delivered.slice().sort((a, b) => (a.completedAt || '').localeCompare(b.completedAt || ''));
      for (const d of sorted) {
        if (cursor + rowH > PAGE_H - MARGIN - FOOT_RESERVED) {
          doc.addPage(); cursor = MARGIN; drawTableHeader();
        }
        const owner = d.ownerId ? userById(d.ownerId) : null;
        const dh = (d.timeEntries || []).reduce((sum, e) => sum + (Number(e.hours) || 0), 0);
        const late = wasLate(d);
        setColor([255,255,255], 'fill'); setColor(BORDER, 'draw');
        doc.rect(MARGIN, cursor, CONTENT_W, rowH, 'FD');
        let cx = MARGIN;
        doc.setFontSize(9);
        doc.setFont('helvetica', 'bold'); setColor(TEXT);
        doc.text(truncate(d.name, 40), cx + 3, cursor + 5.3);
        cx += cols[0].w;
        doc.setFont('helvetica', 'normal');
        doc.text(owner ? truncate(owner.name, 22) : '—', cx + 3, cursor + 5.3);
        cx += cols[1].w;
        doc.text(d.deadline ? fmtDate(d.deadline) : '—', cx + 3, cursor + 5.3);
        cx += cols[2].w;
        if (late) setColor(RED); else setColor(TEXT);
        doc.text(d.completedAt ? fmtDate(d.completedAt) : '—', cx + 3, cursor + 5.3);
        if (late) {
          doc.setFontSize(6);
          const tw = doc.getTextWidth('ATRASADA') + 2;
          setColor(RED_BG, 'fill');
          doc.roundedRect(cx + 15, cursor + 1.8, tw, 4, 0.5, 0.5, 'F');
          setColor(RED);
          doc.text('ATRASADA', cx + 16, cursor + 4.9);
          doc.setFontSize(9);
        }
        cx += cols[3].w;
        setColor(TEXT); doc.setFont('helvetica', 'bold');
        doc.text(fmtHours(dh), cx + cols[4].w - 3, cursor + 5.3, { align: 'right' });
        cursor += rowH;
      }
      cursor += 6;
    }

    const drawBarSection = (title, entries, emptyMsg, labelResolver) => {
      drawSectionTitle(title);
      if (!entries.length) { drawEmptyBox(emptyMsg); return; }
      const rowH = 9;
      const labelW = 55;
      const valueW = 22;
      const barW = CONTENT_W - labelW - valueW - 6;
      const barH = 4;
      const max = Math.max(...entries.map(([, h]) => h));
      for (const [key, h] of entries) {
        ensureSpace(rowH);
        const label = labelResolver ? labelResolver(key) : String(key);
        doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
        setColor(TEXT);
        doc.text(truncate(label, 30), MARGIN, cursor + 5);
        const barX = MARGIN + labelW;
        const barY = cursor + 3;
        setColor([230, 230, 234], 'fill');
        doc.roundedRect(barX, barY, barW, barH, 1, 1, 'F');
        const pct = max > 0 ? (h / max) : 0;
        setColor(ACCENT, 'fill');
        doc.roundedRect(barX, barY, Math.max(0.5, barW * pct), barH, 1, 1, 'F');
        doc.setFontSize(9); setColor(TEXT);
        doc.text(fmtHours(h), MARGIN + CONTENT_W, cursor + 5, { align: 'right' });
        cursor += rowH;
      }
      cursor += 6;
    };

    const roleEntries = [...hoursByRole.entries()].sort((a, b) => b[1] - a[1]);
    drawBarSection('HORAS POR FUNÇÃO', roleEntries, 'Sem horas apontadas neste mês.');

    const userEntries = [...hoursByUser.entries()]
      .filter(([uid]) => userById(uid))
      .sort((a, b) => b[1] - a[1]);
    drawBarSection('HORAS POR RESPONSÁVEL', userEntries, 'Ninguém apontou horas neste mês.',
      (uid) => userById(uid)?.name || 'Usuário');

    // Footer.
    const totalPages = doc.internal.getNumberOfPages();
    const genLabel = `Gerado em ${new Date().toLocaleString('pt-BR')} · reWork`;
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
      setColor(MUTED);
      doc.text(genLabel, MARGIN, PAGE_H - MARGIN + 4);
      doc.text(`${i} / ${totalPages}`, PAGE_W - MARGIN, PAGE_H - MARGIN + 4, { align: 'right' });
    }
    doc.save(filename);
    toast('Relatório baixado!');
  } catch (e) {
    console.error('[downloadProjectReport]', e);
    toast(e.message || 'Erro ao gerar PDF', 'error');
  }
}

/* ─── MODAL: NOVO/EDITAR CLIENTE ─── */
function openClientModal(id) {
  editingClientId = id || null;
  const c = id ? clientById(id) : null;
  const isNew = !c;
  $('client-modal-title').textContent = isNew ? 'Novo Cliente' : 'Editar Cliente';
  $('c-name').value = c?.name || '';
  $('c-segment').value = c?.segment || '';
  $('c-drive-files').value = c?.driveFiles || '';
  $('c-brand-assets').value = c?.brandAssets || '';
  $('c-guidelines').value = c?.guidelines || '';
  setColorValue('c-color', c?.color || '#7A00FF');
  // Workspace
  const wsSel = $('c-workspace');
  const accessibleWs = workspaces.filter(w => me.isAdmin || (me.workspaces || []).includes(w.id));
  wsSel.innerHTML = accessibleWs.map(w =>
    `<option value="${w.id}" ${(c ? c.workspaceId : activeWs) === w.id ? 'selected' : ''}>${esc(w.name)}</option>`
  ).join('');
  // Avatar
  clientAvatarData = c?.avatar || null;
  refreshClientAvatarPreview();
  // Datalist de segmentos existentes
  const segs = [...new Set(clients.map(x => x.segment).filter(Boolean))].sort();
  $('client-segments-datalist').innerHTML = segs.map(s => `<option value="${esc(s)}">`).join('');
  // Footer: edit mostra status toggle + excluir + salvar como modelo
  $('c-foot-left').style.display = '';
  // Excluir cliente restrito a admin/moderador — server também bloqueia via modOrAdmin.
  const canDeleteClient = !!(me.isAdmin || me.isModerator);
  $('c-delete-btn').style.display = (isNew || !canDeleteClient) ? 'none' : '';
  $('c-status-group').style.display = isNew ? 'none' : '';
  $('c-save-template-btn').style.display = isNew ? 'none' : '';
  if (c) {
    clientModalStatusActive = c.active !== false;
    refreshClientStatusUI();
  }
  // Onboarding: dropdown de modelos só no Novo. Modelos são globais — mostra
  // a biblioteca inteira. O cliente novo entra no workspace escolhido no combo
  // logo abaixo (c-workspace), independente de onde o modelo foi criado.
  const tplBar = $('c-template-bar');
  const tplSel = $('c-template');
  if (isNew && tplSel && tplBar) {
    const myTpls = (clientTemplates || [])
      .slice().sort((a, b) => (a.name || '').localeCompare(b.name || '', 'pt-BR', { sensitivity: 'base' }));
    if (myTpls.length) {
      tplBar.style.display = '';
      tplSel.innerHTML = `<option value="">— Em branco —</option>` +
        myTpls.map(t => {
          const nProj = (t.projects || []).length;
          const nFlow = (t.projects || []).reduce((s, p) => s + (p.flows || []).length, 0);
          return `<option value="${t.id}">${esc(t.name)} (${nProj} projeto${nProj === 1 ? '' : 's'} · ${nFlow} fluxo${nFlow === 1 ? '' : 's'})</option>`;
        }).join('');
      tplSel.value = '';
    } else {
      tplBar.style.display = 'none';
    }
  } else if (tplBar) {
    tplBar.style.display = 'none';
  }
  openModal('client-modal');
  navPush(isNew ? '/clients/new' : (clientPath(id) + '/edit'));
}
function openClientModalEdit() {
  if (currentClientId) openClientModal(currentClientId);
}
function refreshClientAvatarPreview() {
  const el = $('c-avatar-preview');
  if (!el) return;
  if (clientAvatarData) {
    el.style.backgroundImage = `url('${clientAvatarData}')`;
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
    el.innerHTML = '';
    $('c-avatar-remove').style.display = '';
  } else {
    el.style.backgroundImage = '';
    el.innerHTML = '<span style="color:var(--text-muted);font-size:12px">Sem foto</span>';
    $('c-avatar-remove').style.display = 'none';
  }
}
function handleClientAvatarUpload(ev) {
  const file = ev.target.files && ev.target.files[0];
  if (!file) return;
  if (file.size > 50 * 1024 * 1024) { toast('Imagem excede 50 MB.', 'error'); ev.target.value = ''; return; }
  const reader = new FileReader();
  reader.onload = (e) => { clientAvatarData = e.target.result; refreshClientAvatarPreview(); };
  reader.readAsDataURL(file);
  ev.target.value = '';
}
function removeClientAvatar() {
  clientAvatarData = null;
  refreshClientAvatarPreview();
}
function setClientModalStatus(active) {
  clientModalStatusActive = active;
  refreshClientStatusUI();
}
function refreshClientStatusUI() {
  document.querySelectorAll('.client-status-pick').forEach(b => {
    b.classList.toggle('active', (b.dataset.val === 'active') === clientModalStatusActive);
  });
}
async function saveClient() {
  const name = ($('c-name').value || '').trim();
  if (!name) { toast('Nome do cliente é obrigatório.', 'error'); return; }
  // Modo "novo a partir de modelo" — usa endpoint dedicado que cria projetos+fluxos junto
  const templateId = !editingClientId && $('c-template') ? $('c-template').value : '';
  if (templateId) {
    try {
      const r = await api('/clients/from-template', 'POST', {
        templateId, name, workspaceId: $('c-workspace').value
      });
      closeModal('client-modal');
      toast(`Cliente criado a partir do modelo (${r.counts.projects} projeto${r.counts.projects === 1 ? '' : 's'}, ${r.counts.flows} fluxo${r.counts.flows === 1 ? '' : 's'}).`);
      await refreshData();
      return;
    } catch (e) {
      toast(e.message || 'Erro ao aplicar modelo', 'error');
      return;
    }
  }
  const payload = {
    name,
    workspaceId: $('c-workspace').value,
    color: $('c-color').value,
    segment: $('c-segment').value,
    driveFiles: $('c-drive-files').value,
    brandAssets: $('c-brand-assets').value,
    guidelines: $('c-guidelines').value,
    avatar: clientAvatarData
  };
  if (editingClientId) payload.active = clientModalStatusActive;
  try {
    const r = editingClientId
      ? await api('/clients/' + editingClientId, 'PUT', payload)
      : await api('/clients', 'POST', payload);
    closeModal('client-modal');
    toast(editingClientId ? 'Cliente atualizado!' : 'Cliente criado!');
    // Se estava na tela de detalhe (URL /clients/<id>/edit), volta pro detalhe
    if (currentClientId) navPush(clientPath(currentClientId));
    await refreshData();
  } catch (e) {
    toast(e.message || 'Erro ao salvar cliente', 'error');
  }
}

/* Salvar cliente atual como modelo — abre confirm que pede o nome */
function openSaveClientTemplate() {
  if (!editingClientId) return;
  const c = clientById(editingClientId);
  if (!c) return;
  const projs = projects.filter(p => p.clientId === c.id && p.active !== false);
  const flowsCount = projs.reduce((sum, p) => sum + flows.filter(f => f.projectId === p.id).length, 0);
  $('c-tpl-save-summary').innerHTML = `Vai salvar <strong>${esc(c.name)}</strong> como modelo: <strong>${projs.length}</strong> projeto${projs.length === 1 ? '' : 's'} e <strong>${flowsCount}</strong> fluxo${flowsCount === 1 ? '' : 's'} ativos. Demandas, agendamentos e atribuições NÃO vão pro modelo.`;
  $('c-tpl-save-name').value = `Modelo: ${c.name}`;
  openModal('client-template-save-modal');
  setTimeout(() => $('c-tpl-save-name').focus(), 60);
}
async function confirmSaveClientTemplate() {
  const name = ($('c-tpl-save-name').value || '').trim();
  if (!name) { toast('Dê um nome ao modelo.', 'error'); return; }
  try {
    await api('/client-templates', 'POST', { sourceClientId: editingClientId, name });
    clientTemplates = await api('/client-templates');
    closeModal('client-template-save-modal');
    toast('Modelo salvo. Disponível ao criar um novo cliente.');
  } catch (e) {
    toast(e.message || 'Erro ao salvar modelo', 'error');
  }
}

/* Exclusão com confirmação (digite o nome) */
function openClientDeleteConfirm() {
  if (!editingClientId) return;
  const c = clientById(editingClientId);
  if (!c) return;
  $('client-delete-title').textContent = `Excluir ${c.name}?`;
  $('client-delete-confirm-text').innerHTML = `Para confirmar, digite <strong>${esc(c.name)}</strong> abaixo:`;
  $('client-delete-input').value = '';
  $('client-delete-input').placeholder = c.name;
  $('client-delete-confirm-btn').disabled = true;
  $('client-delete-warning').textContent = '';
  // Aviso se tem projetos vinculados
  const linked = projects.filter(p => p.clientId === c.id).length;
  if (linked > 0) {
    $('client-delete-warning').textContent = `⚠ Este cliente tem ${linked} projeto(s) vinculado(s). Exclua ou mova os projetos antes.`;
  }
  openModal('client-delete-modal');
}
function updateClientDeleteBtnState() {
  if (!editingClientId) return;
  const c = clientById(editingClientId);
  const typed = ($('client-delete-input').value || '').trim();
  const linked = projects.filter(p => p.clientId === c.id).length;
  $('client-delete-confirm-btn').disabled = !(c && typed === c.name && linked === 0);
}
async function confirmDeleteClient() {
  if (!editingClientId) return;
  try {
    const delId = editingClientId;
    await api('/clients/' + delId, 'DELETE');
    closeModal('client-delete-modal');
    closeModal('client-modal');
    editingClientId = null;
    toastWithUndo('Cliente excluído.', () => api('/clients/' + delId + '/undelete', 'POST'));
    await refreshData();
    closeClientDetail();
  } catch (e) {
    toast(e.message || 'Erro ao excluir', 'error');
  }
}

/* Atalho: abrir modal de projeto já com o cliente atual pré-selecionado */
function openProjectModalForCurrentClient() {
  if (typeof openProjectModal === 'function') openProjectModal(null, currentClientId);
}

/* ─── AGENDA ────────────────────────────────────────────────────
   Planejamento semanal por usuário. Bloco = (userId, demandId, date,
   startMin, endMin). Grid renderizado como CSS Grid + blocos absolutos
   posicionados nas colunas de dia via `grid-column`. */
const AGENDA_DAY_START_MIN = 9 * 60;   // 09:00
const AGENDA_DAY_END_MIN   = 18 * 60;  // 18:00
const AGENDA_SLOT_MIN      = 15;       // 15min por linha (granularidade fina)
const AGENDA_SLOT_PX       = 22;       // px por slot — tabela alta o suficiente sem virar 2 telas
const AGENDA_LUNCH_MIN     = 12 * 60;  // 12:00–13:00 destacado
const AGENDA_ROWS = Math.ceil((AGENDA_DAY_END_MIN - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN);
// Minuto (arredondado ao slot) sob o cursor, dada a célula-coluna e o clientY.
// As colunas agora são UMA célula que cobre o dia inteiro (sem célula por slot),
// então o slot vem da posição vertical do mouse dentro da coluna.
function agendaMinFromY(colCell, clientY) {
  const rect = colCell.getBoundingClientRect();
  let slot = Math.floor((clientY - rect.top) / AGENDA_SLOT_PX);
  slot = Math.max(0, Math.min(AGENDA_ROWS - 1, slot));
  return AGENDA_DAY_START_MIN + slot * AGENDA_SLOT_MIN;
}
let agendaUserId = null;          // usuário filtrado (default = me)
let agendaWeekStart = null;       // segunda da semana atual visualizada
// Em mobile começa em 1 semana (2 não cabe nem com column shrink); desktop mantém 2.
let agendaWeeks = (typeof window !== 'undefined' && window.innerWidth < 640) ? 1 : 2;
let editingScheduleId = null;     // id do bloco sendo editado no modal
let _agendaDrag = null;           // estado interno de drag
// Modo Individual (1 user, N semanas) vs Time (M users, 1 dia).
let agendaMode = 'individual';    // 'individual' | 'team'
let agendaTeamUsers = [];         // userIds selecionados no modo Time
let agendaTeamDate = null;        // Date do dia visualizado no modo Time

function agendaWeekStartFor(d) {
  const x = new Date(d);
  x.setHours(0,0,0,0);
  const dow = x.getDay(); // 0=dom, 1=seg...
  const diff = (dow === 0 ? -6 : 1 - dow);
  x.setDate(x.getDate() + diff);
  return x;
}
function agendaYmd(d) {
  return d.toISOString().slice(0, 10);
}
function agendaMinsToHHMM(mins) {
  const h = Math.floor(mins / 60), m = mins % 60;
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
}
function agendaHHMMtoMins(s) {
  const [h, m] = (s || '').split(':').map(Number);
  return (h || 0) * 60 + (m || 0);
}
function agendaInit() {
  if (!agendaUserId) agendaUserId = me?.id || null;
  if (!agendaWeekStart) agendaWeekStart = agendaWeekStartFor(new Date());
}
function agendaPrevWeek() {
  agendaWeekStart.setDate(agendaWeekStart.getDate() - 7);
  renderAgenda();
}
function agendaNextWeek() {
  agendaWeekStart.setDate(agendaWeekStart.getDate() + 7);
  renderAgenda();
}
function agendaThisWeek() {
  agendaWeekStart = agendaWeekStartFor(new Date());
  renderAgenda();
}
function setAgendaView(n) {
  agendaWeeks = n === 1 ? 1 : 2;
  document.querySelectorAll('.agenda-view-btn').forEach(b => b.classList.toggle('active', Number(b.dataset.view) === agendaWeeks));
  renderAgenda();
}
function onAgendaUserChange() {
  agendaUserId = $('agenda-user').value || null;
  renderAgenda();
}
/* ── Modo Time (multi-user, 1 dia) ── */
function setAgendaMode(mode) {
  agendaMode = mode === 'team' ? 'team' : 'individual';
  // Default: só o próprio usuário selecionado. Se já tinha seleção prévia, mantém.
  if (agendaMode === 'team' && !agendaTeamUsers.length) {
    if (me?.id) agendaTeamUsers = [me.id];
  }
  if (agendaMode === 'team' && !agendaTeamDate) agendaTeamDate = new Date();
  document.querySelectorAll('.agenda-mode-btn').forEach(b => b.classList.toggle('is-active', b.dataset.mode === agendaMode));
  const single = $('agenda-user-pick-single');
  const team = $('agenda-user-pick-team');
  const navW = $('agenda-nav-week');
  const navD = $('agenda-nav-day');
  const viewTog = $('agenda-view-toggle-weeks');
  if (single) single.style.display = agendaMode === 'individual' ? '' : 'none';
  if (team)   team.style.display   = agendaMode === 'team' ? '' : 'none';
  if (navW)   navW.style.display   = agendaMode === 'individual' ? '' : 'none';
  if (navD)   navD.style.display   = agendaMode === 'team' ? '' : 'none';
  if (viewTog) viewTog.style.display = agendaMode === 'individual' ? '' : 'none';
  updateAgendaTeamBtnLabel();
  renderAgenda();
}
function updateAgendaTeamBtnLabel() {
  const lbl = $('agenda-team-btn-lbl');
  if (!lbl) return;
  const n = agendaTeamUsers.length;
  lbl.textContent = n ? `${n} pessoa${n === 1 ? '' : 's'}` : 'Escolher pessoas';
}
function agendaPrevDay() {
  const d = new Date(agendaTeamDate || new Date());
  d.setDate(d.getDate() - 1);
  agendaTeamDate = d; renderAgenda();
}
function agendaNextDay() {
  const d = new Date(agendaTeamDate || new Date());
  d.setDate(d.getDate() + 1);
  agendaTeamDate = d; renderAgenda();
}
function agendaTodayDay() { agendaTeamDate = new Date(); renderAgenda(); }

function openAgendaTeamPicker() {
  const wrap = $('agenda-team-picker-list');
  const wsU = wsUsers().filter(u => u.active !== false)
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  wrap.innerHTML = wsU.map(u => `
    <label class="agenda-team-picker-item">
      <input type="checkbox" data-uid="${esc(u.id)}" ${agendaTeamUsers.includes(u.id) ? 'checked' : ''}>
      ${avatarHTML(u, 'avatar avatar-sm')}
      <span>${esc(u.name)}${u.id === me?.id ? ' (você)' : ''}</span>
    </label>`).join('');
  openModal('agenda-team-picker-modal');
}
function saveAgendaTeamPicker() {
  const wrap = $('agenda-team-picker-list');
  const boxes = wrap.querySelectorAll('input[type="checkbox"][data-uid]');
  const picked = [...boxes].filter(b => b.checked).map(b => b.dataset.uid);
  if (!picked.length) { toast('Escolha pelo menos uma pessoa.', 'warn'); return; }
  if (picked.length > 6) { toast('Máximo 6 pessoas por vez.', 'warn'); return; }
  agendaTeamUsers = picked;
  updateAgendaTeamBtnLabel();
  closeModal('agenda-team-picker-modal');
  renderAgenda();
}

/* Lista de dias úteis (seg-sex) no período visualizado.
   Modo Time: só 1 dia (agendaTeamDate), todos os dias da semana. */
function agendaDays() {
  agendaInit();
  if (agendaMode === 'team') {
    return agendaTeamDate ? [new Date(agendaTeamDate)] : [new Date()];
  }
  const days = [];
  const totalDays = 7 * agendaWeeks;
  const base = new Date(agendaWeekStart);
  for (let i = 0; i < totalDays; i++) {
    const d = new Date(base);
    d.setDate(base.getDate() + i);
    const dow = d.getDay();
    if (dow === 0 || dow === 6) continue;
    days.push(d);
  }
  return days;
}

/* Layout das colunas.
   Individual: 1 col por dia útil, gap entre semanas quando 2 semanas.
   Time: 1 col por usuário selecionado (todos no mesmo agendaTeamDate).
   Retorna {cols, gridTemplate, days}. Cada col tem
   { type:'day'|'gap'|'user', gridCol, day?, user?, dayIdx? }. */
function agendaColumnsLayout() {
  // Em telas estreitas, encolhe a coluna de horário e a min-width das colunas
  // de dia/usuário — o grid ainda scrolla horizontalmente, mas cabe mais coluna
  // visível de uma vez sem precisar rolar (5 dias em ~375px fica utilizável).
  const isNarrow = window.innerWidth < 640;
  const timeColW = isNarrow ? '44px' : '60px';
  const dayColMin = isNarrow ? '70px' : '110px';
  const userColMin = isNarrow ? '90px' : '130px';
  const cols = [];
  const tmpl = [timeColW]; // coluna de tempo (HORÁRIO)
  let gridCol = 2;
  if (agendaMode === 'team') {
    const day = agendaTeamDate || new Date();
    agendaTeamUsers.forEach((uid, i) => {
      const user = userById(uid);
      if (!user) return;
      cols.push({ type: 'user', user, day: new Date(day), dayIdx: i, gridCol });
      tmpl.push(`minmax(${userColMin}, 1fr)`);
      gridCol++;
    });
    return { cols, gridTemplate: tmpl.join(' '), days: [new Date(day)] };
  }
  const days = agendaDays();
  days.forEach((d, i) => {
    // Antes do 6º dia (segunda da semana 2) insere a divisória
    if (agendaWeeks === 2 && i === 5) {
      cols.push({ type: 'gap', gridCol });
      tmpl.push('14px');
      gridCol++;
    }
    cols.push({ type: 'day', day: d, dayIdx: i, gridCol });
    tmpl.push(`minmax(${dayColMin}, 1fr)`);
    gridCol++;
  });
  return { cols, gridTemplate: tmpl.join(' '), days };
}

/* ─── GOOGLE EVENTS na agenda ─────────────────────────────────
   Cache por usuário — evita refetch a cada mudança de semana.
   Auto-refresh disparado por: entrar na agenda, sync manual, mudança de
   usuário no seletor. Se o usuário não conectou Google, cache fica vazio. */
let googleEventsForUser = {}; // { userId: [events] }
let _googleEventsFetchInFlight = {}; // { userId: Promise } — evita fetches duplicados

async function refreshGoogleEventsForUser(userId) {
  if (!userId) return [];
  if (_googleEventsFetchInFlight[userId]) return _googleEventsFetchInFlight[userId];
  const p = (async () => {
    try {
      const events = await api('/google/events?userId=' + encodeURIComponent(userId));
      googleEventsForUser[userId] = Array.isArray(events) ? events : [];
      // Re-render se estamos numa tela que mostra agenda.
      if (currentPage === 'agenda' || currentPage === 'mine') renderAgenda();
      return googleEventsForUser[userId];
    } catch (e) {
      // Falha silenciosa — se não conectou Google, endpoint devolve [] normal.
      // Erros de rede real ficam só no console.
      console.debug('[google] fetch events:', e.message);
      googleEventsForUser[userId] = [];
      return [];
    } finally {
      delete _googleEventsFetchInFlight[userId];
    }
  })();
  _googleEventsFetchInFlight[userId] = p;
  return p;
}

// Converte evento Google (start/end ISO) pro shape de bloco da agenda.
// Retorna null se o evento não cair no dia (ex: allDay, outro dia).
function googleEventToBlock(ev, dayYmd) {
  if (!ev || !ev.start) return null;
  if (ev.allDay) {
    // Eventos all-day não são renderizados na grade horária — decisão de MVP.
    // Podem ganhar uma faixa no topo depois.
    return null;
  }
  const startIso = ev.start;
  const endIso = ev.end || ev.start;
  const startYmd = startIso.slice(0, 10);
  const endYmd = endIso.slice(0, 10);
  // Filtra pra apenas o dia atual (multi-day: só o primeiro dia por enquanto)
  if (startYmd !== dayYmd) return null;
  const startDate = new Date(startIso);
  const endDate = new Date(endIso);
  const startMin = startDate.getHours() * 60 + startDate.getMinutes();
  // Se end for em outro dia, corta em 23:59
  const endMin = (endYmd === dayYmd)
    ? endDate.getHours() * 60 + endDate.getMinutes()
    : 24 * 60;
  return {
    kind: 'google',
    id: ev.id,
    startMin,
    endMin: Math.max(startMin + 15, endMin), // duração mínima visível
    summary: ev.summary || '(Sem título)',
    htmlLink: ev.htmlLink || null,
    // Cor padrão de eventos Google no reWork — fixa em #0b57d0 pra que TODOS
    // os eventos externos fiquem visualmente identificáveis, independente da
    // cor do calendário de origem.
    backgroundColor: '#0b57d0',
    meeting: ev.meeting || null,
    startIso: ev.start || null,
    endIso: ev.end || null,
    selfResponseStatus: ev.selfResponseStatus || null
  };
}

// Classe visual do bloco Google conforme resposta do dono do calendário.
// null/aceito/tentativo → filled azul (default). needsAction → outline azul.
// declined → outline vermelho. Consumido em buildAgendaGrid.
function googleResponseClass(status) {
  if (status === 'declined') return 'is-declined';
  if (status === 'needsAction') return 'is-needs-response';
  return ''; // accepted, tentative, null (solo) → estilo padrão
}

// Minutos de reunião do usuário num dia — conta pro day-cap junto com schedules.
// Exclui allDay, declinadas e eventos totalmente fora do dia (multi-day corta em 23:59).
function dayGoogleMinutes(userId, ymd) {
  const events = googleEventsForUser[userId] || [];
  let sum = 0;
  for (const ev of events) {
    if (!ev || !ev.start || ev.allDay) continue;
    if (ev.selfResponseStatus === 'declined') continue;
    const startYmd = String(ev.start).slice(0, 10);
    if (startYmd !== ymd) continue; // mesma regra do googleEventToBlock
    const s = new Date(ev.start);
    const startMin = s.getHours() * 60 + s.getMinutes();
    const endYmd = ev.end ? String(ev.end).slice(0, 10) : ymd;
    let endMin;
    if (endYmd === ymd) {
      const e = new Date(ev.end || ev.start);
      endMin = e.getHours() * 60 + e.getMinutes();
    } else {
      endMin = 24 * 60;
    }
    sum += Math.max(0, endMin - startMin);
  }
  return sum;
}

// Ícone por tipo de plataforma da reunião — usa lucide.
function meetingIconName(kind) {
  if (kind === 'meet') return 'video';
  if (kind === 'zoom') return 'video';
  if (kind === 'teams') return 'users';
  return 'link';
}
function meetingLabel(kind) {
  if (kind === 'meet') return 'Google Meet';
  if (kind === 'zoom') return 'Zoom';
  if (kind === 'teams') return 'Microsoft Teams';
  return 'Reunião';
}

// N-lane column layout — pra 2+ blocos que se sobrepõem no mesmo dia,
// atribui uma "coluna" a cada um sem overlap dentro dela. Retorna
// { assign: { blockId: colIdx }, totalCols }.
function computeLaneLayout(blocks) {
  const sorted = blocks.slice().sort((a, b) => a.startMin - b.startMin);
  const columns = []; // columns[i] = array de blocos naquela coluna
  const assign = {};
  for (const b of sorted) {
    let placedCol = -1;
    for (let i = 0; i < columns.length; i++) {
      const col = columns[i];
      const conflict = col.some(x => !(x.endMin <= b.startMin || x.startMin >= b.endMin));
      if (!conflict) { col.push(b); placedCol = i; break; }
    }
    if (placedCol < 0) { columns.push([b]); placedCol = columns.length - 1; }
    assign[b.id] = placedCol;
  }
  return { assign, totalCols: columns.length };
}

function renderAgenda() {
  agendaInit();
  // Popula select de usuários (só na página standalone /agenda)
  const sel = $('agenda-user');
  if (sel) {
    const wsU = wsUsers().slice().sort((a,b) => norm(a.name).localeCompare(norm(b.name)));
    sel.innerHTML = wsU.map(u =>
      `<option value="${u.id}" ${u.id === agendaUserId ? 'selected' : ''}>${esc(u.name)}${u.id === me.id ? ' (você)' : ''}</option>`
    ).join('');
    if (!sel.value && wsU[0]) { agendaUserId = wsU[0].id; sel.value = agendaUserId; }
  }
  // Renderiza nos dois alvos possíveis — standalone (Agenda) e embed (Minhas Demandas)
  renderAgendaInto('agenda-grid-wrap', 'agenda-week-label', agendaUserId);
  renderAgendaInto('mine-agenda-grid-wrap', 'mine-agenda-week-label', me?.id || null);
  // Label do dia (modo Time — só na página standalone)
  if (agendaMode === 'team') {
    const dl = $('agenda-day-label');
    if (dl) {
      const d = agendaTeamDate || new Date();
      dl.textContent = d.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' }).replace('.', '');
    }
  }
}

function renderAgendaInto(wrapId, weekLabelId, userId) {
  const wrap = document.getElementById(wrapId);
  if (!wrap) return; // página não montada nesse momento
  // Só constrói a grade se a página que a contém está visível. Sem isso,
  // renderAgenda() montava DUAS grades toda vez (a standalone /agenda E a embed
  // de Minhas Demandas), mesmo a escondida — cada uma custa centenas de células.
  const page = wrap.closest('.page');
  if (page && !page.classList.contains('active')) return;
  // Modo Time só na página standalone (não em Minhas Demandas embed).
  const isStandalone = (wrapId === 'agenda-grid-wrap');
  const useTeam = isStandalone && agendaMode === 'team';
  const days = useTeam ? [new Date(agendaTeamDate || new Date())] : agendaDays();
  const first = days[0], last = days[days.length - 1];
  const wkLabel = document.getElementById(weekLabelId);
  if (wkLabel && first && last && !useTeam) {
    const fmt = (d) => d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
    wkLabel.textContent = `${fmt(first)} → ${fmt(last)}`;
  }
  if (useTeam) {
    if (!agendaTeamUsers.length) {
      wrap.innerHTML = '<div class="agenda-empty">Escolha pessoas pra montar a vista de time.</div>';
      return;
    }
    buildAgendaGrid(wrap, null, days, { team: true });
    return;
  }
  if (!userId) { wrap.innerHTML = '<div class="agenda-empty">Sem usuário pra exibir.</div>'; return; }
  buildAgendaGrid(wrap, userId, days);
}

function buildAgendaGrid(wrap, agendaUserIdLocal, days, opts) {
  const isTeam = !!(opts && opts.team);
  if (!isTeam && !agendaUserIdLocal) { wrap.innerHTML = '<div class="agenda-empty">Selecione um usuário pra ver a agenda.</div>'; return; }

  const slotsPerDay = Math.ceil((AGENDA_DAY_END_MIN - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN);
  const rows = slotsPerDay;
  const layout = agendaColumnsLayout();
  // "dayCols" = colunas de conteúdo (dia ou user, dependendo do modo).
  const dayCols = layout.cols.filter(c => c.type === 'day' || c.type === 'user');
  // ymd por coluna, calculado UMA vez (agendaYmd faz toISOString — caro em loop).
  layout.cols.forEach(c => { if (c.day) c._ymd = agendaYmd(c.day); });

  const grid = document.createElement('div');
  grid.className = 'agenda-grid';
  grid.style.gridTemplateColumns = layout.gridTemplate;
  grid.style.gridTemplateRows = `auto repeat(${rows}, ${AGENDA_SLOT_PX}px)`;
  grid.style.width = '100%';
  // O grid carrega o userId alvo no dataset pra que handlers de drag/click
  // (que podem ser de qualquer instância: standalone OU embed em Minhas Demandas)
  // saibam pra quem agendar/editar — sem depender da variável global agendaUserId.
  grid.dataset.userId = agendaUserIdLocal;
  // Um único listener delegado no grid (era 1 por célula → ~900 listeners/render).
  grid.addEventListener('mousedown', onAgendaCellMouseDown);

  // Canto (0,0)
  const corner = document.createElement('div');
  corner.className = 'agenda-corner';
  corner.style.gridRow = '1 / 2';
  corner.style.gridColumn = '1 / 2';
  grid.appendChild(corner);

  const todayYmd = agendaYmd(new Date());
  // Headers da linha 1 — itera sobre todas as colunas (day + gap)
  layout.cols.forEach(c => {
    if (c.type === 'gap') {
      const gapHead = document.createElement('div');
      gapHead.className = 'agenda-cell is-day-header is-week-gap';
      gapHead.style.gridRow = '1 / 2';
      gapHead.style.gridColumn = `${c.gridCol} / ${c.gridCol + 1}`;
      grid.appendChild(gapHead);
      return;
    }
    const d = c.day;
    const head = document.createElement('div');
    head.className = 'agenda-cell is-day-header';
    if (c._ymd === todayYmd) head.classList.add('is-today');
    if (c.type === 'user') {
      // Header do modo Time: avatar + nome + capacidade do dia daquele user.
      const u = c.user;
      // Só demanda + blocos "Reunião" contam no tempo. Livre (focus/off/other) fica de fora.
      const schedMin = schedules
        .filter(s => s.userId === u.id && s.date === c._ymd)
        .filter(s => s.demandId || s.kind === 'meeting')
        .reduce((sum, s) => sum + (s.endMin - s.startMin), 0);
      const dayMin = schedMin + dayGoogleMinutes(u.id, c._ymd);
      const dayHours = dayMin / 60;
      const capacityH = 8;
      let capClass = '';
      if (dayHours > capacityH) capClass = 'over';
      else if (dayHours > capacityH * 0.85) capClass = 'high';
      const capLabel = `${dayHours.toFixed(1).replace('.', ',')}h / ${capacityH}h`;
      head.classList.add('is-user-header');
      head.innerHTML = `${avatarHTML(u, 'avatar avatar-sm')}<span class="agenda-user-head-name">${esc(u.name)}</span><span class="day-cap ${capClass}">${esc(capLabel)}</span>`;
    } else {
      const dayName = d.toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', '').toUpperCase();
      const dayDate = d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      const schedMin = schedules
        .filter(s => s.userId === agendaUserIdLocal && s.date === c._ymd)
        .filter(s => s.demandId || s.kind === 'meeting')
        .reduce((sum, s) => sum + (s.endMin - s.startMin), 0);
      const dayMin = schedMin + dayGoogleMinutes(agendaUserIdLocal, c._ymd);
      const dayHours = dayMin / 60;
      const capacityH = 8;
      let capClass = '';
      if (dayHours > capacityH) capClass = 'over';
      else if (dayHours > capacityH * 0.85) capClass = 'high';
      const capLabel = `${dayHours.toFixed(1).replace('.', ',')}h / ${capacityH}h`;
      head.innerHTML = `<span>${esc(dayName)}</span><span class="day-date">${esc(dayDate)}</span><span class="day-cap ${capClass}">${esc(capLabel)}</span>`;
    }
    head.style.gridRow = '1 / 2';
    head.style.gridColumn = `${c.gridCol} / ${c.gridCol + 1}`;
    grid.appendChild(head);
  });

  // Coluna de horários: UMA célula por HORA (span de 4 slots), não 1 por slot de
  // 15min — o rótulo só aparecia no :00 mesmo.
  for (let min = AGENDA_DAY_START_MIN; min < AGENDA_DAY_END_MIN; min += 60) {
    const rowIdx = Math.floor((min - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
    const span = Math.min(60, AGENDA_DAY_END_MIN - min) / AGENDA_SLOT_MIN;
    const t = document.createElement('div');
    t.className = 'agenda-cell is-time';
    t.textContent = agendaMinsToHHMM(min);
    t.style.gridRow = `${rowIdx} / ${rowIdx + span}`;
    t.style.gridColumn = '1 / 2';
    grid.appendChild(t);
  }

  // Colunas de conteúdo: UMA célula por coluna cobrindo todas as linhas. As
  // linhas de 15/30/60min viram gradiente CSS (.agenda-col) — antes eram ~250
  // células individuais (cada uma com borda/fundo/relative), o que dominava o
  // "presentation delay". O minuto do drag é calculado pelo Y do mouse.
  layout.cols.forEach(c => {
    const col = document.createElement('div');
    col.style.gridRow = `2 / ${rows + 2}`;
    col.style.gridColumn = `${c.gridCol} / ${c.gridCol + 1}`;
    if (c.type === 'gap') {
      col.className = 'agenda-cell is-week-gap';
    } else {
      col.className = 'agenda-cell agenda-col';
      col.dataset.date = c._ymd;
      if (c.type === 'user') col.dataset.userId = c.user.id;
    }
    grid.appendChild(col);
  });

  // Blocos por cima. Antes de renderizar, computamos o "lane layout" por dia
  // pra que schedules + google events sobrepostos fiquem lado a lado ao invés
  // de empilhados. Cada coluna é isolada das outras no layout.
  // Individual: 1 user, N dias. Time: N users, 1 dia.
  const userSchedules = isTeam
    ? schedules.filter(s => agendaTeamUsers.includes(s.userId))
    : schedules.filter(s => s.userId === agendaUserIdLocal);
  // Eventos Google por coluna: team → do dono da coluna; individual → do user primary.
  const googleEventsForCol = (c) => {
    const uid = c.type === 'user' ? c.user.id : agendaUserIdLocal;
    return googleEventsForUser[uid] || [];
  };

  // Chave do layout por coluna: individual usa "ymd", time usa "userId:ymd".
  // Cacheia o ymd por coluna — agendaYmd() faz toISOString(), caro em loop.
  dayCols.forEach(c => { if (c._ymd === undefined) c._ymd = agendaYmd(c.day); });
  const colKey = (c) => c.type === 'user' ? `${c.user.id}:${c._ymd}` : c._ymd;
  const schedKey = (s) => isTeam ? `${s.userId}:${s.date}` : s.date;

  // Processa SÓ os agendamentos das colunas visíveis. Antes, os loops abaixo
  // varriam TODO o histórico do usuário (cresce sem limite) e ainda chamavam
  // agendaYmd/toISOString milhares de vezes — o gargalo real da agenda.
  const colByKey = new Map(dayCols.map(c => [colKey(c), c]));
  const schedByKey = new Map(); // colKey -> [schedules visíveis]
  const visibleSchedules = [];
  for (const s of userSchedules) {
    const k = schedKey(s);
    if (!colByKey.has(k)) continue;
    let arr = schedByKey.get(k);
    if (!arr) { arr = []; schedByKey.set(k, arr); }
    arr.push(s);
    visibleSchedules.push(s);
  }

  // Índices O(1) pra resolver demanda/projeto/cliente dos blocos — era .find()
  // linear por bloco (O(blocos × total de demandas), explode com muitos dados).
  const demandByIdMap = new Map(demands.map(d => [d.id, d]));
  const projectByIdMap = new Map(projects.map(p => [p.id, p]));
  const clientByIdMap = new Map(clients.map(c => [c.id, c]));

  const dayLayouts = {}; // { colKey: { assign, totalCols } }
  dayCols.forEach(c => {
    const key = colKey(c);
    const ymd = c._ymd;
    const inCol = (schedByKey.get(key) || []).map(s => ({
      id: 'sched:' + s.id, startMin: s.startMin, endMin: s.endMin, kind: 'sched', ref: s
    }));
    const dayGoogles = googleEventsForCol(c)
      .map(ev => googleEventToBlock(ev, ymd))
      .filter(Boolean)
      .map(b => ({ ...b, id: 'gcal:' + b.id, kind: 'google', ref: b }));
    dayLayouts[key] = computeLaneLayout([...inCol, ...dayGoogles]);
  });

  // Helper: converte col/totalCols → width%/left% inline pra bloco absoluto.
  const laneStyle = (col, totalCols) => {
    if (totalCols <= 1) return '';
    const w = 100 / totalCols;
    return `left: ${(col * w).toFixed(3)}%; width: calc(${w.toFixed(3)}% - 4px);`;
  };

  visibleSchedules.forEach(s => {
    const dayCol = colByKey.get(schedKey(s));
    if (!dayCol) return;
    const startRow = Math.max(0, Math.floor((s.startMin - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN));
    const endRow = Math.min(rows, Math.ceil((s.endMin - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN));
    if (endRow <= startRow) return;
    const isFree = !s.demandId;
    const demand = isFree ? null : (demandByIdMap.get(s.demandId) || null);
    const project = demand ? (projectByIdMap.get(demand.projectId) || null) : null;
    const client = project && project.clientId ? (clientByIdMap.get(project.clientId) || null) : null;
    const kindMeta = isFree ? scheduleKindOf(s.kind) : null;
    // Cor:
    //  - Livre: s.color explícita (do save) → cor do kind → accent
    //  - Vinculado atrasado (mesma pessoa): vermelho
    //  - Vinculado normal: stageColorSnapshot → cor do projeto → fallback
    let color;
    if (isFree) {
      color = s.color || kindMeta.color || '#7A00FF';
    } else {
      const isBlockLate = demand && !isDone(demand) && isLate(demand) && demand.ownerId === s.userId;
      color = isBlockLate ? '#EF4444' : (s.stageColorSnapshot || project?.color || '#7A00FF');
    }
    const layout = dayLayouts[schedKey(s)];
    const myCol = layout ? layout.assign['sched:' + s.id] : 0;
    const totalCols = layout ? layout.totalCols : 1;
    const block = document.createElement('div');
    block.className = 'agenda-block';
    if (totalCols > 1) block.classList.add('is-laned');
    if (isFree) block.classList.add('agenda-block--free');
    block.dataset.scheduleId = s.id;
    block.style.gridRow = `${startRow + 2} / ${endRow + 2}`;
    block.style.gridColumn = `${dayCol.gridCol} / ${dayCol.gridCol + 1}`;
    if (totalCols > 1) block.style.cssText += laneStyle(myCol, totalCols);
    block.style.background = color;
    const canEdit = !!(me && (me.isAdmin || s.userId === me.id));
    const actions = canEdit ? `
      <div class="agenda-block-actions">
        <button class="agenda-block-action" title="Editar" data-action="edit"><i data-lucide="pencil" class="ic-xs"></i></button>
        <button class="agenda-block-action danger" title="Excluir" data-action="delete"><i data-lucide="x" class="ic-xs"></i></button>
      </div>` : '';
    let nameHtml, metaHtml;
    if (isFree) {
      nameHtml = `<div class="agenda-block-name"><i data-lucide="${kindMeta.icon}" class="agenda-block-free-icon"></i>${esc(s.title || kindMeta.label)}</div>`;
      metaHtml = `<div class="agenda-block-project">${esc(kindMeta.label)}</div>`;
    } else {
      const projName = project ? project.name : '';
      const clientName = client ? client.name : '';
      const demandName = demand ? demand.name : '(demanda removida)';
      nameHtml = `<div class="agenda-block-name">${esc(demandName)}</div>`;
      const meta = [clientName, projName].filter(Boolean).join(' · ');
      metaHtml = meta ? `<div class="agenda-block-project">${esc(meta)}</div>` : '';
    }
    block.innerHTML = `
      ${actions}
      ${nameHtml}
      ${metaHtml}
      ${canEdit ? '<div class="agenda-block-resize" data-resize="1"></div>' : ''}`;
    block.addEventListener('mousedown', (e) => {
      if (e.target.closest('[data-action]')) return;
      onAgendaBlockMouseDown(e, s, canEdit);
    });
    block.addEventListener('click', (e) => {
      const actionBtn = e.target.closest('[data-action]');
      if (actionBtn) {
        e.stopPropagation();
        if (actionBtn.dataset.action === 'edit') openScheduleModal(s.id);
        else if (actionBtn.dataset.action === 'delete') confirmDeleteSchedule(s.id);
        return;
      }
      if (!_agendaDrag || !_agendaDrag.moved) {
        if (demand) showDetail(demand.id);
        else if (isFree) openScheduleModal(s.id); // clique em bloco livre abre edição
      }
    });
    grid.appendChild(block);
  });

  // Google Calendar events — blocos read-only, azuis, sem drag/resize.
  // Clique abre modal enxuto com título + link "Abrir no Google Calendar".
  dayCols.forEach(c => {
    const ymd = c._ymd;
    const layout = dayLayouts[colKey(c)];
    if (!layout) return;
    const dayEvents = googleEventsForCol(c)
      .map(ev => googleEventToBlock(ev, ymd))
      .filter(Boolean);
    dayEvents.forEach(gb => {
      const startRow = Math.max(0, Math.floor((gb.startMin - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN));
      const endRow = Math.min(rows, Math.ceil((gb.endMin - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN));
      if (endRow <= startRow) return;
      const laneId = 'gcal:' + gb.id;
      const myCol = layout.assign[laneId] ?? 0;
      const totalCols = layout.totalCols;
      const block = document.createElement('div');
      block.className = 'agenda-block agenda-block--google';
      const respClass = googleResponseClass(gb.selfResponseStatus);
      if (respClass) block.classList.add(respClass);
      if (totalCols > 1) block.classList.add('is-laned');
      block.style.gridRow = `${startRow + 2} / ${endRow + 2}`;
      block.style.gridColumn = `${c.gridCol} / ${c.gridCol + 1}`;
      if (totalCols > 1) block.style.cssText += laneStyle(myCol, totalCols);
      // Filled só quando aceito/tentativo/sem attendees; outros variantes usam
      // background da variante (deixamos o CSS decidir).
      if (!respClass) block.style.background = gb.backgroundColor || '#0b57d0';
      // Ícone da plataforma da reunião ao lado do título — só aparece se detectou link.
      const meetIcon = gb.meeting
        ? `<i data-lucide="${meetingIconName(gb.meeting.kind)}" class="agenda-block-meet-icon"></i>`
        : '';
      block.innerHTML = `
        <div class="agenda-block-name">
          <svg class="agenda-block-google-icon" viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2.4">
            <rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>
          </svg>
          <span>${esc(gb.summary)}</span>
          ${meetIcon}
        </div>`;
      block.addEventListener('click', () => openGoogleEventDetail(gb));
      grid.appendChild(block);
    });
  });

  wrap.innerHTML = '';
  wrap.appendChild(grid);
  // Linha "agora" logo depois do append pra pegar as posições do grid corretas.
  placeAgendaNowLine(grid);
  paintIcons(grid); // escopa no grid — evita varrer o documento inteiro
  // Garante que o ticker está rodando pra atualizar a linha e disparar lembretes.
  startAgendaTicker();

  // Se ainda sem cache de eventos, dispara fetch async. O backend devolve []
  // se o usuário-alvo não tem Google conectado, então não custa nada tentar.
  // Re-render acontece dentro de refreshGoogleEventsForUser quando termina.
  // Time: dispara pra CADA usuário selecionado (max 6, então N no máximo).
  if (isTeam) {
    agendaTeamUsers.forEach(uid => {
      if (!googleEventsForUser[uid]) refreshGoogleEventsForUser(uid);
    });
  } else if (!googleEventsForUser[agendaUserIdLocal]) {
    refreshGoogleEventsForUser(agendaUserIdLocal);
  }
}

/* ─── Linha do horário atual + lembretes de reunião ───
   Ticker global: atualiza a "linha vermelha" da agenda a cada 30s e checa
   eventos Google prestes a começar (janela -30s a +60s). Deduplica lembretes
   por event.id na _notifiedEventIds. */
let _agendaTicker = null;
const _notifiedEventIds = new Set();
function startAgendaTicker() {
  if (_agendaTicker) return;
  _agendaTicker = setInterval(() => {
    updateAgendaNowLine();
    checkEventReminders();
  }, 30000);
}
function updateAgendaNowLine() {
  document.querySelectorAll('.agenda-now-line').forEach(el => el.remove());
  document.querySelectorAll('.agenda-grid').forEach(placeAgendaNowLine);
}
function placeAgendaNowLine(grid) {
  if (!grid) return;
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  if (nowMin < AGENDA_DAY_START_MIN || nowMin > AGENDA_DAY_END_MIN) return;
  const todayYmd = agendaYmd(now);
  // Acha uma célula do dia de hoje pra pegar a coluna do grid.
  const todayCell = grid.querySelector(`.agenda-cell[data-date="${todayYmd}"]`);
  if (!todayCell) return;
  const gridColumn = todayCell.style.gridColumn;
  const offsetMin = nowMin - AGENDA_DAY_START_MIN;
  const slotIdx = Math.floor(offsetMin / AGENDA_SLOT_MIN);
  const withinSlot = (offsetMin % AGENDA_SLOT_MIN) / AGENDA_SLOT_MIN;
  const line = document.createElement('div');
  line.className = 'agenda-now-line';
  line.style.gridColumn = gridColumn;
  line.style.gridRow = `${slotIdx + 2} / ${slotIdx + 3}`;
  line.style.setProperty('--now-y', (withinSlot * 100) + '%');
  line.title = `Agora — ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
  grid.appendChild(line);
}
function checkEventReminders() {
  if (!me?.id) return;
  const events = googleEventsForUser[me.id] || [];
  const now = Date.now();
  events.forEach(ev => {
    if (!ev.start || ev.allDay) return;
    if (_notifiedEventIds.has(ev.id)) return;
    const startMs = new Date(ev.start).getTime();
    if (!Number.isFinite(startMs)) return;
    const diff = startMs - now;
    // Janela: dispara de -30s até +60s da hora de início.
    if (diff > -30000 && diff <= 60000) {
      showEventReminder(ev);
      _notifiedEventIds.add(ev.id);
    }
  });
}
function showEventReminder(ev) {
  const startDate = new Date(ev.start);
  const endDate = ev.end ? new Date(ev.end) : null;
  const startLbl = `${String(startDate.getHours()).padStart(2,'0')}:${String(startDate.getMinutes()).padStart(2,'0')}`;
  const endLbl = endDate ? `${String(endDate.getHours()).padStart(2,'0')}:${String(endDate.getMinutes()).padStart(2,'0')}` : '';
  const timeLbl = endLbl ? `${startLbl} — ${endLbl}` : startLbl;
  // Popup in-app — cria overlay flutuante bottom-right.
  const wrapId = 'event-reminder-wrap';
  let wrap = document.getElementById(wrapId);
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = wrapId;
    document.body.appendChild(wrap);
  }
  const card = document.createElement('div');
  card.className = 'event-reminder-card';
  const meetBtn = ev.meeting?.url
    ? `<a class="btn btn-primary" href="${esc(ev.meeting.url)}" target="_blank" rel="noopener"><i data-lucide="${meetingIconName(ev.meeting.kind)}" class="ic-sm"></i> Entrar no ${esc(meetingLabel(ev.meeting.kind))}</a>`
    : (ev.htmlLink ? `<a class="btn btn-primary" href="${esc(ev.htmlLink)}" target="_blank" rel="noopener"><i data-lucide="external-link" class="ic-sm"></i> Abrir</a>` : '');
  card.innerHTML = `
    <div class="event-reminder-head">
      <span class="event-reminder-badge"><i data-lucide="bell" class="ic-sm"></i> Reunião começando</span>
      <button class="event-reminder-close" title="Dispensar" onclick="this.closest('.event-reminder-card').remove()"><i data-lucide="x" class="ic-sm"></i></button>
    </div>
    <div class="event-reminder-title">${esc(ev.summary || '(Sem título)')}</div>
    <div class="event-reminder-time">${esc(timeLbl)}</div>
    <div class="event-reminder-actions">${meetBtn}</div>`;
  wrap.appendChild(card);
  paintIcons();
  // Auto-dispensa após 5 min pra não acumular.
  setTimeout(() => card.remove(), 5 * 60 * 1000);
  // Notificação nativa do browser (bônus — funciona com aba em background).
  if ('Notification' in window && Notification.permission === 'granted') {
    try {
      const n = new Notification(ev.summary || 'Reunião começando', {
        body: timeLbl + (ev.meeting?.url ? ' · ' + meetingLabel(ev.meeting.kind) : ''),
        tag: ev.id,
        requireInteraction: false
      });
      n.onclick = () => { window.focus(); if (ev.meeting?.url) window.open(ev.meeting.url, '_blank'); };
    } catch {}
  } else if ('Notification' in window && Notification.permission === 'default') {
    // Pede permissão silenciosamente na 1ª vez.
    Notification.requestPermission().catch(() => {});
  }
}

// Modal enxuto pro evento Google — título + horário + botão "Abrir no Google Calendar".
// Cria o overlay on-demand pra não poluir o HTML com mais um modal fixo.
function openGoogleEventDetail(gb) {
  const startHH = String(Math.floor(gb.startMin / 60)).padStart(2, '0');
  const startMM = String(gb.startMin % 60).padStart(2, '0');
  const endHH = String(Math.floor(gb.endMin / 60)).padStart(2, '0');
  const endMM = String(gb.endMin % 60).padStart(2, '0');
  const timeLabel = `${startHH}:${startMM} — ${endHH}:${endMM}`;
  let modal = document.getElementById('gcal-event-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'gcal-event-modal';
    modal.className = 'modal-overlay';
    // Sem data-no-outside-close: o handler global de outside-click cuida do fechar.
    modal.innerHTML = `
      <div class="modal modal-sm">
        <div class="modal-body">
          <div class="gcal-modal-badge">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4">
              <rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>
            </svg>
            <span>Evento do Google Calendar</span>
          </div>
          <div class="gcal-modal-title" id="gcal-modal-title"></div>
          <div class="gcal-modal-time" id="gcal-modal-time"></div>
          <div class="gcal-modal-meeting" id="gcal-modal-meeting" style="display:none"></div>
        </div>
        <div class="modal-footer" style="justify-content:space-between">
          <button class="btn btn-ghost" onclick="closeModal('gcal-event-modal')">Fechar</button>
          <a class="btn btn-primary" id="gcal-modal-link" target="_blank" rel="noopener">
            <i data-lucide="external-link" class="ic-sm"></i> Abrir no Google Calendar
          </a>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }
  $('gcal-modal-title').textContent = gb.summary;
  $('gcal-modal-time').textContent = timeLabel;
  const linkEl = $('gcal-modal-link');
  if (gb.htmlLink) {
    linkEl.href = gb.htmlLink;
    linkEl.style.display = '';
  } else {
    linkEl.style.display = 'none';
  }
  // Botão "Entrar" da reunião — só aparece quando detectou link (Meet/Zoom/Teams).
  const meetEl = $('gcal-modal-meeting');
  if (meetEl) {
    if (gb.meeting && gb.meeting.url) {
      meetEl.style.display = '';
      meetEl.innerHTML = `<a class="btn btn-primary gcal-meet-btn" href="${esc(gb.meeting.url)}" target="_blank" rel="noopener"><i data-lucide="${meetingIconName(gb.meeting.kind)}" class="ic-sm"></i> Entrar no ${esc(meetingLabel(gb.meeting.kind))}</a>`;
    } else {
      meetEl.style.display = 'none';
      meetEl.innerHTML = '';
    }
  }
  openModal('gcal-event-modal');
  paintIcons();
}

// Resolve o scope de exclusão (one|future|series) para blocos livres com
// recurrenceGroupId. Modal ad-hoc — showConfirm só tem 2 botões.
function _pickScheduleDeleteScope(s) {
  if (!s || !s.recurrenceGroupId) return Promise.resolve('one');
  const patternLabel = s.recurrencePattern === 'weekdays' ? 'todo dia útil' : 'semanal';
  return new Promise(resolve => {
    let overlay = document.getElementById('sch-scope-modal');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'sch-scope-modal';
      overlay.className = 'modal-overlay';
      overlay.innerHTML = `<div class="modal modal-sm" data-no-outside-close="1">
        <div class="modal-header">
          <div class="modal-title">Excluir bloco de série</div>
          <button class="modal-close" data-scope="cancel"><i data-lucide="x" class="ic-sm"></i></button>
        </div>
        <div class="modal-body">
          <div id="sch-scope-msg" style="font-size:13px;color:var(--text-dim)"></div>
        </div>
        <div class="modal-footer" style="flex-wrap:wrap;gap:8px;justify-content:flex-end">
          <button class="btn btn-ghost" data-scope="cancel">Cancelar</button>
          <button class="btn btn-danger" data-scope="one">Apenas este</button>
          <button class="btn btn-danger" data-scope="future">Deste dia em diante</button>
          <button class="btn btn-danger" data-scope="series">Toda a série</button>
        </div>
      </div>`;
      document.body.appendChild(overlay);
    }
    overlay.querySelector('#sch-scope-msg').textContent =
      `Este bloco faz parte de uma série (${patternLabel}). O que você quer excluir?`;
    const onClick = (e) => {
      const btn = e.target.closest('[data-scope]');
      if (!btn) return;
      const scope = btn.dataset.scope;
      overlay.removeEventListener('click', onClick);
      closeModal('sch-scope-modal');
      resolve(scope === 'cancel' ? null : scope);
    };
    overlay.addEventListener('click', onClick);
    openModal('sch-scope-modal');
    paintIcons(overlay);
  });
}
async function _resolveDeleteScope(s) {
  if (s && s.recurrenceGroupId) return _pickScheduleDeleteScope(s);
  const ok = await showConfirm({
    title: 'Excluir bloco', message: 'Remover esse bloco da agenda?',
    okLabel: 'Excluir', danger: true
  });
  return ok ? 'one' : null;
}
async function confirmDeleteSchedule(id) {
  const s = schedules.find(x => x.id === id);
  const scope = await _resolveDeleteScope(s);
  if (!scope) return;
  try {
    const q = scope !== 'one' ? '?scope=' + scope : '';
    await api('/schedules/' + id + q, 'DELETE');
    schedules = await api('/schedules');
    renderAgenda();
  } catch (e) { toast(e.message, 'error'); }
}
async function deleteScheduleFromModal() {
  if (!editingScheduleId) return;
  const s = schedules.find(x => x.id === editingScheduleId);
  const scope = await _resolveDeleteScope(s);
  if (!scope) return;
  try {
    const q = scope !== 'one' ? '?scope=' + scope : '';
    await api('/schedules/' + editingScheduleId + q, 'DELETE');
    schedules = await api('/schedules');
    closeModal('schedule-modal');
    renderAgenda();
  } catch (e) { toast(e.message, 'error'); }
}

/* ── Drag-to-create ──
   mousedown numa célula vazia, mousemove pinta ghost, mouseup abre modal. */
function onAgendaCellMouseDown(e) {
  if (e.button !== 0) return;
  // Delegado no grid: resolve a célula-coluna do dia pelo alvo. Ignora headers,
  // coluna de horários, gaps e blocos (que têm handler próprio).
  const cell = e.target.closest('.agenda-col');
  if (!cell || !cell.dataset.date) return;
  const grid = cell.closest('.agenda-grid');
  // Célula do modo Time carrega userId próprio; individual pega do grid.
  const targetUserId = cell.dataset.userId || grid?.dataset.userId || agendaUserId;
  if (me && !me.isAdmin && targetUserId !== me.id) return;
  e.preventDefault();
  const date = cell.dataset.date;
  const startMin = agendaMinFromY(cell, e.clientY);
  const startRowIdx = Math.floor((startMin - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
  _agendaDrag = { mode: 'create', date, startRow: startMin, endRow: startMin + AGENDA_SLOT_MIN, ghost: null, moved: false, targetUserId, grid };
  document.addEventListener('mousemove', onAgendaCreateMove);
  document.addEventListener('mouseup', onAgendaCreateUp, { once: true });
  const ghost = document.createElement('div');
  ghost.className = 'agenda-ghost';
  ghost.style.gridColumn = cell.style.gridColumn;
  ghost.style.gridRow = `${startRowIdx} / ${startRowIdx + 1}`;
  ghost.textContent = agendaMinsToHHMM(startMin) + ' → ' + agendaMinsToHHMM(startMin + AGENDA_SLOT_MIN);
  grid.appendChild(ghost);
  _agendaDrag.ghost = ghost;
  _agendaDrag.ghostCol = cell.style.gridColumn;
}
function onAgendaCreateMove(e) {
  if (!_agendaDrag || _agendaDrag.mode !== 'create') return;
  const el = document.elementFromPoint(e.clientX, e.clientY);
  if (!el) return;
  const cell = el.closest && el.closest('.agenda-col');
  if (!cell || cell.dataset.date !== _agendaDrag.date) return;
  // Modo Time: mantém drag na coluna do MESMO user (não vaza pra outro).
  if (cell.dataset.userId && cell.dataset.userId !== _agendaDrag.targetUserId) return;
  _agendaDrag.moved = true;
  const cur = agendaMinFromY(cell, e.clientY) + AGENDA_SLOT_MIN;
  _agendaDrag.endRow = Math.max(_agendaDrag.startRow + AGENDA_SLOT_MIN, cur);
  const startRowIdx = Math.floor((_agendaDrag.startRow - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
  const endRowIdx = Math.ceil((_agendaDrag.endRow - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
  _agendaDrag.ghost.style.gridRow = `${startRowIdx} / ${endRowIdx}`;
  // Atualiza a label com a faixa horária arrastada — feedback visual imediato.
  _agendaDrag.ghost.textContent = agendaMinsToHHMM(_agendaDrag.startRow) + ' → ' + agendaMinsToHHMM(_agendaDrag.endRow);
}
function onAgendaCreateUp() {
  document.removeEventListener('mousemove', onAgendaCreateMove);
  if (_agendaDrag && _agendaDrag.ghost && _agendaDrag.ghost.parentNode) {
    _agendaDrag.ghost.parentNode.removeChild(_agendaDrag.ghost);
  }
  if (_agendaDrag) {
    openScheduleModal(null, { date: _agendaDrag.date, startMin: _agendaDrag.startRow, endMin: _agendaDrag.endRow, userId: _agendaDrag.targetUserId || agendaUserId });
  }
  _agendaDrag = null;
}

/* ── Drag-to-move + drag-to-resize ──
   mousedown num bloco existente → ou move (corpo) ou resize (borda inferior).
   Em move: ghost segue cursor e ancora em cell mais próxima.
   Em resize: ajusta só o endMin. */
function onAgendaBlockMouseDown(e, schedule, canEdit) {
  if (!canEdit) return;
  if (e.button !== 0) return;
  e.stopPropagation();
  e.preventDefault();
  const isResize = !!(e.target.dataset && e.target.dataset.resize);
  const block = e.currentTarget;
  _agendaDrag = {
    mode: isResize ? 'resize' : 'move',
    scheduleId: schedule.id,
    origDate: schedule.date,
    origStart: schedule.startMin,
    origEnd: schedule.endMin,
    origGridRow: block.style.gridRow,
    origGridColumn: block.style.gridColumn,
    block,
    ghost: null,
    moved: false
  };
  block.classList.add('dragging');
  // Ghost card: só faz sentido pra mover (o resize é preview no próprio bloco).
  // Clona o bloco pra que o ghost tenha exatamente o mesmo visual, com styles
  // do drag-ghost por cima (opacity/outline).
  if (!isResize) {
    const ghost = block.cloneNode(true);
    ghost.classList.add('agenda-block-ghost');
    ghost.classList.remove('dragging');
    ghost.removeAttribute('data-schedule-id');
    // Remove interações do ghost — ele é só visual.
    ghost.style.pointerEvents = 'none';
    block.parentElement.appendChild(ghost);
    _agendaDrag.ghost = ghost;
  }
  document.addEventListener('mousemove', onAgendaBlockMove);
  document.addEventListener('mouseup', onAgendaBlockUp, { once: true });
}
function onAgendaBlockMove(e) {
  if (!_agendaDrag) return;
  const el = document.elementFromPoint(e.clientX, e.clientY);
  if (!el) return;
  const cell = el.closest && el.closest('.agenda-col');
  if (!cell || !cell.dataset.date) return; // fora de uma coluna de dia (gap/header)
  const min = agendaMinFromY(cell, e.clientY);
  if (_agendaDrag.mode === 'move') {
    const duration = _agendaDrag.origEnd - _agendaDrag.origStart;
    _agendaDrag.newDate = cell.dataset.date;
    _agendaDrag.newStart = min;
    _agendaDrag.newEnd = Math.min(AGENDA_DAY_END_MIN, min + duration);
    _agendaDrag.moved = true;
    // Bloco original fica onde está (com .dragging aplicando opacity).
    // O ghost é que segue o cursor com preview da posição alvo.
    const startRowIdx = Math.floor((_agendaDrag.newStart - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
    const endRowIdx = Math.ceil((_agendaDrag.newEnd - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
    if (_agendaDrag.ghost) {
      _agendaDrag.ghost.style.gridRow = `${startRowIdx} / ${endRowIdx}`;
      _agendaDrag.ghost.style.gridColumn = cell.style.gridColumn;
    }
  } else { // resize — sem ghost, preview no próprio bloco
    const newEnd = Math.max(_agendaDrag.origStart + AGENDA_SLOT_MIN, min + AGENDA_SLOT_MIN);
    if (newEnd === _agendaDrag.newEnd) return;
    _agendaDrag.newEnd = Math.min(AGENDA_DAY_END_MIN, newEnd);
    _agendaDrag.moved = true;
    const startRowIdx = Math.floor((_agendaDrag.origStart - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
    const endRowIdx = Math.ceil((_agendaDrag.newEnd - AGENDA_DAY_START_MIN) / AGENDA_SLOT_MIN) + 2;
    _agendaDrag.block.style.gridRow = `${startRowIdx} / ${endRowIdx}`;
  }
}
async function onAgendaBlockUp() {
  document.removeEventListener('mousemove', onAgendaBlockMove);
  if (!_agendaDrag) return;
  const drag = _agendaDrag;
  drag.block.classList.remove('dragging');
  if (drag.ghost && drag.ghost.parentElement) drag.ghost.parentElement.removeChild(drag.ghost);
  _agendaDrag = null;
  if (!drag.moved) return; // click puro, deixa o click handler abrir o detalhe
  const payload = {};
  if (drag.mode === 'move') {
    payload.date = drag.newDate;
    payload.startMin = drag.newStart;
    payload.endMin = drag.newEnd;
  } else {
    payload.endMin = drag.newEnd;
  }
  try {
    await api('/schedules/' + drag.scheduleId, 'PUT', payload);
    schedules = await api('/schedules'); // refetch sempre — fonte da verdade é o backend
    renderAgenda();
  } catch (e) {
    console.error('[agenda drag] PUT falhou:', e);
    toast(e.message || 'Erro ao mover/redimensionar', 'error');
    renderAgenda();
  }
}

/* ── Modal de agendar/editar bloco ── */
let _schedulePresetUserId = null; // userId do contexto de criação
// Estado da recorrência escolhida no modal atual. null = "não se repete".
// Formato: { pattern, interval, byWeekday?, count?, until? } (ver server.js).
let _scheduleRecurrence = null;

/* Labels dinâmicas do dropdown de recorrência, estilo Google Calendar.
   Populadas a partir da data selecionada no modal (usa o dow/nth/mês do dia). */
const WEEKDAY_LONG = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const WEEKDAY_SHORT = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];
const WEEKDAY_ORDINAL = ['primeiro(a)', 'segundo(a)', 'terceiro(a)', 'quarto(a)', 'último(a)'];
const MONTHS_LONG = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

// Popula o <select id="sch-recur"> baseado na data escolhida (dow/nth/mês).
// Restaura seleção anterior quando possível — mantém "personalizado" após reabrir.
function _populateScheduleRecur(dateYmd) {
  const sel = $('sch-recur');
  if (!sel) return;
  const d = dateYmd ? new Date(dateYmd + 'T12:00:00') : new Date();
  const dow = d.getDay();
  const dayName = WEEKDAY_LONG[dow];
  const nth = Math.min(5, Math.ceil(d.getDate() / 7));
  const nthLabel = WEEKDAY_ORDINAL[Math.min(nth - 1, WEEKDAY_ORDINAL.length - 1)];
  const monthName = MONTHS_LONG[d.getMonth()];
  const day = d.getDate();
  const options = [
    { v: 'none',      lbl: 'Não se repete' },
    { v: 'daily',     lbl: 'Todos os dias' },
    { v: 'weekly',    lbl: `Semanal: cada ${dayName}` },
    { v: 'monthly',   lbl: `Mensal no(a) ${nthLabel} ${dayName}` },
    { v: 'yearly',    lbl: `Anual em ${monthName} ${day}` },
    { v: 'weekdays',  lbl: 'Todos os dias da semana (segunda a sexta-feira)' },
    { v: 'custom',    lbl: 'Personalizar…' }
  ];
  const prev = sel.value;
  sel.innerHTML = options.map(o => `<option value="${o.v}">${esc(o.lbl)}</option>`).join('');
  // Restaura seleção anterior se ainda válida; se o usuário tinha custom, mantém.
  if (prev && options.some(o => o.v === prev)) sel.value = prev;
  else sel.value = 'none';
}

// Handler do onchange do dropdown. 'custom' abre o modal; presets salvam objeto.
function onScheduleRecurPick(value) {
  const dateYmd = $('sch-date')?.value || null;
  const d = dateYmd ? new Date(dateYmd + 'T12:00:00') : new Date();
  const dow = d.getDay();
  if (value === 'custom') {
    openScheduleRecurCustomModal();
    return;
  }
  if (value === 'none') {
    _scheduleRecurrence = null;
  } else if (value === 'daily') {
    _scheduleRecurrence = { pattern: 'daily', interval: 1 };
  } else if (value === 'weekly') {
    _scheduleRecurrence = { pattern: 'weekly', interval: 1, byWeekday: [dow] };
  } else if (value === 'monthly') {
    _scheduleRecurrence = { pattern: 'monthly-nth-weekday', interval: 1 };
  } else if (value === 'yearly') {
    _scheduleRecurrence = { pattern: 'yearly', interval: 1 };
  } else if (value === 'weekdays') {
    _scheduleRecurrence = { pattern: 'weekdays', interval: 1 };
  }
  _updateScheduleRecurInfo();
}

// Info textual embaixo do dropdown quando há recorrência não-trivial.
function _updateScheduleRecurInfo() {
  const info = $('sch-recur-info');
  if (!info) return;
  const r = _scheduleRecurrence;
  if (!r) { info.style.display = 'none'; info.textContent = ''; return; }
  const parts = [];
  const unitPlural = { daily: 'dias', weekly: 'semanas', 'monthly-nth-weekday': 'meses', yearly: 'anos', weekdays: 'dia útil' };
  const unitSingular = { daily: 'dia', weekly: 'semana', 'monthly-nth-weekday': 'mês', yearly: 'ano', weekdays: 'dia útil' };
  const unit = r.interval === 1 ? unitSingular[r.pattern] : unitPlural[r.pattern];
  parts.push(`A cada ${r.interval} ${unit}`);
  if (r.pattern === 'weekly' && r.byWeekday && r.byWeekday.length) {
    parts.push(`em ${r.byWeekday.map(i => WEEKDAY_LONG[i]).join(', ')}`);
  }
  if (r.count) parts.push(`por ${r.count} ocorrências`);
  else if (r.until) parts.push(`até ${_fmtBrShort(r.until)}`);
  else parts.push('por até 2 anos');
  info.textContent = parts.join(' · ');
  info.style.display = '';
}
function _fmtBrShort(ymd) {
  const [y, m, d] = ymd.split('-');
  return `${d}/${m}/${y}`;
}

// Modal "Recorrência personalizada" — criado on-demand (sem poluir index.html).
function openScheduleRecurCustomModal() {
  let modal = document.getElementById('sch-recur-custom-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'sch-recur-custom-modal';
    modal.className = 'modal-overlay';
    modal.innerHTML = `
      <div class="modal modal-sm" data-no-outside-close="1">
        <div class="modal-header">
          <div class="modal-title">Recorrência personalizada</div>
          <button class="modal-close" onclick="closeScheduleRecurCustomModal()"><i data-lucide="x" class="ic-sm"></i></button>
        </div>
        <div class="modal-body">
          <div class="rec-cust-row">
            <label class="rec-cust-label">Repetir a cada:</label>
            <input type="number" class="form-control rec-cust-num" id="rec-cust-interval" min="1" max="365" value="1">
            <select class="form-control rec-cust-unit" id="rec-cust-unit">
              <option value="daily">dias</option>
              <option value="weekly">semanas</option>
              <option value="monthly-nth-weekday">meses</option>
              <option value="yearly">anos</option>
            </select>
          </div>
          <div class="rec-cust-row rec-cust-days-row" id="rec-cust-days-row">
            <label class="rec-cust-label">Repetir:</label>
            <div class="rec-cust-days" id="rec-cust-days"></div>
          </div>
          <div class="rec-cust-end">
            <div class="rec-cust-label">Termina em</div>
            <label class="rec-cust-end-opt">
              <input type="radio" name="rec-cust-end" value="never" checked>
              <span>Nunca</span>
            </label>
            <label class="rec-cust-end-opt">
              <input type="radio" name="rec-cust-end" value="until">
              <span>Em</span>
              <input type="date" class="form-control rec-cust-end-input" id="rec-cust-until" disabled>
            </label>
            <label class="rec-cust-end-opt">
              <input type="radio" name="rec-cust-end" value="count">
              <span>Após</span>
              <input type="number" class="form-control rec-cust-end-input" id="rec-cust-count" min="1" max="260" placeholder="13" disabled>
              <span class="rec-cust-end-suffix">ocorrências</span>
            </label>
          </div>
        </div>
        <div class="modal-footer">
          <button class="btn btn-ghost" onclick="closeScheduleRecurCustomModal()">Cancelar</button>
          <button class="btn btn-primary" onclick="saveScheduleRecurCustom()">Concluir</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    // Handlers dos radios end-mode (habilita/desabilita os inputs).
    modal.addEventListener('change', (e) => {
      if (e.target?.name === 'rec-cust-end') {
        const mode = e.target.value;
        $('rec-cust-until').disabled = mode !== 'until';
        $('rec-cust-count').disabled = mode !== 'count';
      }
      if (e.target?.id === 'rec-cust-unit') {
        $('rec-cust-days-row').style.display = e.target.value === 'weekly' ? '' : 'none';
      }
    });
  }
  // Popula os chips de dias da semana (multi-select).
  const daysWrap = $('rec-cust-days');
  const baseYmd = $('sch-date')?.value || null;
  const baseD = baseYmd ? new Date(baseYmd + 'T12:00:00') : new Date();
  const currentPick = (_scheduleRecurrence?.byWeekday || [baseD.getDay()]);
  daysWrap.innerHTML = WEEKDAY_SHORT.map((lbl, i) => `
    <button type="button" class="rec-cust-day ${currentPick.includes(i) ? 'is-active' : ''}" data-dow="${i}"
      onclick="this.classList.toggle('is-active')">${esc(lbl)}</button>`).join('');
  // Estado inicial dos campos — usa _scheduleRecurrence se já for um custom, senão fresh.
  const r = _scheduleRecurrence;
  const isWeekly = !r || r.pattern === 'weekly';
  $('rec-cust-interval').value = r?.interval || 1;
  $('rec-cust-unit').value = (r && r.pattern) || 'weekly';
  $('rec-cust-days-row').style.display = $('rec-cust-unit').value === 'weekly' ? '' : 'none';
  // End mode: prioridade count > until > never
  let endMode = 'never';
  if (r?.count) endMode = 'count';
  else if (r?.until) endMode = 'until';
  modal.querySelectorAll('input[name="rec-cust-end"]').forEach(inp => { inp.checked = inp.value === endMode; });
  $('rec-cust-until').disabled = endMode !== 'until';
  $('rec-cust-count').disabled = endMode !== 'count';
  $('rec-cust-until').value = r?.until || '';
  $('rec-cust-count').value = r?.count || '';
  openModal('sch-recur-custom-modal');
  paintIcons(modal);
}
function closeScheduleRecurCustomModal() {
  closeModal('sch-recur-custom-modal');
  // Se o usuário cancelou sem já ter recorrência custom, reverte seleção pro que
  // já tá em _scheduleRecurrence (ou 'none').
  const sel = $('sch-recur');
  if (sel && sel.value === 'custom' && !_scheduleRecurrence) sel.value = 'none';
}
function saveScheduleRecurCustom() {
  const interval = Math.max(1, Math.min(365, Number.parseInt($('rec-cust-interval').value, 10) || 1));
  const unit = $('rec-cust-unit').value;
  const rec = { pattern: unit, interval };
  if (unit === 'weekly') {
    const picked = [...document.querySelectorAll('#rec-cust-days .rec-cust-day.is-active')]
      .map(b => Number.parseInt(b.dataset.dow, 10));
    if (!picked.length) { toast('Escolha ao menos um dia da semana.', 'error'); return; }
    rec.byWeekday = picked;
  }
  const endMode = document.querySelector('input[name="rec-cust-end"]:checked')?.value || 'never';
  if (endMode === 'until') {
    const until = $('rec-cust-until').value;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) { toast('Informe uma data válida.', 'error'); return; }
    rec.until = until;
  } else if (endMode === 'count') {
    const count = Math.max(1, Math.min(260, Number.parseInt($('rec-cust-count').value, 10) || 0));
    if (!count) { toast('Informe o número de ocorrências.', 'error'); return; }
    rec.count = count;
  }
  _scheduleRecurrence = rec;
  closeModal('sch-recur-custom-modal');
  _updateScheduleRecurInfo();
}

/* Presets de tipo pros blocos livres — ícone + cor default. */
const SCHEDULE_KINDS = [
  { k: 'meeting', label: 'Reunião', icon: 'video',    color: '#3B82F6' }, // blue — comunicação
  { k: 'focus',   label: 'Foco',    icon: 'target',   color: '#7A00FF' }, // roxo accent — foco profundo
  { k: 'off',     label: 'Off',     icon: 'coffee',   color: '#F59E0B' }, // âmbar — pausa
  { k: 'other',   label: 'Outro',   icon: 'bookmark', color: '#64748B' }  // slate — neutro
];
function scheduleKindOf(k) { return SCHEDULE_KINDS.find(x => x.k === k) || SCHEDULE_KINDS[3]; }

let _scheduleMode = 'demand'; // 'demand' | 'free'
let _scheduleKind = 'meeting';
function setScheduleMode(mode) {
  _scheduleMode = mode === 'free' ? 'free' : 'demand';
  $('sch-mode-demand')?.classList.toggle('is-active', _scheduleMode === 'demand');
  $('sch-mode-free')?.classList.toggle('is-active', _scheduleMode === 'free');
  // Posiciona o thumb deslizante do toggle (anima via CSS).
  $('sch-mode-toggle')?.classList.toggle('mode-free', _scheduleMode === 'free');
  const demandRow = $('sch-demand-row');
  const titleRow  = $('sch-title-row');
  const kindRow   = $('sch-kind-row');
  const recurRow  = $('sch-recur-row');
  if (demandRow) demandRow.style.display = _scheduleMode === 'demand' ? '' : 'none';
  if (titleRow)  titleRow.style.display  = _scheduleMode === 'free'   ? '' : 'none';
  if (kindRow)   kindRow.style.display   = _scheduleMode === 'free'   ? '' : 'none';
  if (recurRow)  recurRow.style.display  = _scheduleMode === 'free'   ? '' : 'none';
  if (_scheduleMode === 'free') renderScheduleKindChips();
}
function renderScheduleKindChips() {
  const wrap = $('sch-kind-chips');
  if (!wrap) return;
  wrap.innerHTML = SCHEDULE_KINDS.map(k => `
    <button type="button" class="sch-kind-chip ${k.k === _scheduleKind ? 'is-active' : ''}" data-kind="${k.k}" onclick="pickScheduleKind('${k.k}')" style="--kind-color:${k.color}">
      <i data-lucide="${k.icon}" class="ic-sm"></i>
      <span>${esc(k.label)}</span>
    </button>`).join('');
  paintIcons();
}
function pickScheduleKind(k) {
  _scheduleKind = SCHEDULE_KINDS.some(x => x.k === k) ? k : 'other';
  renderScheduleKindChips();
}

function openScheduleModal(id, preset) {
  editingScheduleId = id || null;
  _schedulePresetUserId = preset?.userId || null;
  const s = id ? schedules.find(x => x.id === id) : null;
  $('schedule-modal-title').textContent = s ? 'Editar bloco' : 'Agendar bloco';
  // Detecta modo: bloco existente sem demandId → free; caso contrário demand.
  const startMode = (s && !s.demandId) ? 'free' : 'demand';
  _scheduleKind = (s && s.kind) ? s.kind : 'meeting';
  setScheduleMode(startMode);
  $('sch-title').value = s?.title || '';
  // Popula select de demandas — TODAS as demandas atribuídas ao usuário
  // selecionado, através de todos os workspaces acessíveis (não só o ativo).
  // Em modo edição, mantém a demanda atual mesmo que não esteja mais atribuída
  // a esse user. A label ganha o nome do workspace pra distinguir quando o
  // usuário tem demandas em mais de um.
  const sel = $('sch-demand');
  const ownerUid = s ? s.userId : (preset?.userId || agendaUserId);
  let list = demands
    .filter(d => !d.deletedAt)
    .filter(d => d.ownerId === ownerUid)
    .sort((a,b) => norm(a.name).localeCompare(norm(b.name)));
  // Se editando e a demanda atual não está mais no usuário, força ela na lista
  if (s && !list.some(d => d.id === s.demandId)) {
    const cur = demands.find(d => d.id === s.demandId);
    if (cur) list.unshift(cur);
  }
  const currentDemandId = s ? s.demandId : '';
  if (!list.length) {
    sel.innerHTML = '<option value="">— Esse usuário não tem demandas atribuídas —</option>';
  } else {
    // Se o usuário tem demandas em mais de um workspace, prefixa o nome do WS
    // na label pra evitar confusão. Se só há 1, mantém o rótulo enxuto.
    const wsIds = new Set(list.map(d => d.workspaceId));
    const showWs = wsIds.size > 1;
    sel.innerHTML = '<option value="">— Selecione uma demanda —</option>' + list.map(d => {
      const p = projects.find(pp => pp.id === d.projectId);
      const c = p && p.clientId ? clients.find(cc => cc.id === p.clientId) : null;
      const ws = showWs ? wsById(d.workspaceId) : null;
      const meta = [ws?.name, c?.name, p?.name].filter(Boolean).join(' · ');
      const lbl = meta ? `${d.name} — ${meta}` : d.name;
      return `<option value="${d.id}" ${d.id === currentDemandId ? 'selected' : ''}>${esc(lbl)}</option>`;
    }).join('');
  }
  const date = (s ? s.date : preset?.date) || agendaYmd(new Date());
  const startMin = s ? s.startMin : (preset?.startMin || AGENDA_DAY_START_MIN);
  const endMin = s ? s.endMin : (preset?.endMin || (startMin + 60));
  $('sch-date').value = date;
  $('sch-start').value = agendaMinsToHHMM(startMin);
  $('sch-end').value = agendaMinsToHHMM(endMin);
  // "Quem" — texto amigável do responsável pelo bloco
  const userName = userById(s ? s.userId : (preset?.userId || agendaUserId))?.name || '—';
  $('sch-when').textContent = `Para ${userName}`;
  // Recorrência: só faz sentido em criação nova de bloco livre. Em edição,
  // esconde o select e mostra info se esse bloco faz parte de série.
  _scheduleRecurrence = null;
  const recurSel = $('sch-recur');
  const recurInfo = $('sch-recur-info');
  if (recurInfo) { recurInfo.style.display = 'none'; recurInfo.textContent = ''; }
  if (recurSel) {
    _populateScheduleRecur(date);
    recurSel.value = 'none';
  }
  if (s && s.recurrenceGroupId) {
    if (recurSel) recurSel.style.display = 'none';
    if (recurInfo) {
      const patternLabel = _recurrenceHumanLabel(s.recurrencePattern);
      recurInfo.style.display = '';
      recurInfo.textContent = `Faz parte de uma série (${patternLabel}). Ao excluir você escolhe apenas este ou toda a série.`;
    }
  } else if (recurSel) {
    recurSel.style.display = s ? 'none' : ''; // edição de bloco solto: sem opção de virar série
  }
  // Re-popula options quando o usuário mudar a data (labels dependem do dow).
  const dateInp = $('sch-date');
  if (dateInp && !dateInp._recurBound) {
    dateInp.addEventListener('change', () => {
      _populateScheduleRecur(dateInp.value);
      // Se estava em uma opção baseada em dow, invalida (o dia da semana mudou).
      const sel = $('sch-recur'); if (sel) sel.value = 'none';
      _scheduleRecurrence = null;
      _updateScheduleRecurInfo();
    });
    dateInp._recurBound = true;
  }
  $('sch-delete-btn').style.display = s ? '' : 'none';
  openModal('schedule-modal');
}
function _recurrenceHumanLabel(pattern) {
  return {
    daily: 'Todos os dias',
    weekly: 'Semanal',
    'monthly-nth-weekday': 'Mensal',
    yearly: 'Anual',
    weekdays: 'Todo dia útil'
  }[pattern] || 'Personalizada';
}
async function saveSchedule() {
  const date = $('sch-date').value;
  const startMin = agendaHHMMtoMins($('sch-start').value);
  const endMin = agendaHHMMtoMins($('sch-end').value);
  if (endMin <= startMin) { toast('Horário final precisa ser depois do início.', 'error'); return; }
  const payload = { date, startMin, endMin };
  if (_scheduleMode === 'free') {
    const title = ($('sch-title').value || '').trim();
    if (!title) { toast('Informe um título pro bloco livre.', 'error'); return; }
    payload.demandId = null;
    payload.title = title;
    payload.kind = _scheduleKind;
    payload.color = scheduleKindOf(_scheduleKind).color;
    // Blocos livres não têm demanda, então precisam de workspaceId explícito.
    payload.workspaceId = activeWs;
    // Recorrência — só em criação, e só em modo Livre. Aceita o objeto
    // _scheduleRecurrence completo (backend valida e expande).
    if (!editingScheduleId && _scheduleRecurrence) {
      payload.recurrence = _scheduleRecurrence;
    }
  } else {
    const demandId = $('sch-demand').value;
    if (!demandId) { toast('Selecione uma demanda.', 'error'); return; }
    payload.demandId = demandId;
  }
  // Pra criar (não-edição), respeita o usuário do contexto: o `_schedulePresetUserId`
  // é setado pelo openScheduleModal a partir do preset (drag em qualquer instância).
  if (!editingScheduleId) payload.userId = _schedulePresetUserId || agendaUserId;
  try {
    if (editingScheduleId) {
      await api('/schedules/' + editingScheduleId, 'PUT', payload);
    } else {
      await api('/schedules', 'POST', payload);
    }
    // Refetch do servidor — garante que o frontend mostra exatamente o que está
    // persistido (sem depender de splice/push manual no array local).
    schedules = await api('/schedules');
    closeModal('schedule-modal');
    renderAgenda();
  } catch (e) {
    console.error('[saveSchedule] falhou:', e);
    toast(e.message || 'Erro ao salvar', 'error');
  }
}

/* ─── REAL-TIME SYNC (Server-Sent Events) ───────────────────────
   EventSource conecta em /api/stream e recebe eventos sempre que
   outro usuário muda algo no workspace acessível. Cada evento dispara
   refetch da entidade afetada + re-render da página corrente.
   Reconexão automática é nativa do EventSource — só tratamos o
   fechamento explícito (logout).
   Debounce: várias mudanças em rajada (ex.: bulk) viram 1 refetch. */
let sseConnection = null;
let _sseEvents = []; // fila de eventos crus pra flush em janela curta
let _sseRefetchTimer = null;

// Mapa entity → { arr: nome da variável global (só pra doc), refetchList: () => Promise, singularPath: (id) => string }
const SSE_ENTITY_MAP = {
  demand:    { get: () => demands,     set: v => { demands = v; },     path: id => '/demands/' + id,    listPath: '/demands' },
  schedule:  { get: () => schedules,   set: v => { schedules = v; },   path: id => '/schedules/' + id,  listPath: '/schedules' },
  client:    { get: () => clients,     set: v => { clients = v; },     path: id => '/clients/' + id,    listPath: '/clients' },
  project:   { get: () => projects,    set: v => { projects = v; },    path: id => '/projects/' + id,   listPath: '/projects' },
  flow:      { get: () => flows,       set: v => { flows = v; },       path: id => '/flows/' + id,      listPath: '/flows' },
  recurring: { get: () => recurrings,  set: v => { recurrings = v; },  path: id => '/recurrings/' + id, listPath: '/recurrings' },
  lista:     { get: () => listas,      set: v => { listas = v; },      path: id => '/listas/' + id,     listPath: '/listas' },
  // tasks: server só emite ('bulk' no apply/'delete'/'update') — sem endpoint
  // singular, então operações granulares caem no fallback do refetch de lista.
  task:      { get: () => tasks,       set: v => { tasks = v; },       path: () => null,                listPath: '/tasks' },
};

function startRealtimeSync() {
  if (sseConnection) return; // já conectado
  try {
    sseConnection = new EventSource('/api/stream');
    sseConnection.addEventListener('message', onSseMessage);
    sseConnection.addEventListener('error', () => {
      // Browser tenta reconectar sozinho. Só logamos pra debug.
      console.debug('[sse] error / reconnecting...');
    });
  } catch (e) {
    console.warn('[sse] não foi possível conectar:', e);
  }
}

function stopRealtimeSync() {
  if (!sseConnection) return;
  sseConnection.close();
  sseConnection = null;
}

function onSseMessage(ev) {
  let data; try { data = JSON.parse(ev.data); } catch { return; }
  if (!data || !data.entity) return;
  _sseEvents.push(data);
  clearTimeout(_sseRefetchTimer);
  _sseRefetchTimer = setTimeout(flushSseRefetch, 250);
}

/* Aplicação granular:
   - op=delete   → remove local (sem network)
   - op=create/update com id → GET singular → substitui/adiciona no array
   - op=bulk ou sem id → refetch lista inteira (fallback)
   Coalesce: eventos com mesmo entity+id em janela curta são deduplicados. */
async function flushSseRefetch() {
  const events = _sseEvents.slice();
  _sseEvents.length = 0;
  // Dedup — última operação por (entity,id) vence
  const dedup = new Map();
  const fullRefetch = new Set(); // entities que precisam refetch da lista inteira
  let demandTouched = false;
  for (const e of events) {
    if (e.entity === 'demand') demandTouched = true;
    const spec = SSE_ENTITY_MAP[e.entity];
    if (!spec) continue;
    if (!e.id || e.op === 'bulk') { fullRefetch.add(e.entity); continue; }
    dedup.set(e.entity + ':' + e.id, e);
  }
  // Renomeado de `tasks` pra evitar shadow da global `tasks` (tarefas de projeto).
  const _pending = [];
  // 1) Refetches em lote (fallback pra bulk/sem-id)
  for (const entity of fullRefetch) {
    const spec = SSE_ENTITY_MAP[entity];
    _pending.push(api(spec.listPath).then(v => spec.set(v)).catch(() => {}));
  }
  // 2) Operações granulares
  for (const e of dedup.values()) {
    const spec = SSE_ENTITY_MAP[e.entity];
    if (e.op === 'delete') {
      spec.set(spec.get().filter(x => x.id !== e.id));
    } else {
      // Entities sem endpoint singular (path retorna null) caem em refetch da lista.
      const singularPath = spec.path(e.id);
      if (!singularPath) {
        _pending.push(api(spec.listPath).then(v => spec.set(v)).catch(() => {}));
        continue;
      }
      _pending.push(
        api(singularPath)
          .then(entity => {
            const arr = spec.get();
            const idx = arr.findIndex(x => x.id === e.id);
            if (idx >= 0) arr[idx] = entity;
            else arr.push(entity);
            spec.set(arr);
          })
          .catch(err => {
            // Se o GET singular deu 404 (perdeu acesso ao workspace, por ex.), tira da lista local
            if (String(err.message || '').match(/não encontrad/i)) {
              spec.set(spec.get().filter(x => x.id !== e.id));
            }
          })
      );
    }
  }
  await Promise.all(_pending);
  renderCurrent();
  if (demandTouched && detailId && currentPage === 'demand-detail') {
    refreshDetailDemand();
  }
}

/* ─── TOOLTIPS CUSTOMIZADOS — REMOVIDO ──────────────────────
   O sistema `.k-tooltip` foi tirado (bugs de travar/vazar). Tooltip agora é
   só CSS-only nos `.qty-cell-hint` (pontos de ajuda "?"). O resto usa title
   nativo do browser (bloqueado por initTooltips no bootstrap, exceto onde
   marcado como exceção pela classe `.qty-cell-hint`). */

/* ─── LOADING STATE EM BOTÕES ─────────────────────────────────
   Helper: chame com um event ou um button + asyncFn. Aplica .is-loading
   (CSS já tem regra com spinner) e disabled enquanto roda, restaura no fim. */
async function withLoading(eventOrBtn, asyncFn) {
  const btn = (eventOrBtn && eventOrBtn.currentTarget) || (eventOrBtn instanceof Element ? eventOrBtn : null);
  if (!btn) return asyncFn();
  btn.disabled = true;
  btn.classList.add('is-loading');
  try { return await asyncFn(); }
  finally {
    btn.disabled = false;
    btn.classList.remove('is-loading');
  }
}

/* ─── WIZARD DA NOVA DEMANDA ─────────────────────────────────────
   4 steps: Cliente → Projeto → Fluxo → Form. Click 1x seleciona um card,
   click duplo avança. Footer mostra Voltar/Avançar (steps 1-3) ou
   Voltar/Salvar como template/Criar demanda (step 4). Editar pula direto
   pro step 4 com seleção pré-preenchida. */
let wizardState = { step: 1, clientId: null, projectId: null, flowId: null };
// Último fluxo cujos defaults (descrição + checklist) já foram aplicados no form.
// Permite re-aplicar quando o usuário troca de fluxo no wizard sem perder edições
// quando ele volta e re-seleciona o MESMO fluxo.
let wizardLastFlowApplied = null;

/* Sequência do wizard: 1 (cliente) → 2 (projeto) → 3 (fluxo) → 'cust' (customizar
   etapas por instância — pular na edição) → 4 (detalhes finais). O step 'cust' é
   novo e opcional na prática — o usuário pode só apertar "Avançar" sem tocar. */
const WIZARD_STEPS = [1, 2, 3, 'cust', 4];
function wizardStepIndex(s) { return WIZARD_STEPS.indexOf(s); }

function wizardGoTo(n) {
  wizardState.step = n;
  // Mostra só o step ativo
  WIZARD_STEPS.forEach(s => {
    const el = document.getElementById('dw-step-' + s);
    if (el) el.style.display = (s === n ? '' : 'none');
  });
  // Footer dinâmico
  const back = $('dw-back-btn');
  const next = $('dw-next-btn');
  const create = $('dw-create-btn');
  const tpl = $('save-as-template-btn');
  const isFinal = (n === 4);
  const idx = wizardStepIndex(n);
  // Voltar: oculto no step 1 (na criação) e em modo edição (não tem wizard).
  if (back) back.style.display = (idx > 0 && !editingId) ? '' : 'none';
  if (next) next.style.display = isFinal ? 'none' : '';
  if (create) create.style.display = isFinal ? '' : 'none';
  if (create) create.textContent = editingId ? 'Salvar Demanda' : 'Criar demanda';
  if (tpl) tpl.style.display = isFinal ? '' : 'none';
  // Render do step ativo
  if (n === 1) renderWizardClients();
  else if (n === 2) renderWizardProjects();
  else if (n === 3) renderWizardFlows();
  else if (n === 'cust') renderWizardCustomization();
  else if (n === 4) renderWizardStep4();
  updateWizardNextEnabled();
  paintIcons();
}

function wizardBack() {
  const idx = wizardStepIndex(wizardState.step);
  if (idx <= 0) return;
  wizardGoTo(WIZARD_STEPS[idx - 1]);
}
function wizardNext() {
  const idx = wizardStepIndex(wizardState.step);
  if (idx < 0 || idx >= WIZARD_STEPS.length - 1) return;
  wizardGoTo(WIZARD_STEPS[idx + 1]);
}
function updateWizardNextEnabled() {
  const btn = $('dw-next-btn');
  if (!btn) return;
  let ok = true; // cust e 4 sempre dá pra prosseguir
  if (wizardState.step === 1) ok = !!wizardState.clientId;
  else if (wizardState.step === 2) ok = !!wizardState.projectId;
  else if (wizardState.step === 3) ok = !!wizardState.flowId;
  btn.disabled = !ok;
}

/* Estado da customização inicial. Reset a cada abertura do wizard.
   Estrutura reflete o que o backend aceita em /api/demands (POST):
     skippedStages: [stageId]
     stageResponsibles: { stageId: userId | null }
     stageLabels: { stageId: 'nome custom' }
     stageOverrides: { stageId: { color?, deadlineDays?, done? } }  ← override de etapas ORIGINAIS
     stageAdditions: [{ id, label, color, deadlineDays, responsibleId, done }]
     stageOrder: [stageId]  ← inclui originais + adicionadas na ordem final */
function resetWizardCustomization() {
  wizardState.customization = {
    skippedStages: [], stageResponsibles: {}, stageLabels: {},
    stageOverrides: {}, stageAdditions: [], stageOrder: null
  };
}
/* Aplica valor efetivo de uma etapa considerando origem + overrides. Usado
   pra renderizar o valor "atual" mesmo pras originais que sofreram override. */
function _custEffectiveStageValue(stage, isAddition, field) {
  if (isAddition) return stage[field];
  const ov = wizardState.customization.stageOverrides[stage.id];
  if (ov && ov[field] !== undefined) return ov[field];
  return stage[field];
}
function renderWizardCustomization() {
  const wrap = $('dw-cust-list');
  if (!wrap) return;
  const flow = flowById(wizardState.flowId);
  if (!flow) { wrap.innerHTML = '<div class="hours-empty">Fluxo não encontrado.</div>'; return; }
  if (!wizardState.customization) resetWizardCustomization();
  // Pré-popula checklist com o default do fluxo (só se ainda tá zerado —
  // evita resetar edições feitas no step 4 se o usuário voltar pro cust).
  if (!Array.isArray(demandChecklistDraft) || !demandChecklistDraft.length) {
    demandChecklistDraft = Array.isArray(flow.defaultChecklist)
      ? flow.defaultChecklist.map(it => ({ text: String(it.text || ''), ownerId: it.ownerId || null }))
      : [];
  }
  const cust = wizardState.customization;
  const wsIdForUsers = wizardState.projectId ? projectById(wizardState.projectId)?.workspaceId : activeWs;
  const userOptions = users
    .filter(u => u.active !== false && (u.isAdmin || (u.workspaces || []).includes(wsIdForUsers)))
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));

  // Ordem efetiva: se stageOrder existe, usa; senão originais + adicionadas.
  const allById = new Map();
  flow.stages.forEach(s => allById.set(s.id, { stage: s, isAddition: false }));
  cust.stageAdditions.forEach(s => allById.set(s.id, { stage: s, isAddition: true }));
  let orderedIds;
  if (Array.isArray(cust.stageOrder) && cust.stageOrder.length) {
    const seen = new Set();
    orderedIds = cust.stageOrder.filter(id => allById.has(id) && !seen.has(id) && seen.add(id));
    // Garante que qualquer id novo (não no stageOrder) apareça no final
    flow.stages.forEach(s => { if (!seen.has(s.id)) { orderedIds.push(s.id); seen.add(s.id); } });
    cust.stageAdditions.forEach(s => { if (!seen.has(s.id)) { orderedIds.push(s.id); seen.add(s.id); } });
  } else {
    orderedIds = [...flow.stages.map(s => s.id), ...cust.stageAdditions.map(s => s.id)];
  }

  // Cascata data ↔ dias — respeita âncoras (deadlineDate) e SKIPA fins de semana.
  const baselineYmd = todayStr();
  const dateByStageId = {};
  let lastEnd = baselineYmd;
  orderedIds.forEach((id, i) => {
    const meta = allById.get(id);
    if (!meta) return;
    const { stage, isAddition } = meta;
    // Âncora explícita: adição.deadlineDate ou stageOverrides[id].deadlineDate.
    const anchor = isAddition ? stage.deadlineDate : cust.stageOverrides[id]?.deadlineDate;
    if (anchor) { dateByStageId[id] = anchor; lastEnd = anchor; return; }
    const days = _custEffectiveStageValue(stage, isAddition, 'deadlineDays');
    const end = _addBusinessDays(lastEnd, Number(days ?? 0));
    dateByStageId[id] = end;
    lastEnd = end;
  });

  const rowHTML = (stageId, i) => {
    const meta = allById.get(stageId);
    if (!meta) return '';
    const { stage, isAddition } = meta;
    const skipped = cust.skippedStages.includes(stageId);
    const label = cust.stageLabels[stageId] || stage.label;
    const color = _custEffectiveStageValue(stage, isAddition, 'color') || '#7A00FF';
    const days = _custEffectiveStageValue(stage, isAddition, 'deadlineDays');
    const done = _custEffectiveStageValue(stage, isAddition, 'done');
    // Padrão do fluxo — resolve stage.responsibleId E também stage.responsibleRole
    // via roleAssignments do projeto/cliente (fluxos frequentemente definem só
    // o papel, não o usuário direto). Sem isso o dropdown ficava "Selecionar…"
    // em todos os fluxos que usam responsibleRole.
    const defaultUserId = isAddition
      ? ''
      : (resolveDefaultUserIdForStage(stage, wizardState.projectId) || '');
    // Para etapas ORIGINAIS: usa override em cust.stageResponsibles, senão o padrão do fluxo.
    // Para etapas NOVAS: o responsibleId vive na própria addition (não em stageResponsibles).
    const respValue = isAddition
      ? (stage.responsibleId || '')
      : ((stageId in cust.stageResponsibles) ? cust.stageResponsibles[stageId] : defaultUserId);
    const placeholderOpt = respValue ? '' : `<option value="" selected>Selecionar executor…</option>`;
    const roleOpts = placeholderOpt + userOptions.map(u => {
      const isDefault = u.id === defaultUserId;
      return `<option value="${u.id}" ${respValue === u.id ? 'selected' : ''} ${isDefault ? 'data-default="1"' : ''}>${esc(u.name)}</option>`;
    }).join('');
    const removeBtn = isAddition
      ? `<button type="button" class="wizard-cust-remove" title="Remover etapa" onclick="wizardCustRemoveAddition('${stageId}')"><i data-lucide="trash-2" class="ic-md"></i></button>`
      : '<span class="wizard-cust-remove-placeholder"></span>';
    const endDate = dateByStageId[stageId] || '';
    // Data considerada "customizada" quando o usuário setou âncora explícita.
    const hasDateAnchor = isAddition
      ? !!stage.deadlineDate
      : !!(cust.stageOverrides[stageId]?.deadlineDate);
    // Dias exibidos = diff entre a data desta etapa e a da anterior (ou baseline
    // pra primeira). Agora é só indicativo — o usuário edita as DATAS, o número
    // recalcula automaticamente. Só o fluxo (página Fluxos) tem SLA editável.
    const prevEnd = i === 0 ? baselineYmd : (dateByStageId[orderedIds[i - 1]] || baselineYmd);
    // Diff em dias ÚTEIS — ignora fim de semana pra não passar impressão errada.
    const computedDays = endDate ? _daysDiffBusiness(prevEnd, endDate) : (days ?? null);
    return `<div class="wizard-cust-row-v2 ${skipped ? 'is-skipped' : ''} ${isAddition ? 'is-added' : ''}" draggable="true" data-stage-id="${stageId}">
      <span class="wizard-cust-drag" title="Arraste pra reordenar"><i data-lucide="grip-vertical" class="ic-md"></i></span>
      <button type="button" class="color-swatch-trigger wizard-cust-color-lg" style="background:${esc(color)}" onclick="openColorPicker(this, (c) => { wizardCustSetColor('${stageId}', c); this.style.background = c; }, '${esc(color)}')" title="Cor da etapa"></button>
      <input type="text" class="wizard-cust-name" value="${esc(label)}" placeholder="Nome da etapa" oninput="wizardCustSetLabel('${stageId}', this.value)">
      <select class="wizard-cust-resp" data-cdrop-icon="user" data-default-value="${esc(defaultUserId || '')}" onchange="wizardCustSetResp('${stageId}', this.value)">${roleOpts}</select>
      <input type="date" class="wizard-cust-date ${hasDateAnchor ? 'is-customized' : ''}" data-fdp-display="short" data-fdp-no-weekend="1" value="${endDate}" onchange="wizardCustSetDate('${stageId}', this.value)">
      <span class="wizard-cust-days-plain" title="Prazo calculado a partir das datas — herdado do fluxo. Edite a data pra alterar.">${(computedDays ?? '—') + 'd'}</span>
      <button type="button" class="cust-icon-toggle cust-toggle-done ${done ? 'on' : ''}" title="${done ? 'Etapa final — conclui a demanda' : 'Marcar como etapa final (conclui a demanda)'}" onclick="wizardCustSetDone('${stageId}', ${!done})"><i data-lucide="flag" class="ic-md"></i></button>
      <button type="button" class="cust-icon-toggle cust-toggle-active ${!skipped ? 'on' : ''}" title="${skipped ? 'Etapa pulada — clique pra ativar' : 'Etapa ativa — clique pra pular'}" onclick="wizardCustToggleSkip('${stageId}', ${skipped})"><i data-lucide="${skipped ? 'eye-off' : 'eye'}" class="ic-md"></i></button>
      ${removeBtn}
    </div>`;
  };
  wrap.innerHTML = orderedIds.map((id, i) => rowHTML(id, i)).join('');
  _installCustDragDrop(wrap);
  renderWizardCustChecklist();
  paintIcons();
}
function renderWizardCustChecklist() {
  const wrap = $('dw-cust-checklist');
  if (!wrap) return;
  // Reusa demandChecklistDraft — o step 4 lê essa mesma variável no submit.
  if (!Array.isArray(demandChecklistDraft)) demandChecklistDraft = [];
  wrap.innerHTML = demandChecklistDraft.length
    ? demandChecklistDraft.map((it, i) => chkItemHTML(it, i, 'wizardCustRemoveChecklistItem')).join('')
    : '<div class="chk-empty">Nenhum item ainda.</div>';
  paintIcons();
}
function wizardCustSetChecklistText(idx, value) {
  if (!demandChecklistDraft[idx]) return;
  demandChecklistDraft[idx].text = value;
}
function wizardCustAddChecklistItem() {
  if (!Array.isArray(demandChecklistDraft)) demandChecklistDraft = [];
  demandChecklistDraft.push({ text: '', ownerId: null });
  renderWizardCustChecklist();
}
function wizardCustRemoveChecklistItem(idx) {
  demandChecklistDraft.splice(idx, 1);
  renderWizardCustChecklist();
}

/* Drag & drop nativo pra reordenar etapas. Guarda a ordem em cust.stageOrder
   (array de stageIds — mistura originais e adicionadas). */
let _custDragId = null;
function _installCustDragDrop(container) {
  container.querySelectorAll('.wizard-cust-row-v2').forEach(row => {
    // Drag só habilita quando o pointer desce na alça — clicar em input/select/botão
    // deixa a linha NÃO-arrastável, liberando digitação e seleção de texto.
    row.addEventListener('pointerdown', (e) => {
      row.draggable = !!e.target.closest('.wizard-cust-drag');
    });
    row.addEventListener('dragstart', (e) => {
      _custDragId = row.dataset.stageId;
      row.classList.add('is-dragging');
      // Alguns browsers precisam de setData pro drag funcionar
      try { e.dataTransfer.setData('text/plain', _custDragId); } catch {}
      e.dataTransfer.effectAllowed = 'move';
    });
    row.addEventListener('dragend', () => {
      row.classList.remove('is-dragging');
      container.querySelectorAll('.wizard-cust-row-v2').forEach(r => r.classList.remove('drop-above', 'drop-below'));
      _custDragId = null;
    });
    row.addEventListener('dragover', (e) => {
      if (!_custDragId || _custDragId === row.dataset.stageId) return;
      e.preventDefault();
      const rect = row.getBoundingClientRect();
      const above = (e.clientY - rect.top) < rect.height / 2;
      row.classList.toggle('drop-above', above);
      row.classList.toggle('drop-below', !above);
    });
    row.addEventListener('dragleave', () => {
      row.classList.remove('drop-above', 'drop-below');
    });
    row.addEventListener('drop', (e) => {
      e.preventDefault();
      if (!_custDragId || _custDragId === row.dataset.stageId) return;
      const rect = row.getBoundingClientRect();
      const above = (e.clientY - rect.top) < rect.height / 2;
      _reorderCust(_custDragId, row.dataset.stageId, above);
    });
  });
}
function _reorderCust(draggedId, targetId, above) {
  const cust = wizardState.customization;
  const flow = flowById(wizardState.flowId);
  // Snapshot da ordem atual (inclui originais + adicionadas).
  const current = Array.isArray(cust.stageOrder) && cust.stageOrder.length
    ? [...cust.stageOrder]
    : [...flow.stages.map(s => s.id), ...cust.stageAdditions.map(s => s.id)];
  const fromIdx = current.indexOf(draggedId);
  if (fromIdx < 0) return;
  current.splice(fromIdx, 1);
  let toIdx = current.indexOf(targetId);
  if (toIdx < 0) return;
  if (!above) toIdx += 1;
  current.splice(toIdx, 0, draggedId);
  cust.stageOrder = current;
  renderWizardCustomization();
}

function wizardCustToggleSkip(stageId, enabled) {
  const cust = wizardState.customization;
  if (enabled) cust.skippedStages = cust.skippedStages.filter(id => id !== stageId);
  else if (!cust.skippedStages.includes(stageId)) cust.skippedStages.push(stageId);
  // Re-render pra visual do skipped (opacity)
  renderWizardCustomization();
}
function wizardCustSetLabel(stageId, value) {
  const cust = wizardState.customization;
  const v = (value || '').trim();
  const flow = flowById(wizardState.flowId);
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) { addition.label = v || 'Nova etapa'; return; }
  const orig = flow?.stages.find(s => s.id === stageId);
  if (orig && v && v !== orig.label) cust.stageLabels[stageId] = v;
  else delete cust.stageLabels[stageId];
}
function wizardCustSetResp(stageId, value) {
  const cust = wizardState.customization;
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) { addition.responsibleId = value || null; return; }
  // Etapa original: se o usuário escolheu o mesmo do padrão do fluxo (ou
  // limpou), remove override — o dropdown já mostra o padrão diretamente.
  const flow = flowById(wizardState.flowId);
  const orig = flow?.stages.find(s => s.id === stageId);
  const defaultUserId = orig?.responsibleId || '';
  if (value === '' || value === defaultUserId) delete cust.stageResponsibles[stageId];
  else cust.stageResponsibles[stageId] = value;
}
function wizardCustSetDate(stageId, isoDate) {
  if (!wizardState.customization) resetWizardCustomization();
  const cust = wizardState.customization;
  const flow = flowById(wizardState.flowId);
  // Bloqueio de fim de semana (safety net — fdp já esconde weekend cells).
  if (isoDate && _isWeekendYmd(isoDate)) {
    toast('Etapas não podem cair em sábado ou domingo.', 'error');
    renderWizardCustomization();
    return;
  }
  // Calcula fim da etapa anterior respeitando âncoras já gravadas.
  const prevEnd = _wizardCustPrevEnd(stageId);
  if (isoDate && prevEnd && isoDate < prevEnd) {
    const orderedIds = _wizardCustOrderedIds();
    const idx = orderedIds.indexOf(stageId);
    const prevId = orderedIds[idx - 1];
    const prevStage = flow?.stages.find(s => s.id === prevId) || cust.stageAdditions.find(s => s.id === prevId);
    const prevLabel = cust.stageLabels[prevId] || prevStage?.label || '';
    _showStageDateTooltip(stageId, `Não é possível colocar data anterior à etapa "${prevLabel}" (termina em ${_fmtDayMonth(prevEnd)}).`);
    renderWizardCustomization();
    return;
  }
  // Grava a data como âncora E recalcula o SLA em dias ÚTEIS (data - prevEnd).
  // Assim o campo "d" reflete quantos dias úteis o usuário terá pra executar.
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) {
    addition.deadlineDate = isoDate || null;
    if (isoDate) addition.deadlineDays = _daysDiffBusiness(prevEnd, isoDate);
  } else {
    if (!cust.stageOverrides[stageId]) cust.stageOverrides[stageId] = {};
    if (isoDate) {
      cust.stageOverrides[stageId].deadlineDate = isoDate;
      cust.stageOverrides[stageId].deadlineDays = _daysDiffBusiness(prevEnd, isoDate);
    } else {
      delete cust.stageOverrides[stageId].deadlineDate;
    }
    if (!Object.keys(cust.stageOverrides[stageId]).length) delete cust.stageOverrides[stageId];
  }
  renderWizardCustomization();
}
/* Helpers do wizard pra cascata data ↔ dias. */
function _wizardCustOrderedIds() {
  const cust = wizardState.customization;
  const flow = flowById(wizardState.flowId);
  const allIds = [...(flow?.stages.map(s => s.id) || []), ...cust.stageAdditions.map(s => s.id)];
  return (Array.isArray(cust.stageOrder) && cust.stageOrder.length)
    ? cust.stageOrder.filter(id => allIds.includes(id))
    : allIds;
}
function _wizardCustPrevEnd(stageId) {
  const cust = wizardState.customization;
  const flow = flowById(wizardState.flowId);
  const orderedIds = _wizardCustOrderedIds();
  const idx = orderedIds.indexOf(stageId);
  if (idx <= 0) return todayStr();
  let lastEnd = todayStr();
  for (let k = 0; k < idx; k++) {
    const id = orderedIds[k];
    const addition = cust.stageAdditions.find(s => s.id === id);
    if (addition) {
      if (addition.deadlineDate) { lastEnd = addition.deadlineDate; continue; }
      lastEnd = _addDays(lastEnd, Number(addition.deadlineDays ?? 0));
      continue;
    }
    const orig = flow?.stages.find(s => s.id === id);
    const ov = cust.stageOverrides[id];
    if (ov?.deadlineDate) { lastEnd = ov.deadlineDate; continue; }
    const days = (ov && ov.deadlineDays !== undefined) ? ov.deadlineDays : orig?.deadlineDays;
    lastEnd = _addDays(lastEnd, Number(days ?? 0));
  }
  return lastEnd;
}
function wizardCustSetDays(stageId, value) {
  const cust = wizardState.customization;
  const n = value === '' ? null : parseInt(value, 10);
  const parsed = (n === null || (Number.isFinite(n) && n >= 0)) ? n : null;
  const flow = flowById(wizardState.flowId);
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) {
    addition.deadlineDays = parsed;
    // Também âncora a data resultante — se o usuário setou dias=0 na etapa X,
    // ao avançar pra ela o server deve respeitar a data planejada, não recalcular.
    if (parsed != null) {
      const prevEnd = _wizardCustPrevEnd(stageId);
      addition.deadlineDate = _addDays(prevEnd, parsed);
    } else {
      addition.deadlineDate = null;
    }
    return;
  }
  const orig = flow?.stages.find(s => s.id === stageId);
  const same = (orig?.deadlineDays ?? null) === (parsed ?? null);
  if (same) {
    // Volta pro padrão do fluxo — remove âncora e override de dias.
    _writeStageOverride(stageId, 'deadlineDays', undefined);
    _writeStageOverride(stageId, 'deadlineDate', undefined);
  } else {
    _writeStageOverride(stageId, 'deadlineDays', parsed);
    // Âncora a data derivada — assim SLA=0 gera "mesmo dia da anterior" ao
    // avançar, e não "hoje".
    const prevEnd = _wizardCustPrevEnd(stageId);
    _writeStageOverride(stageId, 'deadlineDate', parsed == null ? undefined : _addDays(prevEnd, parsed));
  }
}
function wizardCustSetColor(stageId, value) {
  if (!/^#[0-9a-f]{6}$/i.test(value || '')) return;
  const cust = wizardState.customization;
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) { addition.color = value; return; }
  const flow = flowById(wizardState.flowId);
  const orig = flow?.stages.find(s => s.id === stageId);
  const same = (orig?.color || '').toLowerCase() === value.toLowerCase();
  _writeStageOverride(stageId, 'color', same ? undefined : value);
}
function wizardCustSetDone(stageId, checked) {
  const cust = wizardState.customization;
  const addition = cust.stageAdditions.find(s => s.id === stageId);
  if (addition) { addition.done = !!checked; renderWizardCustomization(); return; }
  const flow = flowById(wizardState.flowId);
  const orig = flow?.stages.find(s => s.id === stageId);
  const same = !!orig?.done === !!checked;
  _writeStageOverride(stageId, 'done', same ? undefined : !!checked);
  renderWizardCustomization();
}
/* Grava/limpa override numa etapa original. undefined = remove override
   (volta ao padrão do fluxo). Se o objeto de override fica vazio, remove todo. */
function _writeStageOverride(stageId, field, value) {
  const cust = wizardState.customization;
  const ov = cust.stageOverrides[stageId] || {};
  if (value === undefined) delete ov[field];
  else ov[field] = value;
  if (Object.keys(ov).length === 0) delete cust.stageOverrides[stageId];
  else cust.stageOverrides[stageId] = ov;
}
function wizardAddCustStage() {
  if (!wizardState.customization) resetWizardCustomization();
  const newStage = {
    id: 'add-' + Math.random().toString(36).slice(2, 10),
    label: 'Nova etapa',
    color: '#7A00FF',
    // Default 0 dias (mesma regra do editor de fluxos): etapa sem SLA definido
    // não empurra o cronograma. Se o usuário quiser, edita depois pra 1+.
    deadlineDays: 0,
    // Pré-seleciona o usuário logado como executor da nova etapa — evita o
    // estado "Escolher executor…" e faz o dropdown já vir preenchido.
    responsibleId: me?.id || null,
    done: false
  };
  wizardState.customization.stageAdditions.push(newStage);
  // Se já tem stageOrder, adiciona no final pra manter consistência
  if (Array.isArray(wizardState.customization.stageOrder)) {
    wizardState.customization.stageOrder.push(newStage.id);
  }
  renderWizardCustomization();
}
function wizardCustRemoveAddition(id) {
  const cust = wizardState.customization;
  cust.stageAdditions = cust.stageAdditions.filter(s => s.id !== id);
  if (Array.isArray(cust.stageOrder)) cust.stageOrder = cust.stageOrder.filter(x => x !== id);
  renderWizardCustomization();
}

/* Renderizadores dos 3 grids de seleção. Card click = seleciona; dblclick = avança. */
function _wizardCardHandlers(el, onSelect) {
  el.addEventListener('click', () => onSelect(false));
  el.addEventListener('dblclick', () => onSelect(true));
}

/* Recentes — guarda os últimos IDs usados por (usuário × tipo) em localStorage.
   MRU: recém-usado vai pra frente, cai fora da lista após WIZARD_RECENTS_MAX.
   Snapshot: ao abrir o wizard, congela a lista pra não reordenar em tempo real
   enquanto o usuário navega (evita "pular" cards durante duplo clique). */
const WIZARD_RECENTS_MAX = 5;
let _wizardRecentsSnapshot = { client: null, flow: null };
function _recentsKey(kind) { return `kastor-recents-${kind}-${me?.id || 'anon'}`; }
function wizardGetRecents(kind) {
  try {
    const raw = localStorage.getItem(_recentsKey(kind));
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch { return []; }
}
function wizardPushRecent(kind, id) {
  if (!id) return;
  let arr = wizardGetRecents(kind).filter(x => x !== id);
  arr.unshift(id);
  arr = arr.slice(0, WIZARD_RECENTS_MAX);
  try { localStorage.setItem(_recentsKey(kind), JSON.stringify(arr)); } catch {}
  // NÃO atualiza o snapshot — mudanças só valem no próximo openNewDemand.
}
function wizardSnapshotRecents() {
  _wizardRecentsSnapshot = {
    client: wizardGetRecents('client'),
    flow:   wizardGetRecents('flow')
  };
}
/* Ordena a lista completa colocando os recentes primeiro (mesma ordem do MRU),
   depois o resto na ordem original. Usa o snapshot da abertura do wizard. */
function wizardSplitRecents(kind, fullList) {
  const recentIds = (_wizardRecentsSnapshot?.[kind]) || wizardGetRecents(kind);
  const byId = new Map(fullList.map(x => [x.id, x]));
  const recents = recentIds.map(id => byId.get(id)).filter(Boolean);
  const recentSet = new Set(recents.map(x => x.id));
  const rest = fullList.filter(x => !recentSet.has(x.id));
  return { recents, rest };
}

function _wizardClientCard(c) {
  const card = document.createElement('div');
  card.className = 'wizard-card' + (wizardState.clientId === c.id ? ' is-selected' : '');
  const avatar = c.avatar
    ? `<div class="wizard-card-avatar" style="background-image:url('${c.avatar}');background-size:cover;background-position:center"></div>`
    : `<div class="wizard-card-avatar" style="background:${hexDim(c.color || '#7A00FF')};color:${c.color || '#7A00FF'}">${esc((c.name || 'C').charAt(0).toUpperCase())}</div>`;
  card.innerHTML = `${avatar}<div class="wizard-card-name">${esc(c.name)}</div>`;
  _wizardCardHandlers(card, (advance) => {
    wizardState.clientId = c.id;
    wizardPushRecent('client', c.id);
    // Limpa downstream se mudou a seleção
    wizardState.projectId = null; wizardState.flowId = null;
    renderWizardClients();
    updateWizardNextEnabled();
    if (advance) wizardNext();
  });
  return card;
}
function renderWizardClients() {
  const wrap = $('dw-clients-grid');
  if (!wrap) return;
  const q = norm(($('dw-client-search')?.value || '').trim());
  const list = clients
    .filter(c => (me.isAdmin || (me.workspaces || []).includes(c.workspaceId)))
    .filter(c => c.active !== false)
    .filter(c => !q || norm(c.name).includes(q))
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  if (!list.length) {
    wrap.innerHTML = emptyState('Nenhum cliente cadastrado', 'Crie clientes em "Clientes" antes de criar uma demanda.', 'users');
    return;
  }
  wrap.innerHTML = '';
  // Se não há busca, mostra "Recentes" no topo (se houver). Com busca, oculta pra
  // não confundir — o usuário está procurando algo específico.
  if (!q) {
    const { recents, rest } = wizardSplitRecents('client', list);
    if (recents.length) {
      const head = document.createElement('div');
      head.className = 'wizard-section-head';
      head.textContent = 'RECENTES';
      wrap.appendChild(head);
      recents.forEach(c => wrap.appendChild(_wizardClientCard(c)));
      const head2 = document.createElement('div');
      head2.className = 'wizard-section-head';
      head2.textContent = 'TODOS';
      wrap.appendChild(head2);
      rest.forEach(c => wrap.appendChild(_wizardClientCard(c)));
      return;
    }
  }
  list.forEach(c => wrap.appendChild(_wizardClientCard(c)));
}

function renderWizardProjects() {
  const wrap = $('dw-projects-grid');
  if (!wrap) return;
  const q = norm(($('dw-project-search')?.value || '').trim());
  const cid = wizardState.clientId;
  const list = projects
    .filter(p => p.clientId === cid && p.active !== false)
    .filter(p => !q || norm(p.name).includes(q))
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  if (!list.length) {
    wrap.innerHTML = emptyState('Nenhum projeto ativo', 'Esse cliente não tem projetos ativos. Crie um pelo painel do cliente.', 'inbox');
    return;
  }
  wrap.innerHTML = '';
  list.forEach(p => {
    const card = document.createElement('div');
    card.className = 'wizard-card' + (wizardState.projectId === p.id ? ' is-selected' : '');
    const avatar = p.avatar
      ? `<div class="wizard-card-avatar" style="background-image:url('${p.avatar}');background-size:cover;background-position:center"></div>`
      : `<div class="wizard-card-avatar" style="background:${hexDim(p.color || '#7A00FF')};color:${p.color || '#7A00FF'}">${esc((p.name || 'P').charAt(0).toUpperCase())}</div>`;
    card.innerHTML = `${avatar}<div class="wizard-card-name">${esc(p.name)}</div>`;
    _wizardCardHandlers(card, (advance) => {
      wizardState.projectId = p.id;
      wizardState.flowId = null;
      renderWizardProjects();
      updateWizardNextEnabled();
      if (advance) wizardNext();
    });
    wrap.appendChild(card);
  });
}

function _wizardFlowCard(f) {
  const card = document.createElement('div');
  card.className = 'wizard-card' + (wizardState.flowId === f.id ? ' is-selected' : '');
  const iconHtml = !f.icon
    ? `<div class="wizard-card-avatar wizard-card-avatar--icon"><i data-lucide="workflow" class="ic-sm"></i></div>`
    : (typeof f.icon === 'string' && f.icon.startsWith('lucide:'))
      ? `<div class="wizard-card-avatar wizard-card-avatar--icon"><i data-lucide="${esc(f.icon.slice(7))}" class="ic-md"></i></div>`
      : `<div class="wizard-card-avatar" style="background-image:url('${f.icon}');background-size:cover;background-position:center"></div>`;
  const sub = f.demandType ? `<div class="wizard-card-sub">${esc(f.demandType)}</div>` : '';
  card.innerHTML = `${iconHtml}<div class="wizard-card-name">${esc(f.name)}</div>${sub}`;
  _wizardCardHandlers(card, (advance) => {
    wizardState.flowId = f.id;
    wizardPushRecent('flow', f.id);
    renderWizardFlows();
    updateWizardNextEnabled();
    if (advance) wizardNext();
  });
  return card;
}
// Filtro de tipo do wizard (chips em linha, estilo aba Análises). Dinâmico:
// cada demandType existente vira um botão. '' = Todos.
let _dwFlowType = '';
let _dwFlowTypes = [];
function renderWizardTypeFilter() {
  const el = $('dw-flow-type-filter');
  if (!el) return;
  // Botão índice: -1 = Todos; i >= 0 = _dwFlowTypes[i]. Passar índice (não a
  // string) evita qualquer problema de escape de aspas no onclick inline.
  let html = `<button type="button" class="dw-type-btn${_dwFlowType === '' ? ' is-active' : ''}" onclick="setWizardFlowType(-1)">Todos</button>`;
  html += _dwFlowTypes.map((t, i) =>
    `<button type="button" class="dw-type-btn${_dwFlowType === t ? ' is-active' : ''}" onclick="setWizardFlowType(${i})">${esc(t)}</button>`
  ).join('');
  el.innerHTML = html;
}
function setWizardFlowType(i) {
  _dwFlowType = (i < 0) ? '' : (_dwFlowTypes[i] || '');
  renderWizardFlows();
}
function renderWizardFlows() {
  const wrap = $('dw-flows-grid');
  if (!wrap) return;
  const q = norm(($('dw-flow-search')?.value || '').trim());
  // Fluxos pertencem ao CLIENTE — cross-workspace. Projeto define o "onde"
  // da demanda, mas não restringe os fluxos disponíveis.
  const allFlows = flowsForClient(wizardState.clientId);
  // Popula filtro de tipo (dinâmico — um chip por demandType existente)
  _dwFlowTypes = [...new Set(allFlows.map(f => f.demandType).filter(Boolean))].sort();
  if (_dwFlowType && !_dwFlowTypes.includes(_dwFlowType)) _dwFlowType = '';
  renderWizardTypeFilter();
  const typeFilter = _dwFlowType;
  const list = allFlows
    .filter(f => !typeFilter || f.demandType === typeFilter)
    .filter(f => !q || norm(f.name).includes(q))
    .sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  if (!list.length) {
    wrap.innerHTML = emptyState('Nenhum fluxo disponível', 'Esse projeto não tem fluxos. Crie um pelo painel do cliente.', 'flow');
    return;
  }
  wrap.innerHTML = '';
  // Recentes só sem busca/filtro — evita confundir quando o usuário está procurando algo.
  if (!q && !typeFilter) {
    const { recents, rest } = wizardSplitRecents('flow', list);
    if (recents.length) {
      const head = document.createElement('div');
      head.className = 'wizard-section-head';
      head.textContent = 'RECENTES';
      wrap.appendChild(head);
      recents.forEach(f => wrap.appendChild(_wizardFlowCard(f)));
      const head2 = document.createElement('div');
      head2.className = 'wizard-section-head';
      head2.textContent = 'TODOS';
      wrap.appendChild(head2);
      rest.forEach(f => wrap.appendChild(_wizardFlowCard(f)));
      paintIcons();
      return;
    }
  }
  list.forEach(f => wrap.appendChild(_wizardFlowCard(f)));
  paintIcons();
}

/* Step 4 — popula o form atual a partir do state do wizard. */
function renderWizardStep4() {
  const cid = wizardState.clientId;
  const pid = wizardState.projectId;
  const fid = wizardState.flowId;
  // Breadcrumb visual
  const c = cid ? clientById(cid) : null;
  const p = pid ? projectById(pid) : null;
  const f = fid ? flowById(fid) : null;
  const bc = $('dw-breadcrumb');
  if (bc) {
    bc.innerHTML = [c?.name, p?.name, f?.name].filter(Boolean).map(s => esc(s)).join(' <span style="opacity:.45">›</span> ');
  }
  // Sincroniza os selects ocultos (compat com o resto do código)
  if (pid) $('f-project').value = pid;
  // Trocou de fluxo desde a última aplicação? Reseta defaults (descrição + checklist)
  // para que o novo fluxo herde seus próprios valores em syncStatusOptions().
  // Só aplica em criação — edição mantém os campos da demanda existente.
  if (!editingId && fid && fid !== wizardLastFlowApplied) {
    $('f-description').value = '';
    demandChecklistDraft = [];
    renderDemandChecklist();
    wizardLastFlowApplied = fid;
  }
  // onDemandProjectChange popula f-flow options; se já tiver, força o nosso
  if (pid) {
    onDemandProjectChange();
    if (fid) {
      $('f-flow').value = fid;
      syncStatusOptions(editingId ? demandById(editingId)?.status : undefined);
    }
  }
  // Sincroniza responsável (se edição) — já feito pelo openEditDemand;
  // na criação, syncStatusOptions já chama buildUserSelect com auto-owner.
  if (!editingId) {
    // Foca o nome
    setTimeout(() => $('f-name').focus(), 60);
  }
}

/* ─── LIXEIRA — recuperação de itens excluídos (30 dias) ───
   Lista clients/projects/demands soft-deletados via GET /api/trash. Restaurar
   reaproveita os endpoints /undelete; a purga permanente usa DELETE /api/trash.
   Acesso mod/admin — usuário comum que chegar por URL vê aviso. */
// Grupos compactados — persiste na sessão entre re-renders (após restore/purga).
const _trashCollapsed = new Set();
function toggleTrashGroup(type) {
  if (_trashCollapsed.has(type)) _trashCollapsed.delete(type);
  else _trashCollapsed.add(type);
  const g = document.querySelector(`.trash-group[data-type="${type}"]`);
  if (g) g.classList.toggle('collapsed', _trashCollapsed.has(type));
}
async function renderTrash() {
  const body = $('trash-body');
  if (!body) return;
  if (!(me && (me.isAdmin || me.isModerator))) {
    body.innerHTML = '<div class="trash-empty"><div class="trash-empty-title">Sem acesso à Lixeira.</div></div>';
    return;
  }
  body.innerHTML = '<div class="trash-loading">Carregando…</div>';
  let data;
  try {
    data = await api('/trash');
  } catch (e) {
    body.innerHTML = `<div class="trash-empty"><div class="trash-empty-title">Não foi possível carregar.</div><div class="trash-empty-sub">${esc(e.message || '')}</div></div>`;
    return;
  }
  const groups = [
    { type: 'clients',         label: 'Clientes',           icon: 'building-2',      items: data.clients         || [] },
    { type: 'projects',        label: 'Projetos',           icon: 'folder',          items: data.projects        || [] },
    { type: 'demands',         label: 'Demandas',           icon: 'clipboard-list',  items: data.demands         || [] },
    { type: 'flows',           label: 'Fluxos',             icon: 'git-branch',      items: data.flows           || [] },
    { type: 'listas',          label: 'Listas de tarefas',  icon: 'list-checks',     items: data.listas          || [] },
    { type: 'clientTemplates', label: 'Modelos de cliente', icon: 'layout-template', items: data.clientTemplates || [] },
  ];
  const total = groups.reduce((n, g) => n + g.items.length, 0);
  if (!total) {
    body.innerHTML = `<div class="trash-empty">
      <div class="trash-empty-icon"><i data-lucide="trash-2"></i></div>
      <div class="trash-empty-title">A lixeira está vazia</div>
      <div class="trash-empty-sub">Itens excluídos aparecem aqui e podem ser restaurados por até 30 dias.</div>
    </div>`;
    paintIcons();
    return;
  }
  body.innerHTML = groups.filter(g => g.items.length).map(g => `
    <div class="trash-group${_trashCollapsed.has(g.type) ? ' collapsed' : ''}" data-type="${g.type}">
      <div class="trash-group-head">
        <button type="button" class="trash-group-toggle" onclick="toggleTrashGroup('${g.type}')" title="Compactar / expandir">
          <i data-lucide="chevron-down" class="ic-sm trash-chevron"></i>
          <i data-lucide="${g.icon}" class="ic-sm"></i>
          <span>${g.label}</span>
          <span class="trash-count">${g.items.length}</span>
        </button>
        <button type="button" class="btn btn-ghost btn-sm trash-clear-btn" onclick="clearTrashGroup('${g.type}','${esc(g.label)}')" title="Limpar toda a lista">
          <i data-lucide="trash-2" class="ic-sm"></i> Limpar
        </button>
      </div>
      <div class="trash-list">
        ${g.items.map(it => trashRowHTML(g.type, it)).join('')}
      </div>
    </div>`).join('');
  paintIcons();
}

function trashRowHTML(type, it) {
  const name = esc(it.name || '(sem nome)');
  const who = it.deletedByName ? ` por ${esc(it.deletedByName)}` : '';
  const ctxBits = [];
  if (it.clientName) ctxBits.push(esc(it.clientName));
  if (it.projectName) ctxBits.push(esc(it.projectName));
  if (it.workspaceName) ctxBits.push(esc(it.workspaceName));
  const meta = [`Excluído ${fmtRelativeTime(it.deletedAt)}${who}`].concat(ctxBits).join(' · ');
  const left = trashTimeLeft(it.purgeAt);
  return `<div class="trash-item">
    <div class="trash-item-main">
      <div class="trash-item-name">${name}</div>
      <div class="trash-item-meta">${meta}</div>
    </div>
    <div class="trash-item-purge${left.soon ? ' soon' : ''}" title="Removido definitivamente após 30 dias">${left.label}</div>
    <div class="trash-item-actions">
      <button class="btn btn-ghost btn-sm" onclick="restoreTrashItem('${type}','${esc(it.id)}')">Restaurar</button>
      <button class="btn btn-ghost btn-sm trash-purge-btn" title="Excluir definitivamente" onclick="purgeTrashItem('${type}','${esc(it.id)}')"><i data-lucide="trash-2" class="ic-sm"></i></button>
    </div>
  </div>`;
}

function trashTimeLeft(purgeAt) {
  const ms = (purgeAt || 0) - Date.now();
  if (ms <= 0) return { label: 'removendo…', soon: true };
  const days = Math.ceil(ms / 86400000);
  if (days <= 1) {
    const hrs = Math.max(1, Math.ceil(ms / 3600000));
    return { label: `${hrs}h restantes`, soon: true };
  }
  return { label: `${days} dias restantes`, soon: days <= 3 };
}

async function restoreTrashItem(type, id) {
  try {
    await api(`/trash/${type}/${id}/restore`, 'POST');
    if (typeof refreshData === 'function') await refreshData();
    toast('Item restaurado.', 'success');
    renderTrash();
  } catch (e) {
    toast('Falha ao restaurar: ' + (e.message || 'erro'), 'error');
  }
}

async function purgeTrashItem(type, id) {
  const ok = await showConfirm({
    title: 'Excluir definitivamente',
    message: 'Este item será removido <strong>permanentemente</strong> do servidor e não poderá ser recuperado. Continuar?',
    okLabel: 'Excluir para sempre',
    danger: true
  });
  if (!ok) return;
  try {
    await api(`/trash/${type}/${id}`, 'DELETE');
    toast('Removido definitivamente.', 'success');
    renderTrash();
  } catch (e) {
    toast('Falha ao remover: ' + (e.message || 'erro'), 'error');
  }
}

async function clearTrashGroup(type, label) {
  const nice = (label || '').toLowerCase();
  const ok = await showConfirm({
    title: `Limpar ${nice}`,
    message: `Todos os itens em <strong>${esc(label || '')}</strong> serão removidos <strong>permanentemente</strong> do servidor e não poderão ser recuperados. Continuar?`,
    okLabel: 'Limpar tudo',
    danger: true
  });
  if (!ok) return;
  try {
    const r = await api(`/trash/${type}`, 'DELETE');
    const n = r && typeof r.purged === 'number' ? r.purged : 0;
    toast(n ? `${n} ${n === 1 ? 'item removido' : 'itens removidos'}.` : 'Nada para remover.', 'success');
    renderTrash();
  } catch (e) {
    toast('Falha ao limpar: ' + (e.message || 'erro'), 'error');
  }
}

/* ─── PWA: registra o Service Worker ───
   Necessário pra Chrome/Edge oferecerem "Instalar como app" no Windows.
   Silencioso — falha de registro (localhost sem HTTPS em prod, extensão
   bloqueando) não impede o app de funcionar como página normal. */
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js', { scope: '/' })
      .catch(err => console.warn('[SW] registro falhou:', err.message));
  });
}

/* ─── COFRE DE SENHAS ─────────────────────────────────────────
   Estado só do cliente: `pwState.unlockedUntil` cache local do timestamp
   devolvido pelo servidor pra pintar o badge de TTL. Servidor é o gate real
   — 403 vault_locked força a locked view. Lista de entradas é buscada
   sob demanda (sem cache global); reveal chama endpoint dedicado que
   registra audit. */
const pwState = {
  unlockedUntil: 0,       // ms; 0 = locked
  ttlMs: 15 * 60 * 1000,  // default; server pode sobrescrever no unlock/status
  entries: [],
  folders: [],            // [{ id, name, ownerId, memberIds, canEdit, memberCount }]
  revealed: {},           // { id: { pw, timeoutId } } — reveals ativos com auto-hide
  ttlTimer: null,
  selectedFolderId: '__all__' // '__all__' | folderId
};
/* ── WebAuthn client helpers ──
   Browser API é `navigator.credentials.create/get`. Todos os campos binários
   trafegam como base64url (do JSON PublicKeyCredential*OptionsJSON do server)
   e voltam pra base64url no JSON de resposta. Convertemos manualmente. */
function _b64uToBuf(b64u) {
  const b64 = String(b64u || '').replace(/-/g, '+').replace(/_/g, '/');
  const pad = b64.length % 4 ? 4 - (b64.length % 4) : 0;
  const bin = atob(b64 + '='.repeat(pad));
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}
function _bufToB64u(buf) {
  const bytes = new Uint8Array(buf);
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
async function isWebauthnPlatformAvailable() {
  if (!window.PublicKeyCredential || !window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable) return false;
  try { return !!(await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()); }
  catch { return false; }
}
/* Wizard de cadastro: pede tipo (Biometria/PIN) + nome antes de iniciar a
   cerimônia WebAuthn. O `kind` é rótulo do usuário — não muda a cerimônia
   (o OS mesmo escolhe o gesto), só serve pra ícone e nome bonito na lista. */
function openPwRegisterWizard() {
  if (!window.PublicKeyCredential) { toast('Este navegador não suporta biometria/WebAuthn.', 'warn'); return; }
  // Reset campos + estado do radio
  const inp = $('pw-wa-name'); if (inp) inp.value = '';
  document.querySelectorAll('input[name="pw-kind"]').forEach(r => { r.checked = r.value === 'biometric'; });
  document.querySelectorAll('.pw-kind-opt').forEach(o => {
    const active = o.querySelector('input')?.checked;
    o.classList.toggle('is-active', !!active);
  });
  // Wire clicks pra atualizar estado visual (o :has() do CSS resolveria, mas
  // não é universal — deixa explícito)
  document.querySelectorAll('.pw-kind-opt input').forEach(r => {
    r.onchange = () => {
      document.querySelectorAll('.pw-kind-opt').forEach(o =>
        o.classList.toggle('is-active', o.querySelector('input') === r));
    };
  });
  openModal('pw-webauthn-register-modal');
  setTimeout(() => $('pw-wa-name')?.focus(), 60);
  paintIcons();
}
async function submitPwRegisterWizard() {
  const kind = document.querySelector('input[name="pw-kind"]:checked')?.value || 'biometric';
  const name = ($('pw-wa-name').value || '').trim() || (kind === 'pin' ? 'PIN do dispositivo' : 'Biometria');
  closeModal('pw-webauthn-register-modal');
  await _registerWebauthnCredential(kind, name);
}
async function _registerWebauthnCredential(kind, label) {
  try {
    const opts = await api('/passwords/webauthn/register/begin', 'POST', {});
    const publicKey = {
      ...opts,
      challenge: _b64uToBuf(opts.challenge),
      user: { ...opts.user, id: _b64uToBuf(opts.user.id) },
      excludeCredentials: (opts.excludeCredentials || []).map(c => ({ ...c, id: _b64uToBuf(c.id) }))
    };
    const cred = await navigator.credentials.create({ publicKey });
    if (!cred) throw new Error('Registro cancelado');
    const response = {
      id: cred.id,
      rawId: _bufToB64u(cred.rawId),
      type: cred.type,
      response: {
        clientDataJSON: _bufToB64u(cred.response.clientDataJSON),
        attestationObject: _bufToB64u(cred.response.attestationObject),
        transports: cred.response.getTransports ? cred.response.getTransports() : undefined
      },
      clientExtensionResults: cred.getClientExtensionResults ? cred.getClientExtensionResults() : {},
      authenticatorAttachment: cred.authenticatorAttachment || undefined
    };
    await api('/passwords/webauthn/register/finish', 'POST', { response, label, kind });
    toast('Acesso cadastrado!', 'success');
    await refreshWebauthnCredsUI();
  } catch (e) {
    if (e.name === 'NotAllowedError') { toast('Cadastro cancelado.', 'warn'); return; }
    if (e.name === 'InvalidStateError') { toast('Este dispositivo já está cadastrado.', 'warn'); return; }
    toast(e.message || 'Falha ao cadastrar acesso.', 'error');
  }
}
// Compat: se alguém ainda chamar o helper antigo, cai no fluxo novo (biometria default).
async function registerWebauthnCredential() { openPwRegisterWizard(); }
async function unlockWithWebauthn() {
  if (!window.PublicKeyCredential) { toast('Este navegador não suporta biometria.', 'warn'); return; }
  try {
    const opts = await api('/passwords/webauthn/auth/begin', 'POST', {});
    const publicKey = {
      ...opts,
      challenge: _b64uToBuf(opts.challenge),
      allowCredentials: (opts.allowCredentials || []).map(c => ({ ...c, id: _b64uToBuf(c.id) }))
    };
    const assertion = await navigator.credentials.get({ publicKey });
    if (!assertion) throw new Error('Cancelado');
    const response = {
      id: assertion.id,
      rawId: _bufToB64u(assertion.rawId),
      type: assertion.type,
      response: {
        clientDataJSON: _bufToB64u(assertion.response.clientDataJSON),
        authenticatorData: _bufToB64u(assertion.response.authenticatorData),
        signature: _bufToB64u(assertion.response.signature),
        userHandle: assertion.response.userHandle ? _bufToB64u(assertion.response.userHandle) : undefined
      },
      clientExtensionResults: assertion.getClientExtensionResults ? assertion.getClientExtensionResults() : {},
      authenticatorAttachment: assertion.authenticatorAttachment || undefined
    };
    const r = await api('/passwords/webauthn/auth/finish', 'POST', { response });
    pwState.unlockedUntil = r.until;
    pwState.ttlMs = r.ttlMs || pwState.ttlMs;
    await renderPasswords();
  } catch (e) {
    if (e.name === 'NotAllowedError') { toast('Cancelado.', 'warn'); return; }
    toast(e.message || 'Falha ao destravar via biometria.', 'error');
  }
}
async function refreshWebauthnCredsUI() {
  const list = $('pw-cred-list');
  if (!list) return;
  let creds = [];
  try { creds = await api('/passwords/webauthn/credentials'); } catch {}
  if (!creds.length) {
    list.innerHTML = `<div class="pw-cred-empty">Nenhum acesso cadastrado ainda.</div>`;
    return;
  }
  list.innerHTML = creds.map(c => {
    const kind = c.kind === 'pin' ? 'pin' : 'biometric';
    const icon = kind === 'pin' ? 'key-round' : 'fingerprint';
    const typeLabel = kind === 'pin' ? 'PIN' : 'Biometria';
    return `
      <div class="pw-cred-row">
        <div class="pw-cred-info">
          <i data-lucide="${icon}" class="ic-sm pw-cred-icon pw-cred-icon--${kind}"></i>
          <div>
            <div class="pw-cred-name">${esc(c.name || typeLabel)}</div>
            <div class="pw-cred-meta">${typeLabel} · cadastrado em ${fmtAuditWhen(c.createdAt)}${c.lastUsedAt ? ' · último uso ' + fmtAuditWhen(c.lastUsedAt) : ''}</div>
          </div>
        </div>
        <button class="pw-icon-btn danger" onclick="removeWebauthnCred('${esc(c.credentialID).replace(/'/g,"&#39;")}')" title="Remover"><i data-lucide="trash-2" class="ic-xs"></i></button>
      </div>`;
  }).join('');
  paintIcons();
}
async function removeWebauthnCred(credId) {
  const ok = await showConfirm({
    title: 'Remover dispositivo',
    message: 'Este dispositivo não poderá mais destravar o cofre. Você ainda pode usar sua senha ou outros dispositivos cadastrados. Continuar?',
    okLabel: 'Remover', danger: true
  });
  if (!ok) return;
  try {
    await api('/passwords/webauthn/credentials/' + encodeURIComponent(credId), 'DELETE');
    toast('Dispositivo removido.', 'success');
    await refreshWebauthnCredsUI();
  } catch (e) { toast(e.message || 'Falha ao remover.', 'error'); }
}
async function _pwUpdateWebauthnUnlockBtn() {
  const btn = $('pw-webauthn-btn');
  const divider = $('pw-webauthn-divider');
  if (!btn) return;
  const supported = await isWebauthnPlatformAvailable();
  if (!supported) { btn.style.display = 'none'; divider.style.display = 'none'; return; }
  let creds = [];
  try { creds = await api('/passwords/webauthn/credentials'); } catch {}
  const has = creds.length > 0;
  btn.style.display = has ? '' : 'none';
  divider.style.display = has ? '' : 'none';
  paintIcons();
}
/* Variante do botão de biometria/PIN dentro do modal de unlock de PASTA. */
async function _pwUpdateFolderWebauthnBtn() {
  const btn = document.getElementById('pw-folder-webauthn-btn');
  const divider = document.getElementById('pw-folder-webauthn-divider');
  if (!btn || !divider) return;
  const supported = await isWebauthnPlatformAvailable();
  if (!supported) { btn.style.display = 'none'; divider.style.display = 'none'; return; }
  let creds = [];
  try { creds = await api('/passwords/webauthn/credentials'); } catch {}
  const has = creds.length > 0;
  btn.style.display = has ? '' : 'none';
  divider.style.display = has ? 'block' : 'none';
  paintIcons();
}
/* Destrava a pasta atualmente sob unlock modal usando biometria/PIN. */
async function unlockFolderWithWebauthn() {
  const folderId = _pwPendingUnlockFolderId;
  if (!folderId) return;
  if (!window.PublicKeyCredential) { toast('Este navegador não suporta biometria.', 'warn'); return; }
  try {
    const opts = await api('/passwords/webauthn/auth/begin', 'POST', {});
    const publicKey = {
      ...opts,
      challenge: _b64uToBuf(opts.challenge),
      allowCredentials: (opts.allowCredentials || []).map(c => ({ ...c, id: _b64uToBuf(c.id) }))
    };
    const assertion = await navigator.credentials.get({ publicKey });
    if (!assertion) throw new Error('Cancelado');
    const response = {
      id: assertion.id,
      rawId: _bufToB64u(assertion.rawId),
      type: assertion.type,
      response: {
        clientDataJSON: _bufToB64u(assertion.response.clientDataJSON),
        authenticatorData: _bufToB64u(assertion.response.authenticatorData),
        signature: _bufToB64u(assertion.response.signature),
        userHandle: assertion.response.userHandle ? _bufToB64u(assertion.response.userHandle) : undefined
      },
      clientExtensionResults: assertion.getClientExtensionResults ? assertion.getClientExtensionResults() : {}
    };
    const r = await api('/passwords/webauthn/auth/finish', 'POST', { response, folderId });
    closeModal('pw-folder-unlock-modal');
    // Atualiza estado local
    const f = _pwFolderById(folderId);
    if (f) { f.unlocked = true; f.unlockedUntil = r.until; }
    pwState.selectedFolderId = folderId;
    await loadPwEntriesForFolder(folderId);
    renderPwFolders();
    _updatePwEntriesHeader();
    _pwStartTtlPaint();
    toast('Pasta destravada via biometria.', 'success');
  } catch (e) {
    if (e.name === 'NotAllowedError') { toast('Cancelado.', 'warn'); return; }
    toast(e.message || 'Falha ao destravar via biometria.', 'error');
  }
}
/* Botão "Biometria" na barra de ações da unlocked view — só aparece se o
   browser suporta WebAuthn (não filtra por "tem cred", pra dar acesso ao
   cadastro do primeiro dispositivo). */
async function _pwUpdateBiometriaBtn() {
  const btn = $('pw-biometria-btn');
  if (!btn) return;
  const supported = await isWebauthnPlatformAvailable();
  btn.style.display = supported ? '' : 'none';
  paintIcons();
}
async function openPwBiometriaModal() {
  openModal('pw-biometria-modal');
  await refreshWebauthnCredsUI();
}

/* Sem unlock global — página abre direto e lista pastas (todas). Entradas
   só carregam depois que o usuário destrava a pasta clicada. */
async function renderPasswords() {
  try {
    await loadPwFolders();
    renderPwFolders();
    // Se tem uma pasta selecionada e destravada, carrega as entradas dela.
    const cur = pwState.selectedFolderId;
    if (cur && cur !== '__all__' && pwState.folders.find(f => f.id === cur && f.unlocked)) {
      await loadPwEntriesForFolder(cur);
    } else {
      pwState.entries = [];
      renderPasswordsTable();
    }
    // Mostra botão "Acesso" (gerenciar biometria/PIN) se suportado pelo browser.
    _pwUpdateBiometriaBtn();
  } catch (e) {
    toast('Falha ao carregar cofre.', 'error');
  }
}
async function loadPwFolders() {
  const folders = await api('/password-folders');
  pwState.folders = folders || [];
}
async function loadPwEntriesForFolder(folderId) {
  const entries = await api('/passwords?folderId=' + encodeURIComponent(folderId));
  pwState.entries = entries || [];
  renderPasswordsTable();
}
/* Não é mais usado — cofre não tranca globalmente. Mantido por compat com
   chamadas antigas de outros lugares. */
async function submitPwUnlock() { /* deprecated */ }
async function lockPwVault() { /* deprecated */ }
/* Trava a pasta atualmente aberta. */
async function lockCurrentFolder() {
  const cur = pwState.selectedFolderId;
  if (!cur || cur === '__all__') return;
  try { await api('/password-folders/' + cur + '/lock', 'POST', {}); } catch {}
  // Limpa reveals dessa pasta
  Object.entries(pwState.revealed).forEach(([id, r]) => {
    const entry = pwState.entries.find(e => e.id === id);
    if (entry && entry.folderId === cur) {
      clearTimeout(r.timeoutId);
      delete pwState.revealed[id];
    }
  });
  toast('Pasta travada.', 'success');
  pwState.selectedFolderId = null;
  await renderPasswords();
}
async function loadPasswords() {
  // Alias legado — delega pro renderPasswords que trata o novo modelo (folders + unlock).
  await renderPasswords();
}
function renderPasswordsTable() {
  const tb = $('pw-tbody');
  if (!tb) return;
  _updatePwEntriesHeader();
  const q = norm(($('pw-search')?.value || '').trim());
  const sel = pwState.selectedFolderId;
  // Sem pasta selecionada = tabela vazia com instrução.
  if (!sel) {
    tb.innerHTML = `<tr><td colspan="6">${emptyMini(pwState.folders.length === 0
      ? 'Crie uma pasta primeiro pra guardar suas senhas.'
      : 'Escolha uma pasta na esquerda pra abrir. Cada uma pede sua senha da conta.')}</td></tr>`;
    return;
  }
  // Se a pasta selecionada está TRAVADA, mostra CTA inline pra destravar
  // (senha ou biometria) sem forçar modal.
  const curFolder = _pwFolderById(sel);
  if (curFolder && !curFolder.unlocked) {
    tb.innerHTML = `<tr><td colspan="6">
      <div class="pw-folder-locked-cta">
        <i data-lucide="lock" class="ic-md"></i>
        <div class="pw-folder-locked-title">${esc(curFolder.name)} está travada</div>
        <div class="pw-folder-locked-sub">Autentique com sua senha da conta pra ver as ${curFolder.entryCount || 0} entrada${curFolder.entryCount === 1 ? '' : 's'}.</div>
        <button class="btn btn-primary" onclick="openFolderUnlockModal('${curFolder.id}')"><i data-lucide="unlock" class="ic-sm"></i> Abrir pasta</button>
      </div>
    </td></tr>`;
    paintIcons();
    return;
  }
  // Filtro textual dentro das entradas da pasta atual (já vieram só dessa pasta do server).
  const list = pwState.entries.filter(p => {
    if (!q) return true;
    return norm(p.name).includes(q)
        || norm(p.description || '').includes(q)
        || norm(p.email || '').includes(q)
        || norm(p.username || '').includes(q);
  });
  if (!list.length) {
    const msg = q ? 'Nenhuma entrada encontrada.' : 'Esta pasta está vazia. Clique em "Nova entrada".';
    tb.innerHTML = `<tr><td colspan="6">${emptyMini(msg)}</td></tr>`;
    return;
  }
  tb.innerHTML = list.map(p => {
    const revealed = pwState.revealed[p.id];
    const pwCell = revealed
      ? `<span class="pw-value pw-value--shown" title="${esc(revealed.pw)}">${esc(revealed.pw)}</span>
         <button class="pw-icon-btn" onclick="copyPwValue('${p.id}')" title="Copiar senha"><i data-lucide="copy" class="ic-sm"></i></button>`
      : `<span class="pw-value">••••••••</span>`;
    const emailEsc = esc(p.email || '');
    const usernameEsc = esc(p.username || '');
    // Row principal (nome/link/email/user/senha/ações) + row secundário full-width
    // com a descrição — só aparece se tiver conteúdo.
    const descRow = p.description
      ? `<tr class="pw-desc-row"><td colspan="6"><i data-lucide="align-left" class="ic-xs"></i> ${esc(p.description)}</td></tr>`
      : '';
    return `
      <tr class="pw-main-row ${p.description ? 'has-desc' : ''}">
        <td class="pw-td-name" title="${esc(p.name)}"><strong>${esc(p.name)}</strong></td>
        <td class="pw-td-link">${p.link ? `<a href="${esc(p.link)}" target="_blank" rel="noopener" class="pw-link" title="${esc(p.link)}">${esc(_pwShortLink(p.link))}</a>` : '—'}</td>
        <td class="pw-td-single" title="${emailEsc}">${emailEsc || '—'}</td>
        <td class="pw-td-single">${p.username ? `<span class="pw-mono" title="${usernameEsc}">${usernameEsc}</span> <button class="pw-icon-btn" onclick="copyToClipboard('${usernameEsc.replace(/'/g,"&#39;")}', 'Usuário')" title="Copiar"><i data-lucide="copy" class="ic-sm"></i></button>` : '—'}</td>
        <td class="pw-cell pw-td-single">${pwCell}</td>
        <td>
          <div class="pw-row-actions">
            <button class="pw-icon-btn" onclick="togglePwReveal('${p.id}')" title="${revealed ? 'Ocultar' : 'Mostrar'} senha">
              <i data-lucide="${revealed ? 'eye-off' : 'eye'}" class="ic-sm"></i>
            </button>
            <button class="pw-icon-btn" onclick="openPwWizard('${p.id}')" title="Editar"><i data-lucide="pencil" class="ic-sm"></i></button>
            <button class="pw-icon-btn danger" onclick="deletePwEntry('${p.id}')" title="Excluir"><i data-lucide="trash-2" class="ic-sm"></i></button>
          </div>
        </td>
      </tr>
      ${descRow}`;
  }).join('');
  paintIcons();
}
/* ── Pastas do cofre ──
   Pastas agora são entidades persistidas com controle de acesso por usuário.
   O usuário só vê pastas que ele criou OU foi adicionado como membro. Cada
   senha vive DENTRO de uma pasta (folderId obrigatório). */
function _pwFolderById(id) {
  return (pwState.folders || []).find(f => f.id === id);
}
function _pwCountInFolder(folderId) {
  return (pwState.entries || []).filter(p => p.folderId === folderId).length;
}
function renderPwFolders() {
  const el = document.getElementById('pw-folders');
  if (!el) return;
  const folders = (pwState.folders || []).slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)));
  const sel = pwState.selectedFolderId;
  const folderItems = folders.map(f => {
    const isActive = sel === f.id;
    const isUnlocked = !!f.unlocked;
    return `<button type="button" class="pw-folder-item ${isActive ? 'is-active' : ''} ${isUnlocked ? 'is-unlocked' : 'is-locked'}" data-folder-id="${f.id}" onclick="selectPwFolder('${f.id}')">
      <i data-lucide="${isUnlocked ? 'folder-open' : 'lock'}" class="ic-sm"></i>
      <span class="pw-folder-name" title="${esc(f.name)}">${esc(f.name)}</span>
      <span class="pw-folder-count">${f.entryCount ?? 0}</span>
      ${f.canEdit ? `<button type="button" class="pw-folder-menu-btn" title="Editar pasta" onclick="event.stopPropagation(); openPwFolderEditor('${f.id}')"><i data-lucide="more-horizontal" class="ic-xs"></i></button>` : ''}
    </button>`;
  }).join('');
  el.innerHTML = `
    <div class="pw-folder-section-title">Pastas</div>
    ${folderItems || '<div class="pw-folder-empty">Nenhuma pasta ainda. Crie a primeira.</div>'}
    <button type="button" class="pw-folder-new-btn" onclick="openPwFolderEditor(null)">
      <i data-lucide="plus" class="ic-sm"></i> Nova pasta
    </button>
  `;
  if (typeof paintIcons === 'function') paintIcons();
}
/* Clicar em QUALQUER pasta (destravada ou travada) seleciona ela. Se
   destravada, carrega entradas direto. Se travada, marca como selecionada
   (visualmente) e mostra o unlock inline no lugar da tabela — sem modal
   bloqueando. Assim é livre trocar entre pastas a qualquer momento. */
async function selectPwFolder(folderId) {
  if (!folderId) return;
  const f = _pwFolderById(folderId);
  if (!f) return;
  pwState.selectedFolderId = folderId;
  if (f.unlocked) {
    await loadPwEntriesForFolder(folderId);
  } else {
    // Zera entradas anteriores (podem ser de outra pasta destravada) e
    // renderiza estado bloqueado inline. Usuário destrava clicando no botão
    // que aparece no lugar da tabela — ou pelo modal se preferir teclado.
    pwState.entries = [];
    renderPasswordsTable();
  }
  _updatePwEntriesHeader();
  renderPwFolders(); // atualiza is-active
}
/* Header da coluna direita: mostra nome + TTL badge + botão Travar. */
function _updatePwEntriesHeader() {
  const header = document.getElementById('pw-entries-header');
  const title = document.getElementById('pw-entries-title');
  const badge = document.getElementById('pw-ttl-badge');
  const cur = pwState.selectedFolderId;
  const f = cur ? _pwFolderById(cur) : null;
  if (!header) return;
  if (f && f.unlocked) {
    header.style.display = '';
    if (title) title.textContent = f.name;
    if (badge && f.unlockedUntil) {
      const secs = Math.max(0, Math.floor((f.unlockedUntil - Date.now()) / 1000));
      const mm = Math.floor(secs / 60), ss = secs % 60;
      badge.textContent = mm + ':' + String(ss).padStart(2, '0');
    }
  } else {
    header.style.display = 'none';
  }
}
/* Modal de unlock por pasta — reusa o mesmo wizard (senha + biometria/PIN). */
let _pwPendingUnlockFolderId = null;
function openFolderUnlockModal(folderId) {
  _pwPendingUnlockFolderId = folderId;
  const f = _pwFolderById(folderId);
  const nameEl = document.getElementById('pw-folder-unlock-name');
  if (nameEl) nameEl.textContent = f ? f.name : 'esta pasta';
  const inp = document.getElementById('pw-folder-unlock-input');
  if (inp) inp.value = '';
  const err = document.getElementById('pw-folder-unlock-err');
  if (err) err.style.display = 'none';
  openModal('pw-folder-unlock-modal');
  _pwUpdateFolderWebauthnBtn(); // mostra botão biometria se houver cred
  setTimeout(() => document.getElementById('pw-folder-unlock-input')?.focus(), 60);
}
async function submitFolderUnlock() {
  const folderId = _pwPendingUnlockFolderId;
  if (!folderId) return;
  const inp = document.getElementById('pw-folder-unlock-input');
  const err = document.getElementById('pw-folder-unlock-err');
  const pw = (inp?.value || '');
  if (!pw) { if (err) { err.textContent = 'Digite sua senha.'; err.style.display = ''; } return; }
  try {
    const r = await api('/password-folders/' + folderId + '/unlock', 'POST', { password: pw });
    if (inp) inp.value = '';
    closeModal('pw-folder-unlock-modal');
    // Atualiza estado local
    const f = _pwFolderById(folderId);
    if (f) { f.unlocked = true; f.unlockedUntil = r.until; }
    pwState.selectedFolderId = folderId;
    await loadPwEntriesForFolder(folderId);
    renderPwFolders();
    _updatePwEntriesHeader();
    _pwStartTtlPaint();
    toast('Pasta destravada.', 'success');
  } catch (e) {
    if (err) { err.textContent = e.message || 'Senha incorreta.'; err.style.display = ''; }
    inp?.focus(); inp?.select();
  }
}
/* Editor de pasta — só nome. Sem whitelist de membros: todos veem, mas
   cada um autentica com a própria senha ao abrir. */
let _pwFolderEditingId = null;
function openPwFolderEditor(folderId) {
  _pwFolderEditingId = folderId || null;
  const f = folderId ? _pwFolderById(folderId) : null;
  $('pw-folder-modal-title').textContent = f ? 'Editar pasta' : 'Nova pasta';
  $('pw-folder-f-name').value = f?.name || '';
  $('pw-folder-delete-btn').style.display = (f && f.canEdit) ? '' : 'none';
  openModal('pw-folder-modal');
  setTimeout(() => $('pw-folder-f-name').focus(), 60);
}
async function submitPwFolderEditor() {
  const name = ($('pw-folder-f-name').value || '').trim();
  if (!name) { toast('Informe o nome da pasta.', 'warn'); return; }
  try {
    if (_pwFolderEditingId) {
      await api('/password-folders/' + _pwFolderEditingId, 'PUT', { name });
      toast('Pasta atualizada.', 'success');
    } else {
      const created = await api('/password-folders', 'POST', { name });
      toast('Pasta criada.', 'success');
    }
    closeModal('pw-folder-modal');
    await renderPasswords();
  } catch (e) { toast(e.message || 'Falha ao salvar pasta.', 'error'); }
}
async function deletePwFolderFromEditor() {
  if (!_pwFolderEditingId) return;
  const f = _pwFolderById(_pwFolderEditingId);
  if (!f) return;
  const count = _pwCountInFolder(f.id);
  if (count > 0) {
    toast(`Mova as ${count} entrada(s) antes de excluir a pasta.`, 'warn');
    return;
  }
  const ok = await showConfirm({
    title: 'Remover pasta',
    message: `A pasta <strong>${esc(f.name)}</strong> será removida. Continuar?`,
    okLabel: 'Remover', danger: true
  });
  if (!ok) return;
  try {
    await api('/password-folders/' + f.id, 'DELETE');
    if (pwState.selectedFolderId === f.id) pwState.selectedFolderId = '__all__';
    closeModal('pw-folder-modal');
    toast('Pasta removida.', 'success');
    await loadPasswords();
  } catch (e) { toast(e.message || 'Falha ao remover.', 'error'); }
}
function _pwShortLink(url) {
  // Encurta pra caber sem quebrar linha. Só o host (sem www.) — remove path/query.
  // Ex.: https://docs.google.com/presentation/d/1habv... → docs.google.com
  try {
    const u = new URL(url);
    const host = u.hostname.replace(/^www\./, '');
    return host.length > 26 ? host.slice(0, 24) + '…' : host;
  } catch { return url.length > 26 ? url.slice(0, 24) + '…' : url; }
}
async function togglePwReveal(id) {
  if (pwState.revealed[id]) {
    clearTimeout(pwState.revealed[id].timeoutId);
    delete pwState.revealed[id];
    renderPasswordsTable();
    return;
  }
  try {
    const r = await api('/passwords/' + id + '/reveal');
    const timeoutId = setTimeout(() => {
      delete pwState.revealed[id];
      renderPasswordsTable();
    }, 20000); // auto-oculta após 20s
    pwState.revealed[id] = { pw: r.password, timeoutId };
    renderPasswordsTable();
  } catch (e) {
    if (String(e.message || '').includes('vault_locked')) {
      pwState.unlockedUntil = 0;
      await renderPasswords();
      toast('Cofre expirou. Destrave de novo.', 'warn');
    } else {
      toast('Falha ao revelar senha.', 'error');
    }
  }
}
async function copyPwValue(id) {
  const r = pwState.revealed[id];
  if (!r) return;
  await copyToClipboard(r.pw, 'Senha');
}
async function copyToClipboard(text, label) {
  try {
    await navigator.clipboard.writeText(text);
    toast(`${label || 'Texto'} copiado.`, 'success');
  } catch {
    toast('Falha ao copiar.', 'error');
  }
}
/* Wizard modal */
function _pwSetToggleIcon(name) {
  // lucide substitui <i data-lucide> por <svg> após paintIcons(). Pra alternar
  // ícone dinamicamente, reescrevo o innerHTML do botão com um <i> fresco e
  // deixo o paintIcons() do próximo tick renderizar.
  const btn = $('pw-f-toggle');
  if (!btn) return;
  btn.innerHTML = `<i data-lucide="${name}" class="ic-sm"></i>`;
  paintIcons();
}
function openPwWizard(id) {
  // Só dá pra criar/editar em pastas DESTRAVADAS (server exige unlock pra CUD).
  const unlockedFolders = (pwState.folders || []).filter(f => f.unlocked);
  if (!id && unlockedFolders.length === 0) {
    toast('Destrave uma pasta antes de criar entradas.', 'warn');
    return;
  }
  $('pw-edit-id').value = id || '';
  $('pw-wizard-title').textContent = id ? 'Editar entrada' : 'Nova entrada';
  const p = id ? pwState.entries.find(x => x.id === id) : null;
  $('pw-f-name').value     = p?.name     || '';
  $('pw-f-description').value = p?.description || '';
  // Popula dropdown só com pastas destravadas (server só aceita gravar em pasta unlocked).
  const cur = pwState.selectedFolderId;
  const prefillFolderId = p ? p.folderId : (cur && unlockedFolders.some(f => f.id === cur) ? cur : (unlockedFolders[0]?.id || ''));
  const folderSel = $('pw-f-folder-id');
  folderSel.innerHTML = unlockedFolders
    .slice().sort((a, b) => norm(a.name).localeCompare(norm(b.name)))
    .map(f => `<option value="${f.id}" ${f.id === prefillFolderId ? 'selected' : ''}>${esc(f.name)}</option>`)
    .join('');
  $('pw-f-link').value     = p?.link     || '';
  $('pw-f-email').value    = p?.email    || '';
  $('pw-f-username').value = p?.username || '';
  $('pw-f-password').value = '';
  $('pw-f-password').type = 'password';
  _pwSetToggleIcon('eye');
  $('pw-edit-hint').style.display = id ? '' : 'none';
  openModal('pw-wizard-modal');
  setTimeout(() => $('pw-f-name').focus(), 60);
}
function pwToggleWizardShow() {
  const inp = $('pw-f-password');
  const showing = inp.type === 'text';
  inp.type = showing ? 'password' : 'text';
  _pwSetToggleIcon(showing ? 'eye' : 'eye-off');
}
function pwGenerateRandom() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*_-+=';
  const len = 20;
  const arr = new Uint32Array(len);
  crypto.getRandomValues(arr);
  const s = [...arr].map(n => chars[n % chars.length]).join('');
  $('pw-f-password').value = s;
  $('pw-f-password').type = 'text';
  _pwSetToggleIcon('eye-off');
}
async function submitPwWizard() {
  const id = $('pw-edit-id').value || null;
  const name = ($('pw-f-name').value || '').trim();
  const pw = $('pw-f-password').value || '';
  if (!name) { toast('Informe um nome.', 'warn'); return; }
  if (!id && !pw) { toast('Informe a senha.', 'warn'); return; }
  const folderId = ($('pw-f-folder-id')?.value || '').trim();
  if (!folderId) { toast('Escolha uma pasta.', 'warn'); return; }
  const body = {
    name,
    folderId,
    description: ($('pw-f-description').value || '').trim(),
    link: ($('pw-f-link').value || '').trim(),
    email: ($('pw-f-email').value || '').trim(),
    username: ($('pw-f-username').value || '').trim()
  };
  if (pw) body.password = pw;
  try {
    if (id) await api('/passwords/' + id, 'PUT', body);
    else    await api('/passwords',        'POST', body);
    closeModal('pw-wizard-modal');
    toast(id ? 'Entrada atualizada.' : 'Entrada criada.', 'success');
    // Seleciona a pasta de destino pra o usuário ver a entrada que acabou de criar/mover.
    pwState.selectedFolderId = folderId;
    await renderPasswords();
  } catch (e) {
    if (String(e.message || '').includes('folder_locked') || String(e.message || '').includes('vault_locked')) {
      closeModal('pw-wizard-modal');
      await renderPasswords();
      toast('Pasta expirou. Destrave de novo.', 'warn');
    } else {
      toast(e.message || 'Falha ao salvar.', 'error');
    }
  }
}
async function deletePwEntry(id) {
  const p = pwState.entries.find(x => x.id === id);
  if (!p) return;
  const ok = await showConfirm({
    title: 'Excluir entrada',
    message: `A entrada <strong>${esc(p.name)}</strong> será removida do cofre. Continuar?`,
    okLabel: 'Excluir', danger: true
  });
  if (!ok) return;
  try {
    await api('/passwords/' + id, 'DELETE');
    toast('Entrada removida.', 'success');
    await loadPasswords();
  } catch (e) {
    toast(e.message || 'Falha ao remover.', 'error');
  }
}
/* Painel de TTL — pinta contagem regressiva e re-checa a cada minuto. */
function _pwStopTtlPaint() {
  if (pwState.ttlTimer) { clearInterval(pwState.ttlTimer); pwState.ttlTimer = null; }
}
function _pwStartTtlPaint() {
  _pwStopTtlPaint();
  const paint = () => {
    const badge = $('pw-ttl-badge'); if (!badge) return;
    const remain = Math.max(0, pwState.unlockedUntil - Date.now());
    if (!remain) {
      badge.textContent = 'expirado';
      pwState.unlockedUntil = 0;
      renderPasswords();
      return;
    }
    const min = Math.floor(remain / 60000);
    const sec = Math.floor((remain % 60000) / 1000);
    badge.textContent = min > 0 ? `${min}min` : `${sec}s`;
  };
  paint();
  pwState.ttlTimer = setInterval(paint, 5000);
}
/* Audit modal (admin/mod) */
async function openPwAuditModal() {
  if (!me?.isAdmin && !me?.isModerator) { toast('Sem permissão.', 'warn'); return; }
  // Popula filtros
  const uSel = $('pw-audit-f-user');
  const eSel = $('pw-audit-f-entry');
  const users = (window.users || []).slice().sort((a,b) => norm(a.name).localeCompare(norm(b.name)));
  uSel.innerHTML = '<option value="">Todos os usuários</option>' + users.map(u => `<option value="${u.id}">${esc(u.name)}</option>`).join('');
  eSel.innerHTML = '<option value="">Todas as entradas</option>' + pwState.entries.map(p => `<option value="${p.id}">${esc(p.name)}</option>`).join('');
  uSel.onchange = loadPwAudit;
  eSel.onchange = loadPwAudit;
  openModal('pw-audit-modal');
  await loadPwAudit();
}
async function loadPwAudit() {
  const tb = $('pw-audit-tbody');
  if (!tb) return;
  const uSel = $('pw-audit-f-user').value;
  const eSel = $('pw-audit-f-entry').value;
  const q = new URLSearchParams();
  if (uSel) q.set('userId', uSel);
  if (eSel) q.set('passwordId', eSel);
  q.set('limit', '500');
  let list = [];
  try { list = await api('/passwords/audit?' + q.toString()); }
  catch (e) { tb.innerHTML = `<tr><td colspan="5">${emptyMini('Falha ao carregar histórico.')}</td></tr>`; return; }
  if (!list.length) { tb.innerHTML = `<tr><td colspan="5">${emptyMini('Nenhum evento no filtro atual.')}</td></tr>`; return; }
  const ACTION_LABEL = {
    unlock: '<span class="pw-audit-tag pw-audit-tag--unlock">destravou</span>',
    lock:   '<span class="pw-audit-tag pw-audit-tag--lock">travou</span>',
    view:   '<span class="pw-audit-tag pw-audit-tag--view">visualizou</span>',
    create: '<span class="pw-audit-tag pw-audit-tag--create">criou</span>',
    update: '<span class="pw-audit-tag pw-audit-tag--update">editou</span>',
    delete: '<span class="pw-audit-tag pw-audit-tag--delete">apagou</span>'
  };
  tb.innerHTML = list.map(a => {
    const u = userById(a.userId);
    // esc só quando o nome vem do meta (input do usuário); fallback é hardcoded seguro.
    const entryCell = a.meta?.name ? esc(a.meta.name) : (a.passwordId ? '—' : '<em>cofre</em>');
    const detail = (a.action === 'update' && a.meta?.fields) ? esc(a.meta.fields.join(', ')) : '';
    return `
      <tr>
        <td>${fmtAuditWhen(a.createdAt)}</td>
        <td>${u ? esc(u.name) : '—'}</td>
        <td>${ACTION_LABEL[a.action] || esc(a.action)}</td>
        <td>${entryCell}</td>
        <td>${detail}</td>
      </tr>`;
  }).join('');
  paintIcons();
}
function fmtAuditWhen(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  return d.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' });
}

/* ─── BASE DE CONHECIMENTO ─────────────────────────────────────
   Posts colaborativos com rich text, tags, autor + contributors auto-mantidos
   pelo servidor (quem edita e não é o autor entra na lista). Suporta
   incorporação de vídeos/dashboards via URL (YouTube, Vimeo, Loom, Google
   Docs, Notion, Miro, Figma, Looker, Airtable, CodePen, CodeSandbox, Canva).
   URL da rota: /knowledge-base (grid) ou /knowledge-base/{slug}-{id} (post). */
const kbState = {
  posts: [],
  currentPostId: null,
  editingTags: []
};
function postById(id) { return (kbState.posts || []).find(p => p.id === id) || null; }

async function loadPosts() {
  try { kbState.posts = await api('/posts'); }
  catch (e) { kbState.posts = []; }
}
async function renderKbFromRoute() {
  const path = location.pathname;
  const m = path.match(/^\/knowledge-base\/([a-z0-9-]+)$/);
  const postId = m ? extractRouteId(m[1]) : null;
  await loadPosts();
  if (postId) openPostDetail(postId, /* fromRoute */ true);
  else showKbGrid();
}
function showKbGrid() {
  kbState.currentPostId = null;
  const grid = $('kb-grid-view');
  const det  = $('kb-detail-view');
  if (grid) grid.style.display = '';
  if (det)  det.style.display  = 'none';
  renderKbAuthorFilter();
  renderKbGrid();
}
function renderKbAuthorFilter() {
  const sel = $('kb-f-author'); if (!sel) return;
  const authorIds = [...new Set((kbState.posts || []).map(p => p.authorId).filter(Boolean))];
  const authors = authorIds.map(id => userById(id)).filter(Boolean).sort((a,b) => norm(a.name).localeCompare(norm(b.name)));
  const prev = sel.value;
  sel.innerHTML = '<option value="">Todos os autores</option>' + authors.map(u => `<option value="${u.id}">${esc(u.name)}</option>`).join('');
  if (authors.some(u => u.id === prev)) sel.value = prev;
}
function renderKbGrid() {
  const wrap = $('kb-cards'); if (!wrap) return;
  const q = norm(($('kb-search')?.value || '').trim());
  const author = $('kb-f-author')?.value || '';
  // Multi-select: activeTags é um Set. Post precisa conter TODAS as tags
  // selecionadas (AND) — filtros cruzados = busca mais precisa.
  if (!(kbState._activeTags instanceof Set)) kbState._activeTags = new Set();
  const activeTags = kbState._activeTags;
  const list = (kbState.posts || []).filter(p => {
    if (author && p.authorId !== author) return false;
    if (activeTags.size) {
      const postTags = new Set(p.tags || []);
      for (const t of activeTags) if (!postTags.has(t)) return false;
    }
    if (!q) return true;
    const hay = norm(p.title || '') + ' ' + norm(_stripHtml(p.content || '')) + ' ' + (p.tags || []).join(' ');
    return hay.includes(q);
  });
  // Tag chips (top-N tags do resultado atual)
  renderKbTagChips();
  if (!list.length) {
    wrap.innerHTML = `<div class="empty-state" style="padding:40px 0">${
      q || author || activeTags.size ? 'Nenhum post encontrado com esses filtros.' : 'Nenhum post ainda. Clique em "+ Novo post" pra começar a base de conhecimento.'
    }</div>`;
    return;
  }
  wrap.innerHTML = list.map(p => {
    const author = userById(p.authorId);
    const excerpt = _stripHtml(p.content || '').slice(0, 160);
    const dt = p.updatedAt ? new Date(p.updatedAt).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }) : '';
    const tagsHtml = (p.tags || []).slice(0, 4).map(t => `<span class="kb-tag">${esc(t)}</span>`).join('');
    const contribs = (p.contributorIds || []).length;
    const cover = p.coverImage
      ? `<div class="kb-card-cover" style="background-image:url('${esc(p.coverImage)}')"></div>`
      : `<div class="kb-card-cover kb-card-cover--empty"><i data-lucide="file-text" class="ic-md"></i></div>`;
    return `
      <button type="button" class="kb-card ${p.coverImage ? 'kb-card--has-cover' : ''}" onclick="openPostDetail('${p.id}')">
        ${cover}
        <div class="kb-card-body">
          <div class="kb-card-head">
            <div class="kb-card-title">${esc(p.title)}</div>
            ${tagsHtml ? `<div class="kb-card-tags">${tagsHtml}</div>` : ''}
          </div>
          ${excerpt ? `<div class="kb-card-excerpt">${esc(excerpt)}${excerpt.length >= 160 ? '…' : ''}</div>` : ''}
          <div class="kb-card-meta">
            ${author ? `${avatarHTML(author, 'avatar avatar-xs')}<span class="kb-card-author">${esc(author.name)}</span>` : ''}
            ${contribs ? `<span class="kb-card-contribs" title="Contribuidores">+${contribs}</span>` : ''}
            <span class="kb-card-date">${esc(dt)}</span>
          </div>
        </div>
      </button>`;
  }).join('');
  paintIcons();
}
function renderKbTagChips() {
  const wrap = $('kb-tag-chips'); if (!wrap) return;
  if (!(kbState._activeTags instanceof Set)) kbState._activeTags = new Set();
  const activeTags = kbState._activeTags;
  const counts = new Map();
  (kbState.posts || []).forEach(p => (p.tags || []).forEach(t => counts.set(t, (counts.get(t) || 0) + 1)));
  const tags = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20);
  if (!tags.length) { wrap.innerHTML = ''; return; }
  wrap.innerHTML =
    `<button type="button" class="kb-chip ${activeTags.size === 0 ? 'is-active' : ''}" onclick="clearKbTagFilter()">Todas</button>` +
    tags.map(([t, n]) => {
      const isOn = activeTags.has(t);
      return `<button type="button" class="kb-chip ${isOn ? 'is-active' : ''}" onclick="toggleKbTagFilter('${esc(t).replace(/'/g,"&#39;")}')">${esc(t)} <span class="kb-chip-count">${n}</span></button>`;
    }).join('');
}
/* Toggle multi-select: adiciona/remove a tag do filtro ativo. AND entre elas. */
function toggleKbTagFilter(t) {
  if (!t) return;
  if (!(kbState._activeTags instanceof Set)) kbState._activeTags = new Set();
  if (kbState._activeTags.has(t)) kbState._activeTags.delete(t);
  else kbState._activeTags.add(t);
  renderKbGrid();
}
function clearKbTagFilter() {
  kbState._activeTags = new Set();
  renderKbGrid();
}
/* Compat com chamadas antigas (setKbTagFilter). */
function setKbTagFilter(t) {
  if (!t) { clearKbTagFilter(); return; }
  toggleKbTagFilter(t);
}
function _stripHtml(html) {
  const div = document.createElement('div');
  div.innerHTML = html;
  // Remove elementos que poluem o excerpt do card (fallback links dos embeds,
  // figcaptions em geral, código, blockquotes vazios).
  div.querySelectorAll('figcaption, .post-embed, script, style').forEach(n => n.remove());
  return (div.textContent || div.innerText || '').replace(/\s+/g, ' ').trim();
}

/* ── Detalhe de post ── */
async function openPostDetail(id, fromRoute) {
  const p = postById(id);
  if (!p) { toast('Post não encontrado.', 'error'); showKbGrid(); return; }
  kbState.currentPostId = id;
  const grid = $('kb-grid-view');
  const det  = $('kb-detail-view');
  if (grid) grid.style.display = 'none';
  if (det)  det.style.display  = '';
  if (!fromRoute) navPush(postPath(p));
  const author = userById(p.authorId);
  const contribs = (p.contributorIds || []).map(userById).filter(Boolean);
  const dt = p.updatedAt ? new Date(p.updatedAt).toLocaleString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
  const isAuthorOrPriv = p.authorId === me?.id || me?.isAdmin || me?.isModerator;
  const canEdit = true; // qualquer um do squad edita (colaborativo)
  const detBody = $('kb-detail-content');
  detBody.innerHTML = `
    <div class="kb-detail-head">
      <button type="button" class="btn btn-ghost btn-sm" onclick="backToKbGrid()"><i data-lucide="arrow-left" class="ic-sm"></i> Voltar</button>
      <div class="kb-detail-actions">
        ${canEdit ? `<button type="button" class="btn btn-ghost btn-sm" onclick="openPostEditor('${p.id}')"><i data-lucide="pencil" class="ic-sm"></i> Editar</button>` : ''}
        ${isAuthorOrPriv ? `<button type="button" class="btn btn-ghost btn-sm" onclick="deletePost('${p.id}')"><i data-lucide="trash-2" class="ic-sm"></i> Excluir</button>` : ''}
      </div>
    </div>
    ${p.coverImage ? `<div class="kb-detail-cover"><img src="${esc(p.coverImage)}" alt="Capa do post"></div>` : ''}
    <h1 class="kb-detail-title">${esc(p.title)}</h1>
    ${(p.tags || []).length ? `<div class="kb-detail-tags">${(p.tags || []).map(t => `<span class="kb-tag">${esc(t)}</span>`).join('')}</div>` : ''}
    <div class="kb-detail-meta">
      ${author ? `${avatarHTML(author, 'avatar avatar-sm')}<div class="kb-detail-author-info"><div class="kb-detail-author-name">${esc(author.name)}</div><div class="kb-detail-author-role">Autor · atualizado ${esc(dt)}</div></div>` : ''}
      ${contribs.length ? `<div class="kb-detail-contribs">
        <span class="kb-detail-contribs-label">Contribuidores</span>
        <div class="kb-detail-contribs-avatars">${contribs.slice(0, 8).map(u => avatarHTML(u, 'avatar avatar-xs')).join('')}${contribs.length > 8 ? `<span class="kb-detail-contribs-more">+${contribs.length - 8}</span>` : ''}</div>
      </div>` : ''}
    </div>
    <div class="kb-detail-body">${p.content || '<p class="empty-state">Sem conteúdo.</p>'}</div>
  `;
  paintIcons();
  window.scrollTo({ top: 0, behavior: 'instant' });
}
function backToKbGrid() {
  navPush('/knowledge-base');
  showKbGrid();
}
async function deletePost(id) {
  const p = postById(id); if (!p) return;
  const ok = await showConfirm({
    title: 'Excluir post',
    message: `O post <strong>${esc(p.title)}</strong> será removido. Continuar?`,
    okLabel: 'Excluir', danger: true
  });
  if (!ok) return;
  try {
    await api('/posts/' + id, 'DELETE');
    toast('Post excluído.', 'success');
    await loadPosts();
    backToKbGrid();
  } catch (e) { toast(e.message || 'Falha ao excluir.', 'error'); }
}

/* ── Editor de post ── página dedicada estilo blog (rota /knowledge-base/new
   ou /knowledge-base/{slug}/edit). Substituiu o modal antigo — mais espaço,
   toolbar sticky, capa dedicada, preview lado-a-lado e proteção contra
   navegação com edições não salvas. */
function openPostEditor(id) {
  // Ponto de entrada externo (botão do grid/detalhe): apenas navega.
  // renderPostEditorFromRoute cuida do resto quando a rota é aplicada.
  if (id) {
    const p = postById(id);
    navPush(p ? (postPath(p) + '/edit') : '/knowledge-base/new');
  } else {
    navPush('/knowledge-base/new');
  }
  applyRoute();
}
async function renderPostEditorFromRoute() {
  // Precisa dos posts carregados antes de decidir edit vs new — só ler pela rota.
  const path = location.pathname;
  const editMatch = path.match(/^\/knowledge-base\/([a-z0-9-]+)\/edit$/);
  const isNew = path === '/knowledge-base/new';
  if (editMatch && !kbState.posts.length) await loadPosts();
  const id = editMatch ? extractRouteId(editMatch[1]) : null;
  const p = id ? postById(id) : null;
  if (id && !p) { toast('Post não encontrado.', 'error'); navPush('/knowledge-base'); applyRoute(); return; }
  _initPostEditor(p, isNew);
}
function _initPostEditor(p, isNew) {
  $('post-edit-id').value = p?.id || '';
  $('post-cover-url').value = p?.coverImage || '';
  $('post-editor-title').textContent = p ? 'Editar post' : 'Novo post';
  $('post-f-title').value = p?.title || '';
  kbState.editingTags = p?.tags ? [...p.tags] : [];
  renderPostTagList();
  _renderPostCover(p?.coverImage || '');
  const body = $('post-f-content');
  body.innerHTML = p?.content || '';
  setPostEditorMode('edit');
  _postEditorDirty = false;
  _updateDirtyBadge();
  paintIcons();
  setTimeout(() => $('post-f-title').focus(), 60);
}
let _postEditorDirty = false;
function _markPostDirty() {
  if (_postEditorDirty) return;
  _postEditorDirty = true;
  _updateDirtyBadge();
}
function _updateDirtyBadge() {
  const el = $('post-editor-dirty'); if (!el) return;
  el.style.display = _postEditorDirty ? '' : 'none';
}
function setPostEditorMode(mode) {
  const editView = $('post-editor-canvas-edit');
  const prevView = $('post-editor-canvas-preview');
  document.querySelectorAll('.post-editor-mode-btn').forEach(b => {
    b.classList.toggle('is-active', b.dataset.mode === mode);
  });
  if (mode === 'preview') {
    _renderPostPreview();
    editView.style.display = 'none';
    prevView.style.display = '';
  } else {
    editView.style.display = '';
    prevView.style.display = 'none';
  }
}
function _renderPostPreview() {
  const body = $('post-editor-preview-body'); if (!body) return;
  const title = ($('post-f-title').value || '').trim() || 'Sem título';
  const content = $('post-f-content').innerHTML || '';
  const cover = $('post-cover-url').value || '';
  const tagsHtml = (kbState.editingTags || []).map(t => `<span class="kb-tag">${esc(t)}</span>`).join('');
  body.innerHTML = `
    ${cover ? `<div class="kb-detail-cover"><img src="${esc(cover)}" alt="Capa"></div>` : ''}
    <h1 class="kb-detail-title">${esc(title)}</h1>
    ${tagsHtml ? `<div class="kb-detail-tags">${tagsHtml}</div>` : ''}
    <div class="kb-detail-body">${content || '<p class="empty-state">Sem conteúdo.</p>'}</div>
  `;
  paintIcons();
}
function cancelPostEditor() {
  if (_postEditorDirty) {
    const ok = confirm('Você tem alterações não salvas. Sair mesmo assim?');
    if (!ok) return;
  }
  _postEditorDirty = false;
  const id = $('post-edit-id').value;
  if (id) {
    const p = postById(id);
    navPush(p ? postPath(p) : '/knowledge-base');
  } else {
    navPush('/knowledge-base');
  }
  applyRoute();
}
async function onPostCoverPicked(evt) {
  const file = (evt.target.files || [])[0];
  evt.target.value = '';
  if (!file || !/^image\//.test(file.type)) return;
  if (file.size > 6 * 1024 * 1024) { toast('Capa muito grande (máx 6 MB).', 'warn'); return; }
  const reader = new FileReader();
  const dataUri = await new Promise(res => { reader.onload = () => res(reader.result); reader.readAsDataURL(file); });
  try {
    const up = await api('/uploads', 'POST', { data: dataUri, name: file.name });
    $('post-cover-url').value = up.url || '';
    _renderPostCover(up.url || '');
    _markPostDirty();
  } catch (e) { toast('Falha ao subir capa: ' + (e.message || ''), 'error'); }
}
function clearPostCover() {
  $('post-cover-url').value = '';
  _renderPostCover('');
  _markPostDirty();
}
function _renderPostCover(url) {
  const empty = $('post-cover-empty');
  const prev  = $('post-cover-preview');
  const img   = $('post-cover-img');
  if (url) {
    img.src = url;
    empty.style.display = 'none';
    prev.style.display  = '';
  } else {
    img.src = '';
    empty.style.display = '';
    prev.style.display  = 'none';
  }
}
function insertPostHR() {
  const body = $('post-f-content');
  body.focus();
  document.execCommand('insertHTML', false, '<hr><p><br></p>');
  _markPostDirty();
}
function execPostCmd(cmd, arg) {
  const body = $('post-f-content');
  body.focus();
  document.execCommand(cmd, false, arg || null);
  _markPostDirty();
}
function onPostTagKey(evt) {
  const inp = evt.currentTarget;
  if (evt.key === 'Enter' || evt.key === ',') {
    evt.preventDefault();
    _addPostTag(inp.value);
    inp.value = '';
  } else if (evt.key === 'Backspace' && !inp.value && kbState.editingTags.length) {
    kbState.editingTags.pop();
    renderPostTagList();
  }
}
function _addPostTag(raw) {
  const t = String(raw || '').trim().toLowerCase().slice(0, 40).replace(/[^a-z0-9-_À-ſ]+/g, '-').replace(/^-+|-+$/g, '');
  if (!t) return;
  if (kbState.editingTags.includes(t)) return;
  if (kbState.editingTags.length >= 12) { toast('Máximo 12 tags.', 'warn'); return; }
  kbState.editingTags.push(t);
  renderPostTagList();
}
function _removePostTag(t) {
  kbState.editingTags = kbState.editingTags.filter(x => x !== t);
  renderPostTagList();
}
function renderPostTagList() {
  const wrap = $('post-tag-list'); if (!wrap) return;
  wrap.innerHTML = (kbState.editingTags || []).map(t => `
    <span class="post-tag-chip">${esc(t)}<button type="button" class="post-tag-remove" onclick="_removePostTag('${esc(t).replace(/'/g,"&#39;")}')" title="Remover">×</button></span>
  `).join('');
}

/* ── Incorporação por CÓDIGO ──
   Usuário cola o código HTML de incorporação (o mesmo que YouTube/Loom/etc.
   dão no botão "Compartilhar → Incorporar"). O reWork extrai o <iframe>, valida
   o host, monta um embed limpo e insere. Providers suportados: os mesmos do
   whitelist do sanitizador (YouTube, Vimeo, Loom, Google Docs/Sheets/Slides/
   Drive/Looker, Notion, Miro, Figma, Airtable, CodePen, CodeSandbox, Canva,
   OneDrive, SharePoint). Cursor do editor é preservado entre modal e insert. */
const POST_EMBED_HOSTS = [
  'youtube.com', 'youtube-nocookie.com', 'youtu.be',
  'vimeo.com', 'player.vimeo.com',
  'loom.com',
  'docs.google.com', 'drive.google.com', 'sheets.google.com', 'lookerstudio.google.com',
  'notion.so', 'notion.site',
  'miro.com',
  'figma.com',
  'airtable.com',
  'codepen.io', 'codesandbox.io',
  'canva.com',
  'onedrive.live.com', 'sharepoint.com'
];
function _isPostEmbedHostAllowed(url) {
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') return false;
    const host = u.hostname.toLowerCase();
    return POST_EMBED_HOSTS.some(sfx => host === sfx || host.endsWith('.' + sfx));
  } catch { return false; }
}
/* Analisa o input colado. Aceita:
   - URL crua (https://youtube.com/watch?v=...) — detecta provider e monta iframe
   - Código de incorporação completo (<iframe ...>) — extrai src
   Retorna { ok, src, title, html?, error }. */
function parsePostEmbedCode(raw) {
  const src = String(raw || '').trim();
  if (!src) return { ok: false, error: 'Cole a URL do vídeo/dashboard ou o código de incorporação (com <iframe>).' };
  // Caminho 1: URL crua. Detecta provider e converte pro embed correto.
  if (/^https?:\/\//i.test(src) && !/<iframe/i.test(src)) {
    const converted = _urlToEmbedSrc(src);
    if (!converted) {
      return { ok: false, error: `Não consegui detectar o serviço a partir dessa URL. Tente colar o código de incorporação (<iframe>) que o próprio serviço oferece.` };
    }
    if (!_isPostEmbedHostAllowed(converted)) {
      return { ok: false, error: `Host "${_urlHost(converted)}" não está na lista de provedores permitidos.` };
    }
    const title = 'Conteúdo incorporado';
    const fallback = _embedToHumanUrlClient(converted);
    const clean = `<figure class="post-embed">
      <iframe src="${esc(converted)}" title="${esc(title)}" loading="lazy" allowfullscreen allow="autoplay; encrypted-media; picture-in-picture; fullscreen"></iframe>
      <figcaption><a href="${esc(fallback)}" target="_blank" rel="noopener noreferrer">Abrir no serviço original ↗</a></figcaption>
    </figure><p><br></p>`;
    return { ok: true, src: converted, title, html: clean };
  }
  // Caminho 2: código de incorporação — parse via DOM.
  const tmp = document.createElement('template');
  tmp.innerHTML = src;
  const iframe = tmp.content.querySelector('iframe');
  if (!iframe) return { ok: false, error: 'Não achei um <iframe> no código. Cole o código completo que o serviço fornece em "Compartilhar → Incorporar" — ou cole a URL do vídeo diretamente.' };
  const url = iframe.getAttribute('src') || '';
  if (!url) return { ok: false, error: 'O <iframe> não tem atributo src. Copie o código de embed novamente.' };
  if (!_isPostEmbedHostAllowed(url)) {
    return { ok: false, error: `Host "${_urlHost(url)}" não está na lista de provedores permitidos (YouTube, Vimeo, Loom, Google, Notion, Miro, Figma, Airtable, CodePen, CodeSandbox, Canva, OneDrive, SharePoint).` };
  }
  const title = iframe.getAttribute('title') || 'Conteúdo incorporado';
  // Reescreve iframe seguro com attrs padronizados (sem confiar em width/style
  // inline — o wrapper .post-embed dá aspect-ratio 16:9).
  // Sem `referrerpolicy=no-referrer`: YouTube e outros bloqueiam embeds sem Referer.
  // Figcaption com link "Abrir no serviço original" — fallback quando o dono
  // do vídeo/dashboard desabilita incorporação (comum em lives, dashboards
  // privados, etc.). Servidor recalcula o mesmo link na sanitização.
  const fallback = _embedToHumanUrlClient(url);
  const clean = `<figure class="post-embed">
    <iframe src="${esc(url)}" title="${esc(title)}" loading="lazy" allowfullscreen allow="autoplay; encrypted-media; picture-in-picture; fullscreen"></iframe>
    <figcaption><a href="${esc(fallback)}" target="_blank" rel="noopener noreferrer">Abrir no serviço original ↗</a></figcaption>
  </figure><p><br></p>`;
  return { ok: true, src: url, title, html: clean };
}
/* Converte URL crua → URL de embed do provider correto.
   YouTube: watch/short/youtu.be → /embed/{id}
   Vimeo:   vimeo.com/{id}       → player.vimeo.com/video/{id}
   Loom:    loom.com/share/{id}  → loom.com/embed/{id}
   Google Docs/Sheets/Slides/Drive: /edit → /preview
   Figma:   figma.com/file/...   → figma.com/embed?embed_host=share&url=...
   Miro/Notion/Airtable/Codepen/CodeSandbox/Canva/OneDrive/SharePoint: passa direto se já for URL de embed; se não, retorna null (usuário usa o iframe). */
function _urlToEmbedSrc(rawUrl) {
  let u;
  try { u = new URL(rawUrl); } catch { return null; }
  const host = u.hostname.replace(/^www\./, '').toLowerCase();
  // YouTube
  if (host === 'youtube.com' || host === 'm.youtube.com') {
    const v = u.searchParams.get('v');
    if (v) return `https://www.youtube.com/embed/${v}`;
    const m = u.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]+)/);
    if (m) return `https://www.youtube.com/embed/${m[1]}`;
  }
  if (host === 'youtu.be') {
    const m = u.pathname.match(/^\/([\w-]+)/);
    if (m) return `https://www.youtube.com/embed/${m[1]}`;
  }
  if (host === 'youtube-nocookie.com') return rawUrl;
  // Vimeo
  if (host === 'vimeo.com') {
    const m = u.pathname.match(/^\/(\d+)/);
    if (m) return `https://player.vimeo.com/video/${m[1]}`;
  }
  if (host === 'player.vimeo.com') return rawUrl;
  // Loom
  if (host === 'loom.com') {
    const m = u.pathname.match(/^\/(?:share|embed)\/([\w-]+)/);
    if (m) return `https://www.loom.com/embed/${m[1]}`;
  }
  // Google Docs / Sheets / Slides / Drive — troca /edit por /preview (embed padrão).
  if (host === 'docs.google.com' || host === 'drive.google.com') {
    if (/\/preview(\?|$)/.test(u.pathname + u.search)) return rawUrl;
    return rawUrl.replace(/\/edit(\?[^#]*)?(#.*)?$/, '/preview$1$2').replace(/\/view(\?[^#]*)?(#.*)?$/, '/preview$1$2');
  }
  // Looker Studio — URL de embed já vem com /embed/reporting
  if (host === 'lookerstudio.google.com') {
    if (u.pathname.includes('/embed/')) return rawUrl;
    return rawUrl.replace('/reporting/', '/embed/reporting/');
  }
  // Figma — URL de arquivo/design vira URL de embed via wrapper oficial.
  if (host === 'figma.com') {
    if (u.pathname.startsWith('/embed')) return rawUrl;
    return `https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(rawUrl)}`;
  }
  // Providers que exigem o modo iframe explícito (retornam null → user usa o código).
  // Notion, Miro, Airtable, CodePen, CodeSandbox, Canva, OneDrive, SharePoint —
  // se a URL colada já é de embed permitido (host bate no whitelist), passa direto.
  if (_isPostEmbedHostAllowed(rawUrl)) return rawUrl;
  return null;
}
function _embedToHumanUrlClient(embedSrc) {
  try {
    const u = new URL(embedSrc);
    const host = u.hostname.replace(/^www\./, '').toLowerCase();
    if (host === 'youtube.com' || host === 'youtube-nocookie.com' || host === 'youtu.be') {
      const m = u.pathname.match(/^\/embed\/([\w-]+)/);
      if (m) return 'https://www.youtube.com/watch?v=' + m[1];
    }
    if (host === 'player.vimeo.com') {
      const m = u.pathname.match(/^\/video\/(\d+)/);
      if (m) return 'https://vimeo.com/' + m[1];
    }
    if (host === 'loom.com') {
      const m = u.pathname.match(/^\/embed\/([\w-]+)/);
      if (m) return 'https://www.loom.com/share/' + m[1];
    }
    if (host === 'docs.google.com') return embedSrc.replace(/\/preview(\?.*)?$/, '/view$1');
    return embedSrc;
  } catch { return embedSrc; }
}
function _urlHost(url) { try { return new URL(url).hostname; } catch { return url.slice(0, 40); } }

// Preserva a posição do cursor no editor antes de abrir o modal.
let _postEmbedSavedRange = null;
function openPostEmbedModal() {
  const sel = window.getSelection();
  _postEmbedSavedRange = sel && sel.rangeCount ? sel.getRangeAt(0).cloneRange() : null;
  const editor = $('post-f-content');
  // Só guarda range se o cursor estava DENTRO do editor.
  if (_postEmbedSavedRange && !editor.contains(_postEmbedSavedRange.commonAncestorContainer)) {
    _postEmbedSavedRange = null;
  }
  $('post-embed-input').value = '';
  $('post-embed-preview').style.display = 'none';
  $('post-embed-preview-body').innerHTML = '';
  $('post-embed-err').style.display = 'none';
  $('post-embed-err').textContent = '';
  openModal('post-embed-modal');
  setTimeout(() => $('post-embed-input')?.focus(), 60);
}
function validatePostEmbed() {
  const raw = $('post-embed-input').value;
  const errEl = $('post-embed-err');
  const previewEl = $('post-embed-preview');
  const previewBody = $('post-embed-preview-body');
  // Input vazio → limpa tudo, sem mostrar erro (o usuário ainda está digitando).
  if (!String(raw || '').trim()) {
    errEl.style.display = 'none';
    previewEl.style.display = 'none';
    previewBody.innerHTML = '';
    return false;
  }
  const result = parsePostEmbedCode(raw);
  if (!result.ok) {
    errEl.textContent = result.error;
    errEl.style.display = '';
    previewEl.style.display = 'none';
    return false;
  }
  errEl.style.display = 'none';
  previewEl.style.display = '';
  previewBody.innerHTML = result.html;
  return true;
}
function insertPostEmbed() {
  const result = parsePostEmbedCode($('post-embed-input').value);
  if (!result.ok) { validatePostEmbed(); return; }
  const editor = $('post-f-content');
  editor.focus();
  // Restaura a posição do cursor onde o usuário estava antes de abrir o modal.
  if (_postEmbedSavedRange) {
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(_postEmbedSavedRange);
  }
  document.execCommand('insertHTML', false, result.html);
  closeModal('post-embed-modal');
  _postEmbedSavedRange = null;
  _markPostDirty();
}
async function openPostLinkPopover() {
  const url = await showPrompt({ title: 'Adicionar link', placeholder: 'https://...', okLabel: 'Adicionar' });
  if (!url) return;
  const body = $('post-f-content');
  body.focus();
  document.execCommand('createLink', false, url);
  // Força target=_blank + rel noopener
  body.querySelectorAll('a[href="' + url + '"]').forEach(a => {
    a.setAttribute('target', '_blank');
    a.setAttribute('rel', 'noopener noreferrer');
  });
  _markPostDirty();
}
async function onPostImagesPicked(evt) {
  const files = [...(evt.target.files || [])];
  evt.target.value = '';
  for (const f of files) {
    if (!/^image\//.test(f.type)) continue;
    const reader = new FileReader();
    const dataUri = await new Promise(res => { reader.onload = () => res(reader.result); reader.readAsDataURL(f); });
    // Upload primeiro (evita estourar limite de body do PUT).
    try {
      const up = await api('/uploads', 'POST', { data: dataUri, name: f.name });
      const body = $('post-f-content'); body.focus();
      document.execCommand('insertHTML', false, `<img src="${esc(up.url)}" alt="${esc(f.name)}"><p><br></p>`);
      _markPostDirty();
    } catch (e) { toast('Falha ao subir imagem: ' + (e.message || ''), 'error'); }
  }
}
async function submitPostEditor() {
  const id = $('post-edit-id').value || null;
  const title = ($('post-f-title').value || '').trim();
  const content = $('post-f-content').innerHTML || '';
  const coverImage = $('post-cover-url').value || '';
  if (!title) { toast('Informe um título.', 'warn'); $('post-f-title').focus(); return; }
  const body = { title, content, tags: kbState.editingTags, coverImage };
  try {
    const saved = id
      ? await api('/posts/' + id, 'PUT', body)
      : await api('/posts',        'POST', body);
    _postEditorDirty = false;
    toast(id ? 'Post atualizado.' : 'Post criado.', 'success');
    await loadPosts();
    // Volta pra tela do post recém-salvo (rota dedicada).
    navPush(postPath(saved));
    applyRoute();
  } catch (e) { toast(e.message || 'Falha ao salvar.', 'error'); }
}

/* ─── START ─── */
boot();
